/* Private cloud reservation editor: an Active hold is not a sale or payment.
   Owner authorization, status constraints and optimistic revision are server-side.
   This module never touches localStorage or enables writes automatically. */
(function(root,factory){
 const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;
 else root.NainaCloudReservations=api;
})(typeof globalThis==='object'?globalThis:this,function(){
 'use strict';
 let pending=false;
 const statuses=['Active','Expired','Cancelled','Converted'];
 const nonActive=['Expired','Cancelled','Converted'];
 function id(v){if(typeof v!=='string'||!v||v.length>256||/[\x00-\x1f]/.test(v))throw Error('Invalid reservation or vehicle ID.');return v;}
 function str(v,max=500){if(typeof v!=='string'||v.length>max||/[\x00-\x1f]/.test(v))throw Error('Invalid reservation text.');return v.trim();}
 function money(v){const s=str(v,30);if(!/^(?:0|[1-9]\d{0,11})(?:\.\d{1,2})?$/.test(s))throw Error('Invalid token amount.');const cents=Math.round(Number(s)*100);if(!Number.isSafeInteger(cents))throw Error('Token amount exceeds safe precision.');return cents/100;}
 function date(v){if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v))throw Error('Choose a valid calendar date.');const d=new Date(v+'T00:00:00Z');if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==v)throw Error('Invalid calendar day.');return v;}
 function uuid(){if(typeof crypto==='undefined'||typeof crypto.randomUUID!=='function')throw Error('Secure reservation ID unavailable.');return crypto.randomUUID();}
 function plan(bike,existing,values,revision,allReservations=[]){
  if(!Number.isSafeInteger(revision)||revision<0||revision>=Number.MAX_SAFE_INTEGER)throw Error('Refresh cloud revision first.');
  if(!bike||typeof bike!=='object')throw Error('Select a verified cloud vehicle.');
  const vehicleId=id(bike.id),v=values||{};
  if(existing&&(existing.vehicle_id!==vehicleId||existing.status!=='Active'))throw Error('Only the matching active reservation can be changed.');
  const customer_name=existing?str(existing.customer_name,300):str(v.customer_name||'',300);
  if(!customer_name)throw Error('Customer name is required.');
  const status=str(v.status||'Active',30);
  if(!statuses.includes(status))throw Error('Invalid reservation status.');
  if(!existing&&status!=='Active')throw Error('A new reservation must start Active.');
  if(!existing&&(bike.status!=='Available'||allReservations.some(r=>r?.vehicle_id===vehicleId&&r.status==='Active')))
   throw Error('Only unreserved available stock can be booked.');
  const reserved_at=existing?date(String(existing.reserved_at).slice(0,10)):date(v.reserved_at||'');
  const requestedExpiry=v.expires_at?date(v.expires_at):null;
  // Keep an original exact-time expiry if the selected calendar day is
  // unchanged. A status-only edit must never downgrade its precision.
  const savedExpiry=typeof existing?.expires_at==='string'?existing.expires_at:null;
  const expires_at=requestedExpiry&&savedExpiry?.slice(0,10)===requestedExpiry&&
    Number.isFinite(Date.parse(savedExpiry))?savedExpiry:requestedExpiry;
  if(expires_at&&Date.parse(expires_at)<Date.parse(existing?.reserved_at??reserved_at))
   throw Error('Reservation expiry cannot precede booking date.');
  const notes=str(v.notes||'',2000);
  // Existing booking metadata is never retransmitted as mutable data.
  const commandData=existing?{status,expires_at,notes}:{
   vehicle_id:vehicleId,customer_name,customer_phone:str(v.customer_phone||'',30),
   token_amount:money(v.token_amount??'0'),reserved_at,expires_at,status,notes};
  return {resource:'reservations',mode:existing?'update':'create',id:existing?id(existing.id):uuid(),
   expectedRevision:revision,idempotencyKey:uuid(),data:commandData};
 }
 async function write(fetchFn,cmd){
  if(!cmd||cmd.resource!=='reservations'||!['create','update'].includes(cmd.mode))throw Error('Invalid reservation command.');
  let response;
  try{response=await fetchFn('/api/private-crm-write',{method:'POST',
    credentials:'same-origin',cache:'no-store',redirect:'error',
    headers:{'Content-Type':'application/json'},body:JSON.stringify(cmd)});}
  catch{throw Error('Reservation save outcome unknown. Refresh before retrying.');}
  if(!response?.ok){
   if(response?.status===423)throw Error('Cloud reservation edits are still locked.');
   if(response?.status===409)throw Error('Reservation conflict. Refresh cloud records before retrying.');
   throw Error('Reservation write was not confirmed. Refresh before retrying.');
  }
  let json;try{json=await response.json();}catch{throw Error('Unreadable reservation receipt. Refresh before retrying.');}
  if(json?.result?.resource!=='reservations'||json.result.id!==cmd.id||
    json.result.revision!==cmd.expectedRevision+1)
   throw Error('Reservation receipt was not verified. Refresh first.');
  return json.result;
 }
 function openDialog({bike,existing=null,reservations=[],revision,notify,refresh,canSubmit}){
  if(pending||typeof canSubmit!=='function'||typeof refresh!=='function')return;
  const dialog=document.getElementById('cloud-reservation-dialog'),
    form=document.getElementById('cloud-reservation-form'),
    holder=document.getElementById('cloud-reservation-fields');
  if(!dialog||!form||!holder)return;
  document.getElementById('cloud-reservation-title').textContent=existing?'Edit or close reservation':'Reserve cloud vehicle';
  holder.replaceChildren();
  function field(label,key,value='',opts=null,type='text',lock=false){
   const wrap=document.createElement('label');wrap.textContent=label+' ';
   const el=document.createElement(opts?'select':'input');el.name=key;
   if(opts){for(const name of opts){const option=document.createElement('option');option.value=name;option.textContent=name;el.appendChild(option);}}
   else{el.type=type;el.maxLength=key==='notes'?2000:300;}
   el.required=['customer_name','reserved_at'].includes(key);el.value=String(value??'');el.disabled=lock;
   wrap.appendChild(el);holder.appendChild(wrap);
  }
  field('Customer name','customer_name',existing?.customer_name||'',null,'text',Boolean(existing));
  field('Contact number','customer_phone',existing?.customer_phone||'',null,'tel',Boolean(existing));
  field('Token amount — informational, NOT a payment (₹)','token_amount',existing?.token_amount??'0',null,'text',Boolean(existing));
  field('Reserved date','reserved_at',existing?.reserved_at?.slice(0,10)||'',null,'date',Boolean(existing));
  field('Expiry date','expires_at',existing?.expires_at?.slice(0,10)||'',null,'date');
  field('Status','status',existing?.status||'Active',existing?statuses:['Active']);
  field('Notes','notes',existing?.notes||'');
  const submit=form.querySelector('button[type="submit"]');
  form.onsubmit=async event=>{
   event.preventDefault();if(pending)return;
   if(!canSubmit()){notify('Cloud state changed while editing. Refresh.');dialog.close();return;}
   let cmd;try{
    const v=Object.fromEntries(new FormData(form));
    cmd=plan(bike,existing,v,revision,reservations);
   }catch(e){notify(e.message);return;}
   const prompt=cmd.data.status==='Converted'
    ?'Mark reservation Converted? This does NOT record a sale or token receipt; complete payment reconciliation separately.'
    :'Confirm this private reservation change? No customer payment or sale will be recorded.';
   if(!confirm(prompt))return;
   if(!canSubmit()){notify('Cloud state changed during confirmation. Refresh.');dialog.close();return;}
   pending=true;submit.disabled=true;
   try{
    await write(fetch,cmd);dialog.close();notify('Cloud reservation saved. Refreshing inventory.');await refresh();
   }catch(e){notify(e.message);}
   finally{pending=false;submit.disabled=false;}
  };
  document.getElementById('cloud-reservation-close').onclick=()=>{if(!pending)dialog.close();};
  if(!dialog.open)dialog.showModal();
 }
 return {plan,write,openDialog,isPending:()=>pending,states:statuses,closedStates:nonActive};
});

