import assert from 'node:assert/strict';
import fs from 'node:fs';
import {authorize,sameOrigin,validateBackup,planImport} from '../lib/cloud-core.mjs';
const b={id:'v1',name:'Test',reg:'UP78AB1234',chassis:'ch1',status:'Available',cost:100,parking:20,otherExpenses:30,expenses:50,sourceInventory:[{column:'A',value:1}]};const backup={version:3,bikes:[b],leads:[]};
assert.equal(authorize(null),401);assert.equal(authorize({userId:'a',email:'other@example.com'}),403);assert.equal(authorize({userId:'a',email:'sakshampathak01@gmail.com'}),200);
assert.equal(sameOrigin('https://evil.example','https://crm.nainamotors.com/api/cloud/test'),false);assert.equal(sameOrigin(null,'https://crm.nainamotors.com'),false);assert.equal(sameOrigin('https://crm.nainamotors.com','https://crm.nainamotors.com/api/cloud/test'),true);
assert.deepEqual(validateBackup(backup),[]);let p=planImport(backup,[],[],0,0);assert.equal(p.counts.insert,1);assert.equal(p.cloudChanged,false);assert.equal(p.importEnabled,false);
assert.equal(planImport(backup,[],[],1,0).valid,false);assert(validateBackup({...backup,bikes:[b,b]}).length>0);assert(validateBackup({...backup,bikes:[b,{...b,id:'v2'}]}).length>0);
assert.deepEqual(validateBackup({...backup,bikes:[{...b,reg:'UNREG',chassis:'c1'},{...b,id:'v2',reg:'UNREG',chassis:'c2'}]}),[]);
const row={id:'v1',status:'Available',payload_json:JSON.stringify(b),registration_key:b.reg,chassis_key:'CH1',revision:1};assert.equal(planImport(backup,[row],[],0,0).counts.skip,1);
assert.equal(planImport({...backup,bikes:[{...b,cost:200}]},[row],[],0,0).counts.conflict,1);assert.equal(planImport({...backup,bikes:[{...b,cost:200,cloudRevision:1}]},[row],[],0,0).counts.update,1);
assert.equal(planImport({...backup,bikes:[{...b,status:'Review'}]},[],[],0,0).counts.review,1);assert.equal(planImport({...backup,bikes:[{...b,expenses:999}]},[],[],0,0).counts.review,1);
assert.throws(()=>planImport(backup,[{...row,id:'different'}],[],0,0),/projection conflicts/);
assert(validateBackup({...backup,bikes:[{...b,parking:-10}]}).length>0);
const js=fs.readFileSync('public/cloud-readiness.js','utf8');assert(!js.includes('localStorage'));assert(!js.includes("call('import'"));
const importRoute=fs.readFileSync('app/api/cloud/import/route.ts','utf8');assert(importRoute.includes('423'));assert(!importRoute.includes('database('));
for(const name of ['status','test','dry-run','records','import'])assert(fs.readFileSync(`app/api/cloud/${name}/route.ts`,'utf8').includes('await guard(request'));
for(const name of ['dry-run','records','status'])assert(!/\b(INSERT|UPDATE|DELETE)\b/.test(fs.readFileSync(`app/api/cloud/${name}/route.ts`,'utf8')));
console.log('PASS: authorization, same-origin checks, validation, duplicate handling, source preservation, revisions, dry-run classifications, disabled import, no browser storage access from cloud UI.');

