import test from 'node:test';
import assert from 'node:assert/strict';
import {buildMediaRecoveryManifest,RecoveryManifestError} from '../lib/media-recovery.mjs';
const hash='a'.repeat(64);
const row={id:'media-1',vehicle_id:'vehicle-1',object_key:'private/never-public',original_filename:'Photo.jpg',mime_type:'image/jpeg',category:'photo',bytes:12,sha256:hash,notes:null,archived_at:null};
function setup({rows=[row],revision=8,changed=false,missing=false,wrong=false,unavailable=false}={}){
 let checks=0;
 const db={prepare(sql){if(sql.includes("cloud_metadata"))return {first:async()=>({value:String(changed&&++checks>1?revision+1:revision)})};
  return {bind(vehicleId,limit,offset){assert.equal(vehicleId,'vehicle-1');return {all:async()=>({success:true,results:rows.slice(offset,offset+limit)})};}};}};
 const bucket={head:async key=>{if(unavailable)throw Error('Storage unavailable');if(missing)return null;return {size:wrong?11:12,customMetadata:{sha256:hash}};}};
 return {db,bucket};
}
test('metadata-only audit keeps storage key and upload owner private',async()=>{
 const x=setup(),res=await buildMediaRecoveryManifest(x.db,x.bucket,'vehicle-1');
 assert.equal(res.revision,8);assert.equal(res.items[0].objectCheck,'metadata-match');
 assert.equal(res.items[0].sha256,hash);assert.equal(res.items[0].recoverableByExport,true);
 assert.equal(res.mediaBytesIncluded,false);assert.equal(res.contentChecksumsVerified,false);
 assert.doesNotMatch(JSON.stringify(res),/never-public|object_key|uploaded_by/);
});
test('unavailable or inconsistent objects require recovery',async()=>{
 for(const props of [{missing:true},{wrong:true}]){const x=setup(props),r=await buildMediaRecoveryManifest(x.db,x.bucket,'vehicle-1');
  assert.equal(r.attentionRequired,true);assert.equal(r.items[0].recoverableByExport,false);}
});
test('pending uploads are not marked exported or safe',async()=>{
 const x=setup({rows:[{...row,notes:'Internal: upload incomplete; reconciliation required'}]});
 const r=await buildMediaRecoveryManifest(x.db,x.bucket,'vehicle-1');
 assert.equal(r.items[0].state,'incomplete');assert.equal(r.items[0].recoverableByExport,false);
});
test('revision changes, R2 outage, bad SHA and invalid paging fail closed',async()=>{
 const x=setup({changed:true});await assert.rejects(buildMediaRecoveryManifest(x.db,x.bucket,'vehicle-1'),/changed during audit/);
 const y=setup({unavailable:true});await assert.rejects(buildMediaRecoveryManifest(y.db,y.bucket,'vehicle-1'),/audit unavailable/);
 const z=setup({rows:[{...row,sha256:'broken'}]});await assert.rejects(buildMediaRecoveryManifest(z.db,z.bucket,'vehicle-1'),/reconciliation/);
 const a=setup();for(const q of [{limit:51},{limit:0},{offset:-1}])await assert.rejects(buildMediaRecoveryManifest(a.db,a.bucket,'vehicle-1',q),RecoveryManifestError);
});
test('manifest revision audit refuses missing/noncanonical D1 metadata before R2 HEAD',async()=>{
 for(const revision of [null,'','00','01','0x10','1e2','-1','1.5','9007199254740992']){
  let heads=0;
  const db={prepare(sql){if(sql.includes('cloud_metadata'))return {first:async()=>revision===null?null:{value:revision}};
   return {bind(){return {all:async()=>({success:true,results:[row]})}}};}};
  const bucket={async head(){heads++;return null;}};
  await assert.rejects(()=>buildMediaRecoveryManifest(db,bucket,'vehicle-1'),/revision unavailable/);
  assert.equal(heads,0,String(revision));
 }
});

