// Ephemeral, LOCAL-ONLY built Worker smoke test. No production bindings or records.
// Runs against the checked-out vinext build with Wrangler's local worker runtime.
import { spawn } from 'node:child_process';
import { existsSync, mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
const root=resolve(fileURLToPath(new URL('..',import.meta.url)));
const config=resolve(root,'dist/server/wrangler.json');
const cli=resolve(root,'node_modules/wrangler/bin/wrangler.js');
if(!existsSync(config)||!existsSync(cli)){
 console.error('FAIL: Missing local vinext build or Wrangler; run pnpm exec vinext build first.');
 process.exitCode=1;
}else{
 const port=Number(process.env.NAINA_SMOKE_PORT||18781);
 if(!Number.isSafeInteger(port)||port<1024||port>65535)throw Error('Invalid local smoke port.');
 const origin='http://127.0.0.1:'+port;
 const state=mkdtempSync(join(tmpdir(),'naina-private-worker-smoke-'));
 let log='',ended=false,child;
 const argv=[
  '--import','./scripts/sites-env.mjs',
  './node_modules/wrangler/bin/wrangler.js','dev','--config','dist/server/wrangler.json',
  '--local','--persist-to',state,'--ip','127.0.0.1','--port',String(port),
  '--inspector-port','0',
 ];
 const safeRequest=async (url,options={})=>{
  const ctrl=new AbortController();
  const timer=setTimeout(()=>ctrl.abort(),2200);
  try{return await fetch(url,{redirect:'manual',cache:'no-store',signal:ctrl.signal,...options});}
  finally{clearTimeout(timer);}
 };
 try{
  child=spawn(process.execPath,argv,{
   cwd:root,env:{...process.env,WRANGLER_SEND_METRICS:'false',WRANGLER_WRITE_LOGS:'false',
    CLOUDFLARE_CF_FETCH_ENABLED:'false',CLOUDFLARE_API_TOKEN:'',CLOUDFLARE_API_KEY:''},
   stdio:['ignore','pipe','pipe'],
  });
  child.stdout.on('data',bytes=>{log=(log+bytes.toString('utf8')).slice(-18000);});
  child.stderr.on('data',bytes=>{log=(log+bytes.toString('utf8')).slice(-18000);});
  child.once('exit',()=>{ended=true;});
  let ready=false;
  const deadline=Date.now()+45000;
  while(Date.now()<deadline){
   if(ended)break;
   try{
    const response=await safeRequest(origin+'/');
    if(response.status>0){ready=true;break;}
   }catch{}
   await new Promise(r=>setTimeout(r,500));
  }
  if(!ready)throw Error('Local Worker did not become ready (no production contact attempted).');
  const homepage=await safeRequest(origin+'/');
  if(homepage.status!==200)throw Error('Homepage returned '+homepage.status);
  const html=await homepage.text();
  if(!/Naina Motors|Dealer Desk/i.test(html))throw Error('Built homepage did not contain Dealer Desk identity.');
  const paths=[
   '/api/private-crm-main?resource=vehicles',
   '/api/private-crm?resource=vehicles',
   '/api/cloud/status',
   '/api/cloud/records',
   '/api/private-crm-write',
   '/api/private-crm-transfer?action=export',
   '/api/private-media?action=list&vehicleId=synthetic',
   '/api/private-crm-preflight',
  ];
  for(const path of paths){
   const response=await safeRequest(origin+path);
   if(![401,403,423].includes(response.status))
    throw Error('Private route returned unexpected '+response.status+' for '+path);
   if(response.headers.get('cache-control')!=='no-store'||
      response.headers.get('x-content-type-options')!=='nosniff'||
      response.headers.get('access-control-allow-origin'))
    throw Error('Private route lacked strict anti-cache/content-type/CORS headers: '+path);
   const body=await response.text();
   if(body.length>8192||/object_key|payload_json|PRIVATE_SECRET/i.test(body))
    throw Error('Unexpected private route output from '+path);
  }
  const mutate=await safeRequest(origin+'/api/private-crm-write',{
   method:'POST',headers:{'Content-Type':'application/json','Origin':'https://untrusted.example'},
   body:JSON.stringify({resource:'vehicles',mode:'create',id:'synthetic',data:{name:'Forbidden'},
    expectedRevision:0,idempotencyKey:'test-never-authorized'}),
  });
  if(![401,403,423].includes(mutate.status))
   throw Error('Cross-site cloud write was not rejected ('+mutate.status+')');
  if(mutate.headers.get('access-control-allow-origin')||
     mutate.headers.get('cache-control')!=='no-store')
   throw Error('Cross-site cloud write returned unsafe response headers.');
  console.log('PASS: Built Dealer Desk worker served homepage; '+paths.length+
   ' private GET endpoints and cross-site POST were denied. Local-only, zero production writes.');
 }catch(err){
  console.error('FAIL: Built Worker smoke: '+String(err?.message||err));
  // Do not copy full logs: runtime logs can contain local environment details.
  console.error('Worker runtime tail (redacted): '+log
   .replace(/(token|key|secret|password)=\S+/gi,'$1=[REDACTED]')
   .slice(-1800));
  process.exitCode=1;
 }finally{
  if(child&&!ended){
   child.kill('SIGTERM');
   await Promise.race([
    new Promise(resolve=>child.once('exit',resolve)),
    new Promise(resolve=>setTimeout(resolve,2200)),
   ]);
   if(!ended)child.kill('SIGKILL');
  }
  rmSync(state,{recursive:true,force:true});
 }
}

