import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import {webcrypto} from 'node:crypto';
const ctx={URLSearchParams,URL,crypto:webcrypto,Blob,Number,Object,Set,JSON,Error};
vm.runInNewContext(fs.readFileSync('public/main-cloud-media.js','utf8'),ctx);
const m=ctx.NainaCloudMedia;
function file(name='photo.jpg',type='image/jpeg',size=8,lastModified=1){return {name,type,size,lastModified};}
test('private URL always uses relative same-origin route with encoded identifiers',()=>{
 const p=m.params('download','UP78 XX/001',{mediaId:'media-special +'});
 assert.match(p,/^\/api\/private-media\?/);
 const url=new URL(p,'https://crm.nainamotors.com');
 assert.equal(url.searchParams.get('vehicleId'),'UP78 XX/001');
 assert.equal(url.searchParams.get('mediaId'),'media-special +');
});
test('unsupported type, mismatched MIME and oversized files rejected',()=>{
 assert.throws(()=>m.validateFile(file('test.svg','image/svg+xml'), 'photo'),/Unsupported/);
 assert.throws(()=>m.validateFile(file('test.pdf','application/pdf'), 'photo'),/Unsupported/);
 assert.throws(()=>m.validateFile(file('test.jpg','application/pdf'), 'photo'),/Unsupported/);
 assert.throws(()=>m.validateFile(file('test.jpg','image/jpeg',16*1024*1024), 'photo'),/15 MiB/);
 assert.throws(()=>m.validateFile(file('../test.jpg','image/jpeg'), 'photo'),/filename/);
});
test('same file retries reuse the same idempotent token without background upload',()=>{
 const f=file(),one=m.tokenFor(f,'vehicle-1','photo'),two=m.tokenFor(f,'vehicle-1','photo');
 assert.equal(one,two);assert.match(one,/^[a-f0-9-]{36}$/);
 assert.notEqual(one,m.tokenFor(f,'vehicle-2','photo'));
 assert.notEqual(one,m.tokenFor(file('photo.jpg','image/jpeg',8,2),'vehicle-1','photo'));
 assert.equal(m.isPending(),false);
});
test('upload is one same-origin POST and receipt must match bytes, filename and ID',async()=>{
 const f=file();let calls=0;const token=m.tokenFor(f,'vehicle-1','photo');
 const result=await m.upload(async(url,opts)=>{calls++;assert.equal(opts.method,'POST');assert.equal(opts.credentials,'same-origin');assert.equal(opts.redirect,'error');assert.equal(opts.body,f);assert.equal(opts.headers['Content-Type'],'image/jpeg');assert.equal(new URL(url,'https://crm.nainamotors.com').searchParams.get('uploadId'),token);return {ok:true,async json(){return {id:'object-1',filename:'photo.jpg',bytes:8}}}},'vehicle-1',f,'photo',token);
 assert.equal(calls,1);assert.equal(result.id,'object-1');
 await assert.rejects(m.upload(async()=>({ok:true,async json(){return {id:'',filename:'other.jpg',bytes:8}}}),'vehicle-1',f,'photo',token),/receipt/);
});
test('network uncertainty never retries on its own and server lock fails closed',async()=>{
 const f=file(),token=m.tokenFor(f,'vehicle-1','photo');let calls=0;
 await assert.rejects(m.upload(async()=>{calls++;throw Error('timeout')},'vehicle-1',f,'photo',token),/unknown/);
 assert.equal(calls,1);
 await assert.rejects(m.upload(async()=>({ok:false,status:423}),'vehicle-1',f,'photo',token),/not activated/);
 await assert.rejects(m.upload(async()=>({ok:false,status:409}),'vehicle-1',f,'photo',token),/incomplete/);
});
test('archive/cover require verified private receipt',async()=>{
 const result=await m.mutate(async(url,opts)=>{assert.equal(opts.method,'POST');return {ok:true,async json(){return {id:'media1',action:'archive'}}}},'archive','vehicle1','media1');
 assert.equal(result.action,'archive');
 await assert.rejects(m.mutate(async()=>({ok:true,async json(){return {id:'bad',action:'cover'}}}),'cover','vehicle1','media1'),/receipt/);
});
test('downloads validate MIME, declared length and returned blob',async()=>{
 const result=await m.download(async()=>({ok:true,headers:{get:key=>key==='content-type'?'image/jpeg':key==='content-length'?'8':null},blob:async()=>new Blob([new Uint8Array(8)],{type:'image/jpeg'})}),'vehicle1','media1',{preview:true});
 assert.equal(result.size,8);
 await assert.rejects(m.download(async()=>({ok:true,headers:{get:key=>key==='content-type'?'image/svg+xml':key==='content-length'?'8':null}}),'vehicle1','media1',{preview:true}),/JPEG/);
 await assert.rejects(m.download(async()=>({ok:true,headers:{get:key=>key==='content-type'?'application/octet-stream':key==='content-length'?'100':null},blob:async()=>new Blob([new Uint8Array(8)])}),'vehicle1','media1'),/Incomplete/);
});

test('archived original is exported through the private route without restoring metadata',async()=>{
 let calls=0;
 const blob=await m.download(async(url,options)=>{
  calls++;
  const u=new URL(url,'https://crm.nainamotors.com');
  assert.equal(u.pathname,'/api/private-media');
  assert.equal(u.searchParams.get('action'),'export');
  assert.equal(u.searchParams.get('vehicleId'),'vehicleA');
  assert.equal(u.searchParams.get('mediaId'),'archivedB');
  assert.equal(options.method,'GET');assert.equal(options.credentials,'same-origin');
  return {ok:true,headers:{get:key=>key==='content-type'?'application/octet-stream':key==='content-length'?'8':null},
   blob:async()=>new Blob([new Uint8Array(8)])};
 },'vehicleA','archivedB',{archived:true});
 assert.equal(blob.size,8);assert.equal(calls,1);
 await assert.rejects(m.download(async()=>{throw Error('Should not issue preview');},'vehicleA','archivedB',{archived:true,preview:true}),/cannot be previewed/);
});
test('main cloud gallery offers recovery audit and archived export without automatic restoration',()=>{
 const s=fs.readFileSync('public/app.js','utf8');
 assert.match(s,/data-cloud-media-manifest/);
 assert.ok(s.includes('data-cloud-media="export"'));
 assert.match(s,/archived:action==='export'/);
 assert.doesNotMatch(s,/automatically restore all media/);
});

