// Server-side query library for the existing DB binding. No write methods.
import type * as schema from '../db/schema';
export type JsonObject = Record<string, unknown>;
export type StockStatus = 'Available' | 'Sold' | 'Review';
export class ReadError extends Error {
  constructor(public readonly code: 'INVALID_QUERY'|'INVALID_RECORD'|'READ_UNAVAILABLE') { super(code); }
}
export interface PageInput { limit?: number; offset?: number; id?: string; vehicleId?: string; saleId?: string; status?: StockStatus }
export interface Page<T> { items: T[]; limit: number; offset: number; nextOffset: number|null }
interface PayloadRow { id: string; payload_json: string; revision: number; owner_id?: string }
interface VehicleRow extends PayloadRow { status: string; registration_key: string|null; chassis_key: string|null; updated_at: string }
interface SaleRow extends PayloadRow { vehicle_id: string; customer_id: string|null }
interface ExpenseRow { id: string; vehicle_id: string; kind: string; amount_json: string; payload_json: string }
export interface PayloadRecord { id: string; revision: number; payload: JsonObject }
export interface VehicleRecord extends PayloadRecord { status: StockStatus; financials: ReturnType<typeof vehicleFinancials>; statusConflict: boolean }
export interface SaleRecord extends PayloadRecord { vehicleId: string; customerId: string|null; buyer: string|null; buyerPhone: string|null; buyerAddress: string|null; saleDate: string|null; sale: number|null; recordedBalance: number|null }
export type FeatureRows = {
 vehicle_media: typeof schema.vehicleMedia.$inferSelect;
 document_requirements: typeof schema.documentRequirements.$inferSelect;
 vehicle_age_baselines: typeof schema.vehicleAgeBaselines.$inferSelect;
 vehicle_locations: typeof schema.vehicleLocations.$inferSelect;
 vehicle_timeline: typeof schema.vehicleTimeline.$inferSelect;
 vehicle_inspections: typeof schema.vehicleInspections.$inferSelect;
 cashbook_entries: typeof schema.cashbookEntries.$inferSelect;
 customer_payments: typeof schema.customerPayments.$inferSelect;
 auction_plans: typeof schema.auctionPlans.$inferSelect;
 reservations: typeof schema.reservations.$inferSelect;
 enquiry_notes: typeof schema.enquiryNotes.$inferSelect;
 price_history: typeof schema.priceHistory.$inferSelect;
 repair_jobs: typeof schema.repairJobs.$inferSelect;
 rto_cases: typeof schema.rtoCases.$inferSelect;
 reminders: typeof schema.reminders.$inferSelect;
 document_expiries: typeof schema.documentExpiries.$inferSelect;
 generated_documents: typeof schema.generatedDocuments.$inferSelect;
 owner_preferences: typeof schema.ownerPreferences.$inferSelect;
};
export const FEATURE_KEYS = Object.freeze({
 vehicle_media:'id',document_requirements:'id',vehicle_age_baselines:'vehicle_id',vehicle_locations:'vehicle_id',
 vehicle_timeline:'id',vehicle_inspections:'id',cashbook_entries:'id',customer_payments:'id',auction_plans:'id',
 reservations:'id',enquiry_notes:'id',price_history:'id',repair_jobs:'id',rto_cases:'id',reminders:'id',
 document_expiries:'id',generated_documents:'id',owner_preferences:'setting_key',
} as const);
export type Feature = keyof FeatureRows;
const STATUSES: readonly string[] = ['Available','Sold','Review'];
function identifier(value: unknown): string {
 if(typeof value!=='string'||!value.length||value.length>1024)throw new ReadError('INVALID_QUERY');
 return value; // Never trim, normalize, or fabricate an ID.
}
export function pageInput(input: PageInput = {}) {
 const limit=input.limit??50,offset=input.offset??0;
 if(!Number.isInteger(limit)||limit<1||limit>100||!Number.isInteger(offset)||offset<0||offset>100000)throw new ReadError('INVALID_QUERY');
 return {limit,offset};
}
function parseJson(text: unknown): unknown {
 if(typeof text!=='string'||text.length>2*1024*1024)throw new ReadError('INVALID_RECORD');
 try{return JSON.parse(text);}catch{throw new ReadError('INVALID_RECORD');}
}
export function objectJson(text: unknown): JsonObject {
 const value=parseJson(text);
 if(!value||typeof value!=='object'||Array.isArray(value))throw new ReadError('INVALID_RECORD');
 return value as JsonObject;
}
export function amount(value: unknown): number|null {
 if(value===undefined||value===null||value==='')return null;
 if((typeof value!=='number'&&typeof value!=='string')||(typeof value==='string'&&!value.trim()))throw new ReadError('INVALID_RECORD');
 const n=Number(value);if(!Number.isFinite(n)||n<0)throw new ReadError('INVALID_RECORD');return n;
}
function optionalText(value: unknown): string|null {
 if(value===undefined||value===null)return null;
 if(typeof value!=='string')throw new ReadError('INVALID_RECORD');return value;
}
export function vehicleFinancials(p: JsonObject) {
 const purchase=amount(p.cost),parking=amount(p.parking),other=amount(p.otherExpenses),legacy=amount(p.expenses);
 const separate=parking!==null&&other!==null;
 const expenseTotal=separate?parking+other:legacy;
 const landed=purchase===null||expenseTotal===null?null:purchase+expenseTotal;
 if((expenseTotal!==null&&!Number.isFinite(expenseTotal))||(landed!==null&&!Number.isFinite(landed)))throw new ReadError('INVALID_RECORD');
 return {purchase,parking,other,legacyCombined:legacy,expenseTotal,landed,
   expenseSource:separate?'components':legacy!==null?'legacy-combined':'unknown',
   expenseConflict:separate&&legacy!==null&&Math.abs(parking+other-legacy)>0.000001};
}
function payload(row: PayloadRow): PayloadRecord {
 if(typeof row.id!=='string'||!row.id||!Number.isSafeInteger(row.revision)||row.revision<1)
  throw new ReadError('INVALID_RECORD');
 const p=objectJson(row.payload_json);
 if(p.id!==undefined&&p.id!==row.id)throw new ReadError('INVALID_RECORD');
 return {id:row.id,revision:row.revision,payload:p};
}
// The stored D1 identity projections must match their own immutable payload.
// A malformed projection is NOT a valid read-only cloud dashboard record.
const normalizedKey=(v:string):string=>v.replace(/[^a-z0-9]/gi,'').toUpperCase();
function identifierKey(value:unknown,registration:boolean):string|null {
 if(value===null||value===undefined||value==='')return null;
 if(typeof value!=='string')throw new ReadError('INVALID_RECORD');
 const key=normalizedKey(value);
 return registration&&['','UNREG','UNREGISTERED','NA','NONE'].includes(key)?null:key||null;
}
function vehicle(row: VehicleRow): VehicleRecord {
 if(!STATUSES.includes(row.status))throw new ReadError('INVALID_RECORD');
 const record=payload(row),p=record.payload;
 if((p.status!==undefined&&p.status!==row.status)||
    identifierKey(p.reg,true)!==identifierKey(row.registration_key,true)||
    identifierKey(p.chassis,false)!==identifierKey(row.chassis_key,false))
  throw new ReadError('INVALID_RECORD');
 return {...record,status:row.status as StockStatus,financials:vehicleFinancials(p),statusConflict:false};
}
function sale(row: SaleRow): SaleRecord {
 const record=payload(row),p=record.payload;
 if(typeof row.vehicle_id!=='string'||!row.vehicle_id||
    (row.customer_id!==null&&row.customer_id!==undefined&&
     (typeof row.customer_id!=='string'||!row.customer_id))||
    (p.vehicleId!==undefined&&p.vehicleId!==row.vehicle_id)||
    (p.customerId!==undefined&&(p.customerId??null)!==(row.customer_id??null)))
  throw new ReadError('INVALID_RECORD');
 return {...record,vehicleId:row.vehicle_id,customerId:row.customer_id,
   buyer:optionalText(p.buyer),buyerPhone:optionalText(p.buyerPhone),buyerAddress:optionalText(p.buyerAddress),
   saleDate:optionalText(p.saleDate),sale:amount(p.sale),recordedBalance:amount(p.balance)};
}
// Only SELECT is available. Reuses the existing Cloudflare D1 binding/API.
export class CrmReads {
 constructor(private readonly db: Pick<D1Database,'prepare'>) {}
 private async query<T>(sql: string,values: (string|number)[]=[]): Promise<T[]> {
  try {const result=await this.db.prepare(sql).bind(...values).all<T>();if(!result.success)throw Error();return result.results;}
  catch{throw new ReadError('READ_UNAVAILABLE');}
 }
 private async page<T,R>(table: string,key: string,input: PageInput,mapper:(row:T)=>R,allowed: readonly string[]=[]) : Promise<Page<R>> {
  const {limit,offset}=pageInput(input),where:string[]=[],values:(string|number)[]=[];
  if(input.id!==undefined){where.push(`${key} = ?`);values.push(identifier(input.id));}
  for(const [field,column] of [['vehicleId','vehicle_id'],['saleId','sale_id'],['status','status']] as const){
   if(input[field]!==undefined){if(!allowed.includes(field))throw new ReadError('INVALID_QUERY');
    if(field==='status'&&!STATUSES.includes(input[field]!))throw new ReadError('INVALID_QUERY');
    where.push(`${column} = ?`);values.push(identifier(input[field]));}
  }
  const rows=await this.query<T>(`SELECT * FROM ${table}${where.length?' WHERE '+where.join(' AND '):''} ORDER BY ${key} LIMIT ? OFFSET ?`,[...values,limit+1,offset]);
  return {items:rows.slice(0,limit).map(mapper),limit,offset,nextOffset:rows.length>limit?offset+limit:null};
 }
 vehicles(input:PageInput={}){return this.page<VehicleRow,VehicleRecord>('vehicles','id',input,vehicle,['status']);}
 sales(input:PageInput={}){return this.page<SaleRow,SaleRecord>('sales','id',input,sale,['vehicleId']);}
 customers(input:PageInput={}){return this.page<PayloadRow,PayloadRecord>('customers','id',input,payload);}
 leads(input:PageInput={}){return this.page<PayloadRow,PayloadRecord>('leads','id',input,payload);}
 expenses(input:PageInput={}){return this.page<ExpenseRow,{id:string;vehicleId:string;kind:'parking'|'other';amount:number|null;payload:JsonObject}>('expenses','id',input,row=>{
  if(!['parking','other'].includes(row.kind))throw new ReadError('INVALID_RECORD');
  return {id:row.id,vehicleId:row.vehicle_id,kind:row.kind as 'parking'|'other',amount:amount(parseJson(row.amount_json)),payload:objectJson(row.payload_json)};
 },['vehicleId']);}
 async stockCounts(){
  const rows=await this.query<{status:string;count:number}>('SELECT status, COUNT(*) AS count FROM vehicles GROUP BY status');
  const counts={Available:0,Sold:0,Review:0};
  for(const row of rows){if(!STATUSES.includes(row.status))throw new ReadError('INVALID_RECORD');counts[row.status as StockStatus]=row.count;}
  return counts;
 }
 // Never send opaque R2 storage keys or upload-owner identifiers in the
 // general CRM feed. Byte operations use the separate owner-guarded media API.
 features<K extends Feature>(name:K,input:PageInput={}):Promise<Page<Omit<FeatureRows[K],'object_key'|'uploaded_by'> & {decoded:JsonObject}>> {
  if(!Object.hasOwn(FEATURE_KEYS,name))throw new ReadError('INVALID_QUERY');
  const filters=name==='customer_payments'?['saleId']:['cashbook_entries','owner_preferences'].includes(name)?[]:['vehicleId'];
  return this.page<FeatureRows[K],Omit<FeatureRows[K],'object_key'|'uploaded_by'> & {decoded:JsonObject}>(name,FEATURE_KEYS[name],input,row=>{
   const decoded:JsonObject={};
   for(const [key,value]of Object.entries(row)){
    if(['metadata_json','checklist_json','snapshot_json'].includes(key)&&value!==null)decoded[key]=objectJson(value);
    if(typeof value==='number'&&!Number.isFinite(value))throw new ReadError('INVALID_RECORD');
    if(['amount','token_amount','asking_price','offered_price','old_price','new_price','estimated_cost','final_cost','estimated_repairs','expected_resale','estimated_parking','estimated_transfer','estimated_transport','other_estimated_expenses','target_profit','maximum_bid','actual_bid'].includes(key))amount(value);
   }
   // Deliberately project a new object instead of mutating the D1 row.
   if(name==='vehicle_media'){
    const {object_key:_key,uploaded_by:_actor,...safe} = row as FeatureRows['vehicle_media'];
    return {...safe,decoded} as unknown as Omit<FeatureRows[K],'object_key'|'uploaded_by'> & {decoded:JsonObject};
   }
   return {...row,decoded};
  },filters);
 }
}

