import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import ts from 'typescript';
import {TABLES} from '../lib/cloud-core.mjs';
const source=ts.transpileModule(fs.readFileSync('lib/cloud-server.ts','utf8'),{
 compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}
}).outputText;
function status(value,hasRevisionTable=true){
 const queries=[];
 const DB={prepare(sql){queries.push(sql);if(sql.includes('sqlite_master'))return {all:async()=>({
  success:true,results:TABLES.filter(t=>hasRevisionTable||t!=='cloud_metadata').map(name=>({name}))
 })};if(sql.includes('cloud_metadata'))return {first:async()=>value===undefined?null:{value}};
 throw Error('Unexpected query');}};
 const exports={};
 vm.runInNewContext(source,{exports,require(name){
  if(name==='cloudflare:workers')return {env:{DB}};
  if(name==='./owner-auth')return {requireOwner:()=>{throw Error('Owner auth must not run in status utility test');}};
  if(name==='./cloud-core.mjs')return {TABLES};
  throw Error('Unexpected import '+name);
 },Response,Number});
 return exports.readStatus().then(result=>({result,queries}));
}
test('missing or malformed status revision never masquerades as revision zero',async()=>{
 for(const value of [undefined,null,'','00','01','0x10','1e2','-1','9007199254740992']){
  const {result}=await status(value);
  assert.equal(result.revision,null,String(value));
  assert.equal(result.revisionValid,false);
  assert.equal(result.cloudSwitchEnabled,false);
 }
});
test('uninitialised schema never claims revision zero',async()=>{
 const {result,queries}=await status(undefined,false);
 assert.equal(result.revision,null);assert.equal(result.revisionValid,false);
 assert.ok(result.missingTables.includes('cloud_metadata'));
 assert.ok(queries.every(q=>!q.includes('INSERT')&&!q.includes('UPDATE')));
});
test('canonical revision string zero and positive integers remain readable without writes',async()=>{
 for(const value of ['0','12','9007199254740991']){
  const {result,queries}=await status(value);
  assert.equal(result.revision,Number(value));
  assert.equal(result.revisionValid,true);
  assert.equal(result.mode,'browser-local');
  assert.ok(queries.every(q=>q.startsWith('SELECT ')));
 }
});

