export async function POST(request:Request){const auth=await guard(request,true);if('error' in auth)return auth.error;const locked=legacyCloudGate();if(locked)return locked;if(!request.headers.get('content-type')?.includes('application/json'))return json({error:'JSON required.'},415);return failure(async()=>{const body=await request.text();if(new TextEncoder().encode(body).length>5*1024*1024)return json({error:'Maximum backup size is 5 MB.'},413);let data;try{data=JSON.parse(body)}catch{return json({error:'Invalid JSON.'},400)}const db=database();const rows=await db.batch([db.prepare("SELECT value FROM cloud_metadata WHERE key='revision'"),db.prepare('SELECT id,payload_json,registration_key,chassis_key,revision FROM vehicles'),db.prepare('SELECT id,payload_json,revision FROM leads')]);const revision=Number((rows[0].results[0] as {value:string}|undefined)?.value??0);const plan=planImport(data.backup,rows[1].results,rows[2].results,revision,data.expectedRevision);const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(stable(data.backup)));return json({...plan,backupSha256:Array.from(new Uint8Array(hash)).map(n=>n.toString(16).padStart(2,'0')).join('')},plan.valid?200:409);});}

