test('missing storage requires explicit empty-workspace confirmation',()=>{const a=boot(null,{confirm:false});a.run('startEmpty()');assert.equal(a.writes.length,0);a.context.confirm=()=>true;a.run('startEmpty()');assert.equal(a.writes.length,1);assert.deepEqual(JSON.parse(a.value),{bikes:[],leads:[]})});
test('normal vehicle editing preserves unrelated data',()=>{const a=boot(JSON.stringify(data()));a.run("showDetails('original-id')");const save=a.dialogs.at(-1)[2];assert.equal(save({name:'Edited',reg:'TEST123',cost:'100',parking:'10',otherExpenses:'20',sale:'',balance:'',ask:'',km:''}),true);const stored=JSON.parse(a.value);assert.equal(stored.bikes[0].name,'Edited');assert.equal(stored.bikes[0].buyer,'Preserved');assert.deepEqual(stored.appliedChanges,['historical-marker']);assert.deepEqual(stored.custom,{keep:true});});
test('normal sale saves once and preserves ID and markers',()=>{const a=boot(JSON.stringify(data()));a.run("recordSale('original-id')");assert.equal(a.dialogs.at(-1)[2]({sale:'200',balance:'50',buyer:'Test buyer',saleDate:'2026-10-11'}),true);assert.equal(a.writes.length,1);const b=JSON.parse(a.value).bikes[0];assert.equal(b.id,bike.id);assert.equal(b.status,'Sold');assert.equal(b.sale,200);assert.equal(b.balance,50)});
test('missing expense components retain legacy cost on unrelated edit',()=>{const a=boot(JSON.stringify(data({...bike,parking:undefined,otherExpenses:undefined})));assert.equal(a.run('total(state.bikes[0])'),130);a.run("showDetails('original-id')");a.dialogs.at(-1)[2]({name:'Edited',reg:'TEST123',cost:'100',parking:'',otherExpenses:'',sale:'',balance:'',ask:'',km:''});assert.equal(JSON.parse(a.value).bikes[0].expenses,30);assert.equal(a.run('total(state.bikes[0])'),130)});
test('explicit expense preview is read-only, cancellable and preserves metadata',()=>{const a=boot(JSON.stringify(data({...bike,parking:undefined,otherExpenses:undefined})),{confirm:false});a.run('previewLegacyExpenses()');assert.equal(a.writes.length,0);assert.equal(a.dialogs.at(-1)[2](),false);a.context.confirm=()=>true;assert.equal(a.dialogs.at(-1)[2](),true);const stored=JSON.parse(a.value);assert.equal(stored.bikes[0].parking,10);assert.equal(stored.bikes[0].otherExpenses,20);assert.deepEqual(stored.appliedChanges,['historical-marker']);assert.equal(stored.importMeta.id,'old')});
test('ambiguous allocation is flagged without changes',()=>{const a=boot(JSON.stringify(data({...bike,expenses:999,parking:undefined,otherExpenses:undefined})));assert.equal(a.run('legacyExpensePlan().rows[0].proposed'),null);assert.equal(a.writes.length,0)});
for(const raw of [null,'{bad',JSON.stringify(data())])test(`confirmed restore preserves exact supplied fields from ${raw===null?'missing':raw==='{'+'bad'?'corrupt':'valid'} storage`,async()=>{const a=boot(raw);const backup={version:3,...data({...bike,reg:'UP85AS8010',parking:undefined,otherExpenses:undefined})};delete backup.appliedChanges;delete backup.importMeta;a.context.event={target:{files:[{text:async()=>JSON.stringify(backup)}],value:'selected'}};await a.run('restore(event)');assert.deepEqual(JSON.parse(a.value),JSON.parse(JSON.stringify(backup)));assert.equal(a.writes.length,1);const b=boot(a.value);assert.equal(b.writes.length,0);assert.deepEqual(JSON.parse(b.value),JSON.parse(JSON.stringify(backup)))});
test('cancelled or invalid restore does not write',async()=>{const a=boot(JSON.stringify(data()),{confirm:false});for(const raw of [JSON.stringify({version:3,...data()}),'{}']){a.context.event={target:{files:[{text:async()=>raw}],value:'x'}};await a.run('restore(event)')}assert.equal(a.writes.length,0)});
test('backup export never writes or drops metadata',()=>{const a=boot(JSON.stringify(data()));a.context.captureBackup=x=>a.context.backupValue=x;a.run('download=(x)=>captureBackup(x);backup()');const exported=JSON.parse(a.context.backupValue);assert.deepEqual(exported.bikes,data().bikes);assert.deepEqual(exported.custom,{keep:true});assert.equal(a.writes.length,0)});
test('cross-tab changes prevent overwriting newer records',()=>{const a=boot(JSON.stringify(data()));a.value='newer external data';assert.equal(a.run('save(state)'),false);assert.equal(a.value,'newer external data');assert.equal(a.writes.length,0)});
test('storage read and write failures do not replace data',()=>{const a=boot(JSON.stringify(data()),{readError:true});assert.equal(a.writes.length,0);assert.equal(a.run('storageStatus'),'recovery');const b=boot(JSON.stringify(data()),{writeError:true});assert.equal(b.run('save({...state,bikes:[]})'),false);assert.deepEqual(JSON.parse(b.value),data())});

