import test from 'node:test';
import assert from 'node:assert/strict';
import {auditBrowserBackup} from '../lib/browser-backup-audit.mjs';
const vehicle=(overrides={})=>({
 id:'PRIVATE_VEHICLE_ID',name:'Synthetic bike',reg:'TEST_REG',chassis:'TEST_CHASSIS',
 status:'Sold',buyer:'PRIVATE_BUYER',saleDate:'2026-10-10',sale:50000,balance:2000,
 cost:30000,ask:55000,km:500,parking:200,otherExpenses:300,expenses:500,
 ...overrides
});
const original=()=>({version:3,exportedAt:'2026-10-14T10:00:00Z',bikes:[vehicle()],leads:[]});

test('source spreadsheet row and serial references are unique and complete without becoming cloud sale IDs',()=>{
 const create=(id,row,serial)=>vehicle({
  id,reg:'SYNTH_REG_'+id,chassis:'SYNTH_CHASSIS_'+id,
  sourceSalesRow:row,
  sourceSales:[{label:'S NO.',value:serial}],
 });
 const input={...original(),bikes:[
  create('synthetic-a',9,1),
  create('synthetic-b',10,2),
  create('synthetic-c',11,3),
 ]};
 const before=JSON.stringify(input);
 const report=auditBrowserBackup(input),s=report.sourceSaleReferences;
 assert.equal(s.vehicleCount,3);
 assert.equal(s.completeDistinctSourceReferences,3);
 assert.equal(s.sourceReferencesUniqueAndComplete,true);
 assert.equal(s.historicalCloudSaleIdsVerified,false);
 assert.equal(s.cloudImportAllowed,false);
 assert.equal(report.uniqueSaleIdMappingVerified,false);
 assert.equal(report.requiresReconciliation,true);
 assert.equal(JSON.stringify(input),before);
 assert.doesNotMatch(JSON.stringify(report),/SYNTH_REG|SYNTH_CHASSIS|synthetic-a/);
});
test('duplicate spreadsheet rows and serials block unverified historical sale mapping',()=>{
 const create=(id,row,serial)=>vehicle({
  id,reg:'SYNTH_REG_'+id,chassis:'SYNTH_CHASSIS_'+id,
  sourceSalesRow:row,sourceSales:[{label:'S NO.',value:serial}],
 });
 const r=auditBrowserBackup({...original(),bikes:[
  create('synthetic-a',9,'001'),create('synthetic-b',9,1),
 ]}).sourceSaleReferences;
 assert.equal(r.duplicateSalesRow,1);
 assert.equal(r.duplicateSerial,1);
 assert.equal(r.sourceReferencesUniqueAndComplete,false);
 assert.equal(r.completeDistinctSourceReferences,1);
});
test('missing, ambiguous, nonnumeric and malformed source references are reported without guessing',()=>{
 const create=(id,extra)=>vehicle({id,reg:'SYNTH_REG_'+id,
  chassis:'SYNTH_CHASSIS_'+id,...extra});
 const r=auditBrowserBackup({...original(),bikes:[
  create('a',{sourceSalesRow:null,sourceSales:[]}),
  create('b',{sourceSalesRow:'1e3',sourceSales:[{label:'S NO.',value:3},{label:'S NO.',value:4}]}),
  create('c',{sourceSalesRow:5,sourceSales:[{label:'S NO.',value:'not a serial'}]}),
 ]}).sourceSaleReferences;
 assert.equal(r.missingSalesRow,1);
 assert.equal(r.invalidSalesRow,1);
 assert.equal(r.missingSerial,1);
 assert.equal(r.ambiguousSerial,1);
 assert.equal(r.invalidSerial,1);
 assert.equal(r.sourceReferencesUniqueAndComplete,false);
 assert.equal(r.historicalCloudSaleIdsVerified,false);
});

test('clean synthetic snapshot produces aggregate-only review report without leaking identifiers',()=>{
 const data=original(),before=JSON.stringify(data),r=auditBrowserBackup(data);
 assert.equal(r.backupValid,true);
 assert.equal(r.statuses.Sold,1);
 assert.equal(r.syntheticEmptyDatabaseProjection.wouldInsertVehicles,1);
 assert.equal(r.uniqueSaleIdMappingVerified,false);
 assert.equal(r.productionD1Compared,false);
 assert.equal(r.cloudImportExecuted,false);
 assert.equal(r.noWritesPerformed,true);
 assert.equal(JSON.stringify(data),before);
 assert.doesNotMatch(JSON.stringify(r),/PRIVATE_VEHICLE_ID|PRIVATE_BUYER|TEST_REG|TEST_CHASSIS/);
});
test('historical sold records missing buyer or sale date require reconciliation; never invented',()=>{
 const r=auditBrowserBackup({...original(),bikes:[vehicle({buyer:'',saleDate:''})]});
 assert.equal(r.legacySalesWithMissingBuyerName,1);
 assert.equal(r.legacySalesWithMissingSaleDate,1);
 assert.equal(r.requiresReconciliation,true);
 assert.equal(r.uniqueSaleIdMappingVerified,false);
});
test('expense split and outstanding balance discrepancies are reported, not corrected',()=>{
 const src=original();src.bikes[0].expenses=600;src.bikes[0].balance=80000;
 const before=JSON.stringify(src),r=auditBrowserBackup(src);
 assert.equal(r.inconsistentExpenseTotals,1);
 assert.equal(r.balanceExceedsSalePrice,1);
 assert.equal(JSON.stringify(src),before);
});
test('invalid duplicate vehicle IDs fail before import estimation',()=>{
 const r=auditBrowserBackup({...original(),bikes:[vehicle(),vehicle({name:'Duplicate'})]});
 assert.equal(r.backupValid,false);assert.ok(r.validationIssueCount>0);
 assert.equal(r.cloudImportExecuted,false);
 assert.doesNotMatch(JSON.stringify(r),/PRIVATE_VEHICLE_ID/);
});
test('available/review records are counted without being marked as sold',()=>{
 const r=auditBrowserBackup({...original(),bikes:[vehicle({status:'Available'}),vehicle({id:'OTHER',reg:'R2',chassis:'C2',status:'Review'})]});
 assert.equal(r.statuses.Sold,0);assert.equal(r.statuses.Available,1);assert.equal(r.statuses.Review,1);
 assert.equal(r.reviewStatusCount,1);
});

test('unchanged original sales-sheet evidence reconciles formatted rupee values without leaking names',()=>{
 const bike=vehicle({
  sourceInventoryStatus:'SOLD',sourceSalesStatus:'SOLD',
  sourceSales:[
   {column:'B',label:'STATUS',value:'SOLD'},
   {column:'C',label:'COSTUMER NAME',value:'PRIVATE_BUYER'},
   {column:'D',label:'SELLING PRICE',value:'₹50,000.00'},
   {column:'E',label:'REMAINNING AMOUNT',value:'2,000.00'},
  ],
 });
 const input={...original(),bikes:[bike]},before=JSON.stringify(input),result=auditBrowserBackup(input);
 assert.equal(result.backupValid,true);
 assert.deepEqual(result.originalSaleEvidenceAudit,{
  missingSalesEvidence:0,sourceStatusDisagreements:0,salePriceDifferences:0,
  remainingAmountDifferences:0,buyerNameDifferences:0,
  missingRemainingAmountEvidence:0,ambiguousRemainingAmountEvidence:0,
 });
 assert.equal(result.crossSheetStatusConflicts,0);
 assert.equal(result.soldWithPositiveOutstandingBalance,1);
 assert.equal(JSON.stringify(input),before);
 assert.doesNotMatch(JSON.stringify(result),/PRIVATE_BUYER|PRIVATE_VEHICLE_ID|TEST_CHASSIS/);
});
test('discrepant original sale details and inventory/sales status conflict block migration',()=>{
 const bike=vehicle({sourceInventoryStatus:'SOLD',sourceSalesStatus:'UNSOLD',
  sourceSales:[
   {column:'B',label:'STATUS',value:'UNSOLD'},
   {column:'C',label:'COSTUMER NAME',value:'Wrong buyer'},
   {column:'D',label:'SELLING PRICE',value:'51000'},
   {column:'E',label:'REMAINNING AMOUNT',value:'2500'},
  ],
 });
 const result=auditBrowserBackup({...original(),bikes:[bike]});
 assert.equal(result.originalSaleEvidenceAudit.sourceStatusDisagreements,1);
 assert.equal(result.originalSaleEvidenceAudit.salePriceDifferences,1);
 assert.equal(result.originalSaleEvidenceAudit.remainingAmountDifferences,1);
 assert.equal(result.originalSaleEvidenceAudit.buyerNameDifferences,1);
 assert.equal(result.crossSheetStatusConflicts,1);
 assert.equal(result.requiresReconciliation,true);
 assert.doesNotMatch(JSON.stringify(result),/Wrong buyer/);
});

test('original sales workbook header REMAINNING AMOUNT reconciles without 325 false differences',()=>{
 const b=vehicle({sourceSalesStatus:'SOLD',sourceInventoryStatus:'SOLD',
  sourceSales:[{label:'STATUS',value:'SOLD'},
   {label:'SELLING PRICE',value:50000},
   {label:'REMAINNING AMOUNT',value:'₹2,000.00'},
   {label:'COSTUMER NAME',value:'PRIVATE_BUYER'}]});
 const input={...original(),bikes:Array.from({length:325},(_,i)=>({...b,
  id:'SYNTHETIC_ID_'+i,reg:'SYNTHETIC_REG_'+i,chassis:'SYNTHETIC_CHASSIS_'+i}))};
 const originalValue=JSON.stringify(input);
 const audit=auditBrowserBackup(input);
 assert.equal(audit.backupValid,true);
 assert.equal(audit.originalSaleEvidenceAudit.remainingAmountDifferences,0);
 assert.equal(audit.originalSaleEvidenceAudit.missingRemainingAmountEvidence,0);
 assert.equal(audit.originalSaleEvidenceAudit.ambiguousRemainingAmountEvidence,0);
 assert.equal(JSON.stringify(input),originalValue);
 assert.doesNotMatch(JSON.stringify(audit),/SYNTHETIC_ID_|SYNTHETIC_REG_|PRIVATE_BUYER/);
});
test('missing and duplicated balance source headers fail closed rather than pretending reconciliation',()=>{
 const b=vehicle({sourceSales:[{label:'SELLING PRICE',value:50000}]});
 const missing=auditBrowserBackup({...original(),bikes:[b]});
 assert.equal(missing.originalSaleEvidenceAudit.missingRemainingAmountEvidence,1);
 assert.equal(missing.requiresReconciliation,true);
 const duplicate={...b,sourceSales:[
  {label:'REMAINNING AMOUNT',value:2000},
  {label:'REMAINNING AMOUNT',value:0}]};
 const ambiguous=auditBrowserBackup({...original(),bikes:[duplicate]});
 assert.equal(ambiguous.originalSaleEvidenceAudit.ambiguousRemainingAmountEvidence,1);
 assert.equal(ambiguous.requiresReconciliation,true);
 const exact=vehicle({sourceSales:[{label:'REMAINING AMOUNT',value:'2000'}]});
