import test from 'node:test';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {stable} from '../lib/cloud-core.mjs';
import {TABLE_NAMES,validatedCloudSnapshot} from '../scripts/compare-local-browser-cloud.mjs';
import {compareLegacyWithCloud} from '../lib/local-migration-compare.mjs';
const vehicle=(x={})=>({id:'synthetic-private-id',name:'Synthetic Bike',reg:'SYNTH-01',
 chassis:'SYNTH-CHASSIS',status:'Available',parking:100,otherExpenses:200,
 expenses:300,cost:12000,...x});
const backup=(x={})=>({version:3,bikes:[vehicle()],leads:[],...x});
const tables=()=>{
 const entries=Object.fromEntries(TABLE_NAMES.map(x=>[x,[]]));
 entries.cloud_metadata=[{key:'revision',value:'0'}];return entries;
};
const signed=t=>{
 const body={format:'naina-cloud-snapshot-v1',exportedAt:'2026-10-15T00:00:00Z',tables:t};
 return {...body,sha256:createHash('sha256').update(stable(body)).digest('hex')};
};
test('offline empty cloud manifests are validated but never authorize imports',()=>{
 const source=backup(),target=validatedCloudSnapshot(signed(tables()));
 const unchanged=JSON.stringify(source),report=compareLegacyWithCloud(source,target);
 assert.equal(report.vehicleComparison.wouldBeNew,1);
 assert.equal(report.cloudVehicles,0);
 assert.equal(report.migrationAllowed,false);
 assert.equal(report.historicalSaleIdsVerified,0);
 assert.equal(report.noWritesPerformed,true);
 assert.equal(JSON.stringify(source),unchanged);
 assert.doesNotMatch(JSON.stringify(report),/synthetic-private-id|SYNTH-01|SYNTH-CHASSIS/);
});
test('unchanged cloud vehicle with matching ID is not counted as a new insert',()=>{
 const source=backup(),target=tables();
 target.vehicles=[{id:source.bikes[0].id,payload_json:JSON.stringify(source.bikes[0]),
  status:'Available',registration_key:'SYNTH01',chassis_key:'SYNTHCHASSIS'}];
 const result=compareLegacyWithCloud(source,validatedCloudSnapshot(signed(target)));
 assert.equal(result.vehicleComparison.identicalExisting,1);
 assert.equal(result.vehicleComparison.wouldBeNew,0);
 assert.equal(result.cloudVehiclesNotPresentInLegacy,0);
 assert.equal(result.migrationAllowed,false);
});
test('different cloud registration owner is counted as a conflict, not an insert',()=>{
 const source=backup(),target=tables();
 target.vehicles=[{id:'different-private-id',payload_json:JSON.stringify({
   id:'different-private-id',name:'synthetic',status:'Available',reg:'SYNTH-01'
  }),status:'Available',registration_key:'SYNTH01',chassis_key:null}];
 const result=compareLegacyWithCloud(source,validatedCloudSnapshot(signed(target)));
 assert.equal(result.vehicleComparison.registrationOrChassisCollision,1);
 assert.equal(result.vehicleComparison.wouldBeNew,0);
 assert.equal(result.cloudVehiclesNotPresentInLegacy,1);
 assert.equal(result.migrationAllowed,false);
});
test('same ID but different cloud payload must never become automatic update',()=>{
 const source=backup(),target=tables();
 target.vehicles=[{id:source.bikes[0].id,payload_json:JSON.stringify({
   id:source.bikes[0].id,name:'modified',status:'Available',
   reg:'SYNTH-01',chassis:'SYNTH-CHASSIS'
  }),status:'Available',registration_key:'SYNTH01',chassis_key:'SYNTHCHASSIS'}];
 const result=compareLegacyWithCloud(source,validatedCloudSnapshot(signed(target)));
 assert.equal(result.vehicleComparison.conflictingExistingId,1);
 assert.equal(result.vehicleComparison.identicalExisting,0);
 assert.equal(result.migrationAllowed,false);
});
test('sold vehicles require explicit sale identity mapping even on a new empty DB',()=>{
 const sold=vehicle({status:'Sold',sale:20000,balance:4000,buyer:'Synthetic Buyer',
  sourceInventoryStatus:'SOLD',sourceSalesStatus:'SOLD',
  sourceSales:[{label:'STATUS',value:'SOLD'},
   {label:'SELLING PRICE',value:20000},
   {label:'REMAINNING AMOUNT',value:4000},
   {label:'COSTUMER NAME',value:'Synthetic Buyer'}]});
 const report=compareLegacyWithCloud(backup({bikes:[sold]}),validatedCloudSnapshot(signed(tables())));
 assert.equal(report.historicalSales.soldVehicles,1);
 assert.equal(report.historicalSales.missingCloudSaleIds,1);
 assert.equal(report.preservedSourceEvidence.originalSourceBalanceDifferences,0);
 assert.equal(report.paymentLedgerReconciled,false);
 assert.doesNotMatch(JSON.stringify(report),/Synthetic Buyer/);
});
test('missing tables, bad SHA, malformed revision and orphan links reject target snapshot',()=>{
 const good=signed(tables());
 assert.throws(()=>validatedCloudSnapshot({...good,sha256:'f'.repeat(64)}),/checksum mismatch/);
 const missing=tables();delete missing.customers;
 assert.throws(()=>validatedCloudSnapshot(signed(missing)),/format/);
 const invalid=tables();invalid.cloud_metadata=[{key:'revision',value:'00'}];
 assert.throws(()=>validatedCloudSnapshot(signed(invalid)),/relationship issues/);
 const orphan=tables();orphan.customer_payments=[{id:'p-1',sale_id:'not-sold',amount:200}];
 assert.throws(()=>validatedCloudSnapshot(signed(orphan)),/relationship issues/);
});
test('invalid browser snapshots or unexpected cloud arrays never produce a plan',()=>{
 const target=validatedCloudSnapshot(signed(tables()));
 assert.throws(()=>compareLegacyWithCloud(backup({version:900}),target),/fails source validation/);
 assert.throws(()=>compareLegacyWithCloud(backup(),{vehicles:[]}),/complete/);
});

test('source-to-target comparison rejects a signed snapshot whose vehicle identity projections disagree',()=>{
 const data=backup(),target=tables();
 target.vehicles=[{id:data.bikes[0].id,payload_json:JSON.stringify(data.bikes[0]),
  status:'Available',registration_key:'WRONG',chassis_key:'SYNTHCHASSIS'}];
 assert.throws(()=>validatedCloudSnapshot(signed(target)),/relationship issues/);
});

