import test from 'node:test';
import assert from 'node:assert/strict';
import { auditSnapshotLinks } from '../lib/snapshot-link-audit.mjs';
const hash='a'.repeat(64);
const clone=value=>JSON.parse(JSON.stringify(value));
function fixture(){
 return {
  vehicles:[{id:'vehicle-one',status:'Sold',payload_json:'{"id":"vehicle-one","status":"Sold"}'}],
  sales:[{id:'sale-one',vehicle_id:'vehicle-one',customer_id:'customer-one'}],
  customers:[{id:'customer-one'}],
  leads:[{id:'lead-one'}],
  expenses:[{id:'expense-one',vehicle_id:'vehicle-one',kind:'parking',amount_json:'500'}],
  customer_payments:[{id:'payment-one',sale_id:'sale-one',amount:500}],
  vehicle_media:[{id:'media-one',vehicle_id:'vehicle-one',object_key:'private/synthetic-only',
   sha256:hash,bytes:32,version_number:1,is_cover:1,category:'photo',mime_type:'image/jpeg',
   archived_at:null,notes:null}],
  vehicle_locations:[{vehicle_id:'vehicle-one',location_type:'Godown'}],
  owner_preferences:[{setting_key:'display-theme',setting_value:'light'}],
  cloud_metadata:[{key:'revision',value:'10'}]
 };
}
const codes=audit=>audit.issues.map(issue=>issue.code);
test('healthy recovered rows pass without reading or changing file bytes',()=>{
 const rows=fixture(),before=JSON.stringify(rows),audit=auditSnapshotLinks(rows);
 assert.equal(audit.consistent,true);assert.equal(audit.issueCount,0);
 assert.equal(audit.readOnly,true);assert.equal(audit.mediaBytesVerified,false);
 assert.equal(audit.checkedTables,10);assert.equal(JSON.stringify(rows),before);
 assert.doesNotMatch(JSON.stringify(audit),/synthetic-only|setting_value|customer-one/);
});
test('orphaned sales, payments and media linkages are reported',()=>{
 const rows=fixture();rows.sales[0].vehicle_id='missing-vehicle';
 rows.customer_payments[0].sale_id='missing-sale';
 rows.vehicle_media[0].vehicle_id='missing-vehicle';
 const audit=auditSnapshotLinks(rows);
 assert.equal(audit.consistent,false);assert.equal(audit.issues.filter(x=>x.code.startsWith('ORPHAN_LINK')).length,3);
});
test('sold vehicles require unique linked sales, available vehicles cannot have a sale',()=>{
 const rows=fixture();rows.sales=[];
 assert.ok(codes(auditSnapshotLinks(rows)).includes('SOLD_WITHOUT_UNIQUE_SALE'));
 const conflict=fixture();conflict.vehicles[0].status='Available';conflict.vehicles[0].payload_json='{"id":"vehicle-one","status":"Available"}';
 assert.ok(codes(auditSnapshotLinks(conflict)).includes('AVAILABLE_WITH_SALE'));
 const dup=fixture();dup.sales.push({...dup.sales[0],id:'sale-two'});
 assert.ok(codes(auditSnapshotLinks(dup)).includes('DUPLICATE_VEHICLE_SALE'));
});
test('duplicate primary and compound expense IDs fail closed',()=>{
 const rows=fixture();rows.customers.push({...rows.customers[0]});
 rows.expenses.push({...rows.expenses[0],id:'expense-two'});
 const audit=auditSnapshotLinks(rows);
 assert.ok(codes(audit).includes('DUPLICATE_PRIMARY_ID'));
 assert.ok(codes(audit).includes('DUPLICATE_EXPENSE_KIND'));
});
test('vehicle payload conflict and malformed amounts are reported without changing rows',()=>{
 const rows=fixture();rows.vehicles[0].payload_json='{"id":"changed","status":"Available"}';
 rows.customer_payments[0].amount=-1;rows.expenses[0].amount_json='-500';
 const audit=auditSnapshotLinks(rows);
 for(const code of ['VEHICLE_PAYLOAD_ID_MISMATCH','VEHICLE_PAYLOAD_STATUS_MISMATCH','INVALID_PAYMENT_AMOUNT','INVALID_EXPENSE_AMOUNT'])
  assert.ok(codes(audit).includes(code),code);
});
test('missing media keys, hashes and byte lengths are not treated as a verified backup',()=>{
 const rows=fixture();rows.vehicle_media[0].sha256='invalid';
 assert.ok(codes(auditSnapshotLinks(rows)).includes('INVALID_MEDIA_METADATA'));
});
test('record caps, issue limit and invalid input fail closed',()=>{
 const rows=fixture();rows.customer_payments=Array.from({length:110},(_,i)=>({id:'pay-'+i,sale_id:'invalid',amount:-1}));
 const audit=auditSnapshotLinks(rows,{maxIssues:10});
 assert.equal(audit.issues.length,10);assert.equal(audit.truncated,true);assert.ok(audit.issueCount>=110);
 assert.throws(()=>auditSnapshotLinks({vehicles:Array(5001).fill({})}),/bounded/);
 assert.throws(()=>auditSnapshotLinks(rows,{maxIssues:2000}),/Invalid/);
});

test('private-media object keys and active vehicle covers cannot be duplicated in a recovery snapshot',()=>{
 const rows=fixture();rows.vehicle_media.push({...rows.vehicle_media[0],id:'media-two'});
 const report=auditSnapshotLinks(rows);
 assert.ok(codes(report).includes('DUPLICATE_MEDIA_OBJECT_KEY'));
 assert.ok(codes(report).includes('MULTIPLE_ACTIVE_COVER_PHOTOS'));
 assert.equal(report.mediaBytesVerified,false);
 assert.doesNotMatch(JSON.stringify(report),/private\/synthetic-only/);
});
test('archived cover is not an active-cover conflict, but bad media state blocks recovery',()=>{
 const rows=fixture();rows.vehicle_media[0].archived_at='2026-10-14T00:00:00Z';
 rows.vehicle_media.push({...rows.vehicle_media[0],id:'media-two',
  object_key:'private/second-synthetic',archived_at:null});
 assert.equal(auditSnapshotLinks(rows).consistent,true);
 rows.vehicle_media[1].is_cover=2;rows.vehicle_media[1].version_number=0;
 rows.vehicle_media[1].notes='Internal: upload incomplete; reconciliation required';
 const report=auditSnapshotLinks(rows);
 for(const expected of ['INVALID_COVER_FLAG','INVALID_MEDIA_METADATA','PENDING_MEDIA_UPLOAD'])
  assert.ok(codes(report).includes(expected),expected);
});

test('recovery refuses missing, malformed or unsafe global D1 revisions',()=>{
 const missing=fixture();missing.cloud_metadata=[];
 assert.ok(codes(auditSnapshotLinks(missing)).includes('MISSING_GLOBAL_REVISION'));
 for(const value of ['',null,'00','0x10','1e3','-1','9007199254740992']){
  const rows=fixture();rows.cloud_metadata[0].value=value;
  assert.ok(codes(auditSnapshotLinks(rows)).includes('INVALID_GLOBAL_REVISION'),String(value));
 }
 const valid=fixture();valid.cloud_metadata[0].value='0';
 assert.equal(auditSnapshotLinks(valid).consistent,true);
});

test('recovery validates sale and vehicle mirrored prices, balances, and expense splits',()=>{
 const rows=fixture();
 rows.vehicles[0].payload_json=JSON.stringify({id:'vehicle-one',status:'Sold',
  sale:1000,balance:500,parking:500,otherExpenses:0,expenses:500});
 rows.sales[0].payload_json=JSON.stringify({id:'sale-one',vehicleId:'vehicle-one',
  sale:1000,balance:500});
 assert.equal(auditSnapshotLinks(rows).consistent,true);
 const mismatch=clone(rows);mismatch.sales[0].payload_json=JSON.stringify({id:'sale-one',
  vehicleId:'vehicle-one',sale:1200,balance:700});
 const result=auditSnapshotLinks(mismatch);
 assert.ok(codes(result).includes('SALE_VEHICLE_SALE_MISMATCH'));
 assert.ok(codes(result).includes('SALE_VEHICLE_BALANCE_MISMATCH'));
 assert.equal(result.mediaBytesVerified,false);
 const expense=clone(rows);expense.expenses[0].amount_json='510';
 assert.ok(codes(auditSnapshotLinks(expense)).includes('EXPENSE_VEHICLE_AMOUNT_MISMATCH'));
 const subtotal=clone(rows);subtotal.vehicles[0].payload_json=JSON.stringify({id:'vehicle-one',
  status:'Sold',parking:500,otherExpenses:100,expenses:500});
 assert.ok(codes(auditSnapshotLinks(subtotal)).includes('VEHICLE_EXPENSE_TOTAL_MISMATCH'));
});
test('recovery rejects overpaid ledgers without requiring all historical receipts to exist',()=>{
 const rows=fixture();rows.sales[0].payload_json=JSON.stringify({id:'sale-one',
  vehicleId:'vehicle-one',sale:1000,balance:500});
 assert.equal(auditSnapshotLinks(rows).consistent,true);
 rows.customer_payments[0].amount=501;
 assert.ok(codes(auditSnapshotLinks(rows)).includes('PAYMENTS_AND_BALANCE_EXCEED_SALE'));
});
test('corrupted sale payload identifiers and values block recovery',()=>{
 const rows=fixture();rows.sales[0].payload_json=JSON.stringify({id:'wrong',vehicleId:'wrong',
  sale:400,balance:500});
 const codesFound=codes(auditSnapshotLinks(rows));
 for(const expected of ['SALE_PAYLOAD_ID_MISMATCH','SALE_PAYLOAD_VEHICLE_MISMATCH',
  'SALE_BALANCE_EXCEEDS_PRICE'])assert.ok(codesFound.includes(expected),expected);
 rows.sales[0].payload_json='not-json';
 assert.ok(codes(auditSnapshotLinks(rows)).includes('INVALID_SALE_PAYLOAD'));
});

test('checksum-valid D1 registration and chassis projections must agree with payload',()=>{
 const rows=fixture();
 rows.vehicles[0].payload_json=JSON.stringify({id:'vehicle-one',status:'Sold',
   reg:'SYNTH-REG',chassis:'SYNTH-CHASSIS'});
 rows.vehicles[0].registration_key='SYNTHREG';
 rows.vehicles[0].chassis_key='SYNTHCHASSIS';
 assert.equal(auditSnapshotLinks(rows).consistent,true);
 rows.vehicles[0].registration_key='DIFFERENT';
 rows.vehicles[0].chassis_key='DIFFERENT';
 const result=auditSnapshotLinks(rows);
 assert.ok(codes(result).includes('VEHICLE_REGISTRATION_PROJECTION_MISMATCH'));
 assert.ok(codes(result).includes('VEHICLE_CHASSIS_PROJECTION_MISMATCH'));
 assert.equal(result.readOnly,true);
 assert.doesNotMatch(JSON.stringify(result),/SYNTH-REG|SYNTH-CHASSIS/);
});
test('placeholder registrations normalize without incorrectly inventing a registration',()=>{
 const rows=fixture();
 rows.vehicles[0].payload_json=JSON.stringify({id:'vehicle-one',status:'Sold',reg:'UNREG'});
 rows.vehicles[0].registration_key=null;
 assert.equal(auditSnapshotLinks(rows).consistent,true);
});

test('customer identity in a recovered sale cannot disagree with D1 customer relationship',()=>{
 const data=fixture();
 data.customers.push({id:'customer-two'});
 data.sales[0].payload_json=JSON.stringify({id:'sale-one',vehicleId:'vehicle-one',
  customerId:'customer-two',buyer:'Synthetic buyer',sale:1000,balance:200});
 const before=JSON.stringify(data),report=auditSnapshotLinks(data);
 assert.ok(codes(report).includes('SALE_PAYLOAD_CUSTOMER_MISMATCH'));
 assert.equal(report.consistent,false);
 assert.equal(JSON.stringify(data),before);
 assert.doesNotMatch(JSON.stringify(report),/customer-two|Synthetic buyer/);
 data.sales[0].payload_json=JSON.stringify({id:'sale-one',vehicleId:'vehicle-one',
  customerId:'customer-one'});
