import { getChatGPTUser } from '../app/chatgpt-auth';
import { authorize, sameOrigin } from './cloud-core.mjs';

// Server route boundary for cloud metadata and future private media operations.
// Identity comes ONLY from the Sites dispatch-backed helper. Never read identity
// from request headers/body/query/cookies here or accept a browser owner object.
// This relies on the hosted Sites ingress, not a directly exposed Worker origin.
function denied(status: number, message: string) {
  return {error: Response.json({error: message}, {status, headers: {
    'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff',
  }})};
}
export async function requireOwner(request: Request, requireSameOrigin = false) {
  let user;
  try { user = await getChatGPTUser(); }
  catch { return denied(401, 'Verified Site identity is unavailable. Sign in again.'); }
  const code = authorize(user);
  if (code !== 200 || !user) return denied(code, code === 401
    ? 'Sign in with the Site owner account.' : 'Owner access required.');
  // The optional flag can strengthen checks, never disable mutation protection.
  const mutating = !['GET', 'HEAD', 'OPTIONS'].includes(request.method.toUpperCase());
  if ((mutating || requireSameOrigin) &&
      (!sameOrigin(request.headers.get('origin'), request.url) ||
       request.headers.get('sec-fetch-site') === 'cross-site')) {
    return denied(403, 'Same-origin request required.');
  }
  return {user: Object.freeze({...user})};
}

