/** Pure, bounded recovery-integrity audit for a CHECKSUM-VERIFIED D1 snapshot.
 * Caller MUST verify signature/checksum + owner authorization first. Read only. */
const RELATIONS = Object.freeze({
 sales:[['vehicle_id','vehicles'],['customer_id','customers']],
 expenses:[['vehicle_id','vehicles']],
 vehicle_media:[['vehicle_id','vehicles']],
 document_requirements:[['vehicle_id','vehicles']],
 vehicle_age_baselines:[['vehicle_id','vehicles']],
 vehicle_locations:[['vehicle_id','vehicles']],
 vehicle_timeline:[['vehicle_id','vehicles']],
 vehicle_inspections:[['vehicle_id','vehicles']],
 customer_payments:[['sale_id','sales']],
 auction_plans:[['vehicle_id','vehicles']],
 reservations:[['vehicle_id','vehicles']],
 enquiry_notes:[['vehicle_id','vehicles'],['lead_id','leads']],
 price_history:[['vehicle_id','vehicles']],
 repair_jobs:[['vehicle_id','vehicles']],
 rto_cases:[['vehicle_id','vehicles']],
 reminders:[['vehicle_id','vehicles']],
 document_expiries:[['vehicle_id','vehicles']],
 generated_documents:[['vehicle_id','vehicles']],
});
const PRIMARY_KEY = Object.freeze({cloud_metadata:'key',vehicle_age_baselines:'vehicle_id',vehicle_locations:'vehicle_id',owner_preferences:'setting_key'});
const strictId=value=>typeof value==='string'&&value.length>0&&value.length<=1024;
// Keep projection normalization consistent with historical import matching.
const normalizedKey=value=>String(value??'').replace(/[^a-z0-9]/gi,'').toUpperCase();
const normalizedReg=value=>{
 const result=normalizedKey(value);
 return ['','UNREG','UNREGISTERED','NA','NONE'].includes(result)?null:result;
};
const normalizedChassis=value=>normalizedKey(value)||null;
const asCents=value=>{
 if(typeof value==='string'&&/^(?:0|[1-9]\d{0,11})(?:\.\d{1,2})?$/.test(value))value=Number(value);
 return typeof value==='number'&&Number.isFinite(value)&&value>=0&&Number.isSafeInteger(Math.round(value*100))&&Math.abs(value*100-Math.round(value*100))<0.000001?Math.round(value*100):null;
};
/** Result contains only table names, safe record IDs and issue codes, not sensitive row payloads. */
export function auditSnapshotLinks(tables,{maxIssues=100}={}){
 if(!tables||typeof tables!=='object'||Array.isArray(tables)||!Number.isInteger(maxIssues)||maxIssues<1||maxIssues>1000)
  throw Error('Invalid snapshot audit input.');
 const entries=Object.entries(tables);
 if(entries.length===0||entries.length>100||entries.some(([,rows])=>!Array.isArray(rows)||rows.length>5000))
  throw Error('Snapshot must have bounded table arrays.');
 const index=new Map(),issues=[];let errorCount=0,checkedRows=0;
 function issue(table,recordId,code){errorCount++;if(issues.length<maxIssues)issues.push({table,recordId:String(recordId??'').slice(0,256),code});}
 for(const [table,rows] of entries){
  const key=PRIMARY_KEY[table]||'id',map=new Map();
  for(const row of rows){
   checkedRows++;
   if(!row||typeof row!=='object'||Array.isArray(row)){issue(table,'','INVALID_ROW');continue;}
   const value=row[key];
   if(!strictId(value)){issue(table,'','INVALID_PRIMARY_ID');continue;}
   if(map.has(value))issue(table,value,'DUPLICATE_PRIMARY_ID');
   else map.set(value,row);
  }
  index.set(table,map);
 }
 for(const [table,links] of Object.entries(RELATIONS)){
  if(!Object.hasOwn(tables,table))continue;
  for(const [id,row] of index.get(table)){
   for(const [column,target] of links){
    const value=row[column];
    if(value===null||value===undefined){
     if((table==='sales'&&column==='vehicle_id')||(table==='expenses'&&column==='vehicle_id')||
       (table==='customer_payments'&&column==='sale_id')||(table==='vehicle_media'&&column==='vehicle_id'))issue(table,id,'MISSING_REQUIRED_LINK:'+column);
     continue;
    }
    if(!strictId(value)||!index.has(target)||!index.get(target).has(value))issue(table,id,'ORPHAN_LINK:'+column);
   }
  }
 }
 const revisions=index.get('cloud_metadata');
 // A checksum-valid snapshot without a trustworthy global revision cannot be
 // safely resumed after a restore, even when all SQLite foreign keys are valid.
 if(!revisions||!revisions.has('revision'))issue('cloud_metadata','revision','MISSING_GLOBAL_REVISION');
 else {
  const raw=revisions.get('revision').value;
  if(typeof raw!=='string'||!/^(?:0|[1-9][0-9]*)$/.test(raw)||
     !Number.isSafeInteger(Number(raw)))
   issue('cloud_metadata','revision','INVALID_GLOBAL_REVISION');
 }
 const vehicles=index.get('vehicles')||new Map(),sales=index.get('sales')||new Map();
 const vehiclePayloads=new Map(),salePayloads=new Map();
 for(const [id,row] of sales){
  // SQL requires sale payload_json in real D1; synthetic sparse fixture rows
  // can omit it to test unrelated link checks.
  if(row.payload_json===undefined)continue;
  let p;
  try {p=JSON.parse(row.payload_json);}catch{issue('sales',id,'INVALID_SALE_PAYLOAD');continue;}
  if(!p||typeof p!=='object'||Array.isArray(p)){
   issue('sales',id,'INVALID_SALE_PAYLOAD');continue;
  }
  salePayloads.set(id,p);
  if(p.id!==undefined&&p.id!==id)issue('sales',id,'SALE_PAYLOAD_ID_MISMATCH');
  if(p.vehicleId!==undefined&&p.vehicleId!==row.vehicle_id)
   issue('sales',id,'SALE_PAYLOAD_VEHICLE_MISMATCH');
  if(p.customerId!==undefined&&(p.customerId??null)!==(row.customer_id??null))
   issue('sales',id,'SALE_PAYLOAD_CUSTOMER_MISMATCH');
  if(p.sale!==undefined&&asCents(p.sale)===null)issue('sales',id,'INVALID_SALE_AMOUNT');
  if(p.balance!==undefined&&asCents(p.balance)===null)issue('sales',id,'INVALID_SALE_BALANCE');
  if(p.sale!==undefined&&p.balance!==undefined){
   const price=asCents(p.sale),owed=asCents(p.balance);
   if(price!==null&&owed!==null&&owed>price)issue('sales',id,'SALE_BALANCE_EXCEEDS_PRICE');
  }
 }
 const salesByVehicle=new Map();
 for(const [id,row] of sales){
  if(!strictId(row.vehicle_id))continue;
  const list=salesByVehicle.get(row.vehicle_id)||[];list.push(id);salesByVehicle.set(row.vehicle_id,list);
  if(list.length>1)issue('sales',id,'DUPLICATE_VEHICLE_SALE');
 }
 const registrations=new Map(),chassisNumbers=new Map();
 for(const [id,row] of vehicles){
  const list=salesByVehicle.get(id)||[];
  if(!['Sold','Available','Review'].includes(row.status))
   issue('vehicles',id,'INVALID_VEHICLE_STATUS');
  if(row.status==='Sold'&&list.length!==1)issue('vehicles',id,'SOLD_WITHOUT_UNIQUE_SALE');
  else if(row.status==='Available'&&list.length)issue('vehicles',id,'AVAILABLE_WITH_SALE');
  const reg=normalizedReg(row.registration_key);
  const chassis=normalizedChassis(row.chassis_key);
  if(row.registration_key!==null&&row.registration_key!==undefined&&
     (typeof row.registration_key!=='string'||row.registration_key!==reg))
   issue('vehicles',id,'NONCANONICAL_REGISTRATION_KEY');
  if(row.chassis_key!==null&&row.chassis_key!==undefined&&
     (typeof row.chassis_key!=='string'||row.chassis_key!==chassis))
   issue('vehicles',id,'NONCANONICAL_CHASSIS_KEY');
  if(reg){
   if(registrations.has(reg)&&registrations.get(reg)!==id)
    issue('vehicles',id,'DUPLICATE_NORMALIZED_REGISTRATION');
   else registrations.set(reg,id);
  }
  if(chassis){
   if(chassisNumbers.has(chassis)&&chassisNumbers.get(chassis)!==id)
    issue('vehicles',id,'DUPLICATE_NORMALIZED_CHASSIS');
   else chassisNumbers.set(chassis,id);
  }
  if(typeof row.payload_json==='string'){
   let payload;
   try {payload=JSON.parse(row.payload_json);}catch{issue('vehicles',id,'INVALID_VEHICLE_PAYLOAD');continue;}
   if(!payload||typeof payload!=='object'||Array.isArray(payload)){issue('vehicles',id,'INVALID_VEHICLE_PAYLOAD');continue;}
   if(payload.id!==undefined&&payload.id!==id)issue('vehicles',id,'VEHICLE_PAYLOAD_ID_MISMATCH');
   if(payload.status!==undefined&&payload.status!==row.status)issue('vehicles',id,'VEHICLE_PAYLOAD_STATUS_MISMATCH');
   if(normalizedReg(payload.reg)!==normalizedReg(row.registration_key))
    issue('vehicles',id,'VEHICLE_REGISTRATION_PROJECTION_MISMATCH');
   if(normalizedChassis(payload.chassis)!==normalizedChassis(row.chassis_key))
    issue('vehicles',id,'VEHICLE_CHASSIS_PROJECTION_MISMATCH');
   vehiclePayloads.set(id,payload);
   // Compare mirrored values only when they really exist in both records:
   // never invent missing historical numbers or buyer data.
   if(list.length===1&&salePayloads.has(list[0])){
    const sale=salePayloads.get(list[0]);
    for(const field of ['sale','balance']){
     if(payload[field]===undefined||sale[field]===undefined)continue;
     const original=asCents(payload[field]),linked=asCents(sale[field]);
     if(original===null||linked===null)issue('vehicles',id,'INVALID_MIRRORED_'+field.toUpperCase());
     else if(original!==linked)issue('vehicles',id,'SALE_VEHICLE_'+field.toUpperCase()+'_MISMATCH');
    }
   }
   const fields=['parking','otherExpenses','expenses'];
   if(fields.every(k=>payload[k]!==undefined)){
    const amounts=fields.map(k=>asCents(payload[k]));
    if(amounts.some(n=>n===null)||amounts[0]+amounts[1]!==amounts[2])
     issue('vehicles',id,'VEHICLE_EXPENSE_TOTAL_MISMATCH');
   }
  }
 }
 const expenseKind=new Set();
 for(const [id,row] of index.get('expenses')||new Map()){
  if(!['parking','other'].includes(row.kind))issue('expenses',id,'INVALID_EXPENSE_KIND');
  const pair=JSON.stringify([row.vehicle_id,row.kind]);
  if(expenseKind.has(pair))issue('expenses',id,'DUPLICATE_EXPENSE_KIND');
  expenseKind.add(pair);
  let cents=null;
  if(typeof row.amount_json==='string'){
   try {cents=asCents(JSON.parse(row.amount_json));}catch{}
  }
  if(cents===null)issue('expenses',id,'INVALID_EXPENSE_AMOUNT');
  else {
   const original=vehiclePayloads.get(row.vehicle_id);
   const field=row.kind==='parking'?'parking':'otherExpenses';
   if(original&&original[field]!==undefined&&asCents(original[field])!==cents)
    issue('expenses',id,'EXPENSE_VEHICLE_AMOUNT_MISMATCH');
  }
 }
 const paidBySale=new Map();
 for(const [id,row] of index.get('customer_payments')||new Map()){
  const cents=asCents(row.amount);
  if(cents===null||cents===0){issue('customer_payments',id,'INVALID_PAYMENT_AMOUNT');continue;}
  if(!sales.has(row.sale_id))continue;
  const total=(paidBySale.get(row.sale_id)||0)+cents;
  if(!Number.isSafeInteger(total))issue('customer_payments',id,'UNSAFE_PAYMENT_TOTAL');
  else paidBySale.set(row.sale_id,total);
 }
 for(const [id,paid] of paidBySale){
  const sale=salePayloads.get(id);
  // Receipts may be historically incomplete: only overstatements are fatal.
  if(!sale||sale.sale===undefined||sale.balance===undefined)continue;
  const price=asCents(sale.sale),owed=asCents(sale.balance);
  if(price!==null&&owed!==null&&paid+owed>price)
   issue('sales',id,'PAYMENTS_AND_BALANCE_EXCEED_SALE');
 }
 const objectKeys=new Set(),activeCovers=new Set();
 for(const [id,row] of index.get('vehicle_media')||new Map()){
  if(!strictId(row.object_key)||typeof row.sha256!=='string'||!/^[a-f0-9]{64}$/.test(row.sha256)||
     !Number.isSafeInteger(row.bytes)||row.bytes<1||
     !Number.isSafeInteger(row.version_number)||row.version_number<1||
     (row.archived_at!==null&&typeof row.archived_at!=='string'))
   issue('vehicle_media',id,'INVALID_MEDIA_METADATA');
  if(strictId(row.object_key)){
   if(objectKeys.has(row.object_key))issue('vehicle_media',id,'DUPLICATE_MEDIA_OBJECT_KEY');
   objectKeys.add(row.object_key);
  }
  if(row.is_cover!==0&&row.is_cover!==1)issue('vehicle_media',id,'INVALID_COVER_FLAG');
  if(row.is_cover===1&&row.archived_at===null){
   if(activeCovers.has(row.vehicle_id))issue('vehicle_media',id,'MULTIPLE_ACTIVE_COVER_PHOTOS');
   activeCovers.add(row.vehicle_id);
   if(row.category!=='photo'||!['image/jpeg','image/png','image/webp','image/heic'].includes(row.mime_type))
    issue('vehicle_media',id,'INVALID_ACTIVE_COVER_TYPE');
  }
  if(row.notes==='Internal: upload incomplete; reconciliation required')
   issue('vehicle_media',id,'PENDING_MEDIA_UPLOAD');
 }
 return {format:'naina-snapshot-link-audit-v1',checkedTables:entries.length,checkedRows,
  issueCount:errorCount,truncated:errorCount>issues.length,issues,consistent:errorCount===0,
  readOnly:true,mediaBytesVerified:false,
  note:'Requires a checksum-verified snapshot; no cloud changes or media-byte verification were performed.'};
}

