import { guard, json, database } from '../../../lib/cloud-server';
import { CrmReads, FEATURE_KEYS, ReadError, type Feature, type StockStatus } from '../../../lib/crm-reads';
import { CRM_READ_FEATURES_ENABLED } from '../../../lib/crm-read-flags';

export async function GET(request: Request) {
 const auth=await guard(request);if('error' in auth)return auth.error;
 if(!CRM_READ_FEATURES_ENABLED)return json({error:'Private cloud reads are not enabled.'},423);
 try{
  const p=new URL(request.url).searchParams;
  const allowed=['resource','id','vehicleId','saleId','status','limit','offset'];
  for(const key of p.keys())if(!allowed.includes(key)||p.getAll(key).length!==1)throw new ReadError('INVALID_QUERY');
  const resource=p.get('resource');
  const input={id:p.get('id')??undefined,vehicleId:p.get('vehicleId')??undefined,saleId:p.get('saleId')??undefined,
   status:(p.get('status')??undefined) as StockStatus|undefined,
   limit:p.has('limit')?Number(p.get('limit')):undefined,offset:p.has('offset')?Number(p.get('offset')):undefined};
  const reads=new CrmReads(database());
  let result;
  switch(resource){
   case 'vehicles':result=await reads.vehicles(input);break;
   case 'sales':result=await reads.sales(input);break;
   case 'customers':result=await reads.customers(input);break;
   case 'leads':result=await reads.leads(input);break;
   case 'expenses':result=await reads.expenses(input);break;
   case 'stock-counts':if(p.size!==1)throw new ReadError('INVALID_QUERY');result=await reads.stockCounts();break;
   default:if(!resource||!Object.hasOwn(FEATURE_KEYS,resource))throw new ReadError('INVALID_QUERY');result=await reads.features(resource as Feature,input);
  }
  return json({mode:'browser-local',cloudSwitchEnabled:false,result});
 }catch(e){
  const code=e instanceof ReadError?e.code:'READ_UNAVAILABLE';
  return json({error:code==='INVALID_QUERY'?'Invalid read request.':code==='INVALID_RECORD'?'Stored data requires review. No records were changed.':'Cloud read unavailable. No records were changed.',code},code==='INVALID_QUERY'?400:code==='INVALID_RECORD'?409:503);
 }
}

