#!/usr/bin/env node
// LOCAL READ-ONLY. Prints aggregate summary only; no customer rows, writes or network access.
import {readFileSync,statSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {auditBrowserBackup} from '../lib/browser-backup-audit.mjs';
const path=process.argv[2];
if(!path||process.argv.length!==3){
 console.error('Usage: node scripts/audit-local-backup.mjs /path/to/local-browser-backup.json');
 process.exitCode=64;
}else{
 try{
  const info=statSync(path);
  if(!info.isFile()||info.size>25*1024*1024||info.size<2)throw Error('Invalid backup size');
  const raw=readFileSync(path);const value=JSON.parse(raw.toString('utf8'));
  const report=auditBrowserBackup(value);
  // Hash identifies the exact source file without exposing its contents.
  console.log(JSON.stringify({sha256:createHash('sha256').update(raw).digest('hex'),...report},null,2));
  if(!report.backupValid)process.exitCode=2;
 }catch{
  console.error('Unable to audit local backup safely; no data was changed.');
  process.exitCode=2;
 }
}

