import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import {webcrypto} from 'node:crypto';
function setup(){
 const nodes=new Map(),calls=[];
 const element=tag=>({tag,value:'',textContent:'',disabled:false,open:false,appendChild(){},append(){},addEventListener(){},replaceChildren(){},showModal(){this.open=true},close(){this.closed=true;this.open=false},querySelector(){return {disabled:false}}});
 const doc={createElement:element,getElementById(id){if(!nodes.has(id))nodes.set(id,element(id));return nodes.get(id);}};
 const sandbox={crypto:webcrypto,document:doc,Date,FormData:class{constructor(){throw Error('Never read stale FormData')}},confirm(){throw Error('Never confirm stale data')},fetch(){calls.push('write');throw Error('Never write in inactive cloud mode')}};
 vm.runInNewContext(fs.readFileSync('public/main-cloud-contacts.js','utf8'),sandbox);
 return {api:sandbox.NainaCloudContacts,nodes,calls};
}
test('new lead gets unique stable ID, validated budget and stage',()=>{
 const {api}=setup();
 const plan=api.plan('leads',null,{name:'Sample lead',phone:'000',stage:'Contacted',budget:'50000.50',date:'2026-10-14'},9);
 assert.equal(plan.resource,'leads');assert.equal(plan.mode,'create');assert.equal(plan.data.budget,50000.5);assert.equal(plan.expectedRevision,9);assert.ok(plan.id);assert.ok(plan.idempotencyKey);
 assert.throws(()=>api.plan('leads',null,{name:'',stage:'New'},9),/Name/);
 assert.throws(()=>api.plan('leads',null,{name:'Demo',stage:'Unknown'},9),/stage/);
 assert.throws(()=>api.plan('leads',null,{name:'Demo',stage:'New',date:'2026-02-30'},9),/calendar/);
});
test('existing customer keeps source ID and cannot become a new record',()=>{
 const {api}=setup();
 const plan=api.plan('customers',{id:'customer-HISTORICAL'},{name:'Sample buyer',phone:'123',address:'Kanpur'},4);
 assert.equal(plan.id,'customer-HISTORICAL');assert.equal(plan.mode,'update');assert.equal(plan.data.address,'Kanpur');
 assert.throws(()=>api.plan('customers',{id:''},{name:'Buyer'},4),/required/);
});
test('one request only, owner write route, and verified revision receipt',async()=>{
 const {api}=setup();const plan=api.plan('customers',{id:'customer1'},{name:'Sample buyer'},4);
 let count=0;
 const result=await api.write(async(url,init)=>{count++;assert.equal(url,'/api/private-crm-write');assert.equal(init.credentials,'same-origin');assert.equal(init.method,'POST');return {ok:true,async json(){return {result:{id:plan.id,resource:plan.resource,revision:5}}}};},plan);
 assert.equal(count,1);assert.equal(result.revision,5);
 await assert.rejects(api.write(async()=>({ok:true,async json(){return {result:{id:'changed',resource:'customers',revision:5}}}}),plan),/receipt/);
});
test('locked, conflicted and uncertain writes do not retry',async()=>{
 const {api}=setup(),plan=api.plan('leads',null,{name:'Demo'},0);
 let count=0;await assert.rejects(api.write(async()=>{count++;throw Error('Offline')},plan),/unknown/);assert.equal(count,1);
 await assert.rejects(api.write(async()=>({ok:false,status:423}),plan),/locked/);
 await assert.rejects(api.write(async()=>({ok:false,status:409}),plan),/conflict/);
});
test('browser form opens, but a stale cloud-view session blocks submission before FormData or network',async()=>{
 const h=setup();
 h.api.openDialog({resource:'leads',revision:2,notify(){},refresh:async()=>{},canSubmit:()=>false});
 assert.equal(h.nodes.get('cloud-contact-dialog').open,true);
 await h.nodes.get('cloud-contact-form').onsubmit({preventDefault(){}});
 assert.equal(h.nodes.get('cloud-contact-dialog').closed,true);
 assert.equal(h.calls.length,0);
});

test('existing customer and enquiry preserve whitespace-significant historical IDs',()=>{
 const {api}=setup();
 const original={id:' customer 001 ',name:'Original Buyer'};
 const before=JSON.stringify(original);
 const customer=api.plan('customers',original,{name:'Edited Buyer'},4);
 assert.equal(customer.id,' customer 001 ');
 assert.equal(customer.mode,'update');
 const enquiry=api.plan('leads',{id:'   historical-lead  ',name:'Old'},
  {name:'Updated lead',stage:'New'},4);
 assert.equal(enquiry.id,'   historical-lead  ');
 assert.equal(JSON.stringify(original),before);
 assert.throws(()=>api.plan('customers',{id:'   '},{name:'No ID'},4),/ID is required/);
});

