import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import ts from 'typescript';
import {webcrypto} from 'node:crypto';
import * as policy from '../lib/cloud-core.mjs';
import {buildMediaRecoveryManifest,RecoveryManifestError} from '../lib/media-recovery.mjs';
const origin='https://crm.nainamotors.com',owner={userId:'synthetic-owner',email:policy.OWNER_EMAIL};
function compile(file,imports){const exports={};vm.runInNewContext(ts.transpileModule(fs.readFileSync(file,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText,{exports,require:n=>{if(!(n in imports))throw Error(n);return imports[n]},Response,URL,TextEncoder,TextDecoder,Uint8Array,DataView,crypto:webcrypto});return exports;}
function setup({identity=owner,enabled=true,max=15*1024*1024,missing=false,noVehicle=false,putFailure=false,insertFailure=false,activationFailure=false,invalidRevision=undefined}={}){
 const trusted=new Headers();if(identity){trusted.set('oai-authenticated-user-id',identity.userId);trusted.set('oai-authenticated-user-email',identity.email);}
 const auth=compile('app/chatgpt-auth.ts',{'next/headers':{headers:async()=>trusted},'next/navigation':{}});
 const guard=compile('lib/owner-auth.ts',{'../app/chatgpt-auth':auth,'./cloud-core.mjs':policy});
 const rows=new Map(),objects=new Map(),calls=[];let cloudRevision=0;
 const db={prepare(sql){return {bind(...args){const stmt={async first(){calls.push(sql);if(sql.includes('FROM vehicles'))return noVehicle?null:{id:args[0]};
  if(sql.includes('FROM cloud_metadata'))return invalidRevision===undefined?{value:String(cloudRevision)}:invalidRevision===null?null:{value:invalidRevision};
  const r=rows.get(args[0]);return r?.vehicle_id===args[1]?r:null;},async all(){calls.push(sql);return {success:true,results:[...rows.values()]};},async run(){calls.push(sql);if(sql.includes('INTO cloud_metadata'))return {success:true};if(sql.startsWith('UPDATE cloud_metadata')){cloudRevision++;return {success:true};}if(sql.startsWith('INSERT')){if(insertFailure)throw Error('duplicate');const [id,vehicle_id,object_key,original_filename,mime_type,bytes,category,uploaded_by,sha256,notes]=args;assert(!rows.has(id));assert(![...rows.values()].some(r=>r.object_key===object_key));rows.set(id,{id,vehicle_id,object_key,original_filename,mime_type,bytes,category,uploaded_by,sha256,notes,archived_at:'pending',is_cover:0});}else if(sql.includes('notes=NULL')){if(activationFailure)throw Error('uncertain');Object.assign(rows.get(args[0]),{notes:null,archived_at:null});}else if(sql.includes('archived_at=CURRENT_TIMESTAMP'))Object.assign(rows.get(args[0]),{archived_at:'archived',is_cover:0});else if(sql.includes('archived_at=NULL'))Object.assign(rows.get(args[0]),{archived_at:null,is_cover:0});else if(sql.includes('is_cover=0')){for(const r of rows.values())if(r.vehicle_id===args[0])r.is_cover=0;}else if(sql.includes('is_cover=1'))rows.get(args[0]).is_cover=1;return {success:true};}};return stmt;}}},async batch(stmts){return Promise.all(stmts.map(s=>s.run()));}};
 const bucket={async put(key,bytes,options){calls.push('r2.put');if(putFailure)throw Error('interrupted');const obj={size:bytes.length,customMetadata:options.customMetadata,body:bytes,arrayBuffer:async()=>bytes.slice().buffer};objects.set(key,obj);return obj;},async get(key){calls.push('r2.get');return objects.get(key);},async head(key){calls.push('r2.head');return objects.get(key);}};
 const flags=enabled===null?compile('lib/private-media-flags.ts',{}):{PRIVATE_MEDIA_ENABLED:enabled,MEDIA_MAX_BYTES:max};
 const service=compile('lib/private-media.ts',{'./owner-auth':guard,'./private-media-flags':flags,'./media-recovery.mjs':{buildMediaRecoveryManifest,RecoveryManifestError}});let accesses=0;
 return {rows,objects,calls,get cloudRevision(){return cloudRevision;},run:r=>service.handlePrivateMedia(r,()=>{accesses++;return missing?{DB:db}:{DB:db,BUCKET:bucket};}),get accesses(){return accesses}};
}
const jpeg=new Uint8Array([255,216,255,224,0,2,255,217]);
const pdf=new TextEncoder().encode('%PDF-1.7\n1 0 obj\n%%EOF');
function request(action='upload',{body=jpeg,name='photo.jpg',mime='image/jpeg',method=['list','download','preview','export'].includes(action)?'GET':'POST',extra={},headers={}}={}){const p=new URLSearchParams({action,vehicleId:'synthetic vehicle / exact',...(action==='upload'?{filename:name,category:'photo'}:{}),...extra});return new Request(origin+'/api/private-media?'+p,{method,headers:{origin,'content-type':mime,...headers},...(method==='POST'?{body}:{} )});}
async function upload(h,opts){const r=await h.run(request('upload',opts));assert.equal(r.status,201);return (await r.json()).id;}
for(const [label,identity,status] of [['anonymous',null,401],['other',{userId:'other',email:'other@example.com'},403]])test(label+' cannot upload or download',async()=>{const h=setup({identity});for(const action of ['upload','download'])assert.equal((await h.run(request(action))).status,status);assert.equal(h.accesses,0)});
test('spoofed browser identity rejected',async()=>{const h=setup({identity:null});assert.equal((await h.run(request('upload',{headers:{'oai-authenticated-user-id':owner.userId,'oai-authenticated-user-email':owner.email}}))).status,401);assert.equal(h.accesses,0)});
test('cross-origin mutations blocked before body and bindings',async()=>{const h=setup();for(const action of ['upload','cover','archive','restore']){const r=request(action,{headers:{origin:'https://evil.example'}});assert.equal((await h.run(r)).status,403);assert.equal(r.bodyUsed,false);}assert.equal(h.accesses,0)});
test('actual disabled flag rejects every operation before body or storage',async()=>{const h=setup({enabled:null});for(const action of ['upload','download','list','cover','archive','restore']){const r=request(action);assert.equal((await h.run(r)).status,423);assert.equal(r.bodyUsed,false);}assert.equal(h.accesses,0);assert.equal(h.calls.length,0)});
test('missing R2 fails closed without body read',async()=>{const h=setup({missing:true}),r=request();assert.equal((await h.run(r)).status,503);assert.equal(r.bodyUsed,false)});
test('unknown vehicle cannot upload',async()=>{const h=setup({noVehicle:true}),r=request();assert.equal((await h.run(r)).status,404);assert.equal(r.bodyUsed,false);assert.equal(h.objects.size,0)});
test('owner JPEG and PDF uploads preserve exact vehicle ID and opaque key',async()=>{const h=setup();await upload(h);await upload(h,{body:pdf,name:'RC.pdf',mime:'application/pdf',extra:{category:'rc'}});assert.equal(h.rows.size,2);for(const row of h.rows.values()){assert.equal(row.vehicle_id,'synthetic vehicle / exact');assert.match(row.object_key,/^private\/[0-9a-f-]{36}$/);assert.equal(row.uploaded_by,owner.userId);assert.equal(row.archived_at,null);assert.equal(row.notes,null)}});
test('invalid signatures, extensions, MIME and traversal rejected',async()=>{for(const opts of [{body:pdf},{name:'photo.pdf'},{mime:'text/html'},{name:'../photo.jpg'},{name:'a\\photo.jpg'},{body:new Uint8Array([1,2,3])}]){const h=setup();assert([400,415].includes((await h.run(request('upload',opts))).status));assert.equal(h.rows.size,0)}});
test('size enforced on streamed bytes and declared length',async()=>{for(const headers of [{},{'content-length':'100'}]){const h=setup({max:4});assert.equal((await h.run(request('upload',{headers}))).status,413);assert.equal(h.rows.size,0)}});
test('interrupted request stream writes nothing',async()=>{const h=setup();const r=new Request(origin+'/api/private-media?action=upload&vehicleId=x&filename=a.jpg&category=photo',{method:'POST',headers:{origin,'content-type':'image/jpeg'},duplex:'half',body:new ReadableStream({pull(c){c.error(Error('interrupted'))}})});assert.equal((await h.run(r)).status,503);assert.equal(h.rows.size,0)});
test('duplicate metadata failure prevents R2 upload',async()=>{const h=setup({insertFailure:true});assert.equal((await h.run(request())).status,503);assert.equal(h.objects.size,0);assert(!h.calls.includes('r2.put'))});
for(const option of ['putFailure','activationFailure'])test(option+' retains staged metadata, never deletes content',async()=>{const h=setup({[option]:true});assert.equal((await h.run(request())).status,503);const row=[...h.rows.values()][0];assert(row.archived_at);assert(row.notes);assert.equal((await h.run(request('restore',{extra:{mediaId:row.id}}))).status,409);assert(!h.calls.some(s=>/DELETE/.test(s)))});
test('private download uses metadata key, attachment and no-store headers',async()=>{const h=setup(),mediaId=await upload(h);const r=await h.run(request('download',{extra:{mediaId}}));assert.equal(r.status,200);assert.equal(r.headers.get('content-type'),'application/octet-stream');assert.match(r.headers.get('content-disposition'),/^attachment;/);assert.match(r.headers.get('cache-control'),/no-store/);assert.equal(r.headers.get('x-content-type-options'),'nosniff');assert.equal((await r.arrayBuffer()).byteLength,jpeg.length);assert.equal((await h.run(request('download',{extra:{mediaId,objectKey:'evil'}}))).status,400)});
test('archive/restore retain bytes and cover selection, including sold inventory',async()=>{const h=setup(),mediaId=await upload(h);assert.equal((await h.run(request('cover',{extra:{mediaId}}))).status,200);assert.equal(h.rows.get(mediaId).is_cover,1);assert.equal((await h.run(request('archive',{extra:{mediaId}}))).status,200);assert.equal(h.objects.size,1);assert.equal((await h.run(request('download',{extra:{mediaId}}))).status,409);assert.equal((await h.run(request('restore',{extra:{mediaId}}))).status,200);assert.equal(h.rows.get(mediaId).is_cover,0);assert(!h.calls.some(s=>/UPDATE (vehicles|sales)|DELETE/.test(s)))});
