import { legacyCloudGate } from '../../../../lib/cloud-release';
import {guard,json,database,readStatus,failure} from '../../../../lib/cloud-server';
export async function POST(request:Request){const auth=await guard(request,true);if('error' in auth)return auth.error;const locked=legacyCloudGate();if(locked)return locked;return failure(async()=>{const status=await readStatus();if(status.missingTables.length)return json({...status,error:'Schema incomplete. Test not run.'},503);const db=database(),id='probe_'+crypto.randomUUID(),nonce=crypto.randomUUID();const results=await db.batch([db.prepare('INSERT INTO connection_probes (id,nonce,created_at) VALUES (?,?,?)').bind(id,nonce,new Date().toISOString()),db.prepare('SELECT nonce FROM connection_probes WHERE id=?').bind(id),db.prepare('DELETE FROM connection_probes WHERE id=?').bind(id),db.prepare('SELECT COUNT(*) AS n FROM connection_probes WHERE id=?').bind(id)]);const read=(results[1].results[0] as {nonce:string})?.nonce===nonce,cleaned=(results[3].results[0] as {n:number})?.n===0;return json({...status,testId:id,writePassed:results[0].success,readPassed:read,cleanupPassed:cleaned,businessRecordsTouched:false,testedAt:new Date().toISOString()},read&&cleaned?200:500);});}

