/* Controlled RTO/HPA and repair history editing, independent of finance.
   Cloud only: never calls localStorage, never books estimated/actual repair expenses. */
(function(root,factory){
 const api=factory();
 if(typeof module==='object'&&module.exports)module.exports=api;
 else root.NainaCloudServiceJobs=api;
})(typeof globalThis==='object'?globalThis:this,function(){
 'use strict';
 let pending=false;
 const rtoStages=['Pending','Documents collected','Submitted','In Process','Completed','On Hold','Cancelled'];
 const repairStages=['Pending','In Progress','Completed','Cancelled'];
 function text(value,max=3000){
  if(typeof value!=='string'||value.length>max||/[\x00-\x1f\x7f]/.test(value))
   throw Error('Invalid or excessive text.');
  return value.trim();
 }
 function identifier(value){
  // Historical IDs may contain significant whitespace: NEVER trim them.
  if(typeof value!=='string'||!value||value.length>256||!value.trim()||
    /[\x00-\x1f\x7f]/.test(value))
   throw Error('Missing original record or vehicle ID.');
  return value;
 }
 function calendar(value,old){
  const v=text(value??'',10);
  if(!v)return old??null; // Blank edit cannot silently delete old evidence.
  if(!/^\d{4}-\d{2}-\d{2}$/.test(v))throw Error('Invalid calendar date.');
  const parsed=new Date(v+'T00:00:00Z');
  if(!Number.isFinite(parsed.getTime())||parsed.toISOString().slice(0,10)!==v)
   throw Error('Invalid calendar date.');
  if(typeof old==='string'&&old.slice(0,10)===v)return old; // Preserve original timestamp/time zone.
  return v;
 }
 function amount(value){
  if(value===null||value===undefined||value==='')return null;
  const v=typeof value==='number'?String(value):text(value,50);
  if(!/^(?:0|[1-9]\d{0,11})(?:\.\d{1,2})?$/.test(v))
   throw Error('Invalid repair amount; use at most two decimal places.');
  const number=Number(v);
  if(!Number.isSafeInteger(Math.round(number*100)))throw Error('Repair amount exceeds safe range.');
  return Math.round(number*100)/100;
 }
 function uuid(){
  if(typeof crypto==='undefined'||typeof crypto.randomUUID!=='function')
   throw Error('Secure ID unavailable.');
  return crypto.randomUUID();
 }
 function plan(kind,bike,existing,values,expectedRevision){
  if(!['rto','repair'].includes(kind)||!bike||!Number.isSafeInteger(expectedRevision)||expectedRevision<0)
   throw Error('Cloud view or operation unavailable.');
  const vehicleId=identifier(bike.id);
  if(existing&&(typeof existing!=='object'||existing.vehicle_id!==vehicleId))
   throw Error('Historical record belongs to another vehicle.');
  const create=!existing,resource=kind==='rto'?'rto_cases':'repair_jobs';
  const fields=create?{vehicle_id:vehicleId}:{};
  const statuses=kind==='rto'?rtoStages:repairStages;
  const stage=text(values.stage??values.status??'',80);
  const originalStatus=existing?(kind==='rto'?existing.stage:existing.status):null;
  if(!statuses.includes(stage)&&!(existing&&stage===originalStatus))
   throw Error('Select a valid workflow stage.');
  if(kind==='rto'){
   if(create){
    fields.procedure=text(values.procedure||'',150);
    if(!fields.procedure)throw Error('Procedure is required.');
    fields.stage=stage;
    fields.next_action_at=calendar(values.next_action_at);
    fields.reference_no=text(values.reference_no||'',200);
    fields.notes=text(values.notes||'');
   }else{
    if(stage!==originalStatus)fields.stage=stage;
    const due=calendar(values.next_action_at,existing.next_action_at);
    if(due!==(existing.next_action_at??null))fields.next_action_at=due;
    const notes=text(values.notes??'',3000);
    if(notes!==text(existing.notes??'',3000))fields.notes=notes;
   }
  }else{
   if(create){
    fields.description=text(values.description||'',1000);
    if(!fields.description)throw Error('Repair description required.');
    fields.status=stage;
    fields.mechanic=text(values.mechanic||'',200);
    fields.estimated_cost=amount(values.estimated_cost);
    fields.final_cost=amount(values.final_cost);
    fields.started_at=calendar(values.started_at);
    fields.completed_at=calendar(values.completed_at);
    fields.notes=text(values.notes||'');
   }else{
    if(stage!==originalStatus)fields.status=stage;
    const completed=calendar(values.completed_at,existing.completed_at);
    if(completed!==(existing.completed_at??null))fields.completed_at=completed;
    const cost=amount(values.final_cost);
    const recorded=existing.final_cost??null;
    const sameAmount=recorded===null?cost===null:amount(recorded)===cost;
    if(!sameAmount)fields.final_cost=cost;
    const notes=text(values.notes??'',3000);
    if(notes!==text(existing.notes??'',3000))fields.notes=notes;
   }
   if(create&&fields.started_at&&fields.completed_at&&
      fields.completed_at.slice(0,10)<fields.started_at.slice(0,10))
    throw Error('Repair completion cannot precede its recorded start.');
   if(!create&&fields.completed_at&&existing.started_at&&
      fields.completed_at.slice(0,10)<existing.started_at.slice(0,10))
    throw Error('Repair completion cannot precede its recorded start.');
  }
  if(!create&&Object.keys(fields).length===0)throw Error('No changes to save.');
  return {resource,id:create?uuid():identifier(existing.id),
   mode:create?'create':'update',data:fields,
   expectedRevision,idempotencyKey:uuid()};
 }
 async function write(fetchFn,instruction){
  if(typeof fetchFn!=='function'||!instruction||
     !['rto_cases','repair_jobs'].includes(instruction.resource)||
     !['create','update'].includes(instruction.mode))
   throw Error('Unsupported private cloud write.');
  let response;
  try{
   response=await fetchFn('/api/private-crm-write',{method:'POST',
    credentials:'same-origin',cache:'no-store',redirect:'error',
    headers:{'Content-Type':'application/json'},body:JSON.stringify(instruction)});
  }catch{throw Error('Save outcome unknown; refresh and verify before retrying.');}
  if(!response?.ok){
   if(response?.status===423)throw Error('Cloud editing is locked.');
   if(response?.status===409)throw Error('Cloud revision conflict; refresh before editing.');
   throw Error('Save not confirmed; inspect the cloud record before retrying.');
  }
  let body;
  try{body=await response.json();}catch{throw Error('Receipt unreadable; refresh and verify before retrying.');}
  if(body?.result?.id!==instruction.id||
     body?.result?.resource!==instruction.resource||
     body?.result?.revision!==instruction.expectedRevision+1)
   throw Error('Cloud receipt mismatch. Refresh before retrying.');
  return body.result;
 }
 function openDialog({kind,bike,existing,revision,notify,refresh,canSubmit}){
  if(pending||!['rto','repair'].includes(kind)||!bike||
    typeof canSubmit!=='function'||!canSubmit()||
    typeof notify!=='function'||typeof refresh!=='function')return;
  const modal=document.getElementById('cloud-service-dialog'),
    form=document.getElementById('cloud-service-form'),
    holder=document.getElementById('cloud-service-fields');
  if(!modal||!form||!holder)return;
  document.getElementById('cloud-service-title').textContent=
   (existing?'Update':'Create')+(kind==='rto'?' RTO / HPA case':' repair job');
  holder.replaceChildren();
  function add(label,name,value='',type='text',options=null){
   const wrap=document.createElement('label');wrap.textContent=label+' ';
   const field=document.createElement(options?'select':'input');
   field.name=name;
   if(options){
    for(const choice of options){const option=document.createElement('option');
     option.value=choice;option.textContent=choice;field.appendChild(option);}
   }else {field.type=type;field.maxLength=3000;}
   field.value=String(value??'');wrap.appendChild(field);holder.appendChild(wrap);
  }
  if(kind==='rto'){
   if(!existing)add('Procedure','procedure');
   add('RTO stage','stage',existing?.stage||'Pending','text',
     existing?.stage&&!rtoStages.includes(existing.stage)?[existing.stage,...rtoStages]:rtoStages);
   add('Next follow-up','next_action_at',existing?.next_action_at?.slice(0,10)||'','date');
   if(!existing)add('RTO reference','reference_no');
   add('Notes','notes',existing?.notes||'');
  }else{
   if(!existing){
    add('Repair description','description');
    add('Mechanic or workshop','mechanic');
    add('Repair estimate (₹), NOT an expense','estimated_cost','','number');
    add('Started','started_at','','date');
   }
   add('Status','status',existing?.status||'Pending','text',
      existing?.status&&!repairStages.includes(existing.status)?[existing.status,...repairStages]:repairStages);
   add('Final cost (₹), NOT booked automatically','final_cost',existing?.final_cost??'','number');
   add('Completed','completed_at',existing?.completed_at?.slice(0,10)||'','date');
   add('Notes','notes',existing?.notes||'');
  }
  const submit=form.querySelector('button[type="submit"]');
  form.onsubmit=async event=>{
   event.preventDefault();if(pending)return;
   if(!canSubmit()){notify('Cloud view changed. Refresh first.');modal.close();return;}
   let instruction;
   try{instruction=plan(kind,bike,existing,Object.fromEntries(new FormData(form)),revision);}
   catch(error){notify(error.message);return;}
   if(!confirm('Confirm this private '+kind+' update? It does not post repair expenses, sale payments or change browser records.'))return;
   if(!canSubmit()){notify('Cloud view changed during confirmation. Refresh first.');modal.close();return;}
   pending=true;if(submit)submit.disabled=true;
   try{await write(fetch,instruction);modal.close();notify('Cloud record confirmed; refreshing.');await refresh();}
   catch(error){notify(error.message);}
   finally{pending=false;if(submit)submit.disabled=false;}
  };
  const close=document.getElementById('cloud-service-close');
  if(close)close.onclick=()=>{if(!pending)modal.close();};
  if(!modal.open)modal.showModal();
 }
 return {plan,write,openDialog,isPending:()=>pending};
});

