// Offline-only rehearsal: checksum + all 27 tables restored to disposable in-memory SQLite.
// Never connects to D1/R2, never overwrites a file, never executes SQL supplied by a backup.
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {createHash} from 'node:crypto';
import {spawnSync} from 'node:child_process';
import {stable} from '../lib/cloud-core.mjs';
import {auditSnapshotLinks} from '../lib/snapshot-link-audit.mjs';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
try{
 const input=process.argv[2],rawSha256=process.argv[3];
 if(process.argv.length!==4||typeof rawSha256!=='string'||!/^[a-f0-9]{64}$/.test(rawSha256))
  throw Error('Independent SHA-256 required.');
 if(typeof input!=='string'||!path.isAbsolute(input))
  throw Error('Private snapshot requires an absolute path.');
 const canonical=fs.realpathSync(input);
 if(canonical===root||canonical.startsWith(root+path.sep)||fs.lstatSync(input).isSymbolicLink())
  throw Error('Private snapshots in repository or symlinked inputs are forbidden.');
 const info=fs.statSync(canonical);
 if(!info.isFile()||info.size<10||info.size>20*1024*1024)
  throw Error('Invalid private snapshot size/type.');
 const raw=fs.readFileSync(canonical);
 if(createHash('sha256').update(raw).digest('hex')!==rawSha256)
  throw Error('Independent raw snapshot checksum mismatch.');
 const snapshot=JSON.parse(raw.toString('utf8'));
 if(snapshot.format!=='naina-cloud-snapshot-v1'||Object.keys(snapshot).sort().join(',')!=='exportedAt,format,sha256,tables')throw Error('Invalid snapshot format');
 const {sha256,...body}=snapshot;
 if(createHash('sha256').update(stable(body)).digest('hex')!==sha256)throw Error('Checksum mismatch');
 // SQLite foreign keys alone cannot catch a Sold vehicle without a linked
 // sale, duplicate historical payments, or invalid private-media metadata.
 // Reject these AFTER checksum verification, BEFORE disposable SQL work.
 const relationshipAudit=auditSnapshotLinks(snapshot.tables);
 if(!relationshipAudit.consistent)throw Error('Business relationship audit failed ('+
  relationshipAudit.issueCount+' issues); no database was changed.');
 const python=String.raw`
import sys,json,sqlite3,pathlib
s=json.load(sys.stdin);root=pathlib.Path(sys.argv[1]);db=sqlite3.connect(':memory:')
db.execute('PRAGMA foreign_keys=ON')
for file in sorted((root/'drizzle').glob('*.sql')): db.executescript(file.read_text())
expected={r[0] for r in db.execute("SELECT name FROM sqlite_master WHERE type='table'")}
assert isinstance(s['tables'],dict) and set(s['tables'])==expected and len(expected)==27, 'Table manifest differs'
db.execute('BEGIN');db.execute('PRAGMA defer_foreign_keys=ON');count=0
for table,rows in s['tables'].items():
 assert isinstance(rows,list) and len(rows)<=5000, 'Invalid row collection'
 columns=[r[1] for r in db.execute('PRAGMA table_info("'+table+'")')]
 for row in rows:
  assert isinstance(row,dict) and set(row)==set(columns), 'Column manifest differs'
  assert all(v is None or type(v) in (str,int,float) for v in row.values()), 'Invalid value'
  db.execute('INSERT INTO "'+table+'" ('+','.join('"'+c+'"' for c in columns)+') VALUES ('+','.join('?' for c in columns)+')',[row[c] for c in columns]);count+=1
assert not db.execute('PRAGMA foreign_key_check').fetchall(), 'Foreign key mismatch'
assert db.execute('PRAGMA integrity_check').fetchone()[0]=='ok', 'Integrity check failed'
for table,rows in s['tables'].items():
 columns=[r[1] for r in db.execute('PRAGMA table_info("'+table+'")')]
 actual=[dict(zip(columns,r)) for r in db.execute('SELECT * FROM "'+table+'"')]
 encode=lambda r:json.dumps({k:int(v) if isinstance(v,float) and v.is_integer() else v for k,v in r.items()},sort_keys=True,separators=(',',':'))
 assert sorted(map(encode,actual))==sorted(map(encode,rows)), 'Roundtrip mismatch'
db.rollback();db.close();print(json.dumps({'valid':True,'tableCount':len(expected),'rowCount':count,'foreignKeys':'passed','roundtrip':'passed','persistentWrites':False,'mediaBytesVerified':False}))
`;
 const result=spawnSync('python',['-c',python,root],{input:JSON.stringify(snapshot),encoding:'utf8',timeout:30000,maxBuffer:1024*1024});
 if(result.status!==0)throw Error('Disposable restore failed: '+(result.stderr.match(/(?:AssertionError|IntegrityError):[^\n]*/)?.[0]||'Schema, integrity, or runtime check failed'));
 process.stdout.write(result.stdout);
}catch(e){
 const explanation=e instanceof Error&&e.message.startsWith('Business relationship audit failed')?
  'Business relationship audit failed.': 'Private disposable restore blocked. Check independent fingerprint and snapshot validity.';
 console.error('FAIL: '+explanation+' No original file changed.');
 process.exitCode=1;
}

