/* Cloud contact/enquiry editor for the existing CRM. No localStorage writes. */
(function(root,factory){
 const api=factory();
 if(typeof module==='object'&&module.exports)module.exports=api;
 else root.NainaCloudContacts=api;
})(typeof globalThis==='object'?globalThis:this,function(){
 'use strict';
 const stages=['New','Contacted','Visit planned','Negotiating','Closed'];
 let pending=false;
 function text(v,max=500){if(typeof v!=='string'||v.length>max||/[\x00-\x1f]/.test(v))throw Error('Invalid text field.');return v.trim();}
 function id(v){if(typeof v!=='string'||!v||!v.trim()||v.length>256||/[\x00-\x1f]/.test(v))throw Error('Record ID is required.');return v;}
 function uuid(){if(typeof crypto==='undefined'||typeof crypto.randomUUID!=='function')throw Error('Secure record IDs unavailable.');return crypto.randomUUID();}
 function date(v){const s=text(v||'',20);if(!s)return '';if(!/^\d{4}-\d{2}-\d{2}$/.test(s))throw Error('Invalid follow-up date.');const d=new Date(s+'T00:00:00Z');if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==s)throw Error('Invalid calendar date.');return s;}
 function rupees(v){if(v===''||v===null||v===undefined)return null;if(typeof v!=='string'||!/^(?:0|[1-9]\d{0,11})(?:\.\d{1,2})?$/.test(v.trim()))throw Error('Invalid budget.');const n=Math.round(Number(v)*100)/100;if(!Number.isSafeInteger(Math.round(n*100)))throw Error('Invalid budget.');return n;}
 function plan(resource,existing,fields,expectedRevision){
  if(!['leads','customers'].includes(resource))throw Error('Invalid contact resource.');
  if(!Number.isSafeInteger(expectedRevision)||expectedRevision<0)throw Error('Refresh cloud records before editing.');
  const values=fields||{},name=text(values.name||'',300);if(!name)throw Error('Name is required.');
  let data;
  if(resource==='leads'){
   const stage=text(values.stage||'New',60);if(!stages.includes(stage))throw Error('Invalid enquiry stage.');
   data={name,phone:text(values.phone||'',50),interest:text(values.interest||'',500),
    budget:rupees(values.budget),stage,source:text(values.source||'',120),date:date(values.date),notes:text(values.notes||'',2000)};
  }else{
   data={name,phone:text(values.phone||'',50),address:text(values.address||'',500),notes:text(values.notes||'',2000)};
  }
  return {resource,mode:existing?'update':'create',id:existing?id(existing.id):uuid(),data,expectedRevision,idempotencyKey:uuid()};
 }
 async function write(fetchFn,instruction){
  if(!instruction||!['leads','customers'].includes(instruction.resource)||!['create','update'].includes(instruction.mode))throw Error('Unsupported cloud contact save.');
  let response;
  try{response=await fetchFn('/api/private-crm-write',{method:'POST',credentials:'same-origin',cache:'no-store',redirect:'error',headers:{'Content-Type':'application/json'},body:JSON.stringify(instruction)});}
  catch{throw Error('Cloud save outcome unknown. Refresh before another attempt.');}
  if(!response?.ok){
   if(response?.status===423)throw Error('Cloud editing is locked until activation.');
   if(response?.status===409)throw Error('Cloud revision conflict. Refresh records before editing.');
   throw Error('Cloud write was not confirmed. Check current records before another attempt.');
  }
  let receipt;try{receipt=await response.json();}catch{throw Error('Invalid receipt. Refresh and reconcile first.');}
  if(receipt?.result?.id!==instruction.id||receipt?.result?.resource!==instruction.resource||receipt?.result?.revision!==instruction.expectedRevision+1)throw Error('Cloud receipt could not be verified. Refresh before another attempt.');
  return receipt.result;
 }
 function openDialog({resource,existing,revision,refresh,notify,canSubmit}){
  if(pending||!['leads','customers'].includes(resource)||typeof canSubmit!=='function')return;
  const modal=document.getElementById('cloud-contact-dialog'),form=document.getElementById('cloud-contact-form'),fields=document.getElementById('cloud-contact-fields');
  if(!modal||!form||!fields)return;
  document.getElementById('cloud-contact-title').textContent=(existing?'Edit ':'Add ')+(resource==='leads'?'cloud enquiry':'cloud customer');
  fields.replaceChildren();
  function field(label,key,value='',options=null,type='text'){
   const wrap=document.createElement('label');wrap.textContent=label+' ';
   const el=document.createElement(options?'select':'input');el.name=key;
   if(options){for(const item of options){const opt=document.createElement('option');opt.value=item;opt.textContent=item;el.appendChild(opt);}}
   else{el.type=type;el.maxLength=2000;}
   el.value=String(value??'');wrap.appendChild(el);fields.appendChild(wrap);return el;
  }
  field('Name','name',existing?.name||'');
  field('Phone','phone',existing?.phone||'');
  if(resource==='leads'){
   field('Interested vehicle','interest',existing?.interest||'');
   field('Budget (₹)','budget',existing?.budget??'');
   field('Pipeline stage','stage',existing?.stage||'New',stages);
   field('Lead source','source',existing?.source||'');
   field('Follow-up date','date',existing?.date||'',null,'date');
  }else field('Address','address',existing?.address||'');
  field('Notes','notes',existing?.notes||'');
  const submit=form.querySelector('button[type="submit"]');
  form.onsubmit=async event=>{
   event.preventDefault();if(pending)return;
   if(!canSubmit()){notify('Cloud view changed. Refresh before editing.');modal.close();return;}
   let instruction;
   try{instruction=plan(resource,existing,Object.fromEntries(new FormData(form)),revision);}
   catch(error){notify(error.message);return;}
   if(!confirm('Confirm '+(existing?'updating':'adding')+' this '+(resource==='leads'?'enquiry':'customer')+' in the private cloud database? Browser records will not change.'))return;
   if(!canSubmit()){notify('Cloud view changed during confirmation. Refresh.');modal.close();return;}
   pending=true;submit.disabled=true;
   try{await write(fetch,instruction);modal.close();pending=false;submit.disabled=false;notify('Cloud contact save confirmed. Reloading records.');await refresh();}
   catch(error){notify(error.message);}finally{pending=false;submit.disabled=false;}
  };
  document.getElementById('cloud-contact-close').onclick=()=>{if(!pending)modal.close();};
  if(!modal.open)modal.showModal();
 }
 return {stages,plan,write,openDialog,isPending:()=>pending};
});

