/* Explicit owner-driven cloud workspace. No startup network or browser storage access. */
(()=>{'use strict';
const $=id=>document.getElementById(id), notice=message=>{$('notice').textContent=message;};
// name: label; ! required; # numeric; | enum. Unknown saved fields are preserved on edit.
const definitions={
vehicle_timeline:['Vehicle history (read-only)'],
vehicles:['Inventory','name!','reg','year#','category','fuel','owner','km#','bank','cost#','ask#','status!|Available|Review','purchaseDate','notes','chassis','engine'],
sales:['Sales','vehicleId!','customerId','buyer!','buyerPhone','buyerAddress','saleDate!','sale!#','balance!#','paymentMethod|Cash|UPI|Bank|Other'],
customers:['Customers','name!','phone','address','notes'],
expenses:['Vehicle expenses','vehicle_id!','kind!|parking|other','amount!#','notes'],
leads:['Enquiries','name!','phone','interest','budget#','stage','source','date','time','notes'],
vehicle_locations:['Vehicle location / parking','location_type!','location_label','notes'],
document_requirements:['Document checklist','vehicle_id!','document_type!','status!|Missing|Pending|Received|Delivered|Not Applicable','due_at','notes'],
customer_payments:['Customer payments','sale_id!','received_at!','amount!#','method!|Cash|UPI|Bank|Other','payment_reference','note'],
cashbook_entries:['Cashbook','occurred_at!','entry_type!|IN|OUT','amount!#','payment_method!|Cash|UPI|Bank|Other','category!','accounting_role!|Overhead|Transfer|Loan|Other','reference_id','description'],
rto_cases:['RTO / HPA','vehicle_id!','procedure!','stage!','bank_noc_at','applied_at','completed_at','next_action_at','reference_no','notes'],
repair_jobs:['Repairs / mechanics','vehicle_id!','mechanic','description!','estimated_cost#','final_cost#','status!|Pending|In progress|Completed|Cancelled','started_at','completed_at','notes'],
reminders:['Reminders','vehicle_id','related_type','related_id','title!','due_at!','status!|Open|Done|Cancelled','priority!|Low|Normal|High','notes'],
reservations:['Reservations','vehicle_id!','customer_name!','customer_phone','token_amount!#','reserved_at!','expires_at','status!|Active|Expired|Cancelled|Converted','notes'],
price_history:['Price changes','vehicle_id!','new_price!#','reason'],
enquiry_notes:['Follow-ups','lead_id','vehicle_id','customer_name','phone','asking_price#','offered_price#','note','followup_at','status'],
document_expiries:['Document expiry','vehicle_id!','document_type!','expires_at!','reminder_days#','notes']};
const readOnly=new Set(['vehicle_timeline']);
const appendOnly=new Set(['vehicle_timeline','sales','customer_payments','cashbook_entries','price_history']);
let mediaOffset=0,generation=0,writing=false,revision=null,ready=false,offset=0,nextOffset=null,selected=null,pendingWrite=null,pendingUpload=null,selectedFile=null;
const uuid=()=>crypto.randomUUID();
async function request(url,options={}){const response=await fetch(url,{...options,credentials:'same-origin',cache:'no-store',redirect:'error'});let body;try{body=await response.json();}catch{throw Error('Unexpected server response. No success has been assumed.');}if(!response.ok){const e=Error(response.status===423?'Cloud operation is locked. No storage operation was performed.':response.status===409?'Conflict or reconciliation required. Refresh and review before changing anything.':body.error||'Request failed.');e.status=response.status;throw e;}return body;}
