for(const [key,[label]] of Object.entries(definitions)){const option=document.createElement('option');option.value=key;option.textContent=label;$('resource').append(option);}editor();
$('resource').addEventListener('change',()=>{generation++;offset=0;nextOffset=null;$('previous').disabled=true;$('more').disabled=true;$('records').replaceChildren();editor();});
