 document_requirements:{columns:'vehicle_id document_type status due_at notes',required:'vehicle_id document_type status'},
 vehicle_age_baselines:{key:'vehicle_id',columns:'purchased_at source_quality notes',required:'source_quality'},
 vehicle_inspections:{columns:'vehicle_id inspected_at inspector odometer_km overall_condition notes checklist_json estimated_repairs',required:'vehicle_id inspected_at'},
 cashbook_entries:{columns:'occurred_at entry_type amount payment_method category accounting_role reference_id description',required:'occurred_at entry_type amount payment_method category accounting_role'},
 reservations:{columns:'vehicle_id customer_name customer_phone token_amount reserved_at expires_at status notes',required:'vehicle_id customer_name reserved_at status'},
 enquiry_notes:{columns:'lead_id vehicle_id customer_name phone asking_price offered_price note followup_at status',required:'status'},
 repair_jobs:{columns:'vehicle_id mechanic description estimated_cost final_cost status started_at completed_at notes',required:'vehicle_id description status'},
 rto_cases:{columns:'vehicle_id procedure stage bank_noc_at applied_at completed_at next_action_at reference_no notes',required:'vehicle_id procedure stage'},
 reminders:{columns:'vehicle_id related_type related_id title due_at status priority notes',required:'title due_at status priority'},
 document_expiries:{columns:'vehicle_id document_type expires_at reminder_days notes',required:'vehicle_id document_type expires_at'},
 auction_plans:{columns:'vehicle_id auction_platform auction_reference expected_resale estimated_repairs estimated_parking estimated_transfer estimated_transport other_estimated_expenses target_profit maximum_bid actual_bid outcome notes',required:'expected_resale maximum_bid outcome'},
};
const payloadFields:Record<string,string>={
 vehicles:'name reg year category fuel owner km bank cost ask status purchaseDate notes chassis engine',
 customers:'name phone address notes',sales:'vehicleId customerId buyer buyerPhone buyerAddress saleDate sale balance paymentMethod notes',
 leads:'name phone interest budget stage source date time notes',
