const specs=[
 ['vehicles_registration_unique','vehicles',['registration_key'],null],
 ['vehicles_chassis_unique','vehicles',['chassis_key'],null],
 ['expenses_vehicle_kind_unique','expenses',['vehicle_id','kind'],null],
 ['uq_document_requirements_vehicle_id_document_type','document_requirements',['vehicle_id','document_type'],null],
 ['uq_document_expiries_vehicle_id_document_type','document_expiries',['vehicle_id','document_type'],null],
 ['uq_vehicle_media_object_key','vehicle_media',['object_key'],null],
 ['uq_vehicle_one_cover_photo','vehicle_media',['vehicle_id'],'is_cover=1 AND archived_at IS NULL'],
 ['uq_vehicle_one_active_reservation','reservations',['vehicle_id'],"status='Active'"]
