function route({owner=true,enabled=false,dbAvailable=true,bucketAvailable=true,
                  missingIndex=false,nonUniqueIndex=false,wrongIndexColumn=false,wrongIndexTable=false,
                  wrongPartialPredicate=false,missingTable=false,badRevision=false,
                  revisionValue='4',foreignKeys=0}={}){
 let databaseCalls=0,bucketCalls=0,selects=[];
 const db={prepare(sql){
  assert.match(sql,/^SELECT |^PRAGMA (?:foreign_key_check|index_info)/,'Only SELECT/PRAGMA reads permitted');
  selects.push(sql);
  const requested=sql.match(/^PRAGMA index_info\('([^']+)'\)/);
  return {
   async all(){
    if(requested){
     const spec=specs.find(x=>x[0]===requested[1]);
     if(!spec)throw Error('Unexpected index name');
     const columns=wrongIndexColumn&&spec[0]===specs[0][0]?['status']:spec[2];
     return {success:true,results:columns.map((name,seqno)=>({name,seqno}))};
    }
    if(sql.includes("type='table'"))return {success:true,results:missingTable?[{name:'vehicles'}]:expectedTables.map(name=>({name}))};
    if(sql.includes("type='index'"))return {success:true,results:(missingIndex?specs.slice(1):specs).map(([name,table,columns,where],i)=>({
     name,tbl_name:wrongIndexTable&&i===0?'incorrect_table':table,
     sql:(nonUniqueIndex&&i===0?'CREATE INDEX ':'CREATE UNIQUE INDEX ')+
      name+' ON '+table+' ('+columns.join(',')+')'+(where?' WHERE '+(wrongPartialPredicate&&name==='uq_vehicle_one_cover_photo'?'is_cover=0 AND archived_at IS NULL':where):'')
    }))};
    if(sql==='PRAGMA foreign_key_check')return {success:true,results:Array(foreignKeys).fill({table:'synthetic'})};
    throw Error('Unexpected D1 query');
   },
   async first(){return {value:badRevision?'bad':revisionValue};}
  };
 }};
 const bucket={async list(input){bucketCalls++;assert.equal(input.limit,1);return {objects:[{key:'PRIVATE_SECRET_DO_NOT_RETURN'}]}}};
 const modules={
  'cloudflare:workers':{env:{BUCKET:bucketAvailable?bucket:undefined}},
  '../../../lib/cloud-server':{
   guard:async()=>owner?{user:{userId:'verified-owner'}}:{error:Response.json({error:'Denied'},{status:403})},
   json:(body,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}}),
   database(){databaseCalls++;if(!dbAvailable)throw Error('No binding');return db;}
  },
  '../../../lib/hosted-preflight-flags':{HOSTED_READONLY_PREFLIGHT_ENABLED:enabled},
  '../../../lib/crm-transfer':{SNAPSHOT_TABLES:expectedTables}
 };
 const exports={};
 const transpiled=ts.transpileModule(fs.readFileSync('app/api/private-crm-preflight/route.ts','utf8'),{
  compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;
 vm.runInNewContext(transpiled,{exports,require(name){if(!Object.hasOwn(modules,name))throw Error('Unexpected import '+name);return modules[name]},
  Response,Request,URL,Set,Number,Array});
 return {GET:exports.GET,get databaseCalls(){return databaseCalls},get bucketCalls(){return bucketCalls},selects};
}
test('nonowner and default lock prevent any D1 or R2 access',async()=>{
 const anonymous=route({owner:false,enabled:true});
 assert.equal((await anonymous.GET(new Request(url))).status,403);
 assert.equal(anonymous.databaseCalls,0);assert.equal(anonymous.bucketCalls,0);
 const locked=route({owner:true,enabled:false});
