#!/usr/bin/env node
// Read-only, staging-only CLI. No secrets, cookies, POSTs or production traffic.
import {readFileSync,statSync} from 'node:fs';
import {stagingOrigin,probeAnonymous,probeSpoofedIdentity,inspectSanitizedPreflight} from '../lib/hosted-staging-audit.mjs';
import {OWNER_EMAIL} from '../lib/cloud-core.mjs';
const args=process.argv.slice(2);
const arg=name=>{const i=args.indexOf(name);return i<0?null:args[i+1]??null;};
try{
 if(args.some(x=>!['--origin','--report'].includes(x)&&
    (args.indexOf('--origin')<0||args[args.indexOf('--origin')+1]!==x)&&
    (args.indexOf('--report')<0||args[args.indexOf('--report')+1]!==x)))
  throw Error('Usage: node scripts/verify-hosted-staging.mjs [--origin https://staging.example] [--report sanitized.json]');
 const origin=arg('--origin'),report=arg('--report');
 if(!origin&&!report)throw Error('Supply a staging origin or an Owner-read-only diagnostic report.');
 if(origin){
  const approved=stagingOrigin(origin);
  const audited=await probeAnonymous(fetch,approved);
  console.log(JSON.stringify(audited,null,2));
  if(/^(?:staging|sandbox|preview)\.crm\.nainamotors\.com$/.test(new URL(approved).hostname)){
   const spoofed=await probeSpoofedIdentity(fetch,approved,OWNER_EMAIL);
   console.log(JSON.stringify(spoofed,null,2));
  }else{
   console.log('HOLD: Forged Owner-header test not attempted on a non-CRM-controlled staging hostname.');
  }
 }
 if(report){
  const stat=statSync(report);if(!stat.isFile()||stat.size>32768||stat.size<10)
   throw Error('Invalid sanitized diagnostic file.');
  const parsed=JSON.parse(readFileSync(report,'utf8'));
  const reviewed=inspectSanitizedPreflight(parsed);
  console.log(JSON.stringify(reviewed,null,2));
 }
 console.log('HOLD: no authenticated Owner, positive D1/R2, backup restore or production release approval established.');
}catch(e){console.error('FAIL: '+(e instanceof Error?e.message:'Staging audit unavailable.'));process.exitCode=1;}

