import { requireOwner } from './owner-auth';
import { PRIVATE_MEDIA_ENABLED, MEDIA_MAX_BYTES } from './private-media-flags';
import { buildMediaRecoveryManifest, RecoveryManifestError } from './media-recovery.mjs';
type Bindings = { DB?: D1Database; BUCKET?: R2Bucket };
type Media = { id:string; vehicle_id:string; object_key:string; original_filename:string; mime_type:string; bytes:number; category:string; archived_at:string|null; notes:string|null; sha256:string; is_cover:number };
class MediaError extends Error { constructor(public status:number, message:string){super(message)} }
const fail=(status:number,message:string):never=>{throw new MediaError(status,message)};
const reply=(data:unknown,status=200)=>Response.json(data,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
const pending='Internal: upload incomplete; reconciliation required';
const formats:Record<string,{mime:string;ext:string[]}>={jpeg:{mime:'image/jpeg',ext:['jpg','jpeg']},png:{mime:'image/png',ext:['png']},webp:{mime:'image/webp',ext:['webp']},pdf:{mime:'application/pdf',ext:['pdf']},heic:{mime:'image/heic',ext:['heic']}};
function id(value:string|null){if(!value||value.length>1024)fail(400,'Invalid identifier.');return value!;}
function filename(value:string|null){if(!value||value.length>180||! /^[A-Za-z0-9][A-Za-z0-9 _().-]*$/.test(value)||value.includes('..'))fail(400,'Use a simple filename without paths.');return value!;}
async function readBytes(request:Request){
 const length=request.headers.get('content-length');
 if(length!==null&&(!/^\d+$/.test(length)||Number(length)>MEDIA_MAX_BYTES))fail(413,'File exceeds size limit.');
 if(!request.body)fail(400,'File is empty.');
 const reader=request.body!.getReader(),chunks:Uint8Array[]=[];let size=0;
 try{while(true){const item=await reader.read();if(item.done)break;size+=item.value.byteLength;if(size>MEDIA_MAX_BYTES)fail(413,'File exceeds size limit.');chunks.push(item.value);}}
 catch(e){await reader.cancel().catch(()=>{});throw e;}finally{reader.releaseLock();}
 if(!size)fail(400,'File is empty.');
 const bytes=new Uint8Array(size);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}return bytes;
}
function format(b:Uint8Array,name:string,mime:string|null){
 const ascii=(start:number,end:number)=>new TextDecoder().decode(b.slice(start,end));let kind='';
 if(b.length>=4&&b[0]===255&&b[1]===216&&b[2]===255&&b.at(-2)===255&&b.at(-1)===217)kind='jpeg';
 if(b.length>=24&&[137,80,78,71,13,10,26,10].every((x,i)=>b[i]===x)&&ascii(12,16)==='IHDR')kind='png';
 if(b.length>=20&&ascii(0,4)==='RIFF'&&ascii(8,12)==='WEBP'&&['VP8 ','VP8L','VP8X'].includes(ascii(12,16))&&new DataView(b.buffer,b.byteOffset,b.byteLength).getUint32(4,true)+8===b.length)kind='webp';
 if(b.length>=12&&/^%PDF-1\.[0-7]|^%PDF-2\.0/.test(ascii(0,8))&&ascii(Math.max(0,b.length-1024),b.length).includes('%%EOF'))kind='pdf';
 if(b.length>=24&&ascii(4,8)==='ftyp'&&['heic','heix'].includes(ascii(8,12))){const box=new DataView(b.buffer,b.byteOffset,b.byteLength).getUint32(0);if(box>=24&&box<=b.length)kind='heic';}
 const f=formats[kind];if(!f||f.mime!==mime||!f.ext.includes(name.split('.').at(-1)!.toLowerCase()))fail(415,'File signature, extension and MIME type must agree.');return f.mime;
}
async function digest(bytes:Uint8Array){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new Uint8Array(bytes)))).map(x=>x.toString(16).padStart(2,'0')).join('');}
async function verifyObject(object:R2ObjectBody,row:Media){
 if(object.size!==row.bytes||object.size>MEDIA_MAX_BYTES||object.customMetadata?.sha256!==row.sha256)fail(409,'File integrity requires review.');
 const bytes=new Uint8Array(await object.arrayBuffer());
 if(bytes.length!==row.bytes||await digest(bytes)!==row.sha256)fail(409,'File checksum mismatch. Metadata retained.');
 format(bytes,row.original_filename,row.mime_type);return bytes;
}
function publicRow(row:Media){const {object_key,notes,...safe}=row;return {...safe,incomplete:notes===pending};}
// All visible media metadata mutations must bump the same D1 revision used by
// cloud-mode cross-device refresh. D1 batch is atomic: metadata and revision
// change together or neither changes. Never mutate the browser-local dataset.
async function commitMediaMutation(db:D1Database,statements:D1PreparedStatement[]){
 const expected=await verifiedRevision(db);
 // Atomic compare-and-set: every media edit shares the CRM global revision
 // and cannot silently recreate, coerce, or overwrite a corrupt revision.
 const check=db.prepare("INSERT INTO cloud_metadata(key,value) VALUES ('media_revision_assert',CASE WHEN (SELECT value FROM cloud_metadata WHERE key='revision')=? THEN 'ok' ELSE NULL END) ON CONFLICT(key) DO UPDATE SET value=excluded.value").bind(String(expected));
 const bump=db.prepare("UPDATE cloud_metadata SET value=? WHERE key='revision'").bind(String(expected+1));
 const results=await db.batch([check,...statements,bump]);
 if(results.some(r=>!r.success))throw Error('Private media revision transaction failed.');
}

// Never coerce absent/invalid global state into a writable revision.
async function verifiedRevision(db:D1Database):Promise<number>{
 const row=await db.prepare("SELECT value FROM cloud_metadata WHERE key='revision'").bind().first<{value:unknown}>();
 const raw=row?.value;
 if(typeof raw!=='string'||!/^(?:0|[1-9][0-9]*)$/.test(raw)||
    !Number.isSafeInteger(Number(raw))||Number(raw)>=Number.MAX_SAFE_INTEGER)
  fail(409,'Cloud revision requires review before private media changes.');
 return Number(raw);
}

// This is the only service entry point. Even internal callers must supply a Request
// and pass the existing platform-backed owner guard; no caller-supplied identity.
export async function handlePrivateMedia(request:Request,bindings:()=>Bindings):Promise<Response>{
 const auth=await requireOwner(request);if('error' in auth)return auth.error;
 if(!PRIVATE_MEDIA_ENABLED)return reply({error:'Private media is not enabled.'},423);
 try{
  const p=new URL(request.url).searchParams;
  for(const key of p.keys())if(!['action','vehicleId','mediaId','filename','category','limit','offset','uploadId'].includes(key)||p.getAll(key).length!==1)fail(400,'Invalid request.');
  const action=p.get('action');
  if(!((request.method==='GET'&&['list','download','preview','export','manifest'].includes(action!))||(request.method==='POST'&&['upload','cover','archive','restore','reconcile'].includes(action!))))fail(405,'Unsupported operation.');
  const {DB:db,BUCKET:bucket}=bindings();if(!db||!bucket)fail(503,'Private storage binding unavailable.');
  const vehicleId=id(p.get('vehicleId'));
  const vehicle=await db!.prepare('SELECT id FROM vehicles WHERE id=?').bind(vehicleId).first();if(!vehicle)fail(404,'Vehicle not found.');
  // Fail BEFORE reading an upload stream or staging media if cloud revision is
  // missing or corrupt; GET remains read-only and does not need this check.
  if(request.method==='POST')await verifiedRevision(db!);
  // Sold vehicles remain eligible. Never mutate inventory or sales.
  if(action==='list'){
   const limit=p.has('limit')?Number(p.get('limit')):50,offset=p.has('offset')?Number(p.get('offset')):0;
   if(!Number.isInteger(limit)||limit<1||limit>100||!Number.isInteger(offset)||offset<0||offset>100000)fail(400,'Invalid pagination.');
   const result=await db!.prepare('SELECT * FROM vehicle_media WHERE vehicle_id=? ORDER BY id LIMIT ? OFFSET ?').bind(vehicleId,limit,offset).all<Media>();
   if(!result.success)throw Error();return reply({items:result.results.map(publicRow),limit,offset});
  }
  if(action==='manifest'){
   // Audits R2 object existence and object HEAD metadata only. No file bytes or secret storage keys are exported.
   const limit=p.has('limit')?Number(p.get('limit')):25,offset=p.has('offset')?Number(p.get('offset')):0;
   return reply(await buildMediaRecoveryManifest(db!,bucket!,vehicleId,{limit,offset}));
  }
  if(action==='upload'){
   const name=filename(p.get('filename')),category=p.get('category');
   if(!['photo','rc','noc','insurance','auction','form','sale','other'].includes(category!))fail(400,'Invalid category.');
   const bytes=await readBytes(request),mime=format(bytes,name,request.headers.get('content-type'));
   if(category==='photo'&&!mime.startsWith('image/'))fail(415,'Photo must be an image.');
   const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new Uint8Array(bytes)))).map(x=>x.toString(16).padStart(2,'0')).join('');
   const token=p.get('uploadId');
   if(token!==null&&!/^[A-Za-z0-9_-]{16,100}$/.test(token))fail(400,'Invalid upload retry token.');
   const mediaId=token?'upload-'+await digest(new TextEncoder().encode(JSON.stringify([vehicleId,token]))):crypto.randomUUID();
   const existing=await db!.prepare('SELECT * FROM vehicle_media WHERE id=? AND vehicle_id=?').bind(mediaId,vehicleId).first<Media>();
   if(existing){
    if(existing.sha256!==hash||existing.bytes!==bytes.length||existing.original_filename!==name||existing.mime_type!==mime||existing.category!==category)fail(409,'Upload token belongs to different content.');
    if(existing.notes!==pending)return reply({id:mediaId,filename:name,bytes:bytes.length,replayed:true});
    // Retry only this staged row's exact bytes; no arbitrary key or active-object overwrite.
    const prior=await bucket!.get(existing.object_key);
    if(prior){await verifyObject(prior,existing);}else{
     const retried=await bucket!.put(existing.object_key,bytes,{httpMetadata:{contentType:mime},customMetadata:{sha256:hash}});if(!retried)throw Error();
    }
    await commitMediaMutation(db!,[db!.prepare('UPDATE vehicle_media SET archived_at=NULL,notes=NULL WHERE id=? AND notes=?').bind(mediaId,pending)]);
    return reply({id:mediaId,filename:name,bytes:bytes.length,replayed:true});
   }
   const key='private/'+crypto.randomUUID();
   // Stage recoverable metadata FIRST. No untracked R2 key on an interrupted put.
   // On uncertain D1 failure do not put bytes, delete objects, or retry inserts.
   const staged=await db!.prepare('INSERT INTO vehicle_media (id,vehicle_id,object_key,original_filename,mime_type,bytes,category,uploaded_by,sha256,archived_at,notes) VALUES (?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP,?)').bind(mediaId,vehicleId,key,name,mime,bytes.length,category!,auth.user!.userId,hash,pending).run();
   if(!staged.success)throw Error();
   const object=await bucket!.put(key,bytes,{httpMetadata:{contentType:mime},customMetadata:{sha256:hash}});if(!object)throw Error();
   await commitMediaMutation(db!,[db!.prepare('UPDATE vehicle_media SET archived_at=NULL,notes=NULL WHERE id=? AND notes=?').bind(mediaId,pending)]);
   return reply({id:mediaId,filename:name,bytes:bytes.length},201);
  }
  const mediaId=id(p.get('mediaId'));
  const row=await db!.prepare('SELECT * FROM vehicle_media WHERE id=? AND vehicle_id=?').bind(mediaId,vehicleId).first<Media>();if(!row)fail(404,'File not found.');
  if(action==='reconcile'){
   if(row!.notes!==pending)return reply({id:mediaId,action,replayed:true});
   const object=await bucket!.get(row!.object_key);if(!object)fail(409,'Upload bytes absent. Retry upload using its original uploadId and identical file.');
   await verifyObject(object!,row!);
   await commitMediaMutation(db!,[db!.prepare('UPDATE vehicle_media SET archived_at=NULL,notes=NULL WHERE id=? AND notes=?').bind(mediaId,pending)]);
   return reply({id:mediaId,action});
  }
  if(row!.notes===pending)fail(409,'Incomplete upload requires reconciliation.');
  if(['download','preview','export'].includes(action!)){
   if(row!.archived_at&&action!=='export')fail(409,'Restore archived metadata before downloading.');
   const object=await bucket!.get(row!.object_key);if(!object)fail(409,'File content unavailable; metadata retained.');
   if(object!.size!==row!.bytes||object!.customMetadata?.sha256!==row!.sha256)fail(409,'File integrity requires review.');
   const bytes=await verifyObject(object!,row!);
   const preview=action==='preview';
   if(preview&&!['image/jpeg','image/png','image/webp'].includes(row!.mime_type))fail(415,'Preview unsupported for this format. Download PDF/HEIC to a compatible application.');
   // No HTML/SVG or inline documents; restrictive headers also apply to raster previews.
   return new Response(bytes,{headers:{'Content-Type':preview?row!.mime_type:'application/octet-stream','Content-Disposition':`${preview?'inline':'attachment'}; filename="${filename(row!.original_filename)}"`,'Content-Length':String(object!.size),'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff','Content-Security-Policy':"sandbox; default-src 'none'",'Cross-Origin-Resource-Policy':'same-origin','Referrer-Policy':'no-referrer'}});
  }
  if(action==='cover'){
   if(row!.archived_at||row!.category!=='photo'||!row!.mime_type.startsWith('image/'))fail(409,'Active photograph required.');
   // D1 batch is transactional. Unique index remains the concurrency backstop.
   await commitMediaMutation(db!,[db!.prepare('UPDATE vehicle_media SET is_cover=0 WHERE vehicle_id=?').bind(vehicleId),db!.prepare('UPDATE vehicle_media SET is_cover=1 WHERE id=? AND vehicle_id=? AND archived_at IS NULL').bind(mediaId,vehicleId)]);
  }else if(action==='archive'){
   await commitMediaMutation(db!,[db!.prepare('UPDATE vehicle_media SET archived_at=CURRENT_TIMESTAMP,is_cover=0 WHERE id=? AND vehicle_id=?').bind(mediaId,vehicleId)]);
  }else{
   const object=await bucket!.get(row!.object_key);if(!object)fail(409,'File content requires recovery.');await verifyObject(object!,row!);
   await commitMediaMutation(db!,[db!.prepare('UPDATE vehicle_media SET archived_at=NULL,is_cover=0 WHERE id=? AND vehicle_id=?').bind(mediaId,vehicleId)]);
  }
  return reply({id:mediaId,action});
 }catch(e){return reply({error:e instanceof MediaError||e instanceof RecoveryManifestError?e.message:'Private media operation incomplete. Metadata retained; retry only after review.'},e instanceof MediaError||e instanceof RecoveryManifestError?e.status:503);}
}

