import test from 'node:test';
import assert from 'node:assert/strict';
import {stagingOrigin,probeAnonymous,probeSpoofedIdentity,inspectSanitizedPreflight,ANONYMOUS_CHECK_COUNT}
 from '../lib/hosted-staging-audit.mjs';
const base='https://staging.crm.nainamotors.com';
function headerMap(values){const m=new Map(Object.entries(values));return {get:k=>m.get(k.toLowerCase())??null};}
const deny=()=>({status:401,headers:headerMap({
 'cache-control':'no-store','x-content-type-options':'nosniff','content-type':'application/json'
 }),json(){throw Error('Protected bodies must not be read.');},text(){throw Error('Body read forbidden.')}});
test('staging audit rejects production/showroom/lookalike/cookie-bearing or unmarked hosts',()=>{
 for(const bad of ['https://crm.nainamotors.com','https://nainamotors.com',
  'https://naina-motors-showroom-staging.example','http://staging.example.com',
  'https://staging.example.com:8443','https://user:pass@staging.example.com',
  'https://staging.example.com/private','https://staging.example.com/?x=1',
  'https://preview-customer.nainamotors.com','https://crm.nainamotors.com.evil.test',
  'https://something.example.com'])assert.throws(()=>stagingOrigin(bad),/staging/);
 assert.equal(stagingOrigin(base+'/'),base);
 assert.equal(stagingOrigin('https://preview.dealer.example'), 'https://preview.dealer.example');
});
test('anonymous staging probe checks all private endpoints using GET with no cookies',async()=>{
 let calls=0;
 const report=await probeAnonymous(async(url,init)=>{
  calls++;assert.ok(url.startsWith(base+'/api/'));
  assert.equal(init.method,'GET');assert.equal(init.credentials,'omit');
  assert.equal(init.redirect,'error');assert.equal(init.cache,'no-store');
  assert.equal(init.headers.Accept,'application/json');
  return deny();
 },base);
 assert.equal(calls,ANONYMOUS_CHECK_COUNT);
 assert.equal(report.protectedRoutesChecked,ANONYMOUS_CHECK_COUNT);
 assert.equal(report.anonymousReadOnlyChecksPassed,true);
 assert.equal(report.productionApproved,false);
 assert.equal(report.ownerSignInVerified,false);
});
test('failed protected response blocks success even when the endpoint is release-locked',async()=>{
 for(const invalid of [
  {status:200,headers:deny().headers},
  {status:423,headers:deny().headers},
  {status:401,headers:headerMap({'cache-control':'public','x-content-type-options':'nosniff'})},
  {status:403,headers:headerMap({'cache-control':'no-store','x-content-type-options':'nosniff','access-control-allow-origin':'*'})},
  {status:403,headers:headerMap({'cache-control':'no-store'})},
 ]){
  let calls=0;
  await assert.rejects(probeAnonymous(async()=>{calls++;return invalid;},base),/anonymous access\/headers failed/);
  assert.equal(calls,1);
 }
});
test('network failure does not create a false staging pass',async()=>{
 await assert.rejects(probeAnonymous(async()=>{throw Error('private underlying exception')},base),
  /probe unavailable/);
});

test('forged Owner headers are denied on every dedicated CRM staging route',async()=>{
 let calls=0;
 const report=await probeSpoofedIdentity(async(url,init)=>{
  calls++;
  assert.ok(url.startsWith(base+'/api/'));
  assert.equal(init.method,'GET');
  assert.equal(init.credentials,'omit');
  assert.equal(init.redirect,'error');
  assert.equal(init.cache,'no-store');
  assert.equal(init.headers['oai-authenticated-user-email'],'owner@example.test');
  assert.equal(init.headers['oai-authenticated-user-id'],'synthetic-forged-owner-id');
  assert.equal(init.headers.authorization,undefined);
  return deny();
 },base,'owner@example.test');
 assert.equal(calls,ANONYMOUS_CHECK_COUNT);
 assert.equal(report.protectedRoutesChecked,ANONYMOUS_CHECK_COUNT);
 assert.equal(report.identitySpoofingVerified,true);
 assert.equal(report.ownerSignInVerified,false);
 assert.equal(report.productionApproved,false);
 assert.doesNotMatch(JSON.stringify(report),/owner@example.test|synthetic-forged-owner-id/);
});
test('forged identity check never sends Owner address to arbitrary staging URLs',async()=>{
 let calls=0;
 await assert.rejects(probeSpoofedIdentity(async()=>{calls++;return deny();},
  'https://preview.dealer.example','owner@example.test'),/restricted/);
 assert.equal(calls,0);
 await assert.rejects(probeSpoofedIdentity(async()=>{calls++;return deny();},
  base,'not an email'),/valid configured Owner/);
 assert.equal(calls,0);
});
test('forged Owner accepted past auth is a blocker even with business switches locked',async()=>{
 for(const invalid of [
  {status:423,headers:deny().headers},
  {status:200,headers:deny().headers},
  {status:403,headers:headerMap({'cache-control':'public','x-content-type-options':'nosniff'})},
  {status:401,headers:headerMap({'cache-control':'no-store','x-content-type-options':'nosniff','access-control-allow-origin':'*'})},
 ]){
  let calls=0;
  await assert.rejects(probeSpoofedIdentity(async()=>{calls++;return invalid;},
   base,'owner@example.test'),/not safely denied/);
  assert.equal(calls,1);
 }
 await assert.rejects(probeSpoofedIdentity(async()=>{throw Error('do not leak this');},
  base,'owner@example.test'),/probe unavailable/);
});

