#!/usr/bin/env node
// One offline Owner action: 27-table D1 equality + all R2 bytes in both copies
// + independent schema/foreign-key/round-trip disposable SQLite rehearsals.
// Inputs are PRIVATE. No writes, network access, cloud restore or GitHub upload.
import {spawnSync} from 'node:child_process';
import {resolve} from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {auditPairedPrivateRecovery} from '../lib/offline-recovery-pair.mjs';

const sqliteVerifier=fileURLToPath(new URL('./verify-cloud-restore.mjs',import.meta.url));
export async function main(args=process.argv.slice(2)){
 if(args.length!==6){
  console.error('Usage: node scripts/verify-private-recovery-readiness.mjs SOURCE_D1.json SOURCE_MEDIA_DIR SOURCE_RAW_SHA256 CANDIDATE_D1.json CANDIDATE_MEDIA_DIR CANDIDATE_RAW_SHA256');
  return 64;
 }
 try{
  const source=args.slice(0,3),candidate=args.slice(3,6);
  const comparison=await auditPairedPrivateRecovery(source,candidate);
  if(!comparison.localCopiesEquivalentAndComplete){
   console.log(JSON.stringify({...comparison,disposableSqliteSourceVerified:false,
    disposableSqliteCandidateVerified:false,releaseReady:false},null,2));
   return 2;
  }
  // Do not log a failed SQLite child's stderr or private file path.
  // This runner tests independent read-only :memory: SQLite on both copies.
  for(const [snapshotPath,independentDigest] of [
   [source[0],source[2]],[candidate[0],candidate[2]]
  ]){
   const result=spawnSync(process.execPath,
    [sqliteVerifier,snapshotPath,independentDigest],{
     encoding:'utf8',timeout:45000,maxBuffer:128*1024,
     env:{...process.env}
    });
   if(result.status!==0||result.error)throw Error('Disposable SQLite rehearsal not verified.');
   let report;
   try{report=JSON.parse(result.stdout);}catch{throw Error('Disposable SQLite receipt malformed.');}
   if(report.valid!==true||report.tableCount!==27||
      report.foreignKeys!=='passed'||report.roundtrip!=='passed'||
      report.persistentWrites!==false||report.mediaBytesVerified!==false)
    throw Error('Disposable SQLite receipt inconsistent.');
  }
  console.log(JSON.stringify({...comparison,
   sqliteRestoreRehearsed:true,
   disposableSqliteSourceVerified:true,
   disposableSqliteCandidateVerified:true,
   hostedD1RestoreVerified:false,hostedR2RestoreVerified:false,
   realOwnerAuthenticationVerified:false,
   productionReleaseApproved:false,
   releaseReady:false,
   note:'Two private local copies and both disposable SQLite rehearsals verified. Hosted Owner identity, offsite backup, genuine D1/R2 restore, live device tests and production approval remain unverified.'
  },null,2));
  return 0;
 }catch{
  console.error('FAIL: Private offline recovery readiness blocked; input backups unchanged. No private paths or business identifiers displayed.');
  return 2;
 }
}
if(process.argv[1]&&import.meta.url===pathToFileURL(resolve(process.argv[1])).href)
 process.exitCode=await main();

