function recoveryPanel(){return `<section class="panel panel-pad"><span class="eyebrow">BROWSER DATA RECOVERY</span><h2>${storageStatus==='missing'?'No saved records in this browser':'Saved records need recovery'}</h2><p>No records have been loaded or replaced. Restore a JSON backup, or return to the browser that holds your records.</p><div class="settings-actions"><label class="filebtn">Choose backup to preview<input type="file" id="restore" accept=".json,application/json"></label>${storageSnapshot!==null?btn('Download original stored data','rawbackup'):btn('Start an empty workspace','startempty')}</div><p>Opening this page does not import bundled Excel records or change browser storage.</p></section>`;}
