// Legacy expense allocation is optional, previewed and never called at startup.
function legacyExpensePlan(){
  const next=JSON.parse(JSON.stringify(state)),rows=[];
  for(const b of next.bikes){
    if(known(b.parking)&&known(b.otherExpenses))continue;
    const before={parking:b.parking,otherExpenses:b.otherExpenses,expenses:b.expenses};
    let parking,other;
    if(known(b.expenses)){
      if(known(b.parking)){parking=num(b.parking);other=num(b.expenses)-parking;}
      else if(known(b.otherExpenses)){other=num(b.otherExpenses);parking=num(b.expenses)-other;}
      else if(known(source(b,'S'))&&known(source(b,'T'))&&num(source(b,'S'))+num(source(b,'T'))===num(b.expenses)){parking=num(source(b,'S'));other=num(source(b,'T'));}
    }
    const applicable=Number.isFinite(parking)&&Number.isFinite(other)&&parking>=0&&other>=0;
    if(applicable){b.parking=parking;b.otherExpenses=other;}
    rows.push({id:b.id,registration:b.reg,before,proposed:applicable?{parking,otherExpenses:other}:null,result:applicable?'Ready for confirmation':'Needs manual review — unchanged'});
  }
  return {next,rows};
}
function previewLegacyExpenses(){
  if(storageStatus!=='ready')return;
  const original=JSON.stringify(state),snapshot=storageSnapshot,{next,rows}=legacyExpensePlan(),count=rows.filter(r=>r.proposed).length;
  showForm('Review legacy expense fields',`<p>${count} records can receive separate fields; ${rows.length-count} need manual review. Original combined expenses, IDs, source rows and markers remain unchanged. No bundled merge or historical removal will run.</p><pre style="white-space:pre-wrap;max-height:45vh;overflow:auto">${esc(JSON.stringify(rows,null,2))}</pre>`,()=>{
    if(!count){notify('No automatic allocation is safe. Review costs individually.');return false;}
    if(storageSnapshot!==snapshot||JSON.stringify(state)!==original){notify('Records changed. Open a fresh preview.');return false;}
    if(!confirm(`Apply only the ${count} expense allocations shown in this preview? Download a backup first.`))return false;
    return save(next);
  },'Confirm previewed allocations','Optional local migration; review every proposed value.');
}
