function overview(){const sold=state.bikes.filter(b=>b.status==='Sold'),available=state.bikes.filter(b=>b.status==='Available'),review=state.bikes.filter(b=>b.status==='Review'),due=state.leads.filter(l=>l.stage!=='Closed'&&l.date&&l.date<=today()),missing=available.filter(b=>docsMissing(b).length),months=new Map();for(const b of sold){if(/^\d{4}-\d{2}-\d{2}$/.test(b.saleDate||'')){const key=b.saleDate.slice(0,7);months.set(key,(months.get(key)||0)+num(b.sale))}}const selected=[...months].sort((a,b)=>a[0].localeCompare(b[0])).slice(-6),max=Math.max(...selected.map(x=>x[1]),1);const latest=[...sold].sort((a,b)=>String(b.saleDate).localeCompare(String(a.saleDate))).slice(0,5);return heading('Business overview','A clear view of your stock, customers and sales.',`<span class="date-chip">${icon('calendar')}${displayDate(today())}</span>${addVehicle()}`)+`<section class="welcome"><div><span class="eyebrow">YOUR DEALERSHIP. ONE WORKSPACE.</span><h2>Welcome back, Saksham.</h2><p>${available.length} vehicles available · ${state.leads.filter(l=>l.stage!=='Closed').length} open enquiries · Let’s keep business moving.</p></div><div class="welcome-right"><div class="welcome-icon">${icon('bike')}</div>${btn('View inventory '+icon('arrow'),'inventory')}</div></section>`+metrics()+`<div class="grid-main"><section class="panel">${panelHead('Sales performance','Last six months with recorded sales','<span class="legend"><i></i> Revenue</span>')}${selected.length?`<div class="chart"><div class="chart-grid">${selected.map(([m,v])=>`<div class="barcol"><span class="bar-value">${money(v)}</span><div class="bar" style="height:${Math.max(1,v/max*125)}px" title="${esc(m)}: ${money(v)}"></div></div>`).join('')}</div></div><div class="bar-labels">${selected.map(([m])=>`<span>${new Date(m+'-01T12:00:00').toLocaleDateString('en-IN',{month:'short',year:'2-digit'})}</span>`).join('')}</div><div class="chart-summary"><div><span>AVERAGE SALE VALUE</span><strong>${sold.length?money(sum(sold,b=>b.sale)/sold.length):'—'}</strong></div><div><span>RECORDED GROSS MARGIN</span><strong>${sum(sold,b=>b.sale)?(sum(sold,profit)/sum(sold,b=>b.sale)*100).toFixed(1)+'%':'—'}</strong></div><div><span>PERIOD</span><strong>All time</strong></div></div>`:empty('Your sales trend starts here','Record a sale with a date to see monthly revenue.')}</section><section class="panel">${panelHead('Needs your attention','The next steps for your dealership','<span class="pill">Action centre</span>')}<div class="action-list">${[['clock','',due.length+' follow-ups due','Keep buyer conversations moving.','enquiries'],['doc','blue',missing.length+' vehicles with document gaps','RC, NOC or FIR / inventory incomplete.','documents'],['alert','',review.length+' stock status conflicts','Confirm mismatches between Excel files.','reviews'],['rupee','green',money(sum(sold,b=>b.balance))+' in buyer dues','Open buyer balances and sale details.','customers']].map(([ic,cls,title,sub,action])=>`<div class="action-item"><span class="action-symbol ${cls}">${icon(ic)}</span><div><strong>${title}</strong><p>${sub}</p></div>${btn(icon('arrow'),action,'icon-button')}</div>`).join('')}</div></section></div><section class="panel">${panelHead('Recent recorded sales','Buyer details and recorded profitability',btn('View sales book '+icon('arrow'),'sales','textbutton'))}${compactSales(latest)}</section><div style="margin-top:16px"><p style="font-size:9px">Totals exclude unresolved status conflicts. Gross profit is before unrecorded overheads. Dates are preserved from your records, including future dates.</p></div>`}
