function drawDocuments(){const rows=state.bikes.filter(b=>matchBike(b)&&(docFilter==='All'||(docFilter==='Available only'?b.status==='Available':b.status==='Available'&&!hasDoc(b,{'RC pending':'rc','NOC pending':'noc','FIR pending':'fir'}[docFilter]))));$('#records').innerHTML=paginated(rows,s=>`<div class="table-wrap"><table><thead><tr><th>Vehicle</th><th>Status</th><th>RC</th><th>NOC</th><th>FIR / inventory</th><th>HSRP</th><th></th></tr></thead><tbody>${s.map(b=>`<tr><td>${vehicleCell(b)}</td><td>${badge(b.status)}</td>${['rc','noc','fir','hsrp'].map(k=>`<td><span class="badge ${hasDoc(b,k)?'':'review'}">${hasDoc(b,k)?'Ready':esc(b.docs?.[k]??source(b,{rc:'K',noc:'L',fir:'J',hsrp:'X'}[k])??'Unknown')}</span></td>`).join('')}<td>${btn('Update','docs','textbutton',b.id)}</td></tr>`).join('')}</tbody></table></div>`)}
function section(title,sub=''){return `<div class="formsection"><h3>${title}</h3>${sub?`<p>${sub}</p>`:''}</div>`}
function input(name,label,value='',type='text',required=false){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="any"':''} maxlength="300"></label>`}
function select(name,label,values,value){const opts=values.includes(value)?values:[value,...values];return `<label>${label}<select name="${name}">${opts.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x||'Not recorded')}</option>`).join('')}</select></label>`}
function textarea(name,label,value=''){return `<label class="wide">${label}<textarea name="${name}" rows="3" maxlength="3000">${esc(value)}</textarea></label>`}
function showForm(title,content,fn,label='Save changes',hint='Changes save on this device.'){clearMediaSelections();submitForm=fn;$('#formtitle').textContent=title;$('#fields').innerHTML=content;$('#formhint').textContent=mainCloudMode?'Cloud preview is read-only. Return to browser data or use Cloud workspace to edit.':hint;$('#form button[type="submit"]').textContent=label;$('#form button[type="submit"]').disabled=mainCloudMode;if(mainCloudMode)for(const field of $('#fields').querySelectorAll('input,select,textarea'))field.disabled=true;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0}
function rawTable(b){return `<div class="rawtable">${[['Original inventory',b.sourceInventory,b.sourceInventoryRow],['Original sales',b.sourceSales,b.sourceSalesRow]].map(([title,rows,row])=>`<h3>${title}${row?' · Excel row '+row:''}</h3>${rows?.length?rows.map(x=>`<div class="row"><span>${esc(x.label)} <small>${esc(x.column)}</small></span><b>${esc(x.value)}</b></div>`).join(''):'<p>No original Excel row for this record.</p>'}`).join('')}</div>`}
// Ephemeral selections only: never serialized into a vehicle or localStorage.
let mediaSelections={photo:[],document:[]},mediaSelectionEpoch=0;
function clearMediaSelections(){mediaSelectionEpoch++;for(const rows of Object.values(mediaSelections))for(const row of rows)if(row.url)URL.revokeObjectURL(row.url);mediaSelections={photo:[],document:[]};}
function vehicleMediaView(b,rows=b.vehicleMedia){return (Array.isArray(rows)?rows:[]).filter(r=>r&&r.vehicle_id===b.id&&!r.archived_at&&typeof r.id==='string'&&typeof r.original_filename==='string').map(r=>({id:r.id,name:r.original_filename,category:r.category,mime:r.mime_type,cover:r.is_cover===1}));}
function mediaGallerySection(b,kind){const photo=kind==='photo',title=photo?'Photo Gallery':'Document Attachments',rows=vehicleMediaView(b).filter(r=>photo?r.category==='photo':r.category!=='photo');
 if(mainCloudMode){
  const enabled=state.cloudMediaEnabled===true;
  const actions=enabled?'<button type="button" data-cloud-media="download" data-id="':'';
  const list=rows.length?'<div class="media-grid">'+rows.map(r=>'<article class="media-tile"><div class="media-placeholder" aria-hidden="true">'+icon(photo?'bike':'doc')+'</div><strong>'+esc(r.name)+'</strong><small>'+esc(r.category)+(r.cover?' · Cover':'')+'</small>'+(enabled?'<button type="button" data-cloud-media="download" data-id="'+esc(r.id)+'" data-vehicle-id="'+esc(b.id)+'">Download</button>'+(photo&&['image/jpeg','image/png','image/webp'].includes(r.mime)?'<button type="button" data-cloud-media="preview" data-id="'+esc(r.id)+'" data-vehicle-id="'+esc(b.id)+'">Preview</button>':'')+(photo&&!r.cover?'<button type="button" data-cloud-media="cover" data-id="'+esc(r.id)+'" data-vehicle-id="'+esc(b.id)+'">Set cover</button>':'')+'<button type="button" data-cloud-media="archive" data-id="'+esc(r.id)+'" data-vehicle-id="'+esc(b.id)+'">Archive</button>':'<span>Storage is not activated</span>')+'</article>').join('')+'</div>':'<div class="media-empty"><strong>No '+(photo?'photos':'documents')+' recorded in cloud metadata.</strong></div>';
  const options=photo?'':'<label>Document category <select data-cloud-media-category><option value="rc">RC</option><option value="noc">Bank NOC</option><option value="form">Form 35 / HPA</option><option value="insurance">Insurance</option><option value="auction">Auction papers</option><option value="sale">Sale documents</option><option value="other">Other / transfer documents</option></select></label>';
  const archivedRows=(Array.isArray(b.vehicleMedia)?b.vehicleMedia:[]).filter(m=>m&&m.vehicle_id===b.id&&Boolean(m.archived_at)&&(photo?m.category==='photo':m.category!=='photo'));
  const archivedList=enabled&&archivedRows.length?'<details class="media-archive"><summary>Archived '+(photo?'photos':'documents')+' ('+archivedRows.length+')</summary>'+archivedRows.map(m=>'<div><span>'+esc(m.original_filename)+'</span> '+(m.notes==='Internal: upload incomplete; reconciliation required'?'<span>Incomplete; reconciliation needed</span>':'<button type="button" data-cloud-media="export" data-id="'+esc(m.id)+'" data-vehicle-id="'+esc(b.id)+'">Export archived original</button>')+'</div>').join('')+'</details>':'';
  const audit=enabled&&photo?'<p><button type="button" data-cloud-media-manifest="'+esc(b.id)+'">Download vehicle media audit (JSON)</button></p><p>Audit contains metadata only, not the actual photos or documents. Download each file separately for an offline backup.</p>':'';
  const upload=enabled?'<div class="media-picker">'+options+'<label>'+(photo?'Take or choose photos':'Choose documents')+'<input type="file" data-cloud-upload="'+kind+'" accept="'+(photo?'image/jpeg,image/png,image/webp,image/heic,.heic':'image/jpeg,image/png,image/webp,image/heic,.heic,application/pdf,.pdf')+'" multiple '+(photo?'capture="environment"':'')+'></label></div><p>Files are uploaded to private R2 only after confirmation; maximum 15 MiB per file. HEIC and PDF do not support inline preview.</p>':'<p>Private R2 storage remains locked. No upload or download is possible in this environment.</p>';
  return '<section class="vehicle-context media-section" aria-label="'+esc(title)+'"><div class="context-heading"><div><span class="eyebrow">PRIVATE CLOUD MEDIA</span><h3>'+esc(title)+'</h3></div><span class="document-status">'+rows.length+' metadata records</span></div>'+list+archivedList+upload+audit+'<p class="context-help">Cloud media actions are independent of browser backups. Sold-vehicle attachments remain linked to their original IDs.</p></section>';
 }
return `<section class="vehicle-context media-section" aria-labelledby="media-${kind}-title"><div class="context-heading"><div><span class="eyebrow">PRIVATE VEHICLE FILES</span><h3 id="media-${kind}-title">${title}</h3></div><span class="document-status">${rows.length} ${photo?'photos':'documents'} in local metadata</span></div><p class="context-help">Cloud files are unavailable. Select files for a temporary preview only — nothing is uploaded or saved with this vehicle.</p>${rows.length?`<div class="media-grid">${rows.map(r=>`<article class="media-tile"><div class="media-placeholder" aria-hidden="true">${icon(photo?'bike':'doc')}</div><strong>${esc(r.name)}</strong><small>${esc(r.category||'Unspecified category')}${r.cover&&photo?' · Cover photo':''}</small><button type="button" disabled>Private preview unavailable</button></article>`).join('')}</div>`:`<div class="media-empty">${icon(photo?'bike':'doc')}<strong>No ${photo?'photos':'attachments'} recorded in this browser</strong><p>Cloud storage has not been connected. This does not confirm whether files exist elsewhere.</p></div>`}<div class="media-picker">${photo?'<label>Take Photo<input type="file" data-media-picker="photo" accept="image/jpeg,image/png,image/webp,image/heic,.heic" capture="environment"></label>':''}<label>${photo?'Choose Photos':'Choose Documents'}<input type="file" data-media-picker="${kind}" accept="image/jpeg,image/png,image/webp,image/heic,.heic${photo?'':',application/pdf,.pdf'}" multiple></label>${photo?'':`<label>Document category<select data-media-category aria-label="Document category">${[['rc','RC'],['noc','Bank NOC'],['form','Form 35'],['insurance','Insurance'],['auction','Auction documents'],['transfer','Transfer papers'],['other','Other']].map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label>`}</div><p class="context-help">JPEG, PNG, WEBP, HEIC${photo?'':' and PDF'} · 15 MiB per file · up to 20 selections. HEIC conversion and PDF preview are not available.</p><div id="media-${kind}-selection" aria-live="polite"></div><div class="context-footer"><p>Uploads and private downloads remain disabled. Closing or switching vehicle records discards these selections.</p><button type="button" disabled>Upload ${photo?'photos':'documents'}</button><button type="button" data-media-clear="${kind}">Clear selections</button></div><p role="status" class="media-upload-status">Upload not started — cloud storage disabled.</p></section>`;}
async function validateMediaSelection(file,kind){
 if(!file||file.size<=0)return 'File is empty.';if(file.size>15*1024*1024)return 'File exceeds 15 MiB.';
 const ext=file.name.split('.').at(-1).toLowerCase(),types={jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp',heic:'image/heic',pdf:'application/pdf'};
 const mime=types[ext];if(!mime||(kind==='photo'&&mime==='application/pdf')||(file.type&&file.type!==mime))return 'Unsupported format or mismatched file type.';
 const bytes=new Uint8Array(await file.slice(0,32).arrayBuffer()),text=(a,b)=>new TextDecoder().decode(bytes.slice(a,b));
 const valid=mime==='image/jpeg'?bytes[0]===255&&bytes[1]===216&&bytes[2]===255:mime==='image/png'?[137,80,78,71,13,10,26,10].every((v,i)=>bytes[i]===v):mime==='image/webp'?text(0,4)==='RIFF'&&text(8,12)==='WEBP':mime==='application/pdf'?text(0,5)==='%PDF-':text(4,8)==='ftyp'&&['heic','heix'].includes(text(8,12));
 return valid?null:'File signature does not match its extension.';
}
function drawMediaSelections(kind){const target=$(`#media-${kind}-selection`);if(!target)return;target.innerHTML=`<h4>Selected on this device · Not uploaded (${mediaSelections[kind].length})</h4><div class="media-grid">${mediaSelections[kind].map((r,i)=>`<article class="media-tile">${r.url?`<button type="button" class="media-thumbnail" data-media-preview="${kind}:${i}" aria-label="Preview ${esc(r.name)}"><img src="${esc(r.url)}" alt="Temporary preview of ${esc(r.name)}"></button>`:'<div class="media-placeholder" aria-hidden="true">'+icon('doc')+'</div>'}<strong>${esc(r.name)}</strong><small>${esc(r.category)}</small><p class="${r.error?'media-error':'context-help'}">${esc(r.error|| (r.url?'Temporary preview only — not uploaded.':'Selected only. Preview/conversion unavailable; not uploaded.'))}</p></article>`).join('')}</div>`;}
async function selectVehicleMedia(files,kind,category){const epoch=mediaSelectionEpoch;const selected=Array.from(files).slice(0,20),rows=[];for(const file of selected){let error;try{error=await validateMediaSelection(file,kind);}catch{error='Unable to read this file.';}if(epoch!==mediaSelectionEpoch){for(const r of rows)if(r.url)URL.revokeObjectURL(r.url);return;}const ext=file.name.split('.').at(-1).toLowerCase();rows.push({name:file.name,category,error,url:!error&&['jpg','jpeg','png','webp'].includes(ext)?URL.createObjectURL(file):null});}
 if(epoch!==mediaSelectionEpoch){for(const r of rows)if(r.url)URL.revokeObjectURL(r.url);return;}
 for(const r of mediaSelections[kind])if(r.url)URL.revokeObjectURL(r.url);mediaSelections[kind]=rows;drawMediaSelections(kind);
 if(files.length>20){const n=document.createElement('p');n.textContent='Only the first 20 files were selected. Choose fewer files.';$(`#media-${kind}-selection`).appendChild(n);}
}
function closeMediaPreview(){const d=$('#media-preview-dialog');if(d){d.close();d.remove();}}
function openMediaPreview(kind,index){const r=mediaSelections[kind]?.[index];if(!r?.url)return;closeMediaPreview();const d=document.createElement('dialog');d.id='media-preview-dialog';d.className='media-preview-dialog';d.setAttribute('aria-label','Temporary photo preview');d.innerHTML=`<button type="button" data-media-preview-close autofocus>Close preview</button><p>${esc(r.name)} · Not uploaded</p><img src="${esc(r.url)}" alt="${esc(r.name)}">`;document.body.appendChild(d);d.showModal();}
document.addEventListener('change',e=>{const kind=e.target.dataset?.mediaPicker;if(!['photo','document'].includes(kind))return;mediaSelectionEpoch++;selectVehicleMedia(Array.from(e.target.files),kind,kind==='photo'?'photo':($('[data-media-category]')?.value||'other'));e.target.value='';});
document.addEventListener('click',e=>{const el=e.target.closest('[data-media-preview],[data-media-clear],[data-media-preview-close]');if(!el)return;if(el.hasAttribute('data-media-preview-close')){closeMediaPreview();return;}if(el.dataset.mediaPreview){const [kind,index]=el.dataset.mediaPreview.split(':');openMediaPreview(kind,Number(index));}if(el.dataset.mediaClear){const kind=el.dataset.mediaClear;mediaSelectionEpoch++;for(const r of mediaSelections[kind])if(r.url)URL.revokeObjectURL(r.url);mediaSelections[kind]=[];drawMediaSelections(kind);}});
$('#modal').addEventListener('close',()=>{closeMediaPreview();clearMediaSelections();});

// Read-only presentation adapters. No fetch, persistence, inference from sale status,
// or conversion of legacy records. Future cloud rows must match the vehicle ID.
function vehicleLocationView(b,row=b.vehicleLocation){
 if(!row||typeof row!=='object'||Array.isArray(row)||(row.vehicle_id!==undefined&&row.vehicle_id!==b.id))return {type:'Location not assigned',label:'Not recorded',notes:'Not recorded',updated:'Not recorded'};
 const text=v=>typeof v==='string'&&v.trim()?v:'Not recorded';
 return {type:text(row.location_type)==='Not recorded'?'Location not assigned':text(row.location_type),label:text(row.location_label),notes:text(row.notes),updated:text(row.changed_at)};
}
function documentChecklistView(b){
 const definitions=[['rc','Registration Certificate (RC)','K'],['noc','Bank NOC','L'],['form35','Form 35'],['hpa','HPA removal'],['insurance','Insurance'],['puc','PUC'],['auctionLetter','Auction sale letter'],['transfer','Vehicle transfer documents'],['fir','FIR / inventory','J'],['hsrp','HSRP','X'],['printed','Documents printed','W']];
 const docs=b.docs&&typeof b.docs==='object'&&!Array.isArray(b.docs)?b.docs:{};
 const extra=Object.keys(docs).filter(k=>!definitions.some(d=>d[0]===k));
 const items=[...definitions,...extra.map(k=>[k,k])].map(([key,label,column])=>{
  const raw=docs[key]??(column?source(b,column):undefined),value=typeof raw==='string'?raw:typeof raw==='boolean'||typeof raw==='number'?String(raw):raw==null?'':'Unrecognized structured value';
  const normalized=value.trim().toUpperCase();
  const status=({YES:'Received',RECEIVED:'Received',NO:'Pending',MISSING:'Pending',PENDING:'Pending','IN PROGRESS':'In Progress','NOT APPLICABLE':'Not Applicable','N/A':'Not Applicable'})[normalized]||'Not Recorded';
  const group=status==='Received'?'complete':['Pending','In Progress'].includes(status)?'pending':status==='Not Applicable'?'na':'unknown';
  return {key,label,value,status,group};
 });
 // Independent D1 checklist rows appear separately from the original Excel flags.
 for(const row of Array.isArray(b.cloudDocuments)?b.cloudDocuments:[]){
  if(!row||typeof row!=='object'||row.vehicle_id!==b.id)continue;
  const raw=typeof row.status==='string'?row.status:'Not Recorded';
  const lower=raw.trim().toLowerCase();
  items.push({key:'cloud:'+String(row.id||''),label:'Cloud · '+String(row.document_type||'Document requirement'),
   value:raw,status:raw,group:['received','complete','completed'].includes(lower)?'complete':['pending','in progress'].includes(lower)?'pending':['not applicable','n/a'].includes(lower)?'na':'unknown'});
 }
 const counts={complete:0,pending:0,unknown:0,na:0};items.forEach(x=>counts[x.group]++);return {items,counts};
}
function locationSection(b){const v=vehicleLocationView(b);return `<section class="vehicle-context" aria-labelledby="vehicle-location-title"><div class="context-heading"><div><span class="eyebrow">STOCK MANAGEMENT</span><h3 id="vehicle-location-title">Vehicle Location</h3></div><span class="context-icon" aria-hidden="true">${icon('box')}</span></div><dl class="location-grid">${[['Current location',v.type],['Specific location / parking spot',v.label],['Location notes',v.notes],['Last updated',v.updated]].map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="context-help">Showroom · Godown · Mechanic · In Transit · Other</p><div class="context-footer"><p id="location-disabled">${mainCloudMode&&state.cloudEditsEnabled?'D1 location editing requires confirmation; browser records stay unchanged.':'Read-only. Location editing is unavailable until cloud integration is approved.'}</p>${mainCloudMode&&state.cloudEditsEnabled?`<button type="button" data-cloud-edit="location" data-id="${esc(b.id)}">Edit cloud location</button>`:'<button type="button" disabled aria-describedby="location-disabled">Edit location</button>'}</div></section>`;}
function documentChecklistSection(b){const {items,counts}=documentChecklistView(b);return `<section class="vehicle-context" aria-labelledby="document-checklist-title"><div class="context-heading"><div><span class="eyebrow">VEHICLE PAPERWORK</span><h3 id="document-checklist-title">Document Checklist</h3></div><span class="context-icon" aria-hidden="true">${icon('doc')}</span></div><div class="document-counts" aria-label="Document status summary"><span><b>${counts.complete}</b> completed</span><span><b>${counts.pending}</b> pending / in progress</span><span><b>${counts.unknown}</b> unknown</span><span><b>${counts.na}</b> not applicable</span></div><p class="context-help">Existing stock document values only. Buyer handover remains separate below. Unrecorded items are checklist prompts, not proof of a missing document.</p><ul class="document-checklist">${items.map(x=>`<li><div><strong>${esc(x.label)}</strong>${x.value?`<small>Recorded value: ${esc(x.value)}</small>`:'<small>No status recorded</small>'}</div><span class="document-status ${x.group}"><span aria-hidden="true">${x.group==='complete'?'✓':x.group==='pending'?'◷':x.group==='na'?'—':'?'}</span> ${esc(x.status)}</span></li>`).join('')}</ul><div class="context-footer"><p id="checklist-disabled">${mainCloudMode&&state.cloudEditsEnabled?'Only independent D1 checklist statuses can be edited; original Excel values stay unchanged.':'Checklist editing and uploads are unavailable. Existing local document controls below remain available.'}</p>${mainCloudMode&&state.cloudEditsEnabled?`<button type="button" data-cloud-edit="document" data-id="${esc(b.id)}">Edit cloud checklist</button>`:'<button type="button" disabled aria-describedby="checklist-disabled">Edit checklist</button>'}<button type="button" disabled aria-describedby="checklist-disabled">Upload documents</button></div></section>`;}

function showDetails(id,tab='vehicle'){const b=state.bikes.find(x=>x.id===id);if(!b)return;modalBikeId=id;const panes=[['vehicle','Vehicle'],['costs','Costs'],['buyer','Buyer & sale'],['docs','Documents'],['work','RTO & repairs'],['source','Original Excel']];const content=`<div class="detail-summary"><div><h3>${esc(b.name)}</h3><p>${esc(b.reg)} · ${esc(b.year||'Year unknown')}</p></div>${badge(b.status)}</div><div class="detail-actions">${mainCloudMode?(state.cloudEditsEnabled?`<button type="button" data-cloud-vehicle="edit" data-id="${esc(b.id)}">Edit cloud vehicle</button><button type="button" data-cloud-vehicle="price" data-id="${esc(b.id)}">Change asking price</button>`:'<span>Cloud inventory read-only</span>'):`${b.status==='Available'?btn('Record sale','sell','primary',id)+btn('Listing text','listing','',id):''}${b.status==='Sold'?btn('Return to available','reopen','',id):''}${btn('Remove vehicle','delete','danger',id)}`}</div><div class="detail-tabs">${panes.map(([k,l])=>`<button type="button" data-tab="${k}" class="${tab===k?'selected':''}">${l}</button>`).join('')}</div><div class="detail-pane" data-pane="vehicle" ${tab!=='vehicle'?'hidden':''}><div class="fields">${b.status==='Review'?`<div class="note warn wide">Inventory: ${esc(b.sourceInventoryStatus)}. Sales: ${esc(b.sourceSalesStatus)}. Confirm the correct dashboard status below.</div>`+select('status','Resolve status',['Review','Available','Sold'],b.status):''}${input('name','Vehicle brand & model',b.name,'text',true)}${input('reg','Registration number',b.reg)}${input('year','Model year',b.year,'number')}${input('km','Kilometres (blank if unknown)',b.km??'','number')}${select('owner','Ownership',['','1st','2nd','3rd','4th+'],b.owner||'')}${input('bank','Bank / financier',b.bank||'')}${input('engine','Engine number',b.engine||'')}${input('chassis','Chassis number',b.chassis||'')}${textarea('notes','Notes / condition',b.notes||'')}</div>${locationSection(b)}${mediaGallerySection(b,'photo')}</div><div class="detail-pane" data-pane="costs" ${tab!=='costs'?'hidden':''}><div class="fields">${section('Vehicle costs','Purchase + parking + other expenses = landed cost.')}${b.costSplitNote?`<div class="note warn wide">${esc(b.costSplitNote)}</div>`:''}${input('cost','Purchase / bid price (₹)',b.cost??'','number')}${input('parking','Parking charges (₹)',b.parking??'','number')}${input('otherExpenses','Other expenses (₹)',b.otherExpenses??'','number')}${input('ask','Expected selling price (₹)',b.ask??'','number')}${input('challan','Challan amount / status (separate)',b.challan??'')}${`<label>Landed cost<div class="readonly" id="liveCost">${money(total(b))}</div></label>`}<p class="wide">Challan is not automatically added to landed cost. Include an actual paid amount in other expenses if appropriate.</p></div>${vehicleFinanceSection(b)}${auctionSection(b)}</div><div class="detail-pane" data-pane="buyer" ${tab!=='buyer'?'hidden':''}><div class="fields">${section('Sale and buyer details','Save a sale from Record sale to move an available vehicle into the sales book.')}${input('sale','Selling price (₹)',b.sale??'','number')}${input('balance','Remaining amount (₹)',b.balance??'','number')}${input('saleDate','Sale date (YYYY-MM-DD)',b.saleDate||'')}${input('buyer','Buyer name',b.buyer||'')}${input('buyerPhone','Buyer contact',b.buyerPhone||'','tel')}${input('buyerAddress','Buyer address',b.buyerAddress||'')}</div>${reservationSection(b)}</div><div class="detail-pane" data-pane="docs" ${tab!=='docs'?'hidden':''}>${documentChecklistSection(b)}${mediaGallerySection(b,'document')}<div class="fields">${section('Stock documents','Existing source values remain visible under Original Excel.')}${[['rc','RC','K'],['noc','NOC','L'],['fir','FIR / inventory','J'],['hsrp','HSRP','X'],['printed','Documents printed','W']].map(([k,l,c])=>select('doc_'+k,l,['Unknown','YES','NO'],String(b.docs?.[k]??source(b,c)??'Unknown'))).join('')}${section('Buyer handover documents')}${[['fir','FIR / inventory provided','L'],['noc','NOC provided','M'],['rc','RC provided','N'],['bond','Bond received','O']].map(([k,l,c])=>select('handover_'+k,l,['Unknown','YES','NO'],String(b.handover?.[k]??source(b,c,'sourceSales')??'Unknown'))).join('')}</div></div><div class="detail-pane" data-pane="work" ${tab!=='work'?'hidden':''}>${rtoSection(b)}${repairsSection(b)}${inspectionSection(b)}</div><div class="detail-pane" data-pane="source" ${tab!=='source'?'hidden':''}>${b.localMergeNote?`<p class="note">${esc(b.localMergeNote)}</p>`:''}${rawTable(b)}</div>`;
showForm('Vehicle record',content,d=>{if(d.year&&(!Number.isInteger(Number(d.year))||+d.year<1950||+d.year>new Date().getFullYear()+1)){notify('Enter a valid model year.');switchTab('vehicle');return false}if(d.reg&&norm(d.reg)!=='UNREG'&&state.bikes.some(x=>x.id!==id&&norm(x.reg)===norm(d.reg))){notify('Another vehicle already has this registration.');switchTab('vehicle');return false}const docs={...b.docs},handover={...b.handover};for(const k of Object.keys(d)){if(k.startsWith('doc_')){docs[k.slice(4)]=d[k];delete d[k]}if(k.startsWith('handover_')){handover[k.slice(9)]=d[k];delete d[k]}}for(const k of ['cost','parking','otherExpenses','ask','km','sale','balance'])d[k]=known(d[k])?Number(d[k]):null;const status=d.status||b.status;if(status==='Sold'&&!known(d.sale)){notify('A sold vehicle needs its selling price.');switchTab('buyer');return false}if(known(d.sale)&&known(d.balance)&&d.balance>d.sale){notify('Remaining amount cannot exceed selling price.');switchTab('buyer');return false}const updated={...b,...d,status,docs,handover,expenses:known(d.parking)&&known(d.otherExpenses)?num(d.parking)+num(d.otherExpenses):b.expenses};return save({...state,bikes:state.bikes.map(x=>x.id===id?updated:x)})});}
function switchTab(tab){$$('[data-pane]').forEach(e=>e.hidden=e.dataset.pane!==tab);$$('[data-tab]').forEach(e=>e.classList.toggle('selected',e.dataset.tab===tab))}
function addBike(){modalBikeId=null;showForm('Add a vehicle',`<div class="fields">${section('Vehicle information')}${input('name','Brand & model','','text',true)}${input('reg','Registration number')}${input('year','Model year',new Date().getFullYear(),'number',true)}${input('km','Kilometres (blank if unknown)','','number')}${select('owner','Ownership',['','1st','2nd','3rd','4th+'],'')}${input('bank','Bank / financier')}${input('engine','Engine number')}${input('chassis','Chassis number')}${section('Purchase and expenses','Each cost is recorded separately.')}${input('cost','Purchase / bid price (₹)','','number',true)}${input('parking','Parking charges (₹)',0,'number',true)}${input('otherExpenses','Other expenses (₹)',0,'number',true)}${input('ask','Expected selling price (₹)','','number')}${textarea('notes','Condition / notes')}</div>`,d=>{if(+d.year<1950||+d.year>new Date().getFullYear()+1||!Number.isInteger(+d.year)){notify('Enter a valid model year.');return false}if(d.reg&&norm(d.reg)!=='UNREG'&&state.bikes.some(b=>norm(b.reg)===norm(d.reg))){notify('This registration is already in your inventory.');return false}for(const k of ['cost','parking','otherExpenses','ask','km'])d[k]=known(d[k])?Number(d[k]):null;return save({...state,bikes:[{...d,id:crypto.randomUUID(),status:'Available',expenses:num(d.parking)+num(d.otherExpenses)},...state.bikes]})},'Add vehicle')}
function recordSale(id){const b=state.bikes.find(x=>x.id===id);showForm('Record a sale',`<div class="detail-summary"><div><h3>${esc(b.name)}</h3><p>${esc(b.reg)} · Landed cost ${money(total(b))}</p></div></div><div class="fields">${input('sale','Selling price (₹)',b.ask??'','number',true)}${input('balance','Remaining amount (₹)',0,'number',true)}${input('saleDate','Sale date',today(),'date',true)}${input('buyer','Buyer name','','text',true)}${input('buyerPhone','Contact number','','tel')}${textarea('buyerAddress','Buyer address')}</div>`,d=>{if(num(d.balance)>num(d.sale)){notify('Remaining amount cannot exceed selling price.');return false}return save({...state,bikes:state.bikes.map(x=>x.id===id?{...x,...d,sale:num(d.sale),balance:num(d.balance),status:'Sold'}:x)})},'Complete sale')}
function leadForm(id){const l=state.leads.find(x=>x.id===id)||{};showForm(id?'Customer enquiry':'New customer enquiry',`<div class="fields">${input('name','Customer name',l.name||'','text',true)}${input('phone','Contact number',l.phone||'','tel',true)}${input('interest','Interested vehicle / preference',l.interest||'')}${input('budget','Budget (₹)',l.budget??'','number')}${select('source','Lead source',['WhatsApp','OLX','Walk-in','Network','Facebook','Other'],l.source||'WhatsApp')}${select('stage','Pipeline stage',stages,l.stage||'New')}${input('date','Next follow-up',l.date||'','date')}${input('time','Follow-up time',l.time||'','time')}${textarea('notes','Conversation notes / next step',l.notes||'')}</div>`,d=>{const item={...l,...d,budget:known(d.budget)?Number(d.budget):null,id:id||crypto.randomUUID()};return save({...state,leads:id?state.leads.map(x=>x.id===id?item:x):[item,...state.leads]})})}
function listing(id){const b=state.bikes.find(x=>x.id===id),lines=[`${b.name} | ${b.year||''}`,b.km!==null&&known(b.km)?num(b.km).toLocaleString('en-IN')+' km driven':'',b.owner?b.owner+' owner':'',known(b.ask)?'Asking price: '+money(b.ask):'Contact for price',b.notes||'','Naina Motors, Shastri Nagar, Kanpur','Contact us to arrange a viewing.'];showForm('Vehicle listing text',`<div class="fields"><label class="wide">Copy this text to your listing<textarea rows="11" readonly>${esc(lines.filter(Boolean).join('\n'))}</textarea></label></div>`,()=>true,'Done','Review the details before posting.')}
function calculator(){return heading('Auction bid calculator','Know your maximum bid before the auction starts.')+`<div class="calc-grid"><section class="panel">${panelHead('Deal assumptions','Example figures — enter your own estimates')}<div class="fields" id="calcfields">${[['resale','Expected resale price',100000],['bid','Auction bid',65000],['parking','Parking charges',1500],['repairs','Repairs',5000],['docs','Transfer & documents',2500],['transport','Transport',1500],['other','Other costs / auction fees',1000],['target','Desired profit',15000]].map(([id,l,v])=>`<label>${l} (₹)<input id="calc_${id}" type="number" min="0" step="100" value="${v}"></label>`).join('')}</div></section><section class="result" id="result"></section></div>`}
function calculate(){const v={};for(const k of ['resale','bid','parking','repairs','docs','transport','other','target'])v[k]=Math.max(0,num($('#calc_'+k).value));const expenses=v.parking+v.repairs+v.docs+v.transport+v.other,cost=v.bid+expenses,p=v.resale-cost,max=v.resale-expenses-v.target;$('#result').innerHTML=`<span class="eyebrow">MAXIMUM BID TO MEET YOUR TARGET</span><strong>${max<0?'No viable bid':money(max)}</strong><p>${max<0?'Expenses and desired profit exceed the resale price.':v.bid<=max?'Your bid is within the target.':'Your bid exceeds the target by '+money(v.bid-max)+'.'}</p><div style="margin-top:28px">${[['Total landed cost',money(cost)],['Expected gross profit',money(p)],['Return on cost',cost?(p/cost*100).toFixed(1)+'%':'—'],['Profit margin',v.resale?(p/v.resale*100).toFixed(1)+'%':'—']].map(([l,n])=>`<div class="row"><span>${l}</span><b>${n}</b></div>`).join('')}</div><p style="margin-top:27px">Maximum bid = resale − parking − all other costs − desired profit. Include applicable fees and taxes in your estimates.</p>`}
function settings(){return heading('Data & workspace','Your records, originals and backups in one place.')+`<div class="settings-grid"><section class="panel panel-pad"><span class="eyebrow">YOUR BUSINESS DATA</span><h2>Backup & restore</h2><p>Existing records load without automatic changes. Owner edits save in this browser only. Download a full backup regularly to preserve new vehicles, customer details and enquiries.</p><div class="settings-actions">${btn(icon('download')+' Full backup','backup','primary')}<label class="filebtn">Restore backup<input type="file" id="restore" accept=".json,application/json"></label></div><div class="note" style="margin:20px 0 0">No automatic cross-device sync. Restore replaces this browser’s records after confirmation. Original Excel files remain unchanged.</div></section><section class="panel panel-pad"><span class="eyebrow">IMPORTED RECORDS</span><h2>Excel source history</h2><p>${esc(state.importMeta?.inventoryFile||'Inventory workbook')}<br>${esc(state.importMeta?.salesFile||'Sales workbook')}</p><p>Original source rows and historical migration markers are retained as stored. Bundled imports and historical removals do not run automatically.</p><div class="settings-actions">${btn('Export inventory CSV','csv')}${btn('Export sales CSV','salescsv')}</div></section><section class="panel panel-pad"><span class="eyebrow">COST DEFINITIONS</span><h2>Separate, traceable expenses</h2><p>Purchase price comes from BID PRICE. Parking comes from PARKING. Other expenses come from EXPENSE. These three values sum to landed cost. Where separate components are missing, totals use the stored combined expense without allocating it. Unknown totals remain unknown.</p><p>Challans are recorded separately, matching the original workbook’s cost treatment.</p>${btn('Preview legacy expense allocation','legacyexpenses')}</section><section class="panel panel-pad"><span class="eyebrow">PRIVACY & ACCESS</span><h2>Private owner workspace</h2><p>Use the same app URL to return to this workspace. Each browser has its own saved changes. This app does not send customer messages or modify the original Excel files.</p><p>${state.bikes.length} vehicle records · ${state.leads.length} enquiries currently on this device.</p></section></div>`}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function backup(){if(mainCloudMode){notify('Cloud data is not a browser backup. Export your D1 snapshot from Cloud workspace.');return;}if(storageStatus!=='ready'){rawBackup();return;}download(JSON.stringify({version:3,exportedAt:new Date().toISOString(),...state},null,2),'naina-motors-backup-'+today()+'.json','application/json')}
function exportCSV(salesOnly=false){const keys=salesOnly?['name','reg','year','buyer','buyerPhone','buyerAddress','saleDate','cost','parking','otherExpenses','landedCost','sale','grossProfit','balance']:['name','reg','chassis','engine','year','km','owner','status','bank','cost','parking','otherExpenses','landedCost','ask','challan','sourceInventoryStatus','sourceSalesStatus'];const quote=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const rows=state.bikes.filter(b=>!salesOnly||b.status==='Sold').map(b=>keys.map(k=>k==='landedCost'?total(b):k==='grossProfit'?profit(b):b[k]));download('\ufeff'+[keys,...rows].map(r=>r.map(quote).join(',')).join('\r\n'),'naina-motors-'+(salesOnly?'sales':'inventory')+'-'+today()+'.csv','text/csv;charset=utf-8')}
function validateBackup(d){if(![1,2,3].includes(d.version)||!Array.isArray(d.bikes)||!Array.isArray(d.leads))throw Error('Invalid format');for(const b of d.bikes){if(typeof b.id!=='string'||typeof b.name!=='string'||!['Available','Sold','Review'].includes(b.status))throw Error('Invalid vehicle');for(const k of ['cost','expenses','parking','otherExpenses','ask','sale','balance','km'])if(b[k]!==null&&b[k]!==undefined&&b[k]!==''&&(!known(b[k])||num(b[k])<0))throw Error('Invalid amount');for(const k of ['sourceInventory','sourceSales'])if(b[k]!==undefined&&(!Array.isArray(b[k])||b[k].some(x=>!x||typeof x!=='object')))throw Error('Invalid source')}for(const l of d.leads){if(typeof l.id!=='string'||typeof l.name!=='string'||typeof(l.phone||'')!=='string')throw Error('Invalid enquiry')}if(new Set(d.bikes.map(b=>b.id)).size!==d.bikes.length||new Set(d.leads.map(l=>l.id)).size!==d.leads.length)throw Error('Duplicate IDs');if(d.appliedChanges!==undefined&&(!Array.isArray(d.appliedChanges)||d.appliedChanges.some(x=>typeof x!=='string')))throw Error('Invalid metadata');return true}
async function restore(e){
  if(mainCloudMode){notify('Switch back to this browser before restoring a browser backup.');e.target.value='';return;}
  const snapshot=storageSnapshot;
  try{
    const file=e.target.files?.[0];if(!file)return;
    const d=JSON.parse(await file.text());validateBackup(d);
    const counts=['Available','Sold','Review'].map(s=>`${s}: ${d.bikes.filter(b=>b.status===s).length}`).join(' · ');
    if(!confirm(`Restore preview: ${d.bikes.length} vehicles and ${d.leads.length} enquiries. ${counts}.\nThis replaces this browser’s records exactly as supplied, including its original markers. No legacy transformations will run. Download your current backup first. Continue?`))return;
    if(snapshot!==storageSnapshot)throw Error('Records changed while reading the backup. Preview again.');
    if(save(d,{recovery:true})){render();notify('Backup restored without transformations.');}
  }catch(e){notify('Could not restore: '+e.message);}finally{e.target.value='';}
}
// Read-only management projections. Exact schema keys; no persistence or cloud calls.
function managementRows(table,vehicleId){const allowed=['cashbook_entries','customer_payments','repair_jobs','rto_cases','reminders','document_expiries','vehicle_inspections','auction_plans'];if(!allowed.includes(table))return [];return (Array.isArray(state[table])?state[table]:[]).filter(r=>r&&typeof r==='object'&&!Array.isArray(r)&&(vehicleId===undefined||r.vehicle_id===vehicleId));}
function financeAmount(v){if((typeof v!=='number'&&typeof v!=='string')||(typeof v==='string'&&!v.trim()))return null;const n=Number(v);return Number.isFinite(n)&&n>=0?n:null;}
function financeVehicle(b){const purchase=financeAmount(b.cost),parking=financeAmount(b.parking),other=financeAmount(b.otherExpenses),legacy=financeAmount(b.expenses),sale=financeAmount(b.sale),balance=financeAmount(b.balance);const separate=parking!==null&&other!==null,expenses=separate?parking+other:legacy,conflict=separate&&legacy!==null&&Math.abs(expenses-legacy)>0.000001;const landed=purchase===null||expenses===null||conflict?null:purchase+expenses;return {purchase,parking,other,legacy,expenses,conflict,landed,gross:b.status==='Sold'&&sale!==null&&landed!==null?sale-landed:null,sale,balance};}
function financialSummary(values){const recorded=values.filter(v=>v!==null&&Number.isFinite(v));return {value:recorded.length?recorded.reduce((a,b)=>a+b,0):null,known:recorded.length,unknown:values.length-recorded.length};}
function managementMoney(v){return v===null||!Number.isFinite(v)?'Not recorded':money(v);}
function managementDate(value){
 if(typeof value!=='string'||!value.trim())return {day:null,text:'Not recorded'};
 if(/^\d{4}-\d{2}-\d{2}$/.test(value)){const d=new Date(value+'T00:00:00Z');if(Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===value)return {day:value,text:new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',day:'numeric',month:'short',year:'numeric'}).format(d)};}
 if(/^\d{4}-\d{2}-\d{2}T.*(?:Z|[+-]\d{2}:\d{2})$/.test(value)){const d=new Date(value);if(Number.isFinite(d.getTime()))return {day:new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(d),text:new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',dateStyle:'medium',timeStyle:'short'}).format(d)+' IST'};}
 return {day:null,text:value+' (date requires review)'};
}
function managementStatus(value){const raw=typeof value==='string'&&value.trim()?value:'Not recorded',s=raw.toLowerCase();return {raw,tone:['completed','done','received'].includes(s)?'complete':['pending','open','in progress'].includes(s)?'pending':'unknown'};}
function managementBadge(value){const s=managementStatus(value);return `<span class="document-status ${s.tone}">${esc(s.raw)}</span>`;}
function managementFields(pairs){return `<dl class="location-grid">${pairs.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v??'Not recorded')}</dd></div>`).join('')}</dl>`;}
function managementPanel(title,body,action='Add record'){return `<section class="vehicle-context management-panel"><div class="context-heading"><h3>${esc(title)}</h3><span class="pill">Read-only</span></div>${body}<div class="context-footer"><p>Cloud editing is unavailable. Viewing this section does not change records.</p><button type="button" disabled>${esc(action)}</button></div></section>`;}
function managementEmpty(label){return `<p class="management-empty">No ${esc(label)} recorded in this browser. Cloud data is unavailable.</p>`;}
function rtoSection(b){
 const docs=documentChecklistView(b).items,doc=k=>docs.find(x=>x.key===k),
  rows=managementRows('rto_cases',b.id),edit=mainCloudMode&&state.cloudEditsEnabled;
 const docStatus='<div class="management-doc-status">'+
