  .map(([k,l])=>'<div><strong>'+esc(l)+'</strong>'+managementBadge(doc(k)?.status)+
   '<small>Checklist value: '+esc(doc(k)?.value||'Not recorded')+'</small></div>').join('')+'</div>';
 const history=rows.length?rows.map(r=>'<article class="management-entry"><h4>'+
   esc(r.procedure||'Procedure not recorded')+'</h4>'+managementBadge(r.stage)+
   managementFields([['Next follow-up',managementDate(r.next_action_at).text],
