   '</article>').join(''):managementEmpty('RTO cases');
 const body=docStatus+'<p class="context-help">Original document checklist, registration transfer and bank NOC evidence remain separate from this case record. Buyer handover is never altered.</p>'+history;
 if(!edit)return managementPanel('RTO & HPA Tracker',body,'Update RTO case');
 return '<section class="vehicle-context management-panel"><div class="context-heading"><h3>RTO & HPA Tracker</h3><span class="pill">Private cloud history</span></div>'+body+
  '<div class="context-footer"><p>Owner revision-checked case operations; browser records untouched.</p>'+
