function repairsSection(b){
 const rows=managementRows('repair_jobs',b.id),edit=mainCloudMode&&state.cloudEditsEnabled;
 const info='<p class="context-help">Repair estimates and final repair costs are informational. Neither is automatically added to parking, other expenses or the cashbook.</p>';
 const history=rows.length?rows.map(r=>'<article class="management-entry"><h4>'+
