async function refreshMainCloud(minimumExpectedRevision=0){
 if(mainCloudLoading)return false;
 if(cloudHasOpenEdits()){notify('Finish or close the current edit before refreshing cloud records.');return false;}
 if(!window.NainaMainCloudAdapter){notify('Cloud preview component is unavailable. Browser records remain unchanged.');return false;}
 mainCloudEpoch++;const requestEpoch=mainCloudEpoch,wasCloudMode=mainCloudMode;mainCloudLoading=true;render();
 try{
  const candidate=await window.NainaMainCloudAdapter.load(fetch);
  if(requestEpoch!==mainCloudEpoch||(wasCloudMode&&!mainCloudMode))return false;
  // The polling revision and the currently displayed cloud revision are lower
  // bounds. A stale snapshot must not replace verified newer laptop/iPhone data.
  const currentMinimum=mainCloudMode&&Number.isSafeInteger(mainCloudRevision)?mainCloudRevision:0;
  const polledMinimum=Number.isSafeInteger(minimumExpectedRevision)&&minimumExpectedRevision>=0?minimumExpectedRevision:0;
  if(!Number.isSafeInteger(candidate.cloudRevision)||
     candidate.cloudRevision<Math.max(currentMinimum,polledMinimum)){
   notify('Cloud response is older than the current revision. Data was not replaced.');
   return false;
  }
  // Complete validated cloud snapshot replaces only the in-memory view.
  // The localStorage key, snapshot, and browser backup remain unchanged.
  state=candidate;mainCloudRevision=candidate.cloudRevision;mainCloudMode=true;
  storageStatus='ready';render();
  if(mainCloudSync){if(mainCloudSync.status().active)mainCloudSync.acknowledged(mainCloudRevision);else mainCloudSync.start(mainCloudRevision);}
  notify('Cloud data refreshed. Your browser records remain unchanged.');return true;
 }catch(e){notify(e instanceof Error?e.message:'Cloud preview could not be loaded.');return false;}
 finally{mainCloudLoading=false;render();}
}
