import { guard, json, database } from '../../../lib/cloud-server';
import { MAIN_CRM_CLOUD_PREVIEW_ENABLED } from '../../../lib/main-crm-flags';
import { CRM_WRITES_ENABLED } from '../../../lib/cloud-write-flags';
import { PRIVATE_MEDIA_ENABLED } from '../../../lib/private-media-flags';
import { CrmReads, ReadError, pageInput, type Feature } from '../../../lib/crm-reads';
import { CrmWrites } from '../../../lib/crm-writes';

// Read-only main-dashboard feed; no imports or writes.
const RESOURCES = new Set([
 'vehicles','sales','leads','customers','vehicle_locations','document_requirements',
 'vehicle_media','cashbook_entries','customer_payments','expenses','repair_jobs','rto_cases',
 'reminders','document_expiries','reservations','vehicle_inspections','auction_plans',
]);
export async function GET(request: Request) {
 const auth=await guard(request);if('error' in auth)return auth.error;
 if(!MAIN_CRM_CLOUD_PREVIEW_ENABLED)return json({error:'Main CRM cloud preview is not activated.'},423);
 try {
  const params=new URL(request.url).searchParams;
  if([...params.keys()].some(k=>!['resource','limit','offset'].includes(k)||params.getAll(k).length!==1))throw new ReadError('INVALID_QUERY');
  const resource=params.get('resource');
  if(!resource||(resource!=='revision'&&!RESOURCES.has(resource)))throw new ReadError('INVALID_QUERY');
  if(resource==='revision'&&(params.has('limit')||params.has('offset')))throw new ReadError('INVALID_QUERY');
  const input=resource==='revision'?null:pageInput({limit:params.has('limit')?Number(params.get('limit')):100,offset:params.has('offset')?Number(params.get('offset')):0});
  const db=database(),reader=new CrmReads(db),revisions=new CrmWrites(db,auth.user.userId);
  const before=await revisions.revision();
  let result:unknown={};
  if(resource!=='revision'){
   switch(resource){
    case 'vehicles':result=await reader.vehicles(input!);break;
    case 'sales':result=await reader.sales(input!);break;
    case 'expenses':result=await reader.expenses(input!);break;
    case 'leads':result=await reader.leads(input!);break;
    case 'customers':result=await reader.customers(input!);break;
    default:result=await reader.features(resource as Feature,input!);
   }
  }
  if(before!==await revisions.revision())return json({error:'Cloud records changed while being read. Retry without changing local records.'},409);
  return json({source:'owner-d1-read-only',revision:before,editEnabled:CRM_WRITES_ENABLED,mediaEnabled:PRIVATE_MEDIA_ENABLED,result});
 } catch(e) {
  const code=e instanceof ReadError?e.code:'READ_UNAVAILABLE';
  return json({error:code==='INVALID_QUERY'?'Invalid main CRM read request.':'Main CRM cloud data unavailable. Local records were not changed.'},code==='INVALID_QUERY'?400:503);
 }
}

