import { guard, json, database } from '../../../lib/cloud-server';
import { CLOUD_TRANSFER_ENABLED,exportSnapshot,verifySnapshot,previewImport,TransferError } from '../../../lib/crm-transfer';
import { auditSnapshotLinks } from '../../../lib/snapshot-link-audit.mjs';
async function handle(request:Request){
 const auth=await guard(request);if('error' in auth)return auth.error;
 if(!CLOUD_TRANSFER_ENABLED)return json({error:'Cloud transfer is disabled pending separate approval.'},423);
 try{
  if(request.method==='GET'){
   const p=new URL(request.url).searchParams;
   if(p.size!==1||p.get('action')!=='export')return json({error:'Invalid export request.'},400);
   return json(await exportSnapshot(database()));
  }
  if(request.headers.get('content-type')?.split(';')[0]!=='application/json')return json({error:'JSON required.'},415);
  if(!request.body)return json({error:'Body required.'},400);
  const reader=request.body.getReader(),chunks:Uint8Array[]=[];let size=0;
  try{while(true){const {value,done}=await reader.read();if(done)break;size+=value.byteLength;if(size>20*1024*1024){await reader.cancel();return json({error:'Maximum transfer size is 20 MB.'},413);}chunks.push(value);}}finally{reader.releaseLock();}
  const bytes=new Uint8Array(size);let pos=0;for(const part of chunks){bytes.set(part,pos);pos+=part.length;}
  let body;try{body=JSON.parse(new TextDecoder().decode(bytes));}catch{return json({error:'Invalid JSON.'},400);}
  if(!body||typeof body!=='object')return json({error:'Invalid request.'},400);
  if(body.action==='verify-restore')return json(await verifySnapshot(body.snapshot));
  if(body.action==='audit'){
   // Check checksum and exact 27-table manifest before assessing any relationships.
   const verification=await verifySnapshot(body.snapshot);
   const integrity=auditSnapshotLinks((body.snapshot as {tables:Record<string,Record<string,unknown>[]>}).tables);
   return json({verification,integrity,cloudChanged:false,restored:false});
  }
  if(body.action==='preview')return json(await previewImport(database(),body.backup,body.expectedRevision));
  return json({error:'Import and hosted restore execution are not enabled.'},423);
 }catch(e){return json({error:e instanceof TransferError?e.message:'Transfer unavailable; no data was changed.'},e instanceof TransferError?e.status:503);}
}
export const GET=handle;export const POST=handle;

