#!/usr/bin/env node
// Compare two independent PRIVATE export directories without copying data,
// restoring hosted resources or writing reports to the repository.
import {resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
import {auditPairedPrivateRecovery} from '../lib/offline-recovery-pair.mjs';
export async function main(args=process.argv.slice(2)){
 if(args.length!==6){
  console.error('Usage: node scripts/verify-private-recovery-pair.mjs SOURCE_D1.json SOURCE_MEDIA_DIR SOURCE_INDEPENDENT_SHA256 CANDIDATE_D1.json CANDIDATE_MEDIA_DIR CANDIDATE_INDEPENDENT_SHA256');
  return 64;
 }
 try{
  const report=await auditPairedPrivateRecovery(args.slice(0,3),args.slice(3));
  console.log(JSON.stringify(report,null,2));
  return report.localCopiesEquivalentAndComplete?0:2;
 }catch{
  // Paths, row IDs, customer data, object keys, private SHA-256 values and
  // individual filenames must never reach CI logs or command output.
  console.error('FAIL: Private offline recovery comparison blocked. No data modified.');
  return 2;
 }
}
if(process.argv[1]&&import.meta.url===pathToFileURL(resolve(process.argv[1])).href){
 process.exitCode=await main();
}

