/** Owner-only, metadata-level media recovery inventory. The caller MUST enforce owner auth. */
export class RecoveryManifestError extends Error {
  constructor(status, message) { super(message); this.status = status; }
}
const text = value => typeof value === 'string' && value.length > 0;
const validHash = value => typeof value === 'string' && /^[a-f0-9]{64}$/.test(value);
const validCount = value => Number.isSafeInteger(value) && value >= 0;

export async function buildMediaRecoveryManifest(db, bucket, vehicleId, {limit=25, offset=0}={}) {
  if (!text(vehicleId) || vehicleId.length > 1024) throw new RecoveryManifestError(400, 'Invalid vehicle identifier.');
  if (!Number.isSafeInteger(limit) || limit < 1 || limit > 50 || !validCount(offset) || offset > 100000)
    throw new RecoveryManifestError(400, 'Invalid manifest pagination.');
  if (!db || !bucket || typeof bucket.head !== 'function')
    throw new RecoveryManifestError(503, 'Recovery check unavailable.');
  const rev = async () => {
    const row = await db.prepare("SELECT value FROM cloud_metadata WHERE key='revision'").first();
    const raw = row?.value;
    // D1 state is valid only as canonical decimal text. Number('') and Number('0x10')
    // must never be accepted as trustworthy cross-device revisions.
    if (typeof raw !== 'string' || !/^(?:0|[1-9][0-9]*)$/.test(raw) ||
        !validCount(Number(raw)))
      throw new RecoveryManifestError(503, 'Cloud revision unavailable.');
    return Number(raw);
  };
  const before = await rev();
  const result = await db.prepare('SELECT id, vehicle_id, object_key, original_filename, mime_type, bytes, category, sha256, archived_at, notes FROM vehicle_media WHERE vehicle_id=? ORDER BY id LIMIT ? OFFSET ?')
    .bind(vehicleId, limit, offset).all();
  if (!result?.success || !Array.isArray(result.results) || result.results.length > limit)
    throw new RecoveryManifestError(503, 'Recovery inventory unavailable.');
  const seen = new Set();
  const items = [];
  for (const row of result.results) {
    if (!row || !text(row.id) || !text(row.object_key) || !text(row.original_filename) ||
        !text(row.mime_type) || !text(row.category) || !validHash(row.sha256) ||
        !Number.isSafeInteger(row.bytes) || row.bytes <= 0 || row.vehicle_id !== vehicleId || seen.has(row.id))
      throw new RecoveryManifestError(409, 'Media metadata requires reconciliation.');
    seen.add(row.id);
    // HEAD checks existence, size and stored metadata only. It cannot verify bytes or prove a backup.
    let head;
    try { head = await bucket.head(row.object_key); }
    catch { throw new RecoveryManifestError(503, 'Private object audit unavailable; try again.'); }
    const objectCheck = !head ? 'missing' :
      head.size !== row.bytes || head.customMetadata?.sha256 !== row.sha256 ? 'metadata-mismatch' : 'metadata-match';
    const state = row.notes === 'Internal: upload incomplete; reconciliation required' ? 'incomplete' :
      row.archived_at ? 'archived' : 'active';
    items.push({id:row.id, filename:row.original_filename, mimeType:row.mime_type, category:row.category,
      bytes:row.bytes, sha256:row.sha256, state, objectCheck,
      recoverableByExport:state !== 'incomplete' && objectCheck === 'metadata-match'});
  }
  const after = await rev();
  if (after !== before) throw new RecoveryManifestError(409, 'Cloud media changed during audit. Retry.');
  return {format:'naina-media-recovery-manifest-v1',vehicleId, revision:before,
    checkedAt:new Date().toISOString(), limit, offset,
    nextOffset:items.length===limit ? offset+limit : null,
    mediaBytesIncluded:false, contentChecksumsVerified:false,
    explanation:'This is a metadata audit, not a media backup. Export each file separately and verify its SHA-256 before relying on an offline copy.',
    attentionRequired:items.some(item=>!item.recoverableByExport), items};
}

