/* Owner-only financial editing adapter for the MAIN CRM. No automatic writes or retries.
   This module never touches localStorage. All activation and authorization are server-enforced. */
(function(root,factory){
 const api=factory();
 if(typeof module==='object'&&module.exports)module.exports=api;
 else root.NainaCloudFinanceEditor=api;
})(typeof globalThis==='object'?globalThis:this,function(){
 'use strict';
 let pending=false;
 const methods=['Cash','UPI','Bank','Other'];
 const own=(o,k)=>Object.prototype.hasOwnProperty.call(o,k);
 function id(s){if(typeof s!=='string'||!s||s.length>256||/[\x00-\x1f]/.test(s))throw Error('Invalid record identifier.');return s;}
 function str(s,max=1000){if(typeof s!=='string'||s.length>max||/[\x00-\x1f]/.test(s))throw Error('Invalid text.');return s.trim();}
 function rupees(s,allowZero=true){if(typeof s!=='string'||!/^(?:0|[1-9]\d{0,11})(?:\.\d{1,2})?$/.test(s.trim()))throw Error('Enter a valid amount with up to two decimals.');const n=Number(s.trim());if(!Number.isSafeInteger(Math.round(n*100))||(n===0&&!allowZero))throw Error('Invalid monetary amount.');return Math.round(n*100)/100;}
 function recorded(n){if(typeof n!=='number'||!Number.isFinite(n)||n<0||Math.abs(n*100-Math.round(n*100))>0.000001)throw Error('Historical amount needs reconciliation.');return Math.round(n*100);}
 function date(s){if(typeof s!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(s))throw Error('Choose a date.');const d=new Date(s+'T00:00:00Z');if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==s)throw Error('Invalid calendar date.');return s;}
 function rev(v){if(!Number.isSafeInteger(v)||v<0)throw Error('Refresh cloud data to obtain a valid revision.');return v;}
 function uuid(){if(typeof crypto==='undefined'||!crypto.randomUUID)throw Error('Secure random identifiers are required.');return crypto.randomUUID();}
 function plan(resource,mode,key,data,expectedRevision){return {resource,mode,id:id(key),data,expectedRevision:rev(expectedRevision),idempotencyKey:uuid()};}
 function sale(bike,existingSales,input,expectedRevision){
  if(!bike||bike.status!=='Available'||!bike.id)throw Error('Only available stock can be sold.');
  const matches=(Array.isArray(existingSales)?existingSales:[]).filter(r=>r.vehicleId===bike.id);
  if(matches.length)throw Error('A sale already exists for this vehicle. Reconcile before proceeding.');
  const buyer=str(input.buyer,300),salePrice=rupees(input.sale,false),balance=rupees(input.balance),method=str(input.paymentMethod||'',30);
  if(!buyer)throw Error('Buyer name is required.');if(balance>salePrice)throw Error('Balance cannot exceed sale price.');
  if(balance<salePrice&&!methods.includes(method))throw Error('Initial receipt method is required.');
  return plan('sales','create',uuid(),{vehicleId:id(bike.id),buyer,buyerPhone:str(input.buyerPhone||'',50),buyerAddress:str(input.buyerAddress||'',500),saleDate:date(input.saleDate),sale:salePrice,balance,paymentMethod:balance<salePrice?method:'Other'},expectedRevision);
 }
 function payment(bike,sales,input,expectedRevision){
  if(!bike||bike.status!=='Sold')throw Error('Customer payments require a sold vehicle.');
  const matches=(Array.isArray(sales)?sales:[]).filter(r=>r.vehicleId===bike.id);
  if(matches.length!==1)throw Error('Exactly one linked cloud sale is required. Reconcile before taking payment.');
  const linked=matches[0];id(linked.id);
  const oldBalance=recorded(linked.recordedBalance),vehicleBalance=recorded(bike.balance),salePrice=recorded(linked.sale),vehiclePrice=recorded(bike.sale);
  if(oldBalance!==vehicleBalance||salePrice!==vehiclePrice||oldBalance>salePrice)throw Error('Sale and vehicle balances disagree. Payment blocked until reconciliation.');
  if(oldBalance===0)throw Error('No recorded amount remains due.');
  const amount=rupees(input.amount,false),method=str(input.method,30);
  if(Math.round(amount*100)>oldBalance)throw Error('Payment exceeds outstanding balance.');
  if(!methods.includes(method))throw Error('Choose a valid payment method.');
  return plan('customer_payments','create',uuid(),{sale_id:linked.id,received_at:date(input.received_at),amount,method,payment_reference:str(input.payment_reference||'',300),note:str(input.note||'',2000)},expectedRevision);
 }
 function expense(bike,expenseRows,input,expectedRevision){
  if(!bike||!bike.id||!['Available','Sold','Review'].includes(bike.status))throw Error('Select a valid cloud vehicle.');
  const kind=str(input.kind,30);if(!['parking','other'].includes(kind))throw Error('Select parking or other expenses.');
  const old=kind==='parking'?bike.parking:bike.otherExpenses;
  recorded(bike.parking);recorded(bike.otherExpenses);
  const current=recorded(old),amount=rupees(input.amount);
  const matches=(Array.isArray(expenseRows)?expenseRows:[]).filter(r=>r.vehicleId===bike.id&&r.kind===kind);
  if(matches.length>1)throw Error('Duplicate expense totals. Reconcile before editing.');
  if(matches.length&&recorded(matches[0].amount)!==current)throw Error('Expense row differs from vehicle total. Reconcile first.');
  return plan('expenses',matches.length?'update':'create',matches.length?id(matches[0].id):uuid(),{vehicle_id:id(bike.id),kind,amount,notes:str(input.notes||'',1000)},expectedRevision);
 }
 async function write(fetchFn,instruction){
  if(!instruction||!['sales','expenses','customer_payments'].includes(instruction.resource)||!['create','update'].includes(instruction.mode))throw Error('Unsupported financial write.');
  let response;
  try{response=await fetchFn('/api/private-crm-write',{method:'POST',credentials:'same-origin',cache:'no-store',redirect:'error',headers:{'Content-Type':'application/json'},body:JSON.stringify(instruction)});}
  catch{throw Error('Network result unknown. Refresh the cloud records and reconcile before any new attempt.');}
  if(!response||!response.ok){if(response?.status===423)throw Error('Cloud writes are not activated.');if(response?.status===409)throw Error('Revision or accounting conflict. Refresh before retrying.');throw Error('Save not confirmed. Refresh cloud records and check the ledger.');}
  let body;try{body=await response.json();}catch{throw Error('Unverified receipt. Refresh and reconcile before retrying.');}
  if(body?.result?.id!==instruction.id||body?.result?.resource!==instruction.resource||body?.result?.revision!==instruction.expectedRevision+1)throw Error('Unexpected receipt. Refresh and reconcile before retrying.');
  return body.result;
 }
 function openDialog({bike,kind,sales,expenses,revision,notify,refresh,canSubmit}){
  if(pending||!bike||!['sale','payment','expense'].includes(kind))return;
  const dlg=document.getElementById('cloud-finance-dialog'),form=document.getElementById('cloud-finance-form'),fields=document.getElementById('cloud-finance-fields');
  if(!dlg||!form||!fields)return;
  try{
   if(kind==='sale'&&(bike.status!=='Available'||sales.some(r=>r.vehicleId===bike.id)))throw Error('This stock record is not eligible for a new sale.');
   if(kind==='payment'&&(bike.status!=='Sold'||sales.filter(r=>r.vehicleId===bike.id).length!==1))throw Error('A uniquely linked cloud sale is required before taking payment.');
   if(kind==='expense'){recorded(bike.parking);recorded(bike.otherExpenses);}
  }catch(error){notify(error.message);return;}
  fields.replaceChildren();
  const labels={sale:'Record cloud sale',payment:'Record customer receipt',expense:'Set vehicle expense total'};
  document.getElementById('cloud-finance-title').textContent=labels[kind];
  function field(label,name,value='',options=null,type='text'){
   const wrap=document.createElement('label');wrap.textContent=label+' ';
   const el=document.createElement(options?'select':'input');el.name=name;
   if(options){for(const item of options){const o=document.createElement('option');o.value=item;o.textContent=item;el.append(o);}}
   else{el.type=type;el.maxLength=2000;}el.value=String(value);wrap.append(el);fields.append(wrap);return el;
  }
  const today=new Date().toISOString().slice(0,10);
  if(kind==='sale'){
   field('Buyer name','buyer');field('Phone','buyerPhone');field('Address','buyerAddress');field('Sale date','saleDate',today,null,'date');
   field('Sale price (₹)','sale');field('Outstanding balance (₹)','balance','0');field('Initial receipt method','paymentMethod','Other',methods);
  }else if(kind==='payment'){
   const linked=sales.find(r=>r.vehicleId===bike.id);field('Sale ID','displaySaleId',linked.id).disabled=true;
   field('Received on','received_at',today,null,'date');field('Payment amount (₹)','amount');field('Method','method','Cash',methods);field('Reference','payment_reference');field('Note','note');
  }else{
   const kindSelect=field('Expense category','kind','parking',['parking','other']);const amount=field('New TOTAL amount (₹), not an additional charge','amount',String(bike.parking));
   kindSelect.addEventListener('change',()=>amount.value=String(kindSelect.value==='parking'?bike.parking:bike.otherExpenses));field('Notes','notes');
  }
  const submit=form.querySelector('button[type="submit"]');
  form.onsubmit=async e=>{
   e.preventDefault();if(pending)return;
   if(typeof canSubmit!=='function'||!canSubmit()){notify('This cloud editor is no longer current. Reload cloud data before editing.');dlg.close();return;}
   let instruction;
   try{const values=Object.fromEntries(new FormData(form));instruction=kind==='sale'?sale(bike,sales,values,revision):kind==='payment'?payment(bike,sales,values,revision):expense(bike,expenses,values,revision);}
   catch(error){notify(error.message);return;}
   const description=kind==='expense'?'REPLACE the recorded '+instruction.data.kind+' expense total with ₹'+instruction.data.amount:kind==='payment'?'record a ₹'+instruction.data.amount+' receipt against sale '+instruction.data.sale_id:'mark this vehicle sold for ₹'+instruction.data.sale+' with outstanding ₹'+instruction.data.balance;
   if(!confirm('Confirm cloud transaction: '+description+'? Browser records will not change.'))return;
   if(!canSubmit()){notify('Cloud view changed while confirming. Reload before editing.');dlg.close();return;}
   pending=true;submit.disabled=true;
   try{await write(fetch,instruction);dlg.close();notify('Financial transaction confirmed. Refreshing cloud records.');pending=false;submit.disabled=false;await refresh();}
   catch(error){notify(error.message)}finally{pending=false;submit.disabled=false;}
  };
  document.getElementById('cloud-finance-close').onclick=()=>{if(!pending)dlg.close();};
  if(!dlg.open)dlg.showModal();
 }
 return {sale,payment,expense,write,openDialog,isPending:()=>pending};
});

