scripts/release-preflight.mjs.value:
// Zero-dependency, read-only gate for the exported Naina Motors Dealer Desk source.
// This does not replace a framework build or hosted security tests.
import { readFileSync, existsSync, readdirSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { Script } from 'node:vm';
const root=resolve(dirname(fileURLToPath(import.meta.url)),'..');
const baseline=process.argv.includes('--baseline-export');
const checks=[];
const read=path=>readFileSync(resolve(root,path),'utf8');
function check(name,condition,detail=''){
 checks.push({name,passed:Boolean(condition),detail});
 if(!condition)process.exitCode=1;
}
function file(path){const ok=existsSync(resolve(root,path));check('File: '+path,ok);return ok;}
const page='ui/crm.html',route='app/route.ts';
if(file(page)&&file(route)){
 const html=read(page),entry=read(route);
 check('HTML served from existing ui/crm.html',entry.includes("../ui/crm.html?raw")&&entry.includes("'Cache-Control':'no-store'"));
 const assets=[...html.matchAll(/<(?:script|link)\b[^>]*?\b(?:src|href)="([^"]+)"/g)].map(x=>x[1]);
 const relative=assets.filter(s=>!s.startsWith('http:')&&!s.startsWith('https:')&&!s.startsWith('/')&&!s.startsWith('#'));
 check('No duplicate relative script/style references',new Set(relative.map(s=>s.split('?')[0])).size===relative.length);
 for(const name of relative){
  const path=name.split('?')[0];
  check('Browser asset exists: '+path,!path.includes('..')&&existsSync(resolve(root,'public',path)));
  if(path.endsWith('.js')&&existsSync(resolve(root,'public',path))){
   try{new Script(read('public/'+path),{filename:path});check('Browser JS parses: '+path,true);}
   catch(e){check('Browser JS parses: '+path,false,String(e.message));}
  }
 }
 check('Browser backup controls retained',html.includes('id="backup"')&&html.includes('id="app"'));
}
const gates=[
 ['lib/main-crm-flags.ts','MAIN_CRM_CLOUD_PREVIEW_ENABLED'],
 ['lib/hosted-preflight-flags.ts','HOSTED_READONLY_PREFLIGHT_ENABLED'],
 ['lib/cloud-release.ts','LEGACY_CLOUD_ENABLED'],
 ['lib/crm-read-flags.ts','CRM_READ_FEATURES_ENABLED'],
 ['lib/cloud-write-flags.ts','CRM_WRITES_ENABLED'],
 ['lib/private-media-flags.ts','PRIVATE_MEDIA_ENABLED'],
 ['lib/crm-transfer.ts','CLOUD_TRANSFER_ENABLED'],
];
for(const [path,name] of gates){
 if(!existsSync(resolve(root,path))&&baseline){
  checks.push({name:'Source export omits '+name,passed:true,detail:'Baseline-only exception; strict PR preflight requires gate'});
  continue;
 }
 if(file(path)){
  const code=read(path);
  check('Production release switch OFF: '+name,new RegExp('\\b(?:export\\s+)?const\\s+'+name+'(?:\\s*:\\s*boolean)?\\s*=\\s*false\\s*;').test(code));
 }
}
for(const [path,guard] of [
 ['app/api/private-crm-write/route.ts','guard(request)'],
 ['app/api/private-crm-transfer/route.ts','guard(request)'],
 ['lib/private-media.ts','requireOwner(request)'],
 ['app/api/private-crm-main/route.ts','guard(request)'],
 ['app/api/private-crm-preflight/route.ts','guard(request)'],
]){
 if(!existsSync(resolve(root,path))&&baseline)continue;
 if(file(path))check('Owner guard present in '+path,read(path).includes(guard));
}
if(file('.gitignore')){
 const ignore=read('.gitignore');
 check('Secrets/dependencies remain excluded',ignore.includes('.env*')&&ignore.includes('/node_modules')&&ignore.includes('*.pem'));
 if(!baseline)check('Private original backups and SQLite data excluded',ignore.includes('/source-data/')&&ignore.includes('naina-motors-backup-')&&ignore.includes('*.sqlite')&&ignore.includes('*.db'));
 if(!baseline)check('Private D1/R2 byte-export and snapshot directories excluded',ignore.includes('**/private-media/')&&ignore.includes('**/private-d1-snapshot*.json')&&ignore.includes('**/verified-d1-snapshot*.json'));
}
if(file('package.json')){
 const pkg=JSON.parse(read('package.json'));
 check('Build script present',typeof pkg.scripts?.build==='string');
 check('Framework dependency defined',Boolean(pkg.devDependencies?.vinext));
}
if(file('drizzle'))check('Database migrations present',readdirSync(resolve(root,'drizzle')).some(f=>f.endsWith('.sql')));
const failures=checks.filter(c=>!c.passed);
for(const c of checks)console.log((c.passed?'PASS':'FAIL')+' '+c.name+(c.detail?' — '+c.detail:''));
console.log('PREFLIGHT '+(failures.length?'FAILED':'PASSED')+': '+(checks.length-failures.length)+'/'+checks.length+' static checks; full framework/build/hosted testing NOT performed.');

