// Read-only staging checks. This module NEVER sends POST, stores auth,
// obtains credentials, reads customer rows, or enables a cloud release.
const resourcePaths=Object.freeze([
 '/api/private-crm-main?resource=revision',
 '/api/private-crm-write',
 '/api/private-crm-transfer',
 '/api/private-crm?resource=vehicles',
 '/api/private-crm-preflight',
 '/api/private-media?action=list&vehicleId=synthetic',
 '/api/cloud/status',
]);
export const ANONYMOUS_CHECK_COUNT=resourcePaths.length;
export function stagingOrigin(value){
 if(typeof value!=='string')throw Error('An explicit staging origin is required.');
 let parsed;try{parsed=new URL(value);}catch{throw Error('Invalid staging origin.');}
 const host=parsed.hostname.toLowerCase();
 if(parsed.protocol!=='https:'||parsed.username||parsed.password||parsed.port||
  parsed.pathname!=='/'||parsed.search||parsed.hash)
  throw Error('Only a bare HTTPS staging origin is permitted.');
 if(host==='crm.nainamotors.com'||host==='nainamotors.com'||
    host.includes('showroom')||host.includes('customer')||
    !/(^|[.-])(staging|sandbox|preview)([.-]|$)/.test(host))
  throw Error('Production, showroom or unmarked URLs are not staging.');
 return parsed.origin;
}
export async function probeAnonymous(fetchFn,origin){
