   response=await fetchFn(origin+path,{
    method:'GET',redirect:'error',cache:'no-store',credentials:'omit',
    headers:{
     Accept:'application/json',
     'oai-authenticated-user-id':'synthetic-forged-owner-id',
     'oai-authenticated-user-email':ownerEmail,
     'oai-authenticated-user-full-name':'Synthetic Unauthenticated Visitor',
    },
    signal:AbortSignal.timeout(8000),
   });
  }catch{
   throw Error('Staging identity spoof probe unavailable; no data was changed.');
  }
  // Deliberately do not inspect or log any response body or private headers.
  const headers=response?.headers;
  const denied=response?.status===401||response?.status===403;
  const noStore=headers?.get('cache-control')?.toLowerCase().includes('no-store')===true;
  const nosniff=headers?.get('x-content-type-options')?.toLowerCase()==='nosniff';
  const noCors=!headers?.get('access-control-allow-origin');
  if(!denied||!noStore||!nosniff||!noCors)
   throw Error('Staging forged identity was not safely denied at '+path.split('?')[0]+'.');
  outcomes.push({route:path.split('?')[0],forgedIdentityDenied:true});
