/* Safe, opt-in Owner cloud reminder editing. Never stores data in the browser. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;
 else root.NainaCloudReminders=api;})(typeof globalThis==='object'?globalThis:this,function(){
 'use strict';let pending=false;const statuses=['Open','Done','Cancelled'],priorities=['Low','Normal','High'];
 function txt(v,max=1000){if(typeof v!=='string'||v.length>max||/[\x00-\x1f]/.test(v))throw Error('Invalid reminder text.');return v.trim();}
 function id(v){if(typeof v!=='string'||!v||v.length>256||/[\x00-\x1f]/.test(v))throw Error('Invalid reminder ID.');return v;}
 function uuid(){if(typeof crypto==='undefined'||typeof crypto.randomUUID!=='function')throw Error('Secure IDs unavailable.');return crypto.randomUUID();}
 function date(v){if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v))throw Error('Select a valid date.');const d=new Date(v+'T00:00:00Z');if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==v)throw Error('Invalid calendar date.');return v;}
 function plan(existing,fields,revision){
  if(!Number.isSafeInteger(revision)||revision<0||revision>=Number.MAX_SAFE_INTEGER)throw Error('Cloud revision must be refreshed.');
  const v=fields||{},title=txt(v.title||'',300),day=date(v.date||''),status=txt(v.status||'Open',30),priority=txt(v.priority||'Normal',30);
  if(!title)throw Error('Reminder title required.');
  if(!statuses.includes(status)||!priorities.includes(priority))throw Error('Invalid task status or priority.');
  const original=existing?.due_at;
  // Title/status edits must not silently discard the original exact-time deadline.
  const due_at=typeof original==='string'&&original.slice(0,10)===day&&Number.isFinite(Date.parse(original))?original:day;
  return {resource:'reminders',mode:existing?'update':'create',id:existing?id(existing.id):uuid(),
   data:{title,due_at,status,priority,notes:txt(v.notes||'',2000),
    vehicle_id:existing?.vehicle_id??null,related_id:existing?.related_id??null,
    related_type:existing?.related_type??'General task'},
   expectedRevision:revision,idempotencyKey:uuid()};
 }
 async function write(fetchFn,p){
  if(!p||p.resource!=='reminders'||!['create','update'].includes(p.mode))throw Error('Unsupported reminder write.');
  let response;
  try{response=await fetchFn('/api/private-crm-write',{method:'POST',credentials:'same-origin',
   cache:'no-store',redirect:'error',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)});}
  catch{throw Error('Reminder save result unknown. Refresh before retrying.');}
  if(!response?.ok){
   if(response?.status===423)throw Error('Cloud editing remains locked.');
   if(response?.status===409)throw Error('Reminder revision conflict. Refresh before editing.');
   throw Error('Reminder save unconfirmed. Refresh before retrying.');
  }
  let data;try{data=await response.json();}catch{throw Error('Unreadable reminder receipt. Refresh first.');}
  if(data?.result?.id!==p.id||data?.result?.resource!=='reminders'||data?.result?.revision!==p.expectedRevision+1)
   throw Error('Unverified reminder receipt. Refresh first.');
  return data.result;
 }
 function openDialog({existing,revision,notify,refresh,canSubmit}){
  if(pending||typeof canSubmit!=='function'||typeof refresh!=='function')return;
  const dialog=document.getElementById('cloud-reminder-dialog'),form=document.getElementById('cloud-reminder-form'),
   fields=document.getElementById('cloud-reminder-fields');
  if(!dialog||!form||!fields)return;
  document.getElementById('cloud-reminder-title').textContent=existing?'Edit cloud reminder':'Add cloud reminder';
  fields.replaceChildren();
  function field(label,name,value='',options=null,type='text'){
   const wrap=document.createElement('label');wrap.textContent=label+' ';
   const element=document.createElement(options?'select':'input');element.name=name;element.required=name==='title'||name==='date';
   if(options){for(const option of options){const o=document.createElement('option');o.value=option;o.textContent=option;element.appendChild(o);}}
   else{element.type=type;element.maxLength=name==='notes'?2000:300;}
   element.value=String(value??'');wrap.appendChild(element);fields.appendChild(wrap);
  }
  field('Task title','title',existing?.title||'');
  field('Due date (IST calendar)','date',typeof existing?.due_at==='string'?existing.due_at.slice(0,10):'',null,'date');
  field('Status','status',existing?.status||'Open',statuses);
  field('Priority','priority',existing?.priority||'Normal',priorities);
  field('Notes','notes',existing?.notes||'');
  const submit=form.querySelector('button[type="submit"]');
  form.onsubmit=async event=>{
   event.preventDefault();if(pending)return;
   if(!canSubmit()){notify('Cloud data changed. Refresh first.');dialog.close();return;}
   let p;try{p=plan(existing,Object.fromEntries(new FormData(form)),revision);}catch(e){notify(e.message);return;}
   if(!confirm('Save this private cloud reminder? Browser records remain unchanged.'))return;
   if(!canSubmit()){notify('Cloud revision changed during confirmation.');dialog.close();return;}
   pending=true;submit.disabled=true;
   try{await write(fetch,p);dialog.close();notify('Reminder saved to cloud. Refreshing.');await refresh();}
   catch(e){notify(e.message);}
   finally{pending=false;submit.disabled=false;}
  };
  const close=document.getElementById('cloud-reminder-close');
  if(close)close.onclick=()=>{if(!pending)dialog.close();};
  if(!dialog.open)dialog.showModal();
 }
 return {plan,write,openDialog,isPending:()=>pending};
});

