/* Safe, explicit, read-only cloud projections for the ORIGINAL dashboard.
   No localStorage access, network writes, or automatic cloud requests. */
(function(root,factory){
 const exported=factory();
 if(typeof module==='object'&&module.exports)module.exports=exported;
 else root.NainaMainCloudAdapter=exported;
})(typeof globalThis==='object'?globalThis:this,function(){
 'use strict';
 const resources=['vehicles','sales','leads','customers','vehicle_locations','document_requirements','vehicle_media','cashbook_entries','customer_payments','expenses','repair_jobs','rto_cases','reminders','document_expiries','reservations','vehicle_inspections','auction_plans'];
 const object=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
 function recordId(record,resource){
  if(!object(record))throw Error('Invalid '+resource+' record.');
  const key=resource==='vehicle_locations'?'vehicle_id':'id';
  const id=record[key];
  if(typeof id!=='string'||!id||id.length>1024)throw Error('Invalid '+resource+' ID.');
  return id;
 }
 function recordsToView(rows){
  if(!object(rows))throw Error('Invalid cloud response.');
  const vehicles=rows.vehicles||[],leads=rows.leads||[];
  if(!Array.isArray(vehicles)||!Array.isArray(leads)||!vehicles.length)throw Error('Cloud inventory is empty or not imported. Browser data remains active.');
  const ids=new Set(),bikes=[];
  for(const row of vehicles){
   const id=recordId(row,'vehicles');
   if(ids.has(id)||!object(row.payload)||!['Available','Sold','Review'].includes(row.status)||
      (row.payload.id!==undefined&&row.payload.id!==id)||
      (row.payload.status!==undefined&&row.payload.status!==row.status)||
      typeof row.payload.name!=='string')throw Error('Cloud vehicle records require reconciliation.');
   ids.add(id);bikes.push({...row.payload,id,status:row.status});
  }
  const leadIds=new Set(),projectedLeads=[];
  for(const row of leads){
   const id=recordId(row,'leads');
   if(leadIds.has(id)||!object(row.payload)||(row.payload.id!==undefined&&row.payload.id!==id)||typeof row.payload.name!=='string')throw Error('Cloud enquiries require reconciliation.');
   leadIds.add(id);projectedLeads.push({...row.payload,id});
  }
  const customerIds=new Set(),projectedCustomers=[];
  for(const row of rows.customers||[]){
   const id=recordId(row,'customers');
   if(customerIds.has(id)||!object(row.payload)||(row.payload.id!==undefined&&row.payload.id!==id)||typeof row.payload.name!=='string'||!row.payload.name.trim())throw Error('Cloud customer records require reconciliation.');
   customerIds.add(id);projectedCustomers.push({...row.payload,id});
  }
  const byId=new Map(bikes.map(b=>[b.id,b]));
  const features=['vehicle_locations','document_requirements','vehicle_media','cashbook_entries','customer_payments','repair_jobs','rto_cases','reminders','document_expiries','reservations','vehicle_inspections','auction_plans'];
  const result={bikes,leads:projectedLeads,customers:projectedCustomers,cloudRevision:rows.revision,cloudEditsEnabled:rows.cloudEditsEnabled===true,cloudMediaEnabled:rows.cloudMediaEnabled===true,sales:rows.sales||[],expenses:rows.expenses||[]};
  for(const name of features)result[name]=rows[name]||[];
  const locationIds=new Set();
  for(const loc of result.vehicle_locations){
   if(!object(loc)||typeof loc.vehicle_id!=='string')throw Error('Cloud location is invalid.');
   const bike=byId.get(loc.vehicle_id);
   if(!bike||locationIds.has(loc.vehicle_id))
    throw Error('Cloud location linkage requires reconciliation.');
   locationIds.add(loc.vehicle_id);bike.vehicleLocation=loc;
  }
  for(const document of result.document_requirements){
   if(!object(document)||typeof document.vehicle_id!=='string')throw Error('Cloud document is invalid.');
   const bike=byId.get(document.vehicle_id);
   if(!bike)throw Error('Cloud document linkage requires reconciliation.');
   (bike.cloudDocuments??=[]).push(document);
  }
  for(const media of result.vehicle_media){
   if(!object(media)||typeof media.vehicle_id!=='string')throw Error('Cloud media metadata is invalid.');
   const bike=byId.get(media.vehicle_id);
   if(!bike)throw Error('Cloud media linkage requires reconciliation.');
   // The normal CRM projection must never trust or copy raw R2 storage keys.
   if(Object.hasOwn(media,'object_key')||Object.hasOwn(media,'uploaded_by'))
    throw Error('Private media metadata must be redacted by the server.');
   (bike.vehicleMedia??=[]).push(media);
  }
  const reservationIds=new Set(),activeVehicles=new Set();
  for(const row of result.reservations){
   const bookingId=recordId(row,'reservations');
   if(reservationIds.has(bookingId)||typeof row.vehicle_id!=='string'||!byId.has(row.vehicle_id)||
     !['Active','Expired','Cancelled','Converted'].includes(row.status)||
     typeof row.customer_name!=='string'||!row.customer_name.trim())
    throw Error('Cloud reservation records require reconciliation.');
   reservationIds.add(bookingId);
   const bike=byId.get(row.vehicle_id);
   if(row.status==='Active'){
    if(activeVehicles.has(row.vehicle_id)||bike.status!=='Available')
     throw Error('Active cloud reservation conflicts with vehicle status.');
    activeVehicles.add(row.vehicle_id);
   }
   (bike.cloudReservations??=[]).push(row);
  }

  // All inspection and auction history records retain their source vehicle ID.
  // They must not be posted into financial totals or silently dropped.
  for(const [resource,field] of [['vehicle_inspections','cloudInspections'],['auction_plans','cloudAuctions']]){
   const seen=new Set();
   for(const row of result[resource]){
    const rowId=recordId(row,resource);
    if(seen.has(rowId)||typeof row.vehicle_id!=='string'||!byId.has(row.vehicle_id))
     throw Error('Cloud '+resource+' linkage requires reconciliation.');
    seen.add(rowId);
    if(resource==='vehicle_inspections'&&(typeof row.inspected_at!=='string'||row.inspected_at.length<10))
     throw Error('Cloud inspection requires reconciliation.');
    if(resource==='auction_plans'&&(!['Planned','Won','Lost','Cancelled'].includes(row.outcome)||
     typeof row.expected_resale!=='number'||row.expected_resale<0||
     typeof row.maximum_bid!=='number'||row.maximum_bid<0))
     throw Error('Cloud auction plan requires reconciliation.');
    (byId.get(row.vehicle_id)[field]??=[]).push(row);
   }
  }
  const saleIds=new Set(),salesByVehicle=new Map();
  for(const row of rows.sales||[]){
   const id=recordId(row,'sales');
   if(saleIds.has(id)||!object(row.payload)||typeof row.vehicleId!=='string')throw Error('Cloud sales require reconciliation.');
   saleIds.add(id);const group=salesByVehicle.get(row.vehicleId)||[];group.push(row);salesByVehicle.set(row.vehicleId,group);
  }
  for(const [vehicleId,sales] of salesByVehicle){
   const bike=byId.get(vehicleId);
   if(!bike||sales.length>1||bike.status!=='Sold')throw Error('Cloud sale linkage requires review before dashboard display.');
   const sale=sales[0];
   for(const key of ['buyer','buyerPhone','buyerAddress','saleDate','sale','balance']){
    const value=key==='balance'?sale.recordedBalance:sale[key];
    if(value!==null&&value!==undefined&&bike[key]!==undefined&&bike[key]!==null&&String(bike[key])!==String(value))throw Error('Vehicle and sale data disagree; review cloud migration.');
    if(value!==null&&value!==undefined)bike[key]=value;
   }
  }
  for(const bike of bikes){
   if(bike.status==='Sold'&&!salesByVehicle.has(bike.id))
    throw Error('Sold cloud stock is missing its linked sale; reconciliation required.');
  }
  // Cloud feature rows can update financial totals independently of the vehicle
  // payload. Never present profit or outstanding balances as reliable when the
  // normalized ledger and the vehicle snapshot disagree.
  const moneyCents=value=>{
   // Legacy inventory payloads may store plain numeric text while normalized
   // D1 payment/expense rows are numbers. Normalize only unambiguous amounts.
   if(typeof value==='string'&&/^(?:0|[1-9]\d{0,11})(?:\.\d{1,2})?$/.test(value.trim()))value=Number(value.trim());
   if(typeof value!=='number'||!Number.isFinite(value)||value<0||Math.abs(value*100-Math.round(value*100))>0.000001)
    throw Error('Cloud financial amount needs reconciliation.');
   return Math.round(value*100);
  };
  const expenseKeys=new Set(),expenseIds=new Set();
  if(!Array.isArray(result.expenses)||!Array.isArray(result.customer_payments))throw Error('Cloud financial rows are invalid.');
  for(const row of result.expenses){
   const id=recordId(row,'expenses'),bike=byId.get(row.vehicleId),key=row.vehicleId+':'+row.kind;
   if(!bike||!['parking','other'].includes(row.kind)||expenseIds.has(id)||expenseKeys.has(key))
    throw Error('Cloud expense linkage requires reconciliation.');
   expenseIds.add(id);expenseKeys.add(key);
   const field=row.kind==='parking'?'parking':'otherExpenses';
   if(moneyCents(row.amount)!==moneyCents(bike[field]))
    throw Error('Cloud expense total disagrees with vehicle records.');
  }
  for(const bike of bikes){
   // Old imports may contain a legacy single expense total. It is safe to
   // display only if it agrees with both recorded component totals.
   if(bike.parking!==undefined&&bike.otherExpenses!==undefined&&bike.expenses!==undefined&&
      moneyCents(bike.parking)+moneyCents(bike.otherExpenses)!==moneyCents(bike.expenses))
    throw Error('Vehicle expense components disagree with their combined total.');
  }
  const payments=new Set(),receivedBySale=new Map();
  for(const payment of result.customer_payments){
   const id=recordId(payment,'customer_payments');
   if(payments.has(id)||typeof payment.sale_id!=='string'||!saleIds.has(payment.sale_id))
    throw Error('Cloud payment linkage requires reconciliation.');
   const cents=moneyCents(payment.amount);
   if(cents===0)throw Error('Cloud payment linkage requires reconciliation.');
   payments.add(id);
   const total=(receivedBySale.get(payment.sale_id)||0)+cents;
   if(!Number.isSafeInteger(total))throw Error('Cloud receipt totals exceed safe limits.');
   receivedBySale.set(payment.sale_id,total);
  }
  for(const sale of rows.sales||[]){
   const received=receivedBySale.get(sale.id)||0;
   if(!received)continue;
   // A legacy import may not contain every old payment row. But recorded
   // receipts plus outstanding balance must NEVER exceed the sale value.
   if(sale.sale===null||sale.sale===undefined||
      sale.recordedBalance===null||sale.recordedBalance===undefined||
      received+moneyCents(sale.recordedBalance)>moneyCents(sale.sale))
    throw Error('Cloud receipts exceed the recorded sale balance; reconciliation required.');
  }
  return result;
 }
 async function load(fetchFn,endpoint='/api/private-crm-main'){
  const rows={},max=10000,limit=100;let revision=null,editsEnabled=null,mediaEnabled=null;
  async function get(resource,offset){
   const p=new URLSearchParams({resource});if(resource!=='revision'){p.set('limit',String(limit));p.set('offset',String(offset));}
   const response=await fetchFn(endpoint+'?'+p,{credentials:'same-origin',cache:'no-store',redirect:'error'});
   if(!response||!response.ok)throw Error('Cloud preview unavailable ('+(response?.status??'network')+'). Browser records unchanged.');
   const data=await response.json();
   if(data.source!=='owner-d1-read-only'||!Number.isSafeInteger(data.revision)||data.revision<0)throw Error('Unverified cloud response.');
   if(typeof data.editEnabled!=='boolean')throw Error('Cloud release capability is not verified.');
   if(editsEnabled===null)editsEnabled=data.editEnabled;else if(editsEnabled!==data.editEnabled)throw Error('Cloud release capability changed during refresh.');
   if(mediaEnabled===null)mediaEnabled=data.mediaEnabled===true;else if(mediaEnabled!==(data.mediaEnabled===true))throw Error('Private media release capability changed during refresh.');
   if(revision===null)revision=data.revision;
   else if(revision!==data.revision)throw Error('Cloud records changed during refresh. Retry.');
   return data.result;
  }
  for(const resource of resources){
   const seen=new Set(),items=[];
   for(let offset=0;;){
    const page=await get(resource,offset);
    if(!object(page)||!Array.isArray(page.items)||page.items.length>limit||page.offset!==offset||page.limit!==limit||
       !(page.nextOffset===null||(Number.isSafeInteger(page.nextOffset)&&page.nextOffset===offset+limit))||
       (page.nextOffset!==null&&page.items.length!==limit))throw Error('Incomplete or invalid cloud page: '+resource);
    for(const item of page.items){const id=recordId(item,resource);if(seen.has(id))throw Error('Duplicate cloud record ID.');seen.add(id);items.push(item);}
    if(items.length>max)throw Error('Cloud preview exceeds safety limit.');
    if(page.nextOffset===null)break;
    offset=page.nextOffset;
   }
   rows[resource]=items;
  }
  await get('revision',0);
  rows.revision=revision;rows.cloudEditsEnabled=editsEnabled===true;rows.cloudMediaEnabled=mediaEnabled===true;
  return recordsToView(rows);
 }
 return {resources,recordsToView,load};
});

