import { env } from 'cloudflare:workers';
import { guard, json, database } from '../../../lib/cloud-server';
import { HOSTED_READONLY_PREFLIGHT_ENABLED } from '../../../lib/hosted-preflight-flags';
import { SNAPSHOT_TABLES } from '../../../lib/crm-transfer';

const REQUIRED_INDEXES = [
 {name:'vehicles_registration_unique',table:'vehicles',columns:['registration_key'],predicate:null},
 {name:'vehicles_chassis_unique',table:'vehicles',columns:['chassis_key'],predicate:null},
 {name:'expenses_vehicle_kind_unique',table:'expenses',columns:['vehicle_id','kind'],predicate:null},
 {name:'uq_document_requirements_vehicle_id_document_type',table:'document_requirements',columns:['vehicle_id','document_type'],predicate:null},
 {name:'uq_document_expiries_vehicle_id_document_type',table:'document_expiries',columns:['vehicle_id','document_type'],predicate:null},
 {name:'uq_vehicle_media_object_key',table:'vehicle_media',columns:['object_key'],predicate:null},
 {name:'uq_vehicle_one_cover_photo',table:'vehicle_media',columns:['vehicle_id'],predicate:'is_cover=1andarchived_atisnull'},
 {name:'uq_vehicle_one_active_reservation',table:'reservations',columns:['vehicle_id'],predicate:"status='active'"},
] as const;
function predicate(sql:string):string|null {
 const match=sql.match(/\bWHERE\s+([\s\S]+?)\s*;?\s*$/i);
 return match?match[1].replace(/\s|`|"|\[|\]/g,'').toLowerCase():null;
}
type NameRow = {name:string;tbl_name?:string;sql?:string|null};
type ColumnRow = {seqno:number;name:string|null};
const ok = (result:{success:boolean;results:unknown[]}) =>
 result?.success===true && Array.isArray(result.results);
function sortedMissing(found:Set<string>,expected:readonly string[]) {
 return expected.filter(name=>!found.has(name)).sort();
}

// Diagnostic is explicitly opt-in, Owner-only and read-only. A 200 response proves
// the hosted owner identity, SELECT-only D1 path, and R2 LIST binding worked;
// it does NOT prove all production controls, migration or recovery are ready.
export async function GET(request:Request) {
 const auth=await guard(request);if('error' in auth)return auth.error;
 if(!HOSTED_READONLY_PREFLIGHT_ENABLED)return json({error:'Hosted read-only diagnostic is locked.'},423);
 const params=new URL(request.url).searchParams;
 if(params.size!==0)return json({error:'Diagnostic takes no parameters.'},400);
 try {
  const db=database();
  const bucket=env.BUCKET;
  if(!bucket||typeof bucket.list!=='function')return json({error:'Object storage binding unavailable.'},503);
  const tables=await db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all<NameRow>();
  const indexes=await db.prepare("SELECT name, tbl_name, sql FROM sqlite_master WHERE type='index' AND sql IS NOT NULL").all<NameRow>();
  if(!ok(tables)||!ok(indexes))return json({error:'Hosted schema inspection unavailable.'},503);
  const missingTables=sortedMissing(new Set(tables.results.map(x=>x.name)),SNAPSHOT_TABLES);
  // The actual table, ordered index columns and partial WHERE predicate
  // must match the migration, not merely the index name and UNIQUE keyword.
  const defined=new Map(indexes.results.map(row=>[row.name,row]));
  const missingIndexes:string[]=[];
  for(const spec of REQUIRED_INDEXES){
   const def=defined.get(spec.name);
   if(!def||def.tbl_name!==spec.table||typeof def.sql!=='string'||
      !/^\s*CREATE\s+UNIQUE\s+INDEX\b/i.test(def.sql)||
      predicate(def.sql)!==spec.predicate){missingIndexes.push(spec.name);continue;}
   const columns=await db.prepare("PRAGMA index_info('"+spec.name+"')").all<ColumnRow>();
   if(!ok(columns)||columns.results.length!==spec.columns.length||
      columns.results.some((col,i)=>col.seqno!==i||col.name!==spec.columns[i]))
    missingIndexes.push(spec.name);
  }
  missingIndexes.sort();
  let revision:number|null=null,foreignKeyViolations:null|number=null;
  if(missingTables.length===0) {
   const row=await db.prepare("SELECT value FROM cloud_metadata WHERE key='revision'").first<{value:string}>();
   // The global revision must be a canonical nonnegative decimal integer.
   // Number(''), Number(null), hex and scientific notation are not valid state.
   if(typeof row?.value==='string' && /^(?:0|[1-9][0-9]*)$/.test(row.value) &&
      Number.isSafeInteger(Number(row.value)))revision=Number(row.value);
   const check=await db.prepare('PRAGMA foreign_key_check').all();
   if(ok(check))foreignKeyViolations=check.results.length;
  }
  // A bounded object-storage LIST checks its binding without reading any object
  // keys into a response or asking for private file bytes.
  const listed=await bucket.list({limit:1});
  if(!listed||!Array.isArray(listed.objects))return json({error:'Object storage check unavailable.'},503);
  const schemaReady=missingTables.length===0&&missingIndexes.length===0&&
    revision!==null&&foreignKeyViolations===0;
  return json({
   format:'naina-owner-hosted-readonly-preflight-v1',
   ownerAuthenticated:true,
   cloudReadOnly:true,
   database:{bound:true,expectedTableCount:SNAPSHOT_TABLES.length,
     missingTables,missingCriticalIndexes:missingIndexes,
     revisionValid:revision!==null,foreignKeyViolations,schemaReady},
   privateObjectStorage:{bound:true,listCheckPassed:true},
   infrastructureReady:schemaReady,
   migrationExecuted:false,mediaBytesVerified:false,
   liveReleaseApproved:false,
   note:'Read-only infrastructure diagnostic. A green result never authorizes imports, writes, release switches or deployment.',
  });
 }catch {
  return json({error:'Read-only infrastructure verification unavailable. No records were changed.'},503);
 }
}

