/**
 * Fully offline check of TWO separate, independently fingerprinted private
 * D1/R2 copies (for example an export and an isolated recovery candidate).
 *
 * This verifies canonical D1 row equivalence and the complete media bytes
 * for each copy. It NEVER restores a hosted database or certifies offsite
 * independence. It uses only local read operations.
 */
import {createHash} from 'node:crypto';
import {lstat,readFile,realpath,stat,readdir} from 'node:fs/promises';
import {dirname,resolve,sep} from 'node:path';
import {fileURLToPath} from 'node:url';
import {stable} from './cloud-core.mjs';
import {validatedCloudSnapshot,TABLE_NAMES} from '../scripts/compare-local-browser-cloud.mjs';
import {auditOfflinePrivateMedia} from './offline-private-media-audit.mjs';

const SHA=/^[a-f0-9]{64}$/;
const ROOT=resolve(dirname(fileURLToPath(import.meta.url)),'..');
const MAX_FILE=20*1024*1024;
const hash=value=>createHash('sha256').update(value).digest('hex');
const contains=(outer,inner)=>outer===inner||inner.startsWith(outer+sep);
const sameFile=(a,b)=>a.dev===b.dev&&a.ino===b.ino;
// A separate local path does not prove separate physical storage. However,
// two hard links to the SAME inode cannot even be considered two local copies.
async function rejectSharedMediaInodes(dirA,dirB){
 const [aEntries,bEntries]=await Promise.all([
  readdir(dirA,{withFileTypes:true}),readdir(dirB,{withFileTypes:true})
 ]);
 if(aEntries.some(e=>!e.isFile())||bEntries.some(e=>!e.isFile()))
  throw Error('Private media directories must contain ordinary independent files.');
 const ids=new Set();
 for(const entry of aEntries){
  const info=await lstat(resolve(dirA,entry.name));
  if(!info.isFile())throw Error('Private media file cannot be a link or special file.');
  ids.add(info.dev+':'+info.ino);
 }
 for(const entry of bEntries){
  const info=await lstat(resolve(dirB,entry.name));
  if(!info.isFile())throw Error('Private media file cannot be a link or special file.');
  if(ids.has(info.dev+':'+info.ino))
   throw Error('Source and candidate media share the same underlying file.');
 }
}

async function checkedPaths(snapshotPath,mediaPath,expectedSha){
 if(typeof snapshotPath!=='string'||typeof mediaPath!=='string'||
    typeof expectedSha!=='string'||!SHA.test(expectedSha))
  throw Error('Two private paths and an independently stored raw SHA-256 are required.');
 const snapshot=resolve(snapshotPath),directory=resolve(mediaPath);
 const [snapshotLstat,mediaLstat]=await Promise.all([lstat(snapshot),lstat(directory)]);
 if(!snapshotLstat.isFile()||snapshotLstat.size<10||
    snapshotLstat.size>MAX_FILE||!mediaLstat.isDirectory())
  throw Error('Invalid private export input.');
 const [fileReal,dirReal,rootReal]=await Promise.all([
  realpath(snapshot),realpath(directory),realpath(ROOT)]);
 if(contains(rootReal,fileReal)||contains(rootReal,dirReal))
  throw Error('Private backup inputs must be outside the repository.');
 if(contains(dirReal,fileReal))
  throw Error('Private D1 snapshot must be separate from media directory.');
 const raw=await readFile(fileReal);
 if(hash(raw)!==expectedSha)throw Error('Independent raw snapshot fingerprint mismatch.');
 const tables=validatedCloudSnapshot(JSON.parse(raw.toString('utf8')));
 const info=await stat(fileReal);
 return {snapshot:fileReal,media:dirReal,info,rawSha:expectedSha,tables};
}
function canonicalTableDigest(rows){
 // Compare the whole row, not a subset of price/ID fields. ORDER BY is
 // irrelevant to a backup, but duplicate rows remain observable.
 const items=rows.map(stable).sort();
 const digester=createHash('sha256');
 for(const item of items)digester.update(String(item.length)+':').update(item);
 return digester.digest('hex');
}
export async function auditPairedPrivateRecovery(source,restored){
 if(!Array.isArray(source)||!Array.isArray(restored)||source.length!==3||
   restored.length!==3)
  throw Error('Expected exactly two independently fingerprinted backup sets.');
 const a=await checkedPaths(...source),b=await checkedPaths(...restored);
 if(a.snapshot===b.snapshot||sameFile(a.info,b.info)||
    contains(a.media,b.media)||contains(b.media,a.media)||
    contains(dirname(a.snapshot),b.media)||contains(dirname(b.snapshot),a.media))
  throw Error('Source and candidate recovery paths are not independent.');
 await rejectSharedMediaInodes(a.media,b.media);
 // Independently inspect every exported media byte in both copies. These
 // re-check internal D1 checksums, 27-table structure and relationships.
 const [mediaA,mediaB]=await Promise.all([
  auditOfflinePrivateMedia(a.snapshot,a.media,a.rawSha),
  auditOfflinePrivateMedia(b.snapshot,b.media,b.rawSha)
 ]);
 const disagree=TABLE_NAMES.filter(name=>
  canonicalTableDigest(a.tables[name])!==canonicalTableDigest(b.tables[name]));
 const rowCounts=Object.fromEntries(TABLE_NAMES.map(name=>[name,a.tables[name].length]));
 const rows=Object.values(rowCounts).reduce((sum,n)=>sum+n,0);
 const sourceFilesComplete=mediaA.backupFilesComplete;
 const candidateFilesComplete=mediaB.backupFilesComplete;
 const identicalD1Rows=disagree.length===0;
 const passed=identicalD1Rows&&sourceFilesComplete&&candidateFilesComplete;
 return {
  format:'naina-offline-recovery-pair-audit-v1',
  independentLocalPathsVerified:true,
  sharedDatabaseOrMediaInodesRejected:true,
  physicallyIndependentStorageVerified:false,
  bothSourceFingerprintsVerified:true,
  bothDatabaseStructuresAndRelationsVerified:true,
  tableCount:TABLE_NAMES.length,totalSourceRows:rows,
  sourceMediaFilesVerified:mediaA.verifiedMediaFiles,
  candidateMediaFilesVerified:mediaB.verifiedMediaFiles,
  sourceMediaBytesVerified:mediaA.verifiedBytes,
  candidateMediaBytesVerified:mediaB.verifiedBytes,
  sourceMediaComplete:sourceFilesComplete,
  candidateMediaComplete:candidateFilesComplete,
  identicalD1Rows,
  differentTableCount:disagree.length,
  differentTables:disagree,
  localCopiesEquivalentAndComplete:passed,
  independentOffsiteStorageProven:false,
  sqliteRestoreRehearsed:false,
  hostedD1RestoreVerified:false,
  hostedR2RestoreVerified:false,
  realOwnerAuthenticationVerified:false,
  productionReleaseApproved:false,
  mutationsPerformed:false,
  note:'Only two LOCAL copies were read. No hosted D1/R2 restore, isolation, provenance, offsite custody, or release approval has been proven.',
 };
}

