/* Main inventory cloud editor: exact historical IDs, no browser-local writes. */
(function(root,factory){
 const api=factory();
 if(typeof module==='object'&&module.exports)module.exports=api;
 else root.NainaCloudInventory=api;
})(typeof globalThis==='object'?globalThis:this,function(){
 'use strict';
 let pending=false;
 const fields=['name','reg','category','fuel','owner','bank','purchaseDate','notes','chassis','engine'];
 const editableStatus=new Set(['Available','Review']);
 function text(v,max=2000){if(typeof v!=='string'||v.length>max||/[\x00-\x1f]/.test(v))throw Error('Invalid vehicle field.');return v.trim();}
 function id(v){if(typeof v!=='string'||!v||!v.trim()||v.length>256||/[\x00-\x1f]/.test(v))throw Error('Vehicle ID required.');return v;}
 function money(v){if(v===''||v===undefined||v===null)return undefined;const s=text(v,40);if(!/^(?:0|[1-9]\d{0,11})(?:\.\d{1,2})?$/.test(s))throw Error('Invalid vehicle amount.');const n=Math.round(Number(s)*100)/100;if(!Number.isSafeInteger(Math.round(n*100)))throw Error('Amount exceeds precision limits.');return n;}
 function year(v){if(v===''||v===undefined||v===null)return undefined;const s=text(v,4),n=Number(s);if(!/^\d{4}$/.test(s)||n<1950||n>new Date().getFullYear()+1)throw Error('Invalid manufacturing year.');return n;}
 function uuid(){if(typeof crypto==='undefined'||typeof crypto.randomUUID!=='function')throw Error('Secure vehicle IDs unavailable.');return crypto.randomUUID();}
 function date(v){const s=text(v||'',20);if(!s)return '';if(!/^\d{4}-\d{2}-\d{2}$/.test(s))throw Error('Invalid purchase date.');const d=new Date(s+'T00:00:00Z');if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==s)throw Error('Invalid purchase calendar date.');return s;}
 function expected(v){if(!Number.isSafeInteger(v)||v<0)throw Error('Refresh cloud data before editing.');return v;}
 function plan(kind,existing,values,revision){
  if(!['create','edit','price'].includes(kind))throw Error('Unknown vehicle edit operation.');
  if(kind==='edit'&&!existing)throw Error('Existing cloud vehicle is required.');
  const data={};let resource='vehicles',mode=kind==='create'?'create':'update',vehicleId=existing?id(existing.id):uuid();
  if(kind==='price'){
   if(!existing)throw Error('Select an existing cloud vehicle.');
   const amount=money(values.new_price),reason=text(values.reason||'',500);
   if(amount===undefined)throw Error('New asking price is required.');
   if(!reason)throw Error('Price change reason is required.');
   resource='price_history';mode='create';data.vehicle_id=vehicleId;data.new_price=amount;data.reason=reason;
   vehicleId=uuid();
  }else{
   if(!values||typeof values!=='object')throw Error('Vehicle form is missing.');
   const supplied=key=>Object.prototype.hasOwnProperty.call(values,key);
   if(kind==='create'){
    const name=text(values.name||'',300);if(!name)throw Error('Vehicle model is required.');
    for(const key of fields){
     if(key==='name')data[key]=name;
     else if(key==='purchaseDate')data[key]=date(values[key]);
     else data[key]=text(values[key]||'',key==='notes'?2000:500);
    }
    const modelYear=year(values.year),cost=money(values.cost),odo=money(values.km);
    if(modelYear!==undefined)data.year=modelYear;
    if(cost!==undefined)data.cost=cost;
    if(odo!==undefined)data.km=odo;
    const status=text(values.status||'Available',30);
    if(!editableStatus.has(status))throw Error('New vehicle must be Available or Review.');
    data.status=status;
    const ask=money(values.ask);if(ask!==undefined)data.ask=ask;
   }else{
    // Updates are sparse: a modal edits only the fields actually changed.
    // Do not normalize untouched original Excel text or wipe an omitted field.
    if(typeof existing.name!=='string'||!existing.name.trim())
     throw Error('Historical vehicle name requires reconciliation.');
    for(const key of fields){
     if(!supplied(key))continue;
     const raw=values[key],previous=existing[key]??'';
     if(typeof raw!=='string')throw Error('Invalid vehicle field.');
     if(raw===String(previous))continue;
     if(key==='purchaseDate'&&typeof previous==='string'&&
        previous.slice(0,10)===raw&&/^\d{4}-\d{2}-\d{2}$/.test(raw))continue;
     const next=key==='purchaseDate'?date(raw):text(raw,key==='name'?300:key==='notes'?2000:500);
     if(key==='name'&&!next)throw Error('Vehicle model is required.');
     if(next===String(previous))continue;
     data[key]=next;
    }
    for(const key of ['year','cost','km']){
     if(!supplied(key))continue;
     const raw=values[key],prior=existing[key];
     if(raw===''||raw===undefined||raw===null){
      if(prior!==null&&prior!==undefined&&prior!=='')
       throw Error('Clearing historical numeric fields requires separate reconciliation.');
      continue;
     }
     const next=key==='year'?year(raw):money(raw);
     if(prior!==null&&prior!==undefined&&prior!==''&&Number(prior)===next)continue;
     data[key]=next;
    }
    if(!Object.keys(data).length)throw Error('No vehicle changes to save.');
   }
  }
  return {resource,mode,id:vehicleId,data,expectedRevision:expected(revision),idempotencyKey:uuid()};
 }
 async function write(fetchFn,instruction){
  if(!instruction||!['vehicles','price_history'].includes(instruction.resource))throw Error('Unsupported vehicle cloud write.');
  let response;
  try{response=await fetchFn('/api/private-crm-write',{method:'POST',credentials:'same-origin',cache:'no-store',redirect:'error',headers:{'Content-Type':'application/json'},body:JSON.stringify(instruction)});}
  catch{throw Error('Cloud write outcome unknown. Refresh and reconcile before trying again.');}
  if(!response?.ok){if(response?.status===423)throw Error('Cloud writes remain locked.');if(response?.status===409)throw Error('Cloud revision or inventory conflict. Refresh before editing.');throw Error('Cloud vehicle save not confirmed. Inspect current records.');}
  let body;try{body=await response.json();}catch{throw Error('Unreadable vehicle save receipt. Refresh and reconcile.');}
  if(body?.result?.resource!==instruction.resource||body?.result?.id!==instruction.id||body?.result?.revision!==instruction.expectedRevision+1)throw Error('Cloud receipt mismatch. Refresh and reconcile.');
  return body.result;
 }
 function openDialog({kind,existing,revision,notify,refresh,canSubmit}){
  if(pending||!['create','edit','price'].includes(kind)||typeof canSubmit!=='function')return;
  const modal=document.getElementById('cloud-vehicle-dialog'),form=document.getElementById('cloud-vehicle-form'),holder=document.getElementById('cloud-vehicle-fields');
  if(!modal||!form||!holder)return;
  document.getElementById('cloud-vehicle-title').textContent={create:'Add cloud vehicle',edit:'Edit cloud vehicle',price:'Change cloud asking price'}[kind];
  holder.replaceChildren();
  function field(label,key,value='',type='text'){
   const wrap=document.createElement('label');wrap.textContent=label+' ';
   const input=document.createElement('input');input.name=key;input.type=type;input.maxLength=2000;input.value=String(value??'');
   wrap.appendChild(input);holder.appendChild(wrap);return input;
  }
  if(kind==='price'){
   if(!existing){notify('Existing vehicle required.');return;}
   field('New asking price (₹)','new_price',existing.ask??'');
   field('Reason for change','reason','');
  }else{
   field('Vehicle model','name',existing?.name||'');
   field('Registration number','reg',existing?.reg||'');
   field('Year','year',existing?.year??'');
   field('Category','category',existing?.category||'');
   field('Fuel','fuel',existing?.fuel||'');
   field('Ownership','owner',existing?.owner||'');
   field('Odometer (km)','km',existing?.km??'');
   field('Source bank','bank',existing?.bank||'');
   field('Purchase cost (₹)','cost',existing?.cost??'');
   if(kind==='create')field('Expected asking price (₹)','ask','');
   field('Purchase date','purchaseDate',existing?.purchaseDate||'','date');
   field('Chassis number','chassis',existing?.chassis||'');
   field('Engine number','engine',existing?.engine||'');
   field('Notes','notes',existing?.notes||'');
  }
  const submit=form.querySelector('button[type="submit"]');
  form.onsubmit=async e=>{
   e.preventDefault();if(pending)return;
   if(!canSubmit()){notify('Cloud view changed while editing. Refresh.');modal.close();return;}
   let instruction;
   try{instruction=plan(kind,existing,Object.fromEntries(new FormData(form)),revision);}
   catch(error){notify(error.message);return;}
   if(!confirm('Confirm '+kind+' on your private cloud inventory? Historical IDs and browser-local records will remain unchanged.'))return;
   if(!canSubmit()){notify('Cloud view changed during confirmation. Refresh.');modal.close();return;}
   pending=true;submit.disabled=true;
   try{await write(fetch,instruction);modal.close();pending=false;submit.disabled=false;notify('Cloud vehicle update confirmed. Reloading records.');await refresh();}
   catch(error){notify(error.message);}finally{pending=false;submit.disabled=false;}
  };
  document.getElementById('cloud-vehicle-close').onclick=()=>{if(!pending)modal.close();};
  if(!modal.open)modal.showModal();
 }
 return {plan,write,openDialog,isPending:()=>pending};
});

