import { sql } from 'drizzle-orm';
import { sqliteTable, text, integer, real, uniqueIndex, index, check } from 'drizzle-orm/sqlite-core';
// Full original record stays in payload_json. Projections are for future queries.
export const vehicles = sqliteTable('vehicles', {
 id:text('id').primaryKey(), ownerId:text('owner_id').notNull(),
 payloadJson:text('payload_json').notNull(), status:text('status').notNull(),
 registrationKey:text('registration_key'), chassisKey:text('chassis_key'),
 revision:integer('revision').notNull().default(1), updatedAt:text('updated_at').notNull(),
}, t=>[uniqueIndex('vehicles_registration_unique').on(t.registrationKey),uniqueIndex('vehicles_chassis_unique').on(t.chassisKey)]);
export const customers=sqliteTable('customers',{id:text('id').primaryKey(),ownerId:text('owner_id').notNull(),payloadJson:text('payload_json').notNull(),revision:integer('revision').notNull().default(1)});
export const sales=sqliteTable('sales',{id:text('id').primaryKey(),vehicleId:text('vehicle_id').notNull().references(()=>vehicles.id),customerId:text('customer_id').references(()=>customers.id),payloadJson:text('payload_json').notNull(),revision:integer('revision').notNull().default(1)});
export const expenses=sqliteTable('expenses',{id:text('id').primaryKey(),vehicleId:text('vehicle_id').notNull().references(()=>vehicles.id),kind:text('kind',{enum:['parking','other']}).notNull(),amountJson:text('amount_json').notNull(),payloadJson:text('payload_json').notNull()},t=>[uniqueIndex('expenses_vehicle_kind_unique').on(t.vehicleId,t.kind)]);
export const leads=sqliteTable('leads',{id:text('id').primaryKey(),ownerId:text('owner_id').notNull(),payloadJson:text('payload_json').notNull(),revision:integer('revision').notNull().default(1)});
export const importHistory=sqliteTable('import_history',{id:text('id').primaryKey(),ownerId:text('owner_id').notNull(),backupHash:text('backup_hash').notNull(),status:text('status').notNull(),previewJson:text('preview_json').notNull(),createdAt:text('created_at').notNull()},t=>[uniqueIndex('import_backup_hash_unique').on(t.backupHash)]);
export const auditLogs=sqliteTable('audit_logs',{id:text('id').primaryKey(),actorId:text('actor_id').notNull(),action:text('action').notNull(),entityId:text('entity_id'),beforeJson:text('before_json'),afterJson:text('after_json'),createdAt:text('created_at').notNull()});
export const metadata=sqliteTable('cloud_metadata',{key:text('key').primaryKey(),value:text('value').notNull()});
export const connectionProbes=sqliteTable('connection_probes',{id:text('id').primaryKey(),nonce:text('nonce').notNull(),createdAt:text('created_at').notNull()});

// Additive private CRM metadata. Existing IDs are referenced verbatim.
// File bytes remain in a future private R2 binding; no uploads or data seeds here.
export const vehicleMedia=sqliteTable('vehicle_media',{
 id:text('id').primaryKey().notNull(),
 vehicle_id:text('vehicle_id').notNull().references(()=>vehicles.id),
 object_key:text('object_key').notNull(),
 original_filename:text('original_filename').notNull(),
 mime_type:text('mime_type').notNull(),
 bytes:integer('bytes').notNull(),
 category:text('category').notNull(),
 notes:text('notes'),
 sha256:text('sha256'),
 version_number:integer('version_number').notNull().default(1),
 is_cover:integer('is_cover').notNull().default(0),
 uploaded_by:text('uploaded_by').notNull(),
 uploaded_at:text('uploaded_at').notNull().default(sql`CURRENT_TIMESTAMP`),
 archived_at:text('archived_at'),
},t=>[
 uniqueIndex('uq_vehicle_media_object_key').on(t.object_key),
 check('ck_vehicle_media_bytes',sql`bytes >= 0`),
 check('ck_vehicle_media_version_number',sql`version_number >= 1`),
 check('ck_vehicle_media_is_cover',sql`is_cover IN (0,1)`),
 index('ix_media_vehicle').on(t.vehicle_id,t.category,t.uploaded_at),
 uniqueIndex('uq_vehicle_one_cover_photo').on(t.vehicle_id).where(sql`is_cover=1 AND archived_at IS NULL`)
]);
export const documentRequirements=sqliteTable('document_requirements',{
 id:text('id').primaryKey().notNull(),
 vehicle_id:text('vehicle_id').notNull().references(()=>vehicles.id),
 document_type:text('document_type').notNull(),
 status:text('status').notNull().default('Missing'),
 due_at:text('due_at'),
 notes:text('notes'),
 updated_at:text('updated_at').notNull().default(sql`CURRENT_TIMESTAMP`),
},t=>[
 check('ck_document_requirements_status',sql`status IN ('Missing','Pending','Received','Delivered','Not Applicable')`),
 uniqueIndex('uq_document_requirements_vehicle_id_document_type').on(t.vehicle_id,t.document_type)
]);
export const vehicleAgeBaselines=sqliteTable('vehicle_age_baselines',{
 vehicle_id:text('vehicle_id').primaryKey().notNull().references(()=>vehicles.id),
 purchased_at:text('purchased_at'),
 source_quality:text('source_quality').notNull().default('Unknown'),
 notes:text('notes'),
},t=>[
 check('ck_vehicle_age_baselines_source_quality',sql`source_quality IN ('Verified','Estimated','Unknown')`)
]);
export const vehicleLocations=sqliteTable('vehicle_locations',{
 vehicle_id:text('vehicle_id').primaryKey().notNull().references(()=>vehicles.id),
 location_type:text('location_type').notNull(),
 location_label:text('location_label'),
 notes:text('notes'),
 changed_at:text('changed_at').notNull().default(sql`CURRENT_TIMESTAMP`),
});
export const vehicleTimeline=sqliteTable('vehicle_timeline',{
 id:text('id').primaryKey().notNull(),
 vehicle_id:text('vehicle_id').notNull().references(()=>vehicles.id),
 event_kind:text('event_kind').notNull(),
 happened_at:text('happened_at').notNull().default(sql`CURRENT_TIMESTAMP`),
 title:text('title').notNull(),
 notes:text('notes'),
 metadata_json:text('metadata_json'),
 actor:text('actor').notNull(),
},t=>[
 index('ix_timeline_vehicle_date').on(t.vehicle_id,t.happened_at)
]);
export const vehicleInspections=sqliteTable('vehicle_inspections',{
 id:text('id').primaryKey().notNull(),
 vehicle_id:text('vehicle_id').notNull().references(()=>vehicles.id),
 inspected_at:text('inspected_at').notNull(),
 inspector:text('inspector'),
 odometer_km:real('odometer_km'),
 overall_condition:text('overall_condition'),
 notes:text('notes'),
 checklist_json:text('checklist_json').notNull().default('{}'),
 estimated_repairs:real('estimated_repairs'),
 created_at:text('created_at').notNull().default(sql`CURRENT_TIMESTAMP`),
});
export const cashbookEntries=sqliteTable('cashbook_entries',{
 id:text('id').primaryKey().notNull(),
