import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';

const sandbox={URL,URLSearchParams,Number,Set,Map,Object,String,Array,Error};
vm.runInNewContext(fs.readFileSync('public/main-cloud-adapter.js','utf8'),sandbox);
const {recordsToView}=sandbox.NainaMainCloudAdapter;

function snapshot(){
 const vehicle={id:'vehicle-A',status:'Sold',payload:{id:'vehicle-A',status:'Sold',name:'Synthetic vehicle',sale:80000,balance:12000,parking:'500',otherExpenses:'125.50',expenses:'625.50'}};
 const sale={id:'sale-A',vehicleId:'vehicle-A',payload:{},sale:80000,recordedBalance:12000};
 return {
  vehicles:[vehicle],leads:[],sales:[sale],
  expenses:[{id:'parking-total',vehicleId:'vehicle-A',kind:'parking',amount:500}],
  customer_payments:[{id:'payment-1',sale_id:'sale-A',amount:1000}],
 };
}
test('reconciled payment and expense projections preserve original vehicle IDs',()=>{
 const view=recordsToView(snapshot());
 assert.equal(view.bikes[0].id,'vehicle-A');
 assert.equal(view.expenses[0].id,'parking-total');
 assert.equal(view.customer_payments[0].sale_id,'sale-A');
});
test('different normalized expense and vehicle totals must prevent cloud view',()=>{
 const s=snapshot();s.expenses[0].amount=505;
 assert.throws(()=>recordsToView(s),/expense total disagrees/);
});
test('duplicate parking or other expense totals must prevent cloud view',()=>{
 const s=snapshot();s.expenses.push({...s.expenses[0],id:'duplicate-total'});
 assert.throws(()=>recordsToView(s),/expense linkage requires reconciliation/);
});
test('dangling or repeated payment references must prevent cloud view',()=>{
 const s=snapshot();s.customer_payments[0].sale_id='unlinked-sale';
 assert.throws(()=>recordsToView(s),/payment linkage requires reconciliation/);
 const other=snapshot();other.customer_payments.push({...other.customer_payments[0]});
 assert.throws(()=>recordsToView(other),/payment linkage requires reconciliation/);
});
test('missing or negative payment amounts must prevent cloud view',()=>{
 const s=snapshot();s.customer_payments[0].amount=-1;
 assert.throws(()=>recordsToView(s),/financial amount/);
 const zero=snapshot();zero.customer_payments[0].amount=0;
 assert.throws(()=>recordsToView(zero),/payment linkage/);
});
test('legacy combined expense components must agree before profit is trusted',()=>{
 const s=snapshot();s.vehicles[0].payload.expenses='625.51';
 assert.throws(()=>recordsToView(s),/components disagree/);
});
test('ambiguous formatted money is rejected rather than guessed',()=>{
 const s=snapshot();s.vehicles[0].payload.parking='5,00';
 assert.throws(()=>recordsToView(s),/financial amount/);
});

test('sold cloud vehicles without any linked sale cannot be displayed as reconciled stock',()=>{
 const s=snapshot();s.sales=[];s.customer_payments=[];
 assert.throws(()=>recordsToView(s),/missing its linked sale/);
});
test('recorded payments plus unpaid balance may never exceed selling price',()=>{
 const s=snapshot();s.customer_payments[0].amount=70000;
 assert.throws(()=>recordsToView(s),/receipts exceed/);
});

