/* Owner-only vehicle media transport. Browser files and private R2 bytes are never persisted
   to localStorage or inserted into source HTML. Call only after server media activation. */
(function(root,factory){
 const api=factory();
 if(typeof module==='object'&&module.exports)module.exports=api;
 else root.NainaCloudMedia=api;
})(typeof globalThis==='object'?globalThis:this,function(){
 'use strict';
 let pending=false;
 const retryTokens=new Map();
 const max=15*1024*1024;
 const categories=new Set(['photo','rc','noc','insurance','auction','form','sale','other']);
 const types={jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp',heic:'image/heic',pdf:'application/pdf'};
 function id(v){if(typeof v!=='string'||!v||v.length>256||/[\x00-\x1f]/.test(v))throw Error('Invalid vehicle or media ID.');return v;}
 function filename(v){if(typeof v!=='string'||!v||v.length>200||/[\/\\\x00-\x1f]/.test(v)||v.includes('..'))throw Error('Invalid filename.');return v;}
 function params(action,vehicle,opts={}){
  const p=new URLSearchParams({action,vehicleId:id(vehicle)});
  for(const [k,v]of Object.entries(opts))if(v!==undefined&&v!==null)p.set(k,String(v));
  return '/api/private-media?'+p.toString();
 }
 function tokenFor(file,vehicleId,category){
  const info=validateFile(file,category),key=JSON.stringify([id(vehicleId),info.name,info.mime,category,file.size,file.lastModified??null]);
  if(retryTokens.has(key))return retryTokens.get(key);
  if(typeof crypto==='undefined'||typeof crypto.randomUUID!=='function')throw Error('Secure upload token unavailable.');
  const token=crypto.randomUUID();retryTokens.set(key,token);return token;
 }
 function validateFile(file,category){
  if(!file||typeof file.name!=='string'||typeof file.size!=='number'||file.size<=0||file.size>max)throw Error('File is empty or exceeds the 15 MiB limit.');
  const name=filename(file.name),ext=name.split('.').at(-1).toLowerCase(),mime=types[ext];
  if(!mime||file.type&&file.type!==mime||!categories.has(category)||category==='photo'&&!mime.startsWith('image/'))throw Error('Unsupported media format or category.');
  return {name,mime,category};
 }
 async function request(fetchFn,url,options){
  let response;try{response=await fetchFn(url,{credentials:'same-origin',cache:'no-store',redirect:'error',...options});}
  catch{throw Error('Private media network result unknown. Check the gallery before retrying.');}
  if(!response?.ok){if(response?.status===423)throw Error('Private media is not activated.');if(response?.status===409)throw Error('Media conflict or incomplete upload. Review metadata before retrying.');throw Error('Private media operation not confirmed ('+(response?.status??'network')+').');}
  return response;
 }
 async function upload(fetchFn,vehicleId,file,category,uploadId){
  const info=validateFile(file,category),token=id(uploadId);
  if(!/^[A-Za-z0-9_-]{16,100}$/.test(token))throw Error('Invalid upload token.');
  const response=await request(fetchFn,params('upload',vehicleId,{filename:info.name,category:info.category,uploadId:token}),{method:'POST',headers:{'Content-Type':info.mime},body:file});
  let body;try{body=await response.json();}catch{throw Error('Upload receipt unreadable. Verify the gallery before retrying.');}
  if(!body||typeof body.id!=='string'||body.filename!==info.name||body.bytes!==file.size)throw Error('Upload receipt incomplete. Verify before retrying.');
  return body;
 }
 async function mutate(fetchFn,action,vehicleId,mediaId){
  if(!['cover','archive','restore'].includes(action))throw Error('Unsupported private media operation.');
  const response=await request(fetchFn,params(action,vehicleId,{mediaId:id(mediaId)}),{method:'POST'});
  const body=await response.json();
  if(body?.id!==mediaId||body?.action!==action)throw Error('Private media receipt invalid. Refresh before proceeding.');
  return body;
 }
 async function download(fetchFn,vehicleId,mediaId,{preview=false,archived=false}={}){
  if(preview&&archived)throw Error('Archived files cannot be previewed. Export the original privately.');
  const response=await request(fetchFn,params(archived?'export':preview?'preview':'download',vehicleId,{mediaId:id(mediaId)}),{method:'GET'});
  const contentType=response.headers?.get('content-type')||'';
  if(preview&&!['image/jpeg','image/png','image/webp'].includes(contentType))throw Error('Private preview is available for JPEG, PNG and WEBP only.');
  if(!preview&&contentType!=='application/octet-stream')throw Error('Unexpected download response type.');
  const length=Number(response.headers?.get('content-length')||'0');
  if(!Number.isSafeInteger(length)||length<1||length>max)throw Error('Invalid download size.');
  const blob=await response.blob();
  if(blob.size!==length||blob.size>max)throw Error('Incomplete private media download.');
  return blob;
 }
 function begin(){if(pending)throw Error('A private media request is already in progress.');pending=true;}
 function end(){pending=false;}
 return {params,tokenFor,validateFile,upload,mutate,download,begin,end,isPending:()=>pending};
});

