import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,writeFileSync,readFileSync,statSync,existsSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join,resolve} from 'node:path';
import {spawnSync} from 'node:child_process';
import {createPrivateSaleReview,attachCloudCandidatesToSaleReview} from '../lib/private-sale-review.mjs';
import {TABLE_NAMES,validatedCloudSnapshot} from '../scripts/compare-local-browser-cloud.mjs';
import {stable} from '../lib/cloud-core.mjs';
import {createHash} from 'node:crypto';

const hash='a'.repeat(64);
const sale=(changes={})=>({
 id:'HISTORIC-SOURCE-VEHICLE',name:'Test motorcycle',status:'Sold',
 reg:'PRIVATE-REG',chassis:'PRIVATE-CHASSIS',
 buyer:'',buyerPhone:'PRIVATE-PHONE',buyerAddress:'PRIVATE-ADDRESS',
 sale:50000,balance:12000,saleDate:'2025-01-01',
 sourceInventoryRow:12,sourceSalesRow:34,
 sourceInventoryStatus:'SOLD',sourceSalesStatus:'SOLD',
 parking:100,otherExpenses:200,expenses:300,
 sourceSales:[
  {label:'S NO.',column:'A',value:7},
  {label:'COSTUMER NAME',column:'C',value:''},
  {label:'SELLING PRICE',column:'E',value:'50000'},
  {label:'REMAINNING AMOUNT',column:'F',value:'12000'},
 ],...changes,
});
const fixture=()=>({version:3,bikes:[
 sale(),sale({id:'UNRESOLVED-VEHICLE',reg:'REVIEW-REG',
  chassis:'REVIEW-CHASSIS',status:'Review',buyer:'',
  sourceSalesRow:35,sourceSales:[{label:'S NO.',value:8}]}),
],leads:[]});

test('private worksheet preserves original source values and never fabricates normalized identities',()=>{
 const original=fixture(),before=JSON.stringify(original);
 const report=createPrivateSaleReview(original,hash);
 assert.equal(report.reviewRowCount,2);
 assert.equal(report.originalVehicleCount,2);
 assert.equal(report.originalStatusCounts.Review,1);
 assert.equal(report.reviewRows[0].originalVehicleId,'HISTORIC-SOURCE-VEHICLE');
 assert.equal(report.reviewRows[0].originalSalesSheetRow,34);
 assert.equal(report.reviewRows[0].originalSalesSerial,7);
 assert.equal(report.reviewRows[0].recordedBuyerName,'');
 assert.equal(report.reviewRows[0].recordedOutstandingBalance,12000);
 assert.equal(report.reviewRows[0].originalSalesEvidence[2].value,'50000');
 assert.equal(report.reviewRows[0].verifiedExistingCloudSaleId,null);
 assert.equal(report.reviewRows[0].verifiedExistingCloudCustomerId,null);
 assert.equal(report.reviewRows[0].paymentLedgerReconciled,false);
 assert.equal(report.reviewRows[0].proposedImportAction,'NONE_REVIEW_ONLY');
 assert.equal(report.reviewRows[1].originalVehicleStatus,'Review');
 assert.equal(report.migrationAllowed,false);
 assert.equal(JSON.stringify(original),before);
});
test('available inventory is counted but not falsely represented as a past sale',()=>{
 const a=fixture();a.bikes.push(sale({id:'AVAILABLE-VEHICLE',
  reg:'AVAILABLE-REG',chassis:'AVAILABLE-CHASSIS',
  status:'Available',sourceSalesRow:36,sourceSales:[{label:'S NO.',value:9}]}));
 const result=createPrivateSaleReview(a,hash);
 assert.equal(result.originalStatusCounts.Available,1);
 assert.equal(result.originalVehicleCount,3);
 assert.equal(result.reviewRowCount,2);
});
test('malformed original backups and unverifiable source hash fail closed',()=>{
 assert.throws(()=>createPrivateSaleReview(fixture(),'invalid'),/SHA-256/);
 assert.throws(()=>createPrivateSaleReview({...fixture(),bikes:[sale(),sale()]},hash),
  /failed validation/);
});
test('CLI creates chmod-0600 outside repository, refuses overwrites and keeps console private',()=>{
 const base=mkdtempSync(join(tmpdir(),'naina-review-test-'));
 try {
  const source=join(base,'original.json'),out=join(base,'review.json');
  const data=JSON.stringify(fixture());writeFileSync(source,data);
  const cli=resolve('scripts/create-private-sale-review.mjs');
  const run=()=>spawnSync(process.execPath,[cli,source,out],{encoding:'utf8'});
  const first=run();
  assert.equal(first.status,0,first.stderr);
  assert.equal(statSync(out).mode&0o777,0o600);
  assert.equal(readFileSync(source,'utf8'),data);
  assert.equal(JSON.parse(readFileSync(out,'utf8')).reviewRowCount,2);
  assert.doesNotMatch(first.stdout,/PRIVATE-REG|PRIVATE-PHONE|HISTORIC-SOURCE-VEHICLE/);
  const again=run();assert.equal(again.status,2);
  assert.equal(JSON.parse(readFileSync(out,'utf8')).reviewRowCount,2);
  // Never store business records in source checkout, even on a new filename.
  const forbidden=join(resolve('.'),'private-manifest-do-not-write.json');
  const unsafe=spawnSync(process.execPath,[cli,source,forbidden],{encoding:'utf8'});
  assert.equal(unsafe.status,2);
  assert.equal(existsSync(forbidden),false);
  // A tracked harmless JSON fixture is sufficient to prove checkout input is denied.
  const fromCheckout=spawnSync(process.execPath,[cli,resolve('package.json'),
   join(base,'unwanted-private-result.json')],{encoding:'utf8'});
  assert.equal(fromCheckout.status,2);
  assert.equal(existsSync(join(base,'unwanted-private-result.json')),false);
 }finally{rmSync(base,{recursive:true,force:true});}
});

const signSnapshot=tables=>{
 const body={format:'naina-cloud-snapshot-v1',exportedAt:'2026-10-25T10:00:00Z',tables};
 return {...body,sha256:createHash('sha256').update(stable(body)).digest('hex')};
};
const cloudData=()=>{
 const t=Object.fromEntries(TABLE_NAMES.map(x=>[x,[]]));
 t.cloud_metadata=[{key:'revision',value:'2'}];
 t.vehicles=[{id:'HISTORIC-SOURCE-VEHICLE',status:'Sold',
  payload_json:JSON.stringify({id:'HISTORIC-SOURCE-VEHICLE',status:'Sold'})}];
 t.customers=[{id:'SYNTHETIC-CLOUD-CUSTOMER'}];
 t.sales=[{id:'SYNTHETIC-CLOUD-SALE',vehicle_id:'HISTORIC-SOURCE-VEHICLE',
  customer_id:'SYNTHETIC-CLOUD-CUSTOMER'}];
 t.customer_payments=[{id:'SYNTHETIC-RECEIPT',sale_id:'SYNTHETIC-CLOUD-SALE',amount:2}];
 return t;
};
test('verified cloud sale IDs become untrusted review candidates, never confirmed identities',()=>{
 const input=fixture(),before=JSON.stringify(input);
 const original=createPrivateSaleReview(input,hash),originalJSON=JSON.stringify(original);
 const tables=validatedCloudSnapshot(signSnapshot(cloudData()));
 const review=attachCloudCandidatesToSaleReview(original,tables,'b'.repeat(64));
 assert.equal(review.cloudSnapshotCompared,true);
 assert.equal(review.cloudVehiclesWithMatchingSourceId,1);
 assert.equal(review.linkedCloudSaleCandidates,1);
 assert.equal(review.cloudSaleCandidatesWithCustomerLinks,1);
 assert.equal(review.existingCloudSaleIdsVerified,0);
 assert.equal(review.existingCloudCustomerIdsVerified,0);
 assert.equal(review.migrationAllowed,false);
 assert.equal(review.reviewRows[0].existingCloudSaleCandidates[0].existingCloudSaleId,
  'SYNTHETIC-CLOUD-SALE');
 assert.equal(review.reviewRows[0].existingCloudSaleCandidates[0].candidatePaymentRowCount,1);
 assert.equal(review.reviewRows[0].paymentLedgerReconciled,false);
 assert.equal(review.reviewRows[0].mappingDecision,'PENDING');
 assert.equal(review.reviewRows[1].existingCloudSaleCandidates.length,0);
 assert.equal(JSON.stringify(original),originalJSON);
 assert.equal(JSON.stringify(input),before);
});
test('cloud status conflicts remain unresolved despite apparently matching vehicle ID',()=>{
 const cloud=cloudData();
 cloud.vehicles[0].status='Available';
 cloud.vehicles[0].payload_json=JSON.stringify({id:'HISTORIC-SOURCE-VEHICLE',status:'Available'});
 // Available stock linked to a completed sale must fail the snapshot auditor.
 assert.throws(()=>validatedCloudSnapshot(signSnapshot(cloud)),/relationship issues/);
 const underReview=cloudData();
 underReview.vehicles[0].status='Review';
 underReview.vehicles[0].payload_json=JSON.stringify({id:'HISTORIC-SOURCE-VEHICLE',status:'Review'});
 const undecided=attachCloudCandidatesToSaleReview(createPrivateSaleReview(fixture(),hash),
  validatedCloudSnapshot(signSnapshot(underReview)),'b'.repeat(64));
 assert.equal(undecided.cloudStatusConflicts,1);
 assert.equal(undecided.linkedCloudSaleCandidates,1);
 assert.equal(undecided.migrationAllowed,false);
 const empty=cloudData();empty.sales=[];empty.customer_payments=[];empty.customers=[];
 empty.vehicles[0].status='Available';
 empty.vehicles[0].payload_json=JSON.stringify({id:'HISTORIC-SOURCE-VEHICLE',status:'Available'});
 const data=attachCloudCandidatesToSaleReview(createPrivateSaleReview(fixture(),hash),
  validatedCloudSnapshot(signSnapshot(empty)),'b'.repeat(64));
 assert.equal(data.cloudStatusConflicts,1);
 assert.equal(data.reviewRows[0].statusConflict,true);
 assert.equal(data.reviewRows[0].proposedImportAction,'NONE_REVIEW_ONLY');
});
test('private CLI accepts independently fingerprinted complete cloud snapshots only',()=>{
 const dir=mkdtempSync(join(tmpdir(),'naina-cloud-sale-candidates-'));
 try{
  const cli=resolve('scripts/create-private-sale-review.mjs');
  const input=join(dir,'browser.json'),cloud=join(dir,'cloud.json'),
    output=join(dir,'review.json');
  const backup=JSON.stringify(fixture()),snapshot=JSON.stringify(signSnapshot(cloudData()));
  writeFileSync(input,backup);writeFileSync(cloud,snapshot);
  const fingerprint=createHash('sha256').update(snapshot).digest('hex');
  const command=(outputFile,expected)=>spawnSync(process.execPath,
    [cli,input,outputFile,cloud,expected],{encoding:'utf8'});
  const bad=command(output,'0'.repeat(64));
  assert.equal(bad.status,2);assert.equal(existsSync(output),false);
  const good=command(output,fingerprint);
  assert.equal(good.status,0,good.stderr);
  const review=JSON.parse(readFileSync(output,'utf8'));
  assert.equal(review.cloudSnapshotCompared,true);
  assert.equal(review.reviewRows[0].existingCloudSaleCandidates.length,1);
  assert.equal(review.migrationAllowed,false);
  assert.doesNotMatch(good.stdout,/SYNTHETIC-CLOUD-SALE|SYNTHETIC-RECEIPT|HISTORIC-SOURCE-VEHICLE/);
  assert.equal(command(output,fingerprint).status,2,'Never overwrite previous private review.');
  assert.equal(readFileSync(input,'utf8'),backup);
  assert.equal(readFileSync(cloud,'utf8'),snapshot);
 }finally{rmSync(dir,{recursive:true,force:true});}
});

