// OFFLINE-ONLY historical sale review. Preserves original evidence verbatim.
// A review worksheet is NOT a verified cloud sale, customer or payment mapping.
import {auditBrowserBackup} from './browser-backup-audit.mjs';

const has=(value,key)=>Object.prototype.hasOwnProperty.call(value,key);
const copied=(source,key)=>has(source,key)?source[key]:null;
const selectedEvidence=new Set([
 'S NO.','STATUS','COSTUMER NAME','COSTUMER ADDRESS','CONTACT NO.',
 'SALE DATE','SELLING PRICE','REMAINNING AMOUNT','REMAINING AMOUNT'
]);
function evidence(bike){
 if(!Array.isArray(bike.sourceSales))return [];
 return bike.sourceSales.filter(cell=>cell&&typeof cell==='object'&&
  selectedEvidence.has(String(cell.label??'').trim().toUpperCase()))
  .map(cell=>({
   column:copied(cell,'column'),label:copied(cell,'label'),
   value:copied(cell,'value'),
  }));
}
export function createPrivateSaleReview(backup,sourceSha256){
 if(typeof sourceSha256!=='string'||!/^[a-f0-9]{64}$/.test(sourceSha256))
  throw Error('Exact source backup SHA-256 required.');
 const audit=auditBrowserBackup(backup);
 if(!audit.backupValid)throw Error('Original browser backup failed validation.');
 const rows=[];
 for(const bike of backup.bikes){
  if(bike.status!=='Sold'&&bike.status!=='Review')continue;
  const cells=evidence(bike);
  const serial=cells.filter(cell=>
   String(cell.label??'').trim().toUpperCase()==='S NO.');
  rows.push({
   originalVehicleId:bike.id,
   originalVehicleStatus:bike.status,
   vehicleName:copied(bike,'name'),
   originalRegistration:copied(bike,'reg'),
   originalChassis:copied(bike,'chassis'),
   originalInventorySheetRow:copied(bike,'sourceInventoryRow'),
   originalSalesSheetRow:copied(bike,'sourceSalesRow'),
   originalSalesSerial:serial.length===1?serial[0].value:null,
   sourceInventoryStatus:copied(bike,'sourceInventoryStatus'),
   sourceSalesStatus:copied(bike,'sourceSalesStatus'),
   recordedBuyerName:copied(bike,'buyer'),
   recordedBuyerPhone:copied(bike,'buyerPhone'),
   recordedBuyerAddress:copied(bike,'buyerAddress'),
   recordedSaleDate:copied(bike,'saleDate'),
   recordedSalePrice:copied(bike,'sale'),
   recordedOutstandingBalance:copied(bike,'balance'),
   originalSalesEvidence:cells,
   verifiedExistingCloudSaleId:null,
   verifiedExistingCloudCustomerId:null,
   historicalSaleIdentityVerified:false,
   historicalCustomerIdentityVerified:false,
   paymentLedgerReconciled:false,
   documentaryEvidenceVerified:false,
   proposedImportAction:'NONE_REVIEW_ONLY',
   mappingDecision:'PENDING',
  });
 }
 return {
  format:'naina-private-sale-review-v1',
  sourceBackupSha256:sourceSha256,
  sourceBackupVersion:backup.version,
  originalVehicleCount:backup.bikes.length,
  originalStatusCounts:structuredClone(audit.statuses),
  reviewRows:rows,
  reviewRowCount:rows.length,
  soldWithUnrecordedBuyerName:audit.legacySalesWithMissingBuyerName,
  originalSpreadsheetRefsComplete:audit.sourceSaleReferences.sourceReferencesUniqueAndComplete,
  cloudSnapshotCompared:false,
  existingCloudSaleIdsVerified:0,
  existingCloudCustomerIdsVerified:0,
  bankOrPaymentReceiptsReconciled:false,
  migrationAllowed:false,
  anyBusinessWritesPerformed:false,
  note:'Private offline review only. Source values and IDs remain unchanged. No cloud IDs or receipts were invented; review documentary evidence before authorizing any migration.',
 };
}

/**
 * Attach only *candidate* D1 relationships from a separately checksum-verified,
 * semantically validated 27-table export. Does not bind customers to buyers,
 * confirm any historic payment, assign IDs, or authorize migration.
 *
 * The caller must validate the snapshot checksum and row relations before use.
 */
export function attachCloudCandidatesToSaleReview(worksheet,verifiedTables,rawSnapshotSha256){
 if(!worksheet||worksheet.format!=='naina-private-sale-review-v1'||
  worksheet.migrationAllowed!==false||!Array.isArray(worksheet.reviewRows)||
  !verifiedTables||!Array.isArray(verifiedTables.sales)||
  !Array.isArray(verifiedTables.vehicles)||!Array.isArray(verifiedTables.customers)||
  !Array.isArray(verifiedTables.customer_payments)||
  typeof rawSnapshotSha256!=='string'||!/^[a-f0-9]{64}$/.test(rawSnapshotSha256))
  throw Error('Complete verified cloud source and private review are required.');
 const vehicleById=new Map(),saleByVehicle=new Map(),receiptsBySale=new Map();
 for(const row of verifiedTables.vehicles){
  if(typeof row?.id!=='string'||vehicleById.has(row.id))
   throw Error('Duplicate or invalid cloud vehicle identities.');
  vehicleById.set(row.id,row);
 }
 for(const row of verifiedTables.sales){
  if(typeof row?.id!=='string'||typeof row.vehicle_id!=='string')
   throw Error('Unverified cloud sale identity.');
  const candidates=saleByVehicle.get(row.vehicle_id)||[];
  candidates.push(row);
  saleByVehicle.set(row.vehicle_id,candidates);
 }
 for(const row of verifiedTables.customer_payments){
  if(typeof row?.sale_id!=='string')throw Error('Unverified cloud receipt linkage.');
  receiptsBySale.set(row.sale_id,(receiptsBySale.get(row.sale_id)||0)+1);
 }
 const knownCustomers=new Set(verifiedTables.customers.map(c=>c.id));
 const rows=worksheet.reviewRows.map(record=>{
  const linkedVehicle=vehicleById.get(record.originalVehicleId);
  const sales=saleByVehicle.get(record.originalVehicleId)||[];
  const candidates=sales.map(s=>({
   existingCloudSaleId:s.id,
   existingCloudCustomerId:typeof s.customer_id==='string'&&
    knownCustomers.has(s.customer_id)?s.customer_id:null,
   candidatePaymentRowCount:receiptsBySale.get(s.id)||0,
   // These are potential matches, NOT confirmed customer/receipt relationships.
   historicalIdentityVerified:false,
   receiptLedgerVerified:false,
  }));
  return {
   ...record,
   cloudVehiclePresent:Boolean(linkedVehicle),
   cloudVehicleStatus:linkedVehicle?.status??null,
   statusConflict:linkedVehicle!==undefined&&
    linkedVehicle.status!==record.originalVehicleStatus,
   existingCloudSaleCandidates:candidates,
   requiresHumanSaleIdReview:record.originalVehicleStatus==='Sold',
   requiresHumanCustomerReview:record.originalVehicleStatus==='Sold',
