import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import { webcrypto } from 'node:crypto';

// Covers actual browser dialog entry points, not just pure helper functions.
// Regression: a helper once named "document" shadowed the DOM document.
function harness(filename) {
 const nodes = new Map();
 let fetchCalls=0,confirmCalls=0;
 const element = name=>({
  name,tagName:name,value:'',textContent:'',disabled:false,open:false,
  append(){},appendChild(){},addEventListener(){},replaceChildren(){},
  showModal(){this.open=true;},close(){this.open=false;this.closed=true;},
  querySelector(){return {disabled:false};},
 });
 const dom={
  createElement:element,
  getElementById(name){if(!nodes.has(name))nodes.set(name,element(name));return nodes.get(name);},
 };
 const context={
  document:dom,crypto:webcrypto,
  FormData:class{constructor(){throw Error('FormData must not be read for stale dialogs.');}},
  confirm(){confirmCalls++;throw Error('Stale confirmation should be blocked.');},
  fetch(){fetchCalls++;throw Error('Network must not be called for a stale dialog.');},
 };
 vm.runInNewContext(fs.readFileSync(filename,'utf8'),context,{filename});
 return {api:context.NainaCloudFeatureEditor||context.NainaCloudFinanceEditor,nodes,get fetchCalls(){return fetchCalls;},get confirmCalls(){return confirmCalls;}};
}
test('vehicle location editor opens successfully and stale session prevents submission',async()=>{
 const h=harness('public/main-cloud-editor.js');
 h.api.openDialog({bike:{id:'synthetic-vehicle'},kind:'location',revision:2,notify(){},refresh(){},canSubmit:()=>false});
 const modal=h.nodes.get('cloud-edit-dialog');
 assert.equal(modal.open,true,'DOM editor must actually open');
 await h.nodes.get('cloud-edit-form').onsubmit({preventDefault(){}});
 assert.equal(modal.closed,true);
 assert.equal(h.fetchCalls,0);assert.equal(h.confirmCalls,0);
});
test('cloud finance editor opens and stale session cannot save',async()=>{
 const h=harness('public/main-cloud-finance.js');
 h.api.openDialog({bike:{id:'synthetic-vehicle',status:'Available',parking:0,otherExpenses:0},
 kind:'expense',sales:[],expenses:[],revision:2,notify(){},refresh(){},canSubmit:()=>false});
 const modal=h.nodes.get('cloud-finance-dialog');assert.equal(modal.open,true);
 await h.nodes.get('cloud-finance-form').onsubmit({preventDefault(){}});
 assert.equal(modal.closed,true);assert.equal(h.fetchCalls,0);assert.equal(h.confirmCalls,0);
});
test('dashboard invalidates open editor on cloud mode change or refresh',()=>{
 const source=fs.readFileSync('public/app.js','utf8');
 assert.match(source,/mainCloudEpoch\+\+;const requestEpoch=mainCloudEpoch,wasCloudMode=mainCloudMode;mainCloudLoading=true/);
 assert.match(source,/requestEpoch!==mainCloudEpoch/);
 assert.match(source,/mainCloudEpoch\+\+;initialise\(\)/);
 assert.ok((source.match(/mainCloudEpoch===epochAtOpen/g)||[]).length>=2,'All editor guards must check the active epoch');
});

