import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import ts from 'typescript';

const source=ts.transpileModule(fs.readFileSync('lib/crm-reads.ts','utf8'),
 {compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;
const exports={};
vm.runInNewContext(source,{exports,require(){throw Error('Unexpected runtime import');},Object,Number});
function reader(rows){
 let selects=0;
 const db={prepare(sql){
  assert.match(sql,/^SELECT /);
  return {bind(){return {async all(){
   selects++;
   const table=/FROM (vehicles|sales)/.exec(sql)?.[1];
   return {success:true,results:rows[table]||[]};
  }}}};
 }};
 return {reader:new exports.CrmReads(db),selects:()=>selects};
}
const vehicle=(extra={})=>({
 id:'synthetic-v',owner_id:'synthetic-owner',revision:1,
 status:'Available',registration_key:'SYNTHREG',chassis_key:'SYNTHCHASSIS',
 updated_at:'2026-10-26T00:00:00Z',
 payload_json:JSON.stringify({
  id:'synthetic-v',name:'Synthetic bike',status:'Available',
  reg:'SYNTH-REG',chassis:'SYNTH-CHASSIS',cost:100,
  parking:10,otherExpenses:20,expenses:30
 }),...extra
});
const sale=(extra={})=>({
 id:'synthetic-sale',vehicle_id:'synthetic-v',customer_id:'synthetic-customer',
 revision:1,payload_json:JSON.stringify({
  id:'synthetic-sale',vehicleId:'synthetic-v',customerId:'synthetic-customer',
  buyer:'Synthetic buyer',sale:200,balance:50
 }),...extra
});
