 const result=(await db.reader.vehicles()).items[0];
 assert.equal(result.id,'synthetic-v');
 assert.equal(result.payload.reg,'SYNTH-REG');
 assert.equal(result.financials.landed,130);
 assert.equal(result.statusConflict,false);
 assert.equal(JSON.stringify(row),before);
