});
test('cloud reader rejects JSON/status mismatches instead of displaying misleading status',async()=>{
 for(const changed of [
  {status:'Sold'},
  {payload_json:JSON.stringify({id:'synthetic-v',name:'Synthetic',status:'Review',
    reg:'SYNTH-REG',chassis:'SYNTH-CHASSIS'})},
