 const record=(await ok.reader.sales()).items[0];
 assert.equal(record.vehicleId,'synthetic-v');
 assert.equal(record.customerId,'synthetic-customer');
 for(const changed of [
  {vehicle_id:'other'},
  {customer_id:'other'},
  {customer_id:7},
  {revision:0},
  {payload_json:JSON.stringify({id:'synthetic-sale',vehicleId:'other',
   customerId:'synthetic-customer'})}
 ]){
  const db=reader({sales:[sale(changed)]});
  await assert.rejects(()=>db.reader.sales(),/INVALID_RECORD/);
 }
});
test('pre-existing sales without a normalized payload customer ID retain their original nullable linkage',async()=>{
 const old=sale({customer_id:null,payload_json:JSON.stringify({
  buyer:'Historical source only',sale:200,balance:40
 })});
 const db=reader({sales:[old]});
 const result=(await db.reader.sales()).items[0];
 assert.equal(result.customerId,null);
 assert.equal(result.buyer,'Historical source only');
});

