import { planImport, stable, TABLES } from './cloud-core.mjs';
import { FEATURE_KEYS } from './crm-reads';
export const CLOUD_TRANSFER_ENABLED: boolean = false;
export const SNAPSHOT_TABLES = [...TABLES, ...Object.keys(FEATURE_KEYS)];
const MAX_ROWS=5000;
type Row=Record<string,unknown>;
export type Snapshot={format:'naina-cloud-snapshot-v1';exportedAt:string;tables:Record<string,Row[]>;sha256:string};
export class TransferError extends Error{constructor(public status:number,message:string){super(message)}}
export async function digest(value:unknown){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(stable(value)));return Array.from(new Uint8Array(bytes)).map(x=>x.toString(16).padStart(2,'0')).join('');}
export async function exportSnapshot(db:D1Database):Promise<Snapshot>{
 // D1 batch runs sequentially as a transaction, preventing mixed-revision exports.
 const results=await db.batch(SNAPSHOT_TABLES.map(table=>db.prepare(`SELECT * FROM ${table} LIMIT ${MAX_ROWS+1}`)));
 const tables:Record<string,Row[]>={};
 for(let i=0;i<SNAPSHOT_TABLES.length;i++){
  if(!results[i].success)throw new TransferError(503,'Snapshot unavailable.');
  if(results[i].results.length>MAX_ROWS)throw new TransferError(413,'Snapshot exceeds bounded export capacity. Use the reviewed database backup procedure.');
  tables[SNAPSHOT_TABLES[i]]=results[i].results as Row[];
 }
 const body={format:'naina-cloud-snapshot-v1' as const,exportedAt:new Date().toISOString(),tables};
 if(new TextEncoder().encode(stable(body)).length>20*1024*1024)throw new TransferError(413,'Snapshot exceeds 20 MB.');
 return {...body,sha256:await digest(body)};
}
export async function verifySnapshot(value:unknown){
 if(!value||typeof value!=='object'||Array.isArray(value))throw new TransferError(400,'Invalid snapshot.');
 const s=value as Snapshot;
 if(s.format!=='naina-cloud-snapshot-v1'||typeof s.exportedAt!=='string'||!Number.isFinite(Date.parse(s.exportedAt))||!s.tables||typeof s.tables!=='object'||Array.isArray(s.tables)||typeof s.sha256!=='string'||!/^[a-f0-9]{64}$/.test(s.sha256))throw new TransferError(400,'Invalid snapshot structure.');
 if(Object.keys(s).sort().join(',')!=='exportedAt,format,sha256,tables'||Object.keys(s.tables).sort().join(',')!==[...SNAPSHOT_TABLES].sort().join(','))throw new TransferError(400,'Snapshot table manifest differs.');
 for(const rows of Object.values(s.tables))if(!Array.isArray(rows)||rows.length>MAX_ROWS||rows.some(r=>!r||typeof r!=='object'||Array.isArray(r)||Object.values(r).some(v=>v!==null&&!(typeof v==='string'||(typeof v==='number'&&Number.isFinite(v))))))throw new TransferError(400,'Invalid snapshot rows.');
 const {sha256,...body}=s;if(await digest(body)!==sha256)throw new TransferError(409,'Snapshot checksum mismatch.');
 return {valid:true,checksumVerified:true,tableCount:SNAPSHOT_TABLES.length,rowCount:Object.values(s.tables).reduce((n,r)=>n+r.length,0),restored:false,requiresDisposableSchemaRestore:true,mediaBytesIncluded:false};
}
export async function previewImport(db:D1Database,backup:unknown,expectedRevision:unknown){
 if(!Number.isSafeInteger(expectedRevision)||Number(expectedRevision)<0)throw new TransferError(400,'Expected cloud revision required.');
 const results=await db.batch([
  db.prepare("SELECT value FROM cloud_metadata WHERE key='revision'"),
  db.prepare('SELECT id,status,payload_json,registration_key,chassis_key,revision FROM vehicles LIMIT 5001'),
  db.prepare('SELECT id,payload_json,revision FROM leads LIMIT 5001'),
  db.prepare('SELECT id,vehicle_id,customer_id,payload_json,revision FROM sales LIMIT 5001'),
 ]);
 if(!Array.isArray(results)||results.length!==4||results.some(r=>r?.success!==true||!Array.isArray(r.results)))
  throw new TransferError(503,'Reconciliation unavailable.');
 if(results.some(r=>r.results.length>MAX_ROWS))throw new TransferError(413,'Cloud reconciliation exceeds bounded capacity.');
 // An uninitialised or malformed revision is NOT silently equivalent to zero.
 // Preview requires a trustworthy comparison point and never initialises D1.
 const metadata=results[0].results as {value:unknown}[];
 const rawRevision=metadata.length===1?metadata[0]?.value:null;
 if(typeof rawRevision!=='string'||!/^(?:0|[1-9][0-9]*)$/.test(rawRevision)||
    !Number.isSafeInteger(Number(rawRevision)))throw new TransferError(409,'Stored revision requires review.');
 const revision=Number(rawRevision);
 let plan;
 try {plan=planImport(backup,results[1].results,results[2].results,revision,expectedRevision);}
 catch {throw new TransferError(409,'Historical cloud rows require review before reconciliation.');}
 if(!plan.valid)return {...plan,importEnabled:false,cloudChanged:false,
  executionBlocker:'Invalid backup or cloud revision; no historical sale/customer mapping attempted.'};
 const data=backup as {bikes?:{id:string;status:string;buyer?:unknown}[];leads?:{id:string}[]};
 const sales=results[3].results as {id:string;vehicle_id:string}[];
 // A matching D1 vehicle_id is NOT evidence that a historical sale ID, buyer,
 // customer ID, receipt or outstanding balance is correctly matched. Never
 // auto-confirm those relationships from record counts or buyer names.
 const saleIdsByVehicle=new Map<string,string[]>();
 for(const row of sales){
  const group=saleIdsByVehicle.get(row.vehicle_id)||[];group.push(row.id);
  saleIdsByVehicle.set(row.vehicle_id,group);
 }
 const saleReconciliation=(Array.isArray(data?.bikes)?data.bikes:[]).filter(b=>b.status==='Sold').map(b=>({
  vehicleId:b.id,existingSaleIds:saleIdsByVehicle.get(b.id)||[],
  requiresExplicitSaleId:true,requiresExplicitCustomerMapping:true,
  requiresPaymentAndBalanceReconciliation:true,
  historicalBuyerNameMissing:typeof b.buyer!=='string'||!b.buyer.trim(),
 }));
 const byLead=new Map((results[2].results as Row[]).map(r=>[r.id,r]));
 const leadRecords=(Array.isArray(data?.leads)?data.leads:[]).map(l=>{
  const r=byLead.get(l.id);let action='insert';
  if(r){
   try{action=stable(JSON.parse(String(r.payload_json)))===stable(l)?'skip':'conflict';}
   catch{action='conflict';}
  }
  return {id:l.id,action};
 });
 return {...plan,leadRecords,saleReconciliation,
  historicalSaleMappingsVerified:0,historicalCustomerMappingsVerified:0,
  outstandingPaymentsReconciled:false,backupSha256:await digest(backup),
  importEnabled:false,cloudChanged:false,
  executionBlocker:'No historical sale/customer/payment mapping is established by this preview. Signed-off reconciliation, backups and approval are required; no writes.'};
}

