import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const code=fs.readFileSync('public/app.js','utf8');
const bike={id:'original-id',name:'Synthetic bike',reg:'TEST123',status:'Available',cost:100,parking:10,otherExpenses:20,expenses:30,buyer:'Preserved',sourceInventory:[{column:'S',value:10},{column:'T',value:20}]};
const data=(b=bike)=>({bikes:[structuredClone(b)],leads:[],importMeta:{id:'old'},appliedChanges:['historical-marker'],custom:{keep:true}});
function boot(raw,options={}){
 let value=raw;const writes=[],nodes=new Map(),dialogs=[];
 const node=()=>({innerHTML:'',textContent:'',value:'',style:{},classList:{toggle(){},remove(){}},addEventListener(){},close(){},showModal(){},click(){}});
 const context=vm.createContext({console,TextDecoder,Intl,Date,JSON,Number,Object,Array,Set,Map,String,Math,Error,crypto:globalThis.crypto,Blob,URL,setTimeout(){},location:{hash:''},confirm:()=>options.confirm??true,window:{NAINA_IMPORT:{meta:{id:'new'},bikes:[{...bike,id:'should-not-import'}]},addEventListener(){}},document:{querySelector(s){if(!nodes.has(s))nodes.set(s,node());return nodes.get(s)},querySelectorAll(){return []},addEventListener(){},createElement:node},localStorage:{getItem(){if(options.readError)throw Error('Access denied');return value},setItem(k,v){if(options.writeError)throw Error('Quota');assert.equal(k,'naina-desk-v1');writes.push(v);value=v},clear(){throw Error('Forbidden clear')},removeItem(){throw Error('Forbidden removal')}}});
 vm.runInContext(code,context);
 const run=s=>vm.runInContext(s,context);
 context.capture=(...args)=>dialogs.push(args);run('showForm=(...args)=>capture(...args)');
 return {run,writes,nodes,dialogs,get value(){return value},set value(v){value=v},context};
}
const inspect=b=>boot(JSON.stringify(data({...bike,...b})));
const syntheticFile=(name,type,bytes,size=bytes.length)=>({name,type,size,slice:()=>({arrayBuffer:async()=>new Uint8Array(bytes).buffer})});
const jpeg=()=>syntheticFile('test.jpg','image/jpeg',[255,216,255,224]);
test('empty galleries do not imply stored files',()=>{const a=inspect({});for(const kind of ['photo','document']){const html=a.run(`mediaGallerySection(state.bikes[0],'${kind}')`);assert.match(html,/No (photos|attachments) recorded/);assert.match(html,/nothing is uploaded or saved/);assert(!html.includes('<img'))}});
test('multiple exact-vehicle metadata rows show count and cover, no object URL leakage',()=>{const a=inspect({vehicleMedia:[{id:'a',vehicle_id:bike.id,category:'photo',is_cover:1,original_filename:'front.jpg',object_key:'secret',url:'https://evil.test'},{id:'b',vehicle_id:bike.id,category:'photo',original_filename:'back.jpg'},{id:'c',vehicle_id:'other',category:'photo',original_filename:'wrong.jpg'}]});const html=a.run("mediaGallerySection(state.bikes[0],'photo')");assert.match(html,/2 photos/);assert.match(html,/Cover photo/);assert(!/secret|evil.test|wrong.jpg/.test(html));assert(!html.includes('<img'))});
for(const status of ['Available','Sold'])test(status+' details retain location checklist handover and new galleries',()=>{const a=inspect({status});a.run("showDetails('original-id')");const html=a.dialogs.at(-1)[1];for(const title of ['Vehicle Location','Document Checklist','Photo Gallery','Document Attachments','Buyer handover documents'])assert(html.includes(title));assert.equal(a.writes.length,0)});
test('category labels and camera input attributes are prepared without form names',()=>{const a=inspect({});const html=a.run("mediaGallerySection(state.bikes[0],'photo')+mediaGallerySection(state.bikes[0],'document')");assert.match(html,/capture="environment"/);assert.match(html,/multiple/);for(const label of ['RC','Bank NOC','Form 35','Insurance','Auction documents','Transfer papers','Other'])assert(html.includes(label));assert(!html.includes('name="'));assert.match(html,/type="button" disabled>Upload/)});
test('invalid size format and spoofed signatures rejected',async()=>{const a=inspect({});for(const file of [syntheticFile('bad.exe','', [1]),syntheticFile('a.jpg','image/jpeg',[1,2]),syntheticFile('a.jpg','image/jpeg',[255,216,255],16*1024*1024),syntheticFile('a.jpg','text/html',[255,216,255])]){a.context.file=file;assert.equal(typeof await a.run("validateMediaSelection(file,'photo')"),'string')}});
test('valid JPEG accepted and PDF rejected for photo picker',async()=>{const a=inspect({});a.context.file=jpeg();assert.equal(await a.run("validateMediaSelection(file,'photo')"),null);a.context.file=syntheticFile('a.pdf','application/pdf',[37,80,68,70,45]);assert.equal(await a.run("validateMediaSelection(file,'document')"),null);assert.equal(typeof await a.run("validateMediaSelection(file,'photo')"),'string')});
test('HEIC recognized but no conversion or preview promised',async()=>{const a=inspect({});a.context.file=syntheticFile('a.heic','image/heic',[0,0,0,24,...new TextEncoder().encode('ftypheic')]);assert.equal(await a.run("validateMediaSelection(file,'photo')"),null);await a.run("selectVehicleMedia([file],'photo','photo')");assert.equal(a.run('mediaSelections.photo[0].url'),null);assert.match(a.nodes.get('#media-photo-selection').innerHTML,/Preview\/conversion unavailable; not uploaded/)});
test('temporary thumbnail selection has no writes or requests and revokes URLs',async()=>{const a=inspect({}),revoked=[];a.context.URL={createObjectURL:()=> 'blob:synthetic-preview',revokeObjectURL:u=>revoked.push(u)};a.context.fetch=()=>{throw Error('network forbidden')};a.context.file=jpeg();await a.run("selectVehicleMedia([file,file],'photo','photo')");assert.equal(a.run('mediaSelections.photo.length'),2);assert.match(a.nodes.get('#media-photo-selection').innerHTML,/data-media-preview="photo:0"/);assert.match(a.nodes.get('#media-photo-selection').innerHTML,/Not uploaded/);a.run('clearMediaSelections()');assert.equal(revoked.length,2);assert.equal(a.writes.length,0)});
test('archived files excluded and no photo URL sourced from business record',()=>{const a=inspect({vehicleMedia:[{id:'a',vehicle_id:bike.id,original_filename:'old.jpg',category:'photo',archived_at:'2026-01-01'}]});assert.equal(a.run('vehicleMediaView(state.bikes[0]).length'),0)});
test('accessible preview controls and responsive grid rules retained',()=>{const a=inspect({});assert.match(a.run("mediaGallerySection(state.bikes[0],'photo')"),/aria-live="polite"/);const css=fs.readFileSync('public/style.css','utf8');assert.match(css,/media-grid\{grid-template-columns:repeat\(2/);assert.match(code,/Temporary photo preview/);assert.match(code,/media-preview-close autofocus/)});

