'use strict';
let selected=null,busy=false;const el=id=>document.getElementById(id);
function lock(value){busy=value;for(const id of ['status','test','preview','file'])el(id).disabled=value||(id==='preview'&&!selected)}
async function call(path,body){const response=await fetch('/api/cloud/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},credentials:'same-origin',cache:'no-store',...(body===undefined?{}:{body:JSON.stringify(body)})});let data;try{data=await response.json()}catch{throw Error('Sign in to the private Site with its owner account, then try again.')}if(!response.ok)throw Error(data.error||data.errors?.join('\n')||'Request failed');return data}
async function task(fn){if(busy)return;lock(true);try{await fn()}catch(e){el('summary').textContent=e.message}finally{lock(false)}}
el('status').onclick=()=>task(async()=>{el('connection').textContent=JSON.stringify(await call('status'),null,2)});
el('test').onclick=()=>task(async()=>{el('connection').textContent=JSON.stringify(await call('test',{}),null,2)});
el('file').onchange=async e=>{selected=null;el('preview').disabled=true;const f=e.target.files[0];if(!f)return;el('filename').textContent=f.name;if(f.size>5*1024*1024){el('summary').textContent='Maximum backup size: 5 MB.';return}try{selected=JSON.parse(await f.text());el('summary').textContent='Selected locally. Click Preview only to validate against cloud records without saving.';el('preview').disabled=false}catch{el('summary').textContent='This file is not valid JSON.'}};
el('preview').onclick=()=>task(async()=>{const status=await call('status');el('connection').textContent=JSON.stringify(status,null,2);if(status.missingTables.length)throw Error('Required tables are missing.');const plan=await call('dry-run',{backup:selected,expectedRevision:status.revision});el('result').textContent=JSON.stringify(plan,null,2);el('summary').textContent=`Preview only: ${plan.counts.insert} insert, ${plan.counts.update} update, ${plan.counts.skip} skip, ${plan.counts.conflict} conflict; ${plan.counts.review} flagged for review. Nothing imported.`});

