import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';

test('outdated cloud refresh must never replace browser-local state',()=>{
 const src=fs.readFileSync('public/app.js','utf8');
 assert.match(src,/const requestEpoch=mainCloudEpoch,wasCloudMode=mainCloudMode/);
 const loaded=src.indexOf('const candidate=await window.NainaMainCloudAdapter.load(fetch)');
 const guard=src.indexOf('if(requestEpoch!==mainCloudEpoch||(wasCloudMode&&!mainCloudMode))return false;',loaded);
 const mutation=src.indexOf('state=candidate;mainCloudRevision=',loaded);
 assert.ok(loaded>=0&&guard>loaded&&mutation>guard,'Reject stale response before assigning cloud state');
});
test('do not leave cloud mode while an in-flight refresh is unfinished',()=>{
 const src=fs.readFileSync('public/app.js','utf8');
 const start=src.indexOf("$('#cloud-mode').onclick=()=>");
 assert.ok(start>=0);
 const busy=src.indexOf("if(mainCloudLoading){notify('Wait for the current cloud request to finish.');return;}",start);
 const stop=src.indexOf('mainCloudSync?.stop();mainCloudMode=false;',start);
 assert.ok(busy>start&&busy<stop);
});

test('polling and existing view revisions are checked before switching the in-memory stock',()=>{
 const src=fs.readFileSync('public/app.js','utf8');
 assert.match(src,/async function refreshMainCloud\(minimumExpectedRevision=0\)/);
 const loaded=src.indexOf('const candidate=await window.NainaMainCloudAdapter.load(fetch)');
 const oldCheck=src.indexOf('candidate.cloudRevision<Math.max(currentMinimum,polledMinimum)',loaded);
 const assignment=src.indexOf('state=candidate;mainCloudRevision=',loaded);
 assert.ok(loaded>=0&&oldCheck>loaded&&assignment>oldCheck,
  'Stale clouds must be rejected before assigning dashboard state');
 assert.match(src,/applyUpdate:async revision=>\{const refreshed=await refreshMainCloud\(revision\)/);
 assert.doesNotMatch(src.slice(loaded,assignment),/localStorage\.(?:setItem|removeItem|clear)\(/);
});

