import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import ts from 'typescript';

function route({authorized=true,enabled=false,revision=3,change=false}={}){
 const exports={};let dbCalled=0;const reads=[];
 class InvalidRead extends Error{constructor(code){super(code);this.code=code;}}
 class CrmReads{
  vehicles(q){reads.push(['vehicles',q]);return Promise.resolve({items:[],...q,nextOffset:null})}
  sales(q){reads.push(['sales',q]);return Promise.resolve({items:[],...q,nextOffset:null})}
  leads(q){reads.push(['leads',q]);return Promise.resolve({items:[],...q,nextOffset:null})}
  customers(q){reads.push(['customers',q]);return Promise.resolve({items:[],...q,nextOffset:null})}
  features(name,q){reads.push([name,q]);return Promise.resolve({items:[],...q,nextOffset:null})}
 }
 class CrmWrites{async revision(){return change?revision++:revision}}
 const cr={CrmReads,ReadError:InvalidRead,pageInput(q){if(!Number.isInteger(q.limit)||q.limit<1||q.limit>100||!Number.isInteger(q.offset)||q.offset<0||q.offset>100000)throw new InvalidRead('INVALID_QUERY');return q;}};
 const stubs={'../../../lib/cloud-server':{guard:async()=>authorized?{user:{userId:'synthetic-owner'}}:{error:Response.json({error:'Forbidden'},{status:403})},json:(v,status=200)=>Response.json(v,{status,headers:{'Cache-Control':'no-store'}}),database(){dbCalled++;return {}}},'../../../lib/main-crm-flags':{MAIN_CRM_CLOUD_PREVIEW_ENABLED:enabled},'../../../lib/cloud-write-flags':{CRM_WRITES_ENABLED:false},'../../../lib/private-media-flags':{PRIVATE_MEDIA_ENABLED:false},'../../../lib/crm-reads':cr,'../../../lib/crm-writes':{CrmWrites}};
 const code=ts.transpileModule(fs.readFileSync('app/api/private-crm-main/route.ts','utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;
 vm.runInNewContext(code,{exports,require:x=>{if(!Object.hasOwn(stubs,x))throw Error('Unexpected import');return stubs[x]},Response,Request,URL,Set,Number});
 return {GET:exports.GET,reads,get dbCalls(){return dbCalled}};
}
const url='https://crm.nainamotors.com/api/private-crm-main?resource=vehicles&limit=100&offset=0';
test('anonymous/nonowner rejected before DB access',async()=>{const r=route({authorized:false,enabled:true});assert.equal((await r.GET(new Request(url))).status,403);assert.equal(r.dbCalls,0)});
test('server-only gate rejects owner before D1 connection',async()=>{const r=route();assert.equal((await r.GET(new Request(url+'&enabled=true'))).status,423);assert.equal(r.dbCalls,0)});
test('synthetic owner read includes a stable revision and no-store',async()=>{const r=route({enabled:true});const response=await r.GET(new Request(url));assert.equal(response.status,200);const payload=await response.json();assert.equal(payload.revision,3);assert.equal(payload.editEnabled,false);assert.equal(response.headers.get('cache-control'),'no-store')});
test('invalid/duplicate params cannot read arbitrary tables',async()=>{const r=route({enabled:true});for(const tail of ['&owner=all','&resource=leads','&limit=101','&offset=-1'])assert.equal((await r.GET(new Request(url+tail))).status,400)});
test('customer directory is an owner-scoped, release-gated read',async()=>{const r=route({enabled:true});const result=await r.GET(new Request(url.replace('resource=vehicles','resource=customers')));assert.equal(result.status,200);assert.equal(r.reads[0][0],'customers');});
test('revision change rejects torn pages',async()=>{const r=route({enabled:true,change:true});assert.equal((await r.GET(new Request(url))).status,409)});

test('inspection and auction history are read-only and behind Owner release lock',async()=>{
 for(const resource of ['vehicle_inspections','auction_plans']){
  const urlForResource=url.replace('resource=vehicles','resource='+resource);
  const locked=route({enabled:false});
  assert.equal((await locked.GET(new Request(urlForResource))).status,423);
  assert.equal(locked.dbCalls,0);
  const allowed=route({enabled:true});
  assert.equal((await allowed.GET(new Request(urlForResource))).status,200);
  assert.equal(allowed.reads[0][0],resource);
 }
});

