import { guard, json, database } from '../../../lib/cloud-server';
import { CRM_WRITES_ENABLED } from '../../../lib/cloud-write-flags';
import { CrmWrites, WriteError } from '../../../lib/crm-writes';
export async function GET(request:Request){
 const auth=await guard(request);if('error' in auth)return auth.error;
 if(!CRM_WRITES_ENABLED)return json({error:'Cloud business operations are locked.'},423);
 try{return json({revision:await new CrmWrites(database(),auth.user.userId).revision()});}
 catch{return json({error:'Cloud revision unavailable.'},503);}
}
export async function POST(request:Request){
 const auth=await guard(request);if('error' in auth)return auth.error;
 if(!CRM_WRITES_ENABLED)return json({error:'Cloud business operations are locked.'},423);
 try{
  if(!request.headers.get('content-type')?.startsWith('application/json'))return json({error:'JSON required.'},415);
  const reader=request.body?.getReader();if(!reader)return json({error:'JSON required.'},400);
  const chunks:Uint8Array[]=[];let size=0;while(true){const {done,value}=await reader.read();if(done)break;size+=value.byteLength;if(size>100000){await reader.cancel();return json({error:'Request too large.'},413);}chunks.push(value);}
  const bytes=new Uint8Array(size);let offset=0;for(const c of chunks){bytes.set(c,offset);offset+=c.length;}
  let input;try{input=JSON.parse(new TextDecoder().decode(bytes));}catch{return json({error:'Invalid JSON.'},400);}
  return json({result:await new CrmWrites(database(),auth.user.userId).write(input)});
 }catch(e){return json({error:e instanceof WriteError?e.code:'Cloud write unavailable.',code:e instanceof WriteError?e.code:'WRITE_UNAVAILABLE'},e instanceof WriteError?e.status:503);}
}

