#!/usr/bin/env node
// Synthetic local D1/R2 Worker integration. Never launches with --remote.
// Counts ONLY the 27 application tables; Wrangler may add its own local system tables.
// Uses no business records, no credentials, no real Sites project connection.
import {randomBytes,createHash,randomInt} from 'node:crypto';
import {existsSync,mkdtempSync,writeFileSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {resolve,join} from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {spawn,spawnSync} from 'node:child_process';
const root=fileURLToPath(new URL('../',import.meta.url));
const binary=resolve(root,'node_modules/wrangler/bin/wrangler.js');
const template="\nconst nonce=__NONCE__;\nconst response=(body,status=200)=>Response.json(body,{status,headers:{'cache-control':'no-store'}});\nconst digest=async bytes=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)))\n .map(x=>x.toString(16).padStart(2,'0')).join('');\nexport default {async fetch(req,env){\n const url=new URL(req.url);\n if(url.hostname!=='127.0.0.1'||url.pathname!=='/__local_binding_probe'||\n    req.method!=='POST'||req.headers.get('x-local-test-nonce')!==nonce)\n  return response({error:'localhost synthetic test only'},403);\n if(!env.DB||!env.BUCKET)return response({error:'Local bindings missing'},503);\n const schema=await env.DB.prepare(\n  \"SELECT COUNT(*) AS n FROM sqlite_master WHERE type='table' AND name IN ('vehicles','sales','customers','leads','expenses','import_history','audit_logs','cloud_metadata','connection_probes','auction_plans','cashbook_entries','customer_payments','document_expiries','document_requirements','enquiry_notes','generated_documents','owner_preferences','price_history','reminders','repair_jobs','reservations','rto_cases','vehicle_age_baselines','vehicle_inspections','vehicle_locations','vehicle_media','vehicle_timeline')\"\n ).first();\n const metadata=await env.DB.prepare(\"SELECT value FROM cloud_metadata WHERE key='revision'\").first();\n const vehicle='synthetic-test-'+nonce,reg='SYNTLOCAL'+nonce.slice(0,8).toUpperCase();\n let d1Read=false,duplicateDenied=false,foreignKeyDenied=false;\n try{\n  await env.DB.prepare(\n   'INSERT INTO vehicles(id,owner_id,payload_json,status,registration_key,chassis_key,revision,updated_at) VALUES(?,?,?,?,?,?,?,?)'\n  ).bind(vehicle,'SYNTHETIC','{\"name\":\"SYNTHETIC TEST\"}','Available',reg,null,1,'2026-10-15T00:00:00Z').run();\n  const record=await env.DB.prepare('SELECT registration_key FROM vehicles WHERE id=?')\n    .bind(vehicle).first();\n  d1Read=record?.registration_key===reg;\n  try{await env.DB.prepare(\n   'INSERT INTO vehicles(id,owner_id,payload_json,status,registration_key,chassis_key,revision,updated_at) VALUES(?,?,?,?,?,?,?,?)'\n  ).bind(vehicle+'duplicate','SYNTHETIC','{}','Available',reg,null,1,'2026-10-15T00:00:00Z').run();}\n  catch{duplicateDenied=true;}\n  try{await env.DB.prepare(\n   'INSERT INTO expenses(id,vehicle_id,kind,amount_json,payload_json) VALUES(?,?,?,?,?)'\n  ).bind('synthetic-fk-'+nonce,'nonexistent-parent','parking','0','{}').run();}\n  catch{foreignKeyDenied=true;}\n }finally{\n  await env.DB.prepare('DELETE FROM expenses WHERE id=?').bind('synthetic-fk-'+nonce).run();\n  await env.DB.prepare('DELETE FROM vehicles WHERE id=? OR id=?')\n   .bind(vehicle,vehicle+'duplicate').run();\n }\n const objectKey='synthetic/test/'+nonce;\n const bytes=new TextEncoder().encode('LOCAL_FAKE_PRIVATE_R2_'+nonce);\n let r2Bytes=false,r2List=false,r2Deleted=false,sha256=null;\n try{\n  await env.BUCKET.put(objectKey,bytes);\n  const fetched=await env.BUCKET.get(objectKey);\n  if(fetched){\n   const restored=new Uint8Array(await fetched.arrayBuffer());\n   sha256=await digest(restored);\n   r2Bytes=restored.byteLength===bytes.byteLength&&sha256===await digest(bytes);\n  }\n  const listed=await env.BUCKET.list({prefix:objectKey,limit:1});\n  r2List=Array.isArray(listed?.objects)&&listed.objects.some(x=>x.key===objectKey);\n }finally{\n  await env.BUCKET.delete(objectKey);\n  r2Deleted=(await env.BUCKET.get(objectKey))===null;\n }\n return response({format:'naina-local-bindings-v1',syntheticOnly:true,localOnly:true,\n  tables:schema?.n??null,revision:metadata?.value??null,d1Read,duplicateDenied,\n  foreignKeyDenied,r2Bytes,r2List,r2Deleted,sha256,\n  hostedOwnerVerified:false,hostedBindingsVerified:false,\n  businessDataImported:false,productionReleaseApproved:false});\n}};\n";
export const D1_LOCAL_TEST_ID='00000000-0000-4000-8000-000000000002';
export function localConfig(){
 return {name:'naina-synthetic-d1-r2-local-only',main:'./probe.mjs',
  compatibility_date:'2026-05-15',
  d1_databases:[{binding:'DB',database_name:'naina-local-d1-test',database_id:D1_LOCAL_TEST_ID}],
  r2_buckets:[{binding:'BUCKET',bucket_name:'naina-local-r2-test'}]};
}
export function validateLocalArgs(a){
 if(!Array.isArray(a)||a.includes('--remote')||a.includes('--preview')||
  !a.includes('--local')||!a.includes('--config')||!a.includes('--persist-to'))
  throw Error('Local Wrangler flags are mandatory; no remote or preview target allowed.');
 return a;
}
export function workerCode(nonce){
 if(typeof nonce!=='string'||!/^[a-f0-9]{32}$/.test(nonce))throw Error('Invalid synthetic nonce.');
 return template.replace('__NONCE__',JSON.stringify(nonce));
}
function localEnv(rootTmp){
 const keys=['PATH','HOME','USER','TMPDIR','SYSTEMROOT','COMSPEC','WINDIR','CI'];
 const env=Object.fromEntries(keys.filter(k=>typeof process.env[k]==='string').map(k=>[k,process.env[k]]));
 return {...env,CLOUDFLARE_API_TOKEN:'',CLOUDFLARE_API_KEY:'',CLOUDFLARE_ACCOUNT_ID:'',
  WRANGLER_SEND_METRICS:'false',WRANGLER_WRITE_LOGS:'false',
  WRANGLER_LOG_PATH:join(rootTmp,'logs'),WRANGLER_REGISTRY_PATH:join(rootTmp,'registry'),
  MINIFLARE_REGISTRY_PATH:join(rootTmp,'registry')};
}
async function run(){
 if(!existsSync(binary))throw Error('Run pnpm install --frozen-lockfile before this test.');
 const tmp=mkdtempSync(join(tmpdir(),'naina-ephemeral-bindings-'));
 const config=join(tmp,'wrangler.json'),state=join(tmp,'state');
 const nonce=randomBytes(16).toString('hex'),port=randomInt(18700,24700);
 const origin='http://127.0.0.1:'+port,env=localEnv(tmp);
 let child=null,exited=false,stderr='';
 const request=async(path,options={})=>{
  // Local Wrangler cold starts and SQLite/R2 initialization can exceed 2.5 s
  // on contended CI runners. Never retry the POST probe after an unknown write.
  const timeout=options.method==='POST'?20000:8000;
  const control=new AbortController(),timer=setTimeout(()=>control.abort(),timeout);
  try{return await fetch(origin+path,{redirect:'manual',cache:'no-store',
   signal:control.signal,...options});}finally{clearTimeout(timer);}
 };
 try{
  writeFileSync(config,JSON.stringify(localConfig()));
  writeFileSync(join(tmp,'probe.mjs'),workerCode(nonce));
  for(const migration of ['0000_deep_mockingbird.sql','0001_private_dashboard_features.sql']){
   const args=validateLocalArgs(['d1','execute','DB','--local','--config',config,
    '--persist-to',state,'--file',resolve(root,'drizzle',migration),'--yes']);
   const result=spawnSync(process.execPath,[binary,...args],{
    cwd:root,env,encoding:'utf8',timeout:80000,maxBuffer:1024*1024});
   if(result.status!==0)throw Error('Synthetic D1 migration failed: '+migration);
  }
  const args=validateLocalArgs(['dev','--local','--config',config,
   '--persist-to',state,'--ip','127.0.0.1','--port',String(port),'--inspector-port','0']);
  child=spawn(process.execPath,[binary,...args],{cwd:root,env,stdio:['ignore','pipe','pipe']});
  const capture=chunk=>{stderr=(stderr+chunk.toString('utf8')).slice(-5000);};
  child.stdout.on('data',capture);child.stderr.on('data',capture);
  child.once('exit',()=>{exited=true;});
  const deadline=Date.now()+50000;
  let ready=false;
  while(Date.now()<deadline&&!exited){
   try{const res=await request('/no-such-endpoint');if(res.status===403){ready=true;break;}}
   catch{}
   await new Promise(r=>setTimeout(r,500));
  }
  if(!ready)throw Error('Synthetic local Worker failed to start. Safe runtime clue: '+
    stderr.replace(/\\x1b\\[[0-9;]*m/g,'')
      .replace(/(?:\/home|\/tmp)\/[^\\s"']+/g,'[path]')
      .replace(/(?:token|secret|password|key)\\s*[:=]\\s*[^\\s"']+/gi,'[redacted]')
      .slice(-950));
  if((await request('/__local_binding_probe')).status!==403)
   throw Error('Synthetic Worker accepted an unauthorized read.');
  const probe=await request('/__local_binding_probe',{
   method:'POST',headers:{'x-local-test-nonce':nonce},body:'{}'});
  if(probe.status!==200)throw Error('Synthetic binding test endpoint rejected integration request.');
  const result=await probe.json();
  const checks=['d1Read','duplicateDenied','foreignKeyDenied','r2Bytes','r2List','r2Deleted'];
  if(result.format!=='naina-local-bindings-v1'||result.tables!==27||
   result.revision!==null||result.syntheticOnly!==true||result.localOnly!==true||
   result.hostedOwnerVerified!==false||result.hostedBindingsVerified!==false||
   result.businessDataImported!==false||result.productionReleaseApproved!==false||
   checks.some(k=>result[k]!==true)){
    const bad=['format','tables','revision','syntheticOnly','localOnly',
      'hostedOwnerVerified','hostedBindingsVerified','businessDataImported',
      'productionReleaseApproved',...checks].filter(k=>{
        const expected={format:'naina-local-bindings-v1',tables:27,revision:null,
          syntheticOnly:true,localOnly:true,hostedOwnerVerified:false,
          hostedBindingsVerified:false,businessDataImported:false,
          productionReleaseApproved:false};
        return result[k]!== (k in expected?expected[k]:true);
      });
    throw Error('Synthetic D1/R2 invariants failed: '+bad.join(', '));
   }
  const sha=createHash('sha256').update('LOCAL_FAKE_PRIVATE_R2_'+nonce).digest('hex');
  if(result.sha256!==sha)throw Error('Synthetic R2 SHA-256 roundtrip failed.');
  console.log('PASS: Local Wrangler D1+R2 integration: 2 migrations / 27 tables; '+
   'fictional insert/read, UNIQUE and FK rejection, R2 put/get/list/delete and SHA-256; '+
   'ephemeral local-only bindings; NOT hosted and NO production data.');
 }finally{
  if(child&&!exited){
   child.kill('SIGTERM');
   await Promise.race([new Promise(r=>child.once('exit',r)),new Promise(r=>setTimeout(r,2200))]);
   if(!exited)child.kill('SIGKILL');
  }
  rmSync(tmp,{recursive:true,force:true});
 }
}
if(process.argv[1]&&import.meta.url===pathToFileURL(resolve(process.argv[1])).href){
 try{await run();}catch(err){console.error('FAIL: Local D1/R2 binding test: '+
  (err instanceof Error?err.message:'Unknown safe error'));process.exitCode=1;}
}

tests/schema-index-uniqueness.test.mjs.value:
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
const script='scripts/verify-schema-sqlite.py';
const run=p=>spawnSync('python3',[p],{encoding:'utf8',timeout:15000});
test('offline migration verifier accepts original UNIQUE constraints',()=>{
 const result=run(script);
 assert.equal(result.status,0,result.stderr);
 assert.match(result.stdout,/27 tables; 18 explicit indexes/);
});
test('offline verifier rejects a same-named non-unique critical index',()=>{
 const root=fs.mkdtempSync(path.join(os.tmpdir(),'naina-unique-check-'));
 try{
  fs.mkdirSync(path.join(root,'drizzle'));fs.mkdirSync(path.join(root,'scripts'));
  fs.copyFileSync(script,path.join(root,script));
  for(const name of fs.readdirSync('drizzle').filter(x=>x.endsWith('.sql'))){
   let sql=fs.readFileSync(path.join('drizzle',name),'utf8');
   if(name.startsWith('0000_')){
    assert.match(sql,/CREATE UNIQUE INDEX `vehicles_registration_unique`/);
    sql=sql.replace('CREATE UNIQUE INDEX `vehicles_registration_unique`',
                    'CREATE INDEX `vehicles_registration_unique`');
   }
   fs.writeFileSync(path.join(root,'drizzle',name),sql);
  }
  const result=run(path.join(root,script));
  assert.notEqual(result.status,0);
  assert.match(result.stderr,/required UNIQUE index/);
 }finally{fs.rmSync(root,{recursive:true,force:true});}
});

test('offline validator catches same-named UNIQUE index on wrong columns',()=>{
 const root=fs.mkdtempSync(path.join(os.tmpdir(),'naina-index-columns-'));
 try{
  fs.mkdirSync(path.join(root,'drizzle'));fs.mkdirSync(path.join(root,'scripts'));
  fs.copyFileSync(script,path.join(root,script));
  for(const name of fs.readdirSync('drizzle').filter(x=>x.endsWith('.sql'))){
   let sql=fs.readFileSync(path.join('drizzle',name),'utf8');
   if(name.startsWith('0000_'))sql=sql.replace(
    'CREATE UNIQUE INDEX `vehicles_registration_unique` ON `vehicles` (`registration_key`)',
    'CREATE UNIQUE INDEX `vehicles_registration_unique` ON `vehicles` (`status`)');
   fs.writeFileSync(path.join(root,'drizzle',name),sql);
  }
  const result=run(path.join(root,script));
  assert.notEqual(result.status,0);
  assert.match(result.stderr,/Incorrect UNIQUE index definition: vehicles_registration_unique/);
 }finally{fs.rmSync(root,{recursive:true,force:true});}
});
test('offline validator catches altered partial-index WHERE predicate',()=>{
 const root=fs.mkdtempSync(path.join(os.tmpdir(),'naina-index-predicate-'));
 try{
  fs.mkdirSync(path.join(root,'drizzle'));fs.mkdirSync(path.join(root,'scripts'));
  fs.copyFileSync(script,path.join(root,script));
  for(const name of fs.readdirSync('drizzle').filter(x=>x.endsWith('.sql'))){
   let sql=fs.readFileSync(path.join('drizzle',name),'utf8');
   if(name.startsWith('0001_'))sql=sql.replace(
    'WHERE is_cover=1 AND archived_at IS NULL',
    'WHERE is_cover=0 AND archived_at IS NULL');
   fs.writeFileSync(path.join(root,'drizzle',name),sql);
  }
  const result=run(path.join(root,script));
  assert.notEqual(result.status,0);
  assert.match(result.stderr,/Incorrect UNIQUE index definition: uq_vehicle_one_cover_photo/);
 }finally{fs.rmSync(root,{recursive:true,force:true});}
});

