/* Owner cloud inspection and auction forms. No localStorage or automatic writes.
   Estimates are informational and NEVER booked as purchases, expenses or receipts. */
(function(root,factory){
 const api=factory();
 if(typeof module==='object'&&module.exports)module.exports=api;
 else root.NainaCloudOperations=api;
})(typeof globalThis==='object'?globalThis:this,function(){
 'use strict';
 let pending=false;
 const conditions=['Unassessed','Excellent','Good','Fair','Needs repair'];
 const checks=['Body & frame','Engine','Tyres','Brakes','Electrical'];
 const states=['Not checked','Pass','Attention'];
 function string(value,max=3000){
  if(typeof value!=='string'||value.length>max||/[\x00-\x1f\x7f]/.test(value))throw Error('Invalid text field.');
  return value.trim();
 }
 function id(value){if(typeof value!=='string'||!value||!value.trim()||value.length>256||/[\x00-\x1f\x7f]/.test(value))throw Error('Vehicle ID required.');return value;}
 function date(value){
  const s=string(value,10),d=new Date(s+'T00:00:00Z');
  if(!/^\d{4}-\d{2}-\d{2}$/.test(s)||!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==s)
   throw Error('Invalid inspection calendar date.');
  return s;
 }
 function money(value,mandatory=false){
  if(value===null||value===undefined||value===''){
   if(mandatory)throw Error('Missing required amount.');
   return null;
  }
  const s=typeof value==='number'?String(value):string(value,40);
  if(!/^(?:0|[1-9]\d{0,11})(?:\.\d{1,2})?$/.test(s))
   throw Error('Invalid amount with more than two decimals.');
  const n=Number(s);
  if(!Number.isSafeInteger(Math.round(n*100)))throw Error('Amount too large.');
  return Math.round(n*100)/100;
 }
 function token(){if(typeof crypto==='undefined'||typeof crypto.randomUUID!=='function')throw Error('Secure ID unavailable.');return crypto.randomUUID();}
 function plan(kind,bike,values,revision){
  if(!bike||!['inspection','auction'].includes(kind))throw Error('Invalid cloud operation.');
  if(!Number.isSafeInteger(revision)||revision<0)throw Error('Cloud revision unavailable.');
  const data={vehicle_id:id(bike.id)};
  if(kind==='inspection'){
   data.inspected_at=date(values.inspected_at);
   data.inspector=string(values.inspector||'',200);
   data.odometer_km=money(values.odometer_km);
   data.overall_condition=string(values.overall_condition||'Unassessed',50);
   if(!conditions.includes(data.overall_condition))throw Error('Invalid vehicle condition.');
   data.estimated_repairs=money(values.estimated_repairs);
   data.notes=string(values.notes||'');
   const checklist={};
   checks.forEach((key,i)=>{
    const v=string(values['check_'+i]||'Not checked',20);
    if(!states.includes(v))throw Error('Invalid checklist value.');
    checklist[key]=v;
   });
   data.checklist_json=JSON.stringify(checklist);
  }else{
   data.auction_platform=string(values.auction_platform||'',120);
   data.auction_reference=string(values.auction_reference||'',150);
   data.expected_resale=money(values.expected_resale,true);
   data.maximum_bid=money(values.maximum_bid,true);
   if(data.expected_resale<=0)throw Error('Expected resale must be positive.');
   for(const field of ['estimated_repairs','estimated_parking','estimated_transfer',
     'estimated_transport','other_estimated_expenses','target_profit'])
    data[field]=money(values[field])??0;
   data.actual_bid=null;
   data.outcome='Planned';
   data.notes=string(values.notes||'');
  }
  return {resource:kind==='inspection'?'vehicle_inspections':'auction_plans',
   id:token(),mode:'create',data,expectedRevision:revision,idempotencyKey:token()};
 }
 async function write(fetchFn,instruction){
  if(typeof fetchFn!=='function'||!instruction||
   !['vehicle_inspections','auction_plans'].includes(instruction.resource)||instruction.mode!=='create')
   throw Error('Unsupported cloud write.');
  let response;
  try{response=await fetchFn('/api/private-crm-write',{method:'POST',
   credentials:'same-origin',cache:'no-store',redirect:'error',
   headers:{'Content-Type':'application/json'},body:JSON.stringify(instruction)})}
  catch{throw Error('Save outcome unknown. Refresh and inspect before retrying.');}
  if(!response?.ok){
   if(response?.status===423)throw Error('Cloud editing locked.');
   if(response?.status===409)throw Error('Cloud revision conflict. Refresh first.');
   throw Error('Cloud save not confirmed. Refresh and reconcile.');
  }
  let body;
  try{body=await response.json();}catch{throw Error('Cloud receipt unreadable. Refresh first.');}
  if(body?.result?.id!==instruction.id||
   body?.result?.resource!==instruction.resource||
   body?.result?.revision!==instruction.expectedRevision+1)
   throw Error('Cloud receipt mismatch. Refresh first.');
  return body.result;
 }
 function openDialog({kind,bike,revision,notify,refresh,canSubmit}){
  if(pending||!['inspection','auction'].includes(kind)||!bike||
     typeof notify!=='function'||typeof refresh!=='function'||
     typeof canSubmit!=='function'||!canSubmit())return;
  const modal=document.getElementById('cloud-operation-dialog'),
   form=document.getElementById('cloud-operation-form'),
   holder=document.getElementById('cloud-operation-fields');
  if(!modal||!form||!holder)return;
  document.getElementById('cloud-operation-title').textContent=
   kind==='inspection'?'New cloud vehicle inspection':'New cloud auction bid plan';
  holder.replaceChildren();
  function add(label,name,value='',type='text',choices=null){
   const wrap=document.createElement('label');wrap.textContent=label+' ';
   const input=document.createElement(choices?'select':'input');input.name=name;
   if(choices){choices.forEach(choice=>{const opt=document.createElement('option');
    opt.value=choice;opt.textContent=choice;input.appendChild(opt);});}
   else {input.type=type;input.maxLength=3000;}
   input.value=String(value??'');wrap.appendChild(input);holder.appendChild(wrap);
  }
  if(kind==='inspection'){
   add('Inspection date','inspected_at',new Date().toISOString().slice(0,10),'date');
   add('Inspector / workshop','inspector');
   add('Odometer reading','odometer_km','','number');
   add('Condition','overall_condition','Unassessed','text',conditions);
   checks.forEach((name,i)=>add(name,'check_'+i,'Not checked','text',states));
   add('Repair estimate (₹) — not booked as expense','estimated_repairs','','number');
   add('Notes','notes');
  }else{
   add('Auction platform','auction_platform');
   add('Lot / bank reference','auction_reference');
   add('Expected resale (₹)','expected_resale','','number');
   add('Maximum bid (₹)','maximum_bid','','number');
   for(const [key,label] of [
    ['estimated_repairs','Estimated repairs (₹)'],
    ['estimated_parking','Estimated parking (₹)'],
    ['estimated_transfer','Estimated transfer (₹)'],
    ['estimated_transport','Estimated transport (₹)'],
    ['other_estimated_expenses','Other estimated expenses (₹)'],
    ['target_profit','Target profit (₹)']
   ])add(label,key,'0','number');
   add('Notes','notes');
  }
  const submit=form.querySelector('button[type="submit"]');
  form.onsubmit=async event=>{
   event.preventDefault();if(pending)return;
   if(!canSubmit()){notify('Cloud view changed. Refresh first.');modal.close();return;}
   let instruction;
   try{instruction=plan(kind,bike,Object.fromEntries(new FormData(form)),revision);}
   catch(error){notify(error.message);return;}
   if(!confirm('Save this private '+kind+' history entry? It will NOT post financial expenses or alter browser records.'))return;
   if(!canSubmit()){notify('Cloud view changed. Refresh first.');modal.close();return;}
   pending=true;if(submit)submit.disabled=true;
   try{await write(fetch,instruction);modal.close();notify('Cloud history confirmed; refreshing.');await refresh();}
   catch(error){notify(error.message);}
   finally{pending=false;if(submit)submit.disabled=false;}
  };
  const close=document.getElementById('cloud-operation-close');
  if(close)close.onclick=()=>{if(!pending)modal.close();};
  if(!modal.open)modal.showModal();
 }
 return {plan,write,openDialog,isPending:()=>pending};
});

