// A strictly read-only, aggregate-only comparison of a verified legacy
// browser backup with a checksum-verified and relationship-audited cloud export.
// No customer or vehicle IDs, registration numbers, or raw values in output.
import {key,regKey,stable,validateBackup} from './cloud-core.mjs';
import {auditBrowserBackup} from './browser-backup-audit.mjs';
const counts=()=>({wouldBeNew:0,identicalExisting:0,conflictingExistingId:0,
  registrationOrChassisCollision:0,malformedCloudPayload:0});
function cloudValue(row){
 if(typeof row.payload_json!=='string')return null;
 try{
  const parsed=JSON.parse(row.payload_json);
  return parsed&&typeof parsed==='object'&&!Array.isArray(parsed)?parsed:null;
 }catch{return null;}
}
function validRow(row){
 return row&&typeof row==='object'&&!Array.isArray(row)&&
  typeof row.id==='string'&&row.id.length>0;
}
export function compareLegacyWithCloud(backup,tables){
 const problems=validateBackup(backup);
 if(problems.length)throw Error('Legacy browser backup fails source validation.');
 if(!tables||typeof tables!=='object'||Array.isArray(tables)||
  !Array.isArray(tables.vehicles)||!Array.isArray(tables.sales)||
  !Array.isArray(tables.customers)||!Array.isArray(tables.customer_payments))
  throw Error('A complete, verified cloud table export is required.');
 if(tables.vehicles.some(x=>!validRow(x))||
   tables.sales.some(x=>!validRow(x)))throw Error('Malformed cloud record identifiers.');
 const legacyAudit=auditBrowserBackup(backup);
 const byId=new Map(),byReg=new Map(),byChassis=new Map();
 let duplicateCloudIds=0;
 for(const row of tables.vehicles){
  if(byId.has(row.id))duplicateCloudIds++;else byId.set(row.id,row);
  const reg=regKey(row.registration_key),chassis=key(row.chassis_key)||null;
  if(reg){
   const ids=byReg.get(reg)||new Set();ids.add(row.id);byReg.set(reg,ids);
  }
  if(chassis){
   const ids=byChassis.get(chassis)||new Set();ids.add(row.id);byChassis.set(chassis,ids);
  }
 }
 if(duplicateCloudIds)throw Error('Cloud snapshot contains duplicate vehicle IDs.');
 const result=counts();
 for(const b of backup.bikes){
  const existing=byId.get(b.id);
  const normalizedReg=regKey(b.reg),normalizedChassis=key(b.chassis)||null;
  const collides=(normalizedReg&&[...(byReg.get(normalizedReg)||[])].some(x=>x!==b.id))||
   (normalizedChassis&&[...(byChassis.get(normalizedChassis)||[])].some(x=>x!==b.id));
  if(collides)result.registrationOrChassisCollision++;
  if(existing){
   const payload=cloudValue(existing);
   if(!payload){result.malformedCloudPayload++;continue;}
   if(stable(payload)===stable(b)&&existing.status===b.status)
    result.identicalExisting++;
   else result.conflictingExistingId++;
  }else if(!collides)result.wouldBeNew++;
 }
 const legacyIds=new Set(backup.bikes.map(x=>x.id));
 const saleCount=new Map();
 for(const row of tables.sales){
  if(typeof row.vehicle_id!=='string'||!row.vehicle_id)
   throw Error('Cloud snapshot has a missing historical sale link.');
  saleCount.set(row.vehicle_id,(saleCount.get(row.vehicle_id)||0)+1);
 }
 const sold=backup.bikes.filter(x=>x.status==='Sold');
 const saleLinks={soldVehicles:sold.length,missingCloudSaleIds:0,
  oneExistingCloudSaleIdStillNeedsVerification:0,multipleCloudSaleIds:0};
 for(const bike of sold){
  const matched=saleCount.get(bike.id)||0;
  if(matched===0)saleLinks.missingCloudSaleIds++;
  else if(matched===1)saleLinks.oneExistingCloudSaleIdStillNeedsVerification++;
  else saleLinks.multipleCloudSaleIds++;
 }
 const projected=legacyAudit.originalSaleEvidenceAudit;
 // Even when the cloud is empty or payloads appear identical, historical
 // sale, customer and payment identities are never inferred automatically.
 return {
  format:'naina-offline-legacy-cloud-compare-v1',
  sourceBackupVersion:backup.version,
  legacyVehicles:backup.bikes.length,
  legacySold:sold.length,legacyReview:legacyAudit.statuses.Review,
  cloudVehicles:tables.vehicles.length,
  cloudSales:tables.sales.length,cloudCustomers:tables.customers.length,
  cloudPayments:tables.customer_payments.length,
  cloudVehiclesNotPresentInLegacy:tables.vehicles.filter(r=>!legacyIds.has(r.id)).length,
  vehicleComparison:result,
  historicalSales:saleLinks,
  preservedSourceEvidence:{
   inventorySalesStatusConflicts:legacyAudit.crossSheetStatusConflicts,
   soldWithoutBuyer:legacyAudit.legacySalesWithMissingBuyerName,
   soldWithOutstandingBalance:legacyAudit.soldWithPositiveOutstandingBalance,
   originalSourceSalePriceDifferences:projected.salePriceDifferences,
   originalSourceBalanceDifferences:projected.remainingAmountDifferences,
   missingSourceBalanceEvidence:projected.missingRemainingAmountEvidence,
   ambiguousSourceBalanceEvidence:projected.ambiguousRemainingAmountEvidence,
  },
  historicalSaleIdsVerified:0,
  customerIdMappingsVerified:false,paymentLedgerReconciled:false,
  mediaBytesVerified:false,hostedOwnerIngressVerified:false,
  importAuthorized:false,importExecuted:false,noWritesPerformed:true,
  migrationAllowed:false,
  note:'Aggregate comparison only; original IDs and values are preserved. Resolve historical sales, buyer/customer mapping, payments, source conflicts and restore before any separate approved import.',
 };
}

