import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
const root=resolve(fileURLToPath(new URL('..',import.meta.url)));
test('portable static release gate passes in safe development configuration',()=>{
 const r=spawnSync(process.execPath,['scripts/release-preflight.mjs'],{cwd:root,encoding:'utf8',timeout:15000});
 assert.equal(r.status,0,r.stdout+'\n'+r.stderr);
 assert.match(r.stdout,/PREFLIGHT PASSED/);
 assert.match(r.stdout,/Production release switch OFF: CRM_WRITES_ENABLED/);
 assert.match(r.stdout,/Production release switch OFF: PRIVATE_MEDIA_ENABLED/);
});
test('release gate script detects unsafe cloud and media activation',()=>{
 const src=readFileSync(resolve(root,'scripts/release-preflight.mjs'),'utf8');
 for(const gate of ['MAIN_CRM_CLOUD_PREVIEW_ENABLED','HOSTED_READONLY_PREFLIGHT_ENABLED','LEGACY_CLOUD_ENABLED','CRM_READ_FEATURES_ENABLED','CRM_WRITES_ENABLED','PRIVATE_MEDIA_ENABLED','CLOUD_TRANSFER_ENABLED'])
  assert.ok(src.includes(gate),'Missing required production flag: '+gate);
 assert.match(src,/process\.exitCode=1/);
 assert.match(src,/Browser JS parses/);
});

