import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import vm from 'node:vm';
import {execFileSync} from 'node:child_process';
import ts from 'typescript';
import * as policy from '../lib/cloud-core.mjs';
function compile(file,imports={}){const exports={};vm.runInNewContext(ts.transpileModule(fs.readFileSync(file,'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText,{exports,require:n=>{if(!(n in imports))throw Error('Unexpected import '+n);return imports[n]},URL,Response,Object});return exports;}
const service=compile('lib/crm-reads.ts');
const flags=compile('lib/crm-read-flags.ts');
const origin='https://crm.nainamotors.com';
function sqlite(data){return JSON.parse(execFileSync('python',['tests/crm-read-sqlite.py'],{input:JSON.stringify(data),encoding:'utf8'}));}
async function fixture(fn,malformed,empty=false){
 const dir=fs.mkdtempSync(path.join(os.tmpdir(),'naina-reads-'));
 const file=path.join(dir,'synthetic.sqlite');
 sqlite({mode:'init',path:file,malformed,empty});
 const before=fs.readFileSync(file),queries=[];
 const db={prepare(sql){
  assert.match(sql,/^SELECT /);queries.push(sql);
  return {bind(...values){return {async all(){
   return {success:true,results:sqlite({mode:'query',path:file,sql,values})};
  }}}};
 }};
 try{await fn(new service.CrmReads(db),db,queries);assert.deepEqual(fs.readFileSync(file),before,'read services changed database bytes');}
 finally{fs.rmSync(dir,{recursive:true,force:true});}
}
const plain=x=>JSON.parse(JSON.stringify(x));
test('vehicle IDs, status and full source payload preserved',()=>fixture(async r=>{const p=await r.vehicles({id:' vehicle A '});assert.equal(p.items[0].id,' vehicle A ');assert.equal(p.items[0].status,'Available');assert.equal(p.items[0].payload.sourceInventory[0].value,10);assert.equal(p.items[0].financials.landed,130)}));
test('sales map actual arbitrary IDs and original buyer balance',()=>fixture(async r=>{const p=await r.sales({id:'arbitrary-sale-ID'});assert.equal(p.items[0].vehicleId,'b');assert.equal(p.items[0].buyer,'Synthetic buyer');assert.equal(p.items[0].recordedBalance,45);assert.equal(p.items[0].revision,7);assert.equal(p.items[0].payload.balance,'45');assert.equal((await r.features('customer_payments',{saleId:'arbitrary-sale-ID'})).items.length,1)}));
test('customers, leads and expenses read actual payload columns',()=>fixture(async r=>{assert.equal((await r.customers()).items[0].payload.name,'Synthetic customer');assert.equal((await r.leads()).items[0].payload.stage,'New');assert.equal((await r.expenses({vehicleId:' vehicle A '})).items[0].amount,10)}));
test('status counts and filtering preserve all three classifications',()=>fixture(async r=>{assert.deepEqual(plain(await r.stockCounts()),{Available:1,Sold:1,Review:1});assert.equal((await r.vehicles({status:'Review'})).items[0].id,'c')}));
test('nullable values and legacy expenses do not become zero or double count',()=>fixture(async r=>{assert.equal((await r.vehicles({id:'b'})).items[0].financials.landed,null);assert.equal((await r.vehicles({id:'c'})).items[0].financials.landed,130);assert.equal(service.vehicleFinancials({cost:100,parking:10,otherExpenses:20,expenses:999}).landed,130);assert.equal(service.vehicleFinancials({parking:10,otherExpenses:20,expenses:999}).expenseConflict,true)}));
test('all 18 feature readers execute against real schema',()=>fixture(async r=>{for(const name of Object.keys(service.FEATURE_KEYS)){const result=await r.features(name);assert.equal(result.items.length,1,name);assert.ok(result.items[0].decoded)}}));
test('pagination is bounded and lookups use exact IDs',()=>fixture(async r=>{const a=await r.vehicles({limit:2});assert.equal(a.items.length,2);assert.equal(a.nextOffset,2);const b=await r.vehicles({limit:2,offset:2});assert.equal(b.items.length,1);assert.equal(b.nextOffset,null);assert.equal((await r.vehicles({id:'vehicle A'})).items.length,0);assert.equal((await r.sales({vehicleId:'missing'})).items.length,0)}));
test('invalid limits and filters fail before querying',()=>fixture(async(r,db,q)=>{for(const input of [{limit:101},{offset:-1},{limit:0},{limit:1.2},{status:'Changed'},{saleId:'x'}])await assert.rejects(()=>r.vehicles(input),/INVALID_QUERY/);assert.equal(q.length,0);assert.throws(()=>r.features('vehicles; DROP TABLE vehicles'),/INVALID_QUERY/)}));
test('SQL injection remains a bound literal',()=>fixture(async(r,db,q)=>{assert.equal((await r.vehicles({id:"' OR 1=1 --"})).items.length,0);assert.ok(q.every(sql=>!sql.includes('OR 1=1')))}));
for(const malformed of ['{bad','[]','null','{"id":"wrong"}','{"cost":true}','{"parking":-1}'])test('invalid stored JSON is controlled: '+malformed,()=>fixture(async r=>{await assert.rejects(()=>r.vehicles({id:'b'}),/INVALID_RECORD/)},malformed));
test('database errors do not expose original exception',async()=>{const r=new service.CrmReads({prepare(){throw Error('SECRET customer info')}});await assert.rejects(()=>r.vehicles(),e=>e.message==='READ_UNAVAILABLE')});
function route(identity,enabled=false,dbFactory=()=>{throw Error('DB MUST NOT BE CALLED')}){
 const auth=compile('app/chatgpt-auth.ts',{'next/headers':{headers:async()=>new Headers(identity?{'oai-authenticated-user-id':identity.id,'oai-authenticated-user-email':identity.email}:{})},'next/navigation':{redirect(){throw Error()}}});
 const guard=compile('lib/owner-auth.ts',{'../app/chatgpt-auth':auth,'./cloud-core.mjs':policy}).requireOwner;
 return compile('app/api/private-crm/route.ts',{'../../../lib/cloud-server':{guard,json:(x,status=200)=>Response.json(x,{status,headers:{'Cache-Control':'no-store'}}),database:dbFactory},'../../../lib/crm-reads':service,'../../../lib/crm-read-flags':{CRM_READ_FEATURES_ENABLED:enabled}});
}
const owner={id:'synthetic-owner',email:policy.OWNER_EMAIL};
test('new API denies anonymous, different user and browser spoofing',async()=>{for(const [identity,status] of [[null,401],[{id:'other',email:'other@example.com'},403]]){const req=new Request(origin+'/api/private-crm?resource=vehicles',{headers:{'oai-authenticated-user-id':owner.id,'oai-authenticated-user-email':owner.email}});assert.equal((await route(identity).GET(req)).status,status)}});
test('release flag is false and owner cannot override it via request',async()=>{assert.equal(flags.CRM_READ_FEATURES_ENABLED,false);const response=await route(owner).GET(new Request(origin+'/api/private-crm?resource=vehicles&enabled=true'));assert.equal(response.status,423);assert.equal(response.headers.get('cache-control'),'no-store')});
test('enabled branch tested only by synthetic injection; GET uses actual service',()=>fixture(async(r,db)=>{const response=await route(owner,true,()=>db).GET(new Request(origin+'/api/private-crm?resource=vehicles&limit=1'));assert.equal(response.status,200);const data=await response.json();assert.equal(data.cloudSwitchEnabled,false);assert.equal(data.result.items.length,1)}));
test('API sanitizes failures and rejects unknown parameters/resources',async()=>{for(const query of ['resource=unknown','resource=vehicles&owner=spoof','resource=vehicles&limit=900']){const response=await route(owner,true,()=>({})).GET(new Request(origin+'/api/private-crm?'+query));assert.equal(response.status,400)}const response=await route(owner,true,()=>{throw Error('SECRET')}).GET(new Request(origin+'/api/private-crm?resource=vehicles'));assert.equal(response.status,503);assert.ok(!(await response.text()).includes('SECRET'));assert.deepEqual(Object.keys(route(owner)),['GET'])});

test('empty tables return empty pages and zero counts',()=>fixture(async r=>{assert.deepEqual(plain(await r.stockCounts()),{Available:0,Sold:0,Review:0});for(const name of ['vehicles','sales','customers','leads','expenses'])assert.equal((await r[name]()).items.length,0);for(const name of Object.keys(service.FEATURE_KEYS))assert.equal((await r.features(name)).items.length,0)},undefined,true));

