const collect=context.NainaMediaRecovery.collect,hash='a'.repeat(64);
const vehicleId='UP78 ZX / 001';
const item={id:'m1',filename:'photo.jpg',mimeType:'image/jpeg',category:'photo',bytes:8,sha256:hash,state:'active',objectCheck:'metadata-match',recoverableByExport:true};
function page(offset,rows,next=null,revision=5){return {format:'naina-media-recovery-manifest-v1',vehicleId,revision,checkedAt:'2026-10-14T17:00:00Z',limit:25,offset,nextOffset:next,mediaBytesIncluded:false,contentChecksumsVerified:false,attentionRequired:false,items:rows};}
function reply(value){return {ok:true,status:200,async json(){return value}};}
test('single private same-origin read yields a metadata-only audit without keys',async()=>{
 let calls=0;
 const out=await collect(async(url,options)=>{calls++;assert.match(url,/^\/api\/private-media\?/);assert.equal(options.credentials,'same-origin');assert.equal(options.cache,'no-store');const p=new URL(url,'https://crm.example').searchParams;assert.equal(p.get('vehicleId'),vehicleId);return reply(page(0,[item]));},vehicleId);
 assert.equal(calls,1);assert.equal(out.items[0].id,'m1');assert.equal(out.mediaBytesIncluded,false);
