 const corrupted=[
  {...item,object_key:'secret'}, {...item,sha256:'invalid'},
  {...item,objectCheck:'missing',recoverableByExport:true},
 ];
 for(const bad of corrupted)await assert.rejects(collect(async()=>reply(page(0,[bad])),vehicleId),/reconciliation/);
 const result=await collect(async()=>reply(page(0,[{...item,objectCheck:'missing',recoverableByExport:false}])),vehicleId);
 assert.equal(result.attentionRequired,true);
});
test('invalid server status and foreign vehicle audit fail closed',async()=>{
 await assert.rejects(collect(async()=>({ok:false,status:423}),vehicleId),/unavailable/);
 await assert.rejects(collect(async()=>reply({...page(0,[item]),vehicleId:'other'}),vehicleId),/Incomplete/);
 await assert.rejects(collect(async()=>{throw Error('Network')},vehicleId),/connection failed/);
});
test('duplicate IDs across pages and mid-audit revision changes are rejected',async()=>{
 const many=Array.from({length:25},(_,i)=>({...item,id:'id'+i}));
 const pages=[page(0,many,25),page(25,[{...item,id:'id24'}])];
 await assert.rejects(collect(async url=>reply(pages[Number(new URL(url,'https://crm.example').searchParams.get('offset'))===0?0:1]),vehicleId),/reconciliation/);
 const changed=[page(0,many,25),page(25,[{...item,id:'id25'}],null,6)];
 await assert.rejects(collect(async url=>reply(changed[Number(new URL(url,'https://crm.example').searchParams.get('offset'))===0?0:1]),vehicleId),/changed during audit/);
