/* Cloud-only revision watcher. Never writes, never accesses localStorage.
   Cloud mode must be deliberately entered before start(). */
(function(root,factory){
 const api=factory();
 if(typeof module==='object'&&module.exports)module.exports=api;
 else root.NainaCloudSync=api;
})(typeof globalThis==='object'?globalThis:this,function(){
 'use strict';
 function create({fetchRevision,applyUpdate,hasOpenEdits,onStatus=()=>{},isCloudActive,
                   everyMs=45000,schedule=setInterval,unschedule=clearInterval}){
  if(typeof fetchRevision!=='function'||typeof applyUpdate!=='function'||
     typeof hasOpenEdits!=='function'||typeof isCloudActive!=='function'||
     !Number.isSafeInteger(everyMs)||everyMs<15000)throw Error('Invalid cloud synchronization configuration.');
  let active=false,busy=false,timer=null,known=null,pending=null,epoch=0;
  const valid=v=>Number.isSafeInteger(v)&&v>=0;
  async function check(){
   if(!active||busy||!isCloudActive())return false;
   busy=true;const generation=epoch;
   try{
    const revision=await fetchRevision();
    if(!active||epoch!==generation||!isCloudActive())return false;
    if(!valid(revision))throw Error('Unverified cloud revision.');
    // Never roll a device backwards if a stale replica or cached response
    // reports a revision older than the verified in-memory cloud view.
    if(revision<known)throw Error('Stale cloud revision.');
    if(known===revision&&pending===null)return true;
    if(hasOpenEdits()){
     pending=revision;onStatus('pending',revision);return false;
    }
    const applied=await applyUpdate(revision);
    if(!active||epoch!==generation||!isCloudActive())return false;
    if(applied===false){pending=revision;onStatus('pending',revision);return false;}
    // applyUpdate must validate the complete snapshot and confirm its revision.
    // It can return the actually applied revision (which may be newer).
    if(!valid(applied)||applied<revision||applied<known){
     pending=revision;onStatus('error',revision);return false;
    }
    known=applied;pending=null;onStatus('synced',applied);return true;
   }catch{
    if(active&&epoch===generation){onStatus('error',pending);}
    return false;
   }finally{busy=false;}
  }
  function start(revision){
   if(!valid(revision))throw Error('Cannot start cloud sync without a verified revision.');
   stop();known=revision;pending=null;active=true;epoch++;
   timer=schedule(()=>{void check();},everyMs);
   onStatus('synced',revision);
  }
  function stop(){
   active=false;epoch++;if(timer!==null){unschedule(timer);timer=null;}
   pending=null;known=null;onStatus('off',null);
  }
  function acknowledged(revision){
   if(!active)return;
   if(!valid(revision)||revision<known)throw Error('Invalid or stale acknowledged revision.');
   // A manually verified refresh supersedes any in-flight polling result.
   epoch++;known=revision;pending=null;onStatus('synced',revision);
  }
  function status(){return {active,busy,knownRevision:known,pendingRevision:pending};}
  return {start,stop,check,acknowledged,status};
 }
 async function readRevision(fetchFn,endpoint='/api/private-crm-main'){
  if(typeof fetchFn!=='function')throw Error('Cloud fetch is unavailable.');
  const response=await fetchFn(endpoint+'?resource=revision',{credentials:'same-origin',cache:'no-store',redirect:'error'});
  if(!response?.ok)throw Error('Cloud revision check unavailable.');
  const data=await response.json();
  if(data?.source!=='owner-d1-read-only'||!Number.isSafeInteger(data.revision)||data.revision<0)
   throw Error('Unverified cloud revision response.');
  return data.revision;
 }
 return {create,readRevision};
});

