import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const sandbox={crypto:globalThis.crypto,Date,Number,Set,Object,String,JSON,Error};
vm.runInNewContext(fs.readFileSync('public/main-cloud-finance.js','utf8'),sandbox);
const f=sandbox.NainaCloudFinanceEditor;
const bike={id:'exact-B1',status:'Sold',sale:72000,balance:12000,parking:500,otherExpenses:250};
const sales=[{id:'sale-A',vehicleId:'exact-B1',recordedBalance:12000,sale:72000}];
const expenses=[{id:'parking-total',vehicleId:'exact-B1',kind:'parking',amount:500}];
const input={received_at:'2026-10-14',amount:'5000.00',method:'UPI',payment_reference:'TX0001',note:'Part payment'};
test('payment preserves exact linked sale and idempotency',()=>{const p=f.payment(bike,sales,input,25);assert.equal(p.resource,'customer_payments');assert.equal(p.mode,'create');assert.equal(p.data.sale_id,'sale-A');assert.equal(p.data.amount,5000);assert.equal(p.expectedRevision,25);assert.ok(p.idempotencyKey)});
test('rejects duplicate sale links, mismatched balance and overpayment',()=>{
 assert.throws(()=>f.payment(bike,[],input,25),/Exactly one/);
 assert.throws(()=>f.payment(bike,[...sales,...sales],input,25),/Exactly one/);
 assert.throws(()=>f.payment({...bike,balance:9000},sales,input,25),/disagree/);
 assert.throws(()=>f.payment(bike,sales,{...input,amount:'12000.01'},25),/exceeds/);
});
test('expense represents the updated TOTAL, never a duplicated charge',()=>{
 const a=f.expense(bike,expenses,{kind:'parking',amount:'800',notes:'Total adjustment'},26);
 assert.equal(a.id,'parking-total');assert.equal(a.mode,'update');assert.equal(a.data.amount,800);
 const b=f.expense(bike,expenses,{kind:'other',amount:'300',notes:''},26);
 assert.equal(b.mode,'create');assert.equal(b.data.amount,300);
