import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,mkdirSync,writeFileSync,readFileSync,rmSync,unlinkSync,linkSync,symlinkSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {createHash} from 'node:crypto';
import {spawnSync} from 'node:child_process';
import {stable} from '../lib/cloud-core.mjs';
import {TABLE_NAMES} from '../scripts/compare-local-browser-cloud.mjs';
import {auditPairedPrivateRecovery} from '../lib/offline-recovery-pair.mjs';

const hash=v=>createHash('sha256').update(v).digest('hex');
function make(){
 const base=mkdtempSync(join(tmpdir(),'naina-private-recovery-pair-'));
 const sourceDir=join(base,'source'),candidateDir=join(base,'candidate');
 mkdirSync(sourceDir);mkdirSync(candidateDir);
 const bytes=Buffer.from('FAKE VEHICLE DOCUMENT BYTES - NOT REAL');
 const vehicle='synthetic-vehicle',mediaId='synthetic-media';
 const tables=Object.fromEntries(TABLE_NAMES.map(table=>[table,[]]));
 tables.cloud_metadata=[{key:'revision',value:'5'}];
 tables.vehicles=[{id:vehicle,status:'Available',payload_json:JSON.stringify({
  id:vehicle,status:'Available',reg:'UNREG',name:'Fictional motorcycle',notes:'original'})}];
 tables.vehicle_media=[{
  id:mediaId,vehicle_id:vehicle,object_key:'private/SECRET-NEVER-SHOW',
  sha256:hash(bytes),bytes:bytes.length,version_number:1,
  original_filename:'SECRET_DOCUMENT.pdf',category:'other',
  mime_type:'application/pdf',archived_at:'2026-10-25T10:00:00Z',
  is_cover:0,notes:null
 }];
 const snapshots={};
 function store(folder,name,rows,mediaBytes=bytes){
  const files=join(folder,'media');mkdirSync(files,{recursive:true});
  writeFileSync(join(files,mediaId+'.bin'),mediaBytes);
  const payload={format:'naina-cloud-snapshot-v1',exportedAt:name,tables:rows};
  const snapshot={...payload,sha256:hash(stable(payload))};
  const file=join(folder,'d1.json'),raw=JSON.stringify(snapshot);
  writeFileSync(file,raw);
  snapshots[folder]=[file,files,hash(raw)];
  return snapshots[folder];
 }
 const source=store(sourceDir,'2026-10-25T10:00:00Z',tables);
 const second=store(candidateDir,'2026-10-25T15:00:00Z',
  JSON.parse(JSON.stringify(tables)));
 return {base,source,second,bytes,tables,mediaId,sourceDir,candidateDir,store,
  cleanup(){rmSync(base,{recursive:true,force:true})}};
}
test('two separate complete D1/R2 snapshots compare exactly without altering originals',async()=>{
 const f=make();
 try{
  const input=readFileSync(f.source[0]),second=readFileSync(f.second[0]);
  const result=await auditPairedPrivateRecovery(f.source,f.second);
  assert.equal(result.tableCount,27);
  assert.equal(result.totalSourceRows,3);
  assert.equal(result.sourceMediaFilesVerified,1);
  assert.equal(result.candidateMediaFilesVerified,1);
  assert.equal(result.sourceMediaBytesVerified,f.bytes.length);
  assert.equal(result.identicalD1Rows,true);
  assert.equal(result.localCopiesEquivalentAndComplete,true);
  assert.equal(result.mutationsPerformed,false);
  assert.equal(result.hostedD1RestoreVerified,false);
  assert.equal(result.hostedR2RestoreVerified,false);
  assert.equal(result.independentOffsiteStorageProven,false);
  assert.equal(readFileSync(f.source[0]).equals(input),true);
  assert.equal(readFileSync(f.second[0]).equals(second),true);
  assert.doesNotMatch(JSON.stringify(result),/synthetic-vehicle|synthetic-media|SECRET/);
 }finally{f.cleanup();}
});
test('changed valid original D1 financial/narrative payload cannot silently pass row equivalence',async()=>{
 const f=make();
 try{
  const updated=JSON.parse(JSON.stringify(f.tables));
  updated.vehicles[0].payload_json=JSON.stringify({
   id:'synthetic-vehicle',status:'Available',reg:'UNREG',
   name:'Fictional motorcycle',notes:'modified'});
  const target=f.store(f.candidateDir,'2026-10-25T15:01:00Z',updated);
  const result=await auditPairedPrivateRecovery(f.source,target);
  assert.equal(result.sourceMediaComplete,true);
  assert.equal(result.candidateMediaComplete,true);
  assert.equal(result.identicalD1Rows,false);
  assert.deepEqual(result.differentTables,['vehicles']);
  assert.equal(result.localCopiesEquivalentAndComplete,false);
 }finally{f.cleanup();}
});
test('missing archived documents and same-size altered files are not certified',async()=>{
 const f=make();
 try{
  const file=join(f.second[1],f.mediaId+'.bin');
  unlinkSync(file);
  let r=await auditPairedPrivateRecovery(f.source,f.second);
  assert.equal(r.candidateMediaComplete,false);
  assert.equal(r.localCopiesEquivalentAndComplete,false);
  writeFileSync(file,Buffer.alloc(f.bytes.length,65));
  r=await auditPairedPrivateRecovery(f.source,f.second);
  assert.equal(r.candidateMediaComplete,false);
  assert.equal(r.localCopiesEquivalentAndComplete,false);
 }finally{f.cleanup();}
});
test('incorrect independent fingerprints and reused source files or folders fail closed',async()=>{
 const f=make();
 try{
  await assert.rejects(auditPairedPrivateRecovery(
   f.source,[f.second[0],f.second[1],'0'.repeat(64)]),/fingerprint mismatch/);
  await assert.rejects(auditPairedPrivateRecovery(f.source,f.source),/not independent/);
  await assert.rejects(auditPairedPrivateRecovery(
   f.source,[f.second[0],f.source[1],f.second[2]]),/not independent/);
 }finally{f.cleanup();}
});
test('CLI exits nonzero on disagreement without exposing original names, IDs, paths or media keys',()=>{
 const f=make();
 try{
  const script='scripts/verify-private-recovery-pair.mjs';
  const args=[...f.source,...f.second];
  const success=spawnSync(process.execPath,[script,...args],{encoding:'utf8'});
  assert.equal(success.status,0,success.stderr);
  assert.equal(JSON.parse(success.stdout).localCopiesEquivalentAndComplete,true);
  assert.doesNotMatch(success.stdout,/SECRET|synthetic-vehicle|synthetic-media/);
  const bad=spawnSync(process.execPath,
   [script,...f.source,f.second[0],f.second[1],'0'.repeat(64)],
   {encoding:'utf8'});
  assert.equal(bad.status,2);
  assert.doesNotMatch(bad.stdout+bad.stderr,/SECRET|synthetic-vehicle|synthetic-media|naina-private-recovery-pair-/);
 }finally{f.cleanup();}
});

test('hard-linked media objects in different folders are NOT independent backup copies',async()=>{
 const f=make();
 try{
  const file=join(f.second[1],f.mediaId+'.bin');
  unlinkSync(file);
  linkSync(join(f.source[1],f.mediaId+'.bin'),file);
  await assert.rejects(auditPairedPrivateRecovery(f.source,f.second),
    /same underlying file/);
 }finally{f.cleanup();}
});
test('hard-linked database snapshots under separate names are NOT independent',async()=>{
 const f=make();
 try{
  const file=f.second[0];
  unlinkSync(file);
  linkSync(f.source[0],file);
  const raw=readFileSync(file);
  await assert.rejects(auditPairedPrivateRecovery(f.source,[file,f.second[1],hash(raw)]),
    /not independent/);
 }finally{f.cleanup();}
});
test('symlink alias to media folder or database snapshot is not accepted',async()=>{
 const f=make();
 try{
  const linkedDir=join(f.base,'media-directory-alias');
  symlinkSync(f.source[1],linkedDir,'dir');
  await assert.rejects(auditPairedPrivateRecovery(f.source,
   [f.second[0],linkedDir,f.second[2]]),/not independent|Invalid private export/);
  const alias=join(f.candidateDir,'alias-d1.json');
  symlinkSync(f.source[0],alias);
  await assert.rejects(auditPairedPrivateRecovery(f.source,
   [alias,f.second[1],f.source[2]]),/not independent|Invalid private export/);
 }finally{f.cleanup();}
});

