import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';

function getModule(){
 const sandbox={setInterval,clearInterval,URL,URLSearchParams};
 vm.runInNewContext(fs.readFileSync('public/main-cloud-sync.js','utf8'),sandbox);
 return sandbox.NainaCloudSync;
}
function harness(options={}){
 const api=getModule();let changed=options.initialRevision??2,edits=false,active=true,refreshes=0,scheduled=null,cleared=0,states=[];
 const sync=api.create({
  fetchRevision:async()=>{if(options.fetchRevision)return options.fetchRevision();return changed;},
  applyUpdate:async revision=>{refreshes++;return options.applyUpdate?options.applyUpdate(revision):revision;},
  hasOpenEdits:()=>edits,isCloudActive:()=>active,
  onStatus:(kind,revision)=>states.push([kind,revision]),
  schedule:(fn,ms)=>{scheduled={fn,ms};return 1;},
  unschedule:()=>{cleared++;}
 });
 return {sync,states,get refreshes(){return refreshes;},get scheduled(){return scheduled;},
  set revision(x){changed=x;},set edits(x){edits=x;},set active(x){active=x;},
  get cleared(){return cleared}};
}
test('never fetches or refreshes until cloud mode has been explicitly entered',async()=>{
 const h=harness();assert.equal(await h.sync.check(),false);assert.equal(h.refreshes,0);
 h.sync.start(2);assert.equal(h.scheduled.ms,45000);assert.equal(await h.sync.check(),true);assert.equal(h.refreshes,0);
});
test('new remote revision is applied once, only when edits are closed',async()=>{
 const h=harness();h.sync.start(1);h.edits=true;
 assert.equal(await h.sync.check(),false);assert.equal(h.sync.status().pendingRevision,2);assert.equal(h.refreshes,0);
 h.edits=false;assert.equal(await h.sync.check(),true);assert.equal(h.sync.status().knownRevision,2);
 assert.equal(h.refreshes,1);await h.sync.check();assert.equal(h.refreshes,1);
});
test('stopping the watcher prevents any subsequent revision from being applied',async()=>{
 let done;const gate=new Promise(resolve=>{done=resolve;});
 const h=harness({fetchRevision:()=>gate});h.sync.start(1);
 const pending=h.sync.check();h.sync.stop();done(3);
 assert.equal(await pending,false);assert.equal(h.refreshes,0);
 assert.equal(h.sync.status().active,false);assert.equal(h.cleared,1);
});
test('failed and uncertain refreshes never advance the known revision',async()=>{
 const h=harness({applyUpdate:()=>false});h.sync.start(1);await h.sync.check();
 assert.equal(h.sync.status().knownRevision,1);assert.equal(h.sync.status().pendingRevision,2);
 assert.equal(h.states.at(-1)[0],'pending');
});
test('manual verified refresh acknowledges new revision',async()=>{
 const h=harness();h.sync.start(1);h.sync.acknowledged(4);
 assert.equal(h.sync.status().knownRevision,4);assert.equal(h.sync.status().pendingRevision,null);
 h.sync.stop();
});
test('revision API requires owner D1 source and safe integer revision',async()=>{
 const api=getModule();
 const valid=await api.readRevision(async(url,init)=>{
  assert.equal(url,'/api/private-crm-main?resource=revision');assert.equal(init.cache,'no-store');
  return {ok:true,json:async()=>({source:'owner-d1-read-only',revision:11})};
 });
 assert.equal(valid,11);
 await assert.rejects(api.readRevision(async()=>({ok:false,status:423})),/unavailable/);
 await assert.rejects(api.readRevision(async()=>({ok:true,json:async()=>({source:'public',revision:11})})),/Unverified/);
 await assert.rejects(api.readRevision(async()=>({ok:true,json:async()=>({source:'owner-d1-read-only',revision:1.5})})),/Unverified/);
});

test('stale remote revisions cannot roll back a verified device snapshot',async()=>{
 const h=harness();h.sync.start(5);h.revision=4;
 assert.equal(await h.sync.check(),false);
 assert.equal(h.refreshes,0);
 assert.equal(h.sync.status().knownRevision,5);
 assert.equal(h.states.at(-1)[0],'error');
});
test('a refresh reporting older data cannot be accepted as a successful sync',async()=>{
 const h=harness({applyUpdate:()=>1});h.sync.start(2);h.revision=3;
 assert.equal(await h.sync.check(),false);
 assert.equal(h.sync.status().knownRevision,2);
 assert.equal(h.sync.status().pendingRevision,3);
 assert.equal(h.states.at(-1)[0],'error');
});
test('manual acknowledgement rejects older revisions and invalidates an in-flight poll',async()=>{
 let resolvePoll;const gate=new Promise(resolve=>{resolvePoll=resolve;});
 const h=harness({fetchRevision:()=>gate});h.sync.start(5);
 const running=h.sync.check();
 assert.throws(()=>h.sync.acknowledged(4),/stale/);
 h.sync.acknowledged(7);resolvePoll(6);
 assert.equal(await running,false);
 assert.equal(h.sync.status().knownRevision,7);
 assert.equal(h.refreshes,0);
});

