/* Owner-only R2 recovery audit. Metadata JSON, never the private file contents. */
(function(root,factory){
 const api=factory();
 if(typeof module==='object'&&module.exports)module.exports=api;
 else root.NainaMediaRecovery=api;
})(typeof globalThis==='object'?globalThis:this,function(){
 'use strict';
 async function collect(fetchFn,vehicleId){
  if(typeof vehicleId!=='string'||!vehicleId||vehicleId.length>256)throw Error('Invalid cloud vehicle ID.');
  const limit=25,seen=new Set(),items=[];let revision=null,checkedAt='',attentionRequired=false;
  for(let offset=0;offset<=1000;){
   const p=new URLSearchParams({action:'manifest',vehicleId,limit:String(limit),offset:String(offset)});
   let response;
   try{response=await fetchFn('/api/private-media?'+p,{credentials:'same-origin',cache:'no-store',redirect:'error'});}
   catch{throw Error('Media audit connection failed. No report was saved.');}
   if(!response?.ok)throw Error('Private media recovery audit unavailable ('+(response?.status||'network')+').');
   let body;try{body=await response.json();}catch{throw Error('Unverified media audit response.');}
   if(body?.format!=='naina-media-recovery-manifest-v1'||body.vehicleId!==vehicleId||
      !Number.isSafeInteger(body.revision)||body.revision<0||body.limit!==limit||body.offset!==offset||
      body.mediaBytesIncluded!==false||body.contentChecksumsVerified!==false||
      !Array.isArray(body.items)||body.items.length>limit||
      !(body.nextOffset===null||(body.nextOffset===offset+limit&&body.items.length===limit)))
    throw Error('Incomplete private media audit.');
   if(revision===null){revision=body.revision;checkedAt=body.checkedAt;}
   else if(revision!==body.revision)throw Error('Media changed during audit. Retry.');
   for(const item of body.items){
    if(!item||typeof item.id!=='string'||!item.id||seen.has(item.id)||
       typeof item.sha256!=='string'||!/^[a-f0-9]{64}$/.test(item.sha256)||
       !['active','archived','incomplete'].includes(item.state)||
       !['metadata-match','metadata-mismatch','missing'].includes(item.objectCheck)||
       typeof item.bytes!=='number'||!Number.isSafeInteger(item.bytes)||item.bytes<1||
       typeof item.filename!=='string'||typeof item.mimeType!=='string'||typeof item.category!=='string'||
       item.recoverableByExport!==(item.state!=='incomplete'&&item.objectCheck==='metadata-match')||
       Object.hasOwn(item,'object_key'))throw Error('Media metadata requires reconciliation.');
    seen.add(item.id);items.push(item);
   }
   if(items.length>1000)throw Error('Media audit exceeds bounded size.');
   attentionRequired||=body.attentionRequired===true||body.items.some(item=>item.recoverableByExport===false);
   if(body.nextOffset===null)return {format:body.format,vehicleId,revision,checkedAt,mediaBytesIncluded:false,
     contentChecksumsVerified:false,attentionRequired,items,
     note:'Metadata audit only. Export each private file separately and verify its SHA-256 before relying on an offline backup.'};
   offset=body.nextOffset;
  }
  throw Error('Media audit exceeds bounded size.');
 }
 return {collect};
});

