import { env } from 'cloudflare:workers';
export { requireOwner as guard } from './owner-auth';
import { TABLES } from './cloud-core.mjs';
export function json(data:unknown,status=200){return Response.json(data,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}})}
export function database(){if(!env.DB)throw Error('D1 binding DB is not available. This version must be deployed before hosted tests can run.');return env.DB;}
export async function readStatus(){const db=database();const result=await db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all<{name:string}>();const names=result.results.map(x=>x.name);const missing=TABLES.filter((t:string)=>!names.includes(t));const rev=missing.includes('cloud_metadata')?null:await db.prepare("SELECT value FROM cloud_metadata WHERE key='revision'").first<{value:string}>();const value=rev?.value;
 const revisionValid=typeof value==='string'&&/^(?:0|[1-9][0-9]*)$/.test(value)&&Number.isSafeInteger(Number(value));
 return {connected:true,binding:'DB',tables:TABLES.filter((t:string)=>names.includes(t)),missingTables:missing,revision:revisionValid?Number(value):null,revisionValid,mode:'browser-local',importEnabled:false,cloudSwitchEnabled:false};}
export async function failure(fn:()=>Promise<Response>){try{return await fn()}catch(e){return json({error:e instanceof Error&&e.message.startsWith('D1 binding')?e.message:'Database operation failed. No business records were changed.',connected:false},503)}}

