import test from 'node:test';
import assert from 'node:assert/strict';
import {planImport} from '../lib/cloud-core.mjs';

const source={id:'historical-vehicle',name:'Synthetic',status:'Sold',reg:'SYNTH-REG',
 chassis:'SYNTH-CHASSIS',parking:0,otherExpenses:0,expenses:0,sale:50000,balance:0};
const backup=(bike=source)=>({version:3,bikes:[bike],leads:[]});
const cloud=(change={})=>({id:source.id,status:source.status,
 payload_json:JSON.stringify(source),registration_key:'SYNTHREG',
 chassis_key:'SYNTHCHASSIS',revision:2,...change});
test('exact source and all cloud projections classify as skip, never authorize import',()=>{
 const b=backup(),before=JSON.stringify(b),r=planImport(b,[cloud()],[],3,3);
 assert.equal(r.counts.skip,1);assert.equal(r.counts.conflict,0);
 assert.equal(r.importEnabled,false);assert.equal(r.cloudChanged,false);
 assert.equal(JSON.stringify(b),before);
});
test('stored status cannot fake an unchanged historical vehicle',()=>{
 for(const row of [
   cloud({status:'Available'}),
   cloud({payload_json:JSON.stringify({...source,status:'Review'})}),
   cloud({registration_key:'DIFFERENT'}),
   cloud({chassis_key:'DIFFERENT'}),
   cloud({revision:0}),
   cloud({revision:1.5}),
 ]){
  assert.throws(()=>planImport(backup(),[row],[],3,3),/reconciliation|projection/);
 }
});
test('differing source status or registration requires explicit review even with matching revision',()=>{
 for(const newFields of [{status:'Available'},{reg:'SYNTH-OTHER'},{chassis:'OTHER'}]){
  const candidate={...source,...newFields,cloudRevision:2};
  const r=planImport(backup(candidate),[cloud()],[],3,3);
  assert.equal(r.counts.conflict,1);
  assert.equal(r.counts.update,0);
  assert.equal(r.counts.skip,0);
  assert.equal(r.importEnabled,false);
 }
});
test('nonidentity payload update still requires matching per-row revision',()=>{
 const updated={...source,cost:50100,cloudRevision:2};
 assert.equal(planImport(backup(updated),[cloud()],[],3,3).counts.update,1);
 assert.equal(planImport(backup({...updated,cloudRevision:1}),[cloud()],[],3,3).counts.conflict,1);
});
test('conflicting duplicate cloud rows or malformed lead payloads fail closed',()=>{
 assert.throws(()=>planImport(backup(),[cloud(),cloud()],[],3,3),/Duplicate cloud vehicle/);
