export const TABLES=['vehicles','sales','customers','leads','expenses','import_history','audit_logs','cloud_metadata','connection_probes'];
export const OWNER_EMAIL='sakshampathak01@gmail.com';
// Sites account IDs and Site-scoped login IDs are not interchangeable.
// Keep the verified email policy until the real Site-scoped owner ID is verified.
export const OWNER_SUBJECT=null;
export function authorize(user,ownerSubject=OWNER_SUBJECT){
  if(!user||typeof user!=='object'||Array.isArray(user)||
    typeof user.userId!=='string'||!user.userId.trim()||user.userId!==user.userId.trim()||
    /[\x00-\x20\x7f,]/.test(user.userId)||
    typeof user.email!=='string'||!user.email.trim()||/[\x00-\x1f\x7f,]/.test(user.email))return 401;
  if(ownerSubject!==null){
    if(typeof ownerSubject!=='string'||!ownerSubject.trim()||ownerSubject!==ownerSubject.trim())return 403;
    return user.userId===ownerSubject?200:403;
  }
  return user.email.trim().toLowerCase()===OWNER_EMAIL?200:403;
}
export function sameOrigin(origin,url){
  try{
    if(!origin||origin==='null')return false;
    const source=new URL(origin),target=new URL(url);
    return ['https:','http:'].includes(source.protocol)&&!source.username&&!source.password&&
      origin===source.origin&&source.origin===target.origin;
  }catch{return false;}
}
export const key=v=>String(v??'').replace(/[^a-z0-9]/gi,'').toUpperCase();
export function regKey(v){const k=key(v);return ['','UNREG','UNREGISTERED','NA','NONE'].includes(k)?null:k;}
export function stable(v){if(Array.isArray(v))return '['+v.map(stable).join(',')+']';if(v&&typeof v==='object')return '{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+stable(v[k])).join(',')+'}';return JSON.stringify(v);}
export function validateBackup(data){const errors=[];if(!data||![1,2,3].includes(data.version)||!Array.isArray(data.bikes)||!Array.isArray(data.leads))return ['Expected a Naina Motors backup (version 1, 2 or 3).'];if(data.bikes.length>2000||data.leads.length>5000)return ['Backup exceeds the review limit.'];const ids=new Set(),regs=new Map(),chassis=new Map();for(const [i,b]of data.bikes.entries()){if(!b||typeof b!=='object'||Array.isArray(b)){errors.push(`Vehicle ${i+1}: invalid record`);continue}const name=`Vehicle ${i+1}`;if(typeof b.id!=='string'||!b.id||b.id.length>200||ids.has(b.id))errors.push(`${name}: missing or duplicate ID`);ids.add(b.id);if(typeof b.name!=='string'||!b.name.trim())errors.push(`${name}: missing vehicle name`);if(!['Available','Sold','Review'].includes(b.status))errors.push(`${name}: invalid status`);for(const f of ['cost','parking','otherExpenses','expenses','ask','sale','balance','km']){if(b[f]!=null&&b[f]!==''&&(typeof b[f]!=='number'&&typeof b[f]!=='string'||!Number.isFinite(Number(b[f]))||Number(b[f])<0))errors.push(`${name}: invalid ${f}`)}for(const f of ['sourceInventory','sourceSales'])if(b[f]!=null&&(!Array.isArray(b[f])||b[f].some(x=>!x||typeof x!=='object'||Array.isArray(x))))errors.push(`${name}: invalid ${f}`);for(const [k,map,label]of [[regKey(b.reg),regs,'registration'],[key(b.chassis)||null,chassis,'chassis']]){if(k){if(map.has(k))errors.push(`${name}: duplicate ${label} with ${map.get(k)}`);else map.set(k,b.id)}}}
const leadIds=new Set();for(const l of data.leads){if(!l||typeof l.id!=='string'||!l.id||leadIds.has(l.id)||typeof l.name!=='string')errors.push('Missing or duplicate lead ID / name');leadIds.add(l?.id)}return errors;}

/**
 * D1 projection integrity gate for historical import previews.
 * A matching payload JSON is never enough: persisted status, registration
 * and chassis projections must agree with that exact stored payload.
 */
function storedVehicle(row){
 if(!row||typeof row!=='object'||Array.isArray(row)||
    typeof row.id!=='string'||!row.id||
    typeof row.payload_json!=='string'||
    !['Available','Sold','Review'].includes(row.status)||
    !Number.isSafeInteger(row.revision)||row.revision<1)
   throw Error('Stored cloud vehicle row requires reconciliation.');
 let payload;
 try{payload=JSON.parse(row.payload_json);}catch{throw Error('Stored cloud vehicle JSON requires reconciliation.');}
 if(!payload||typeof payload!=='object'||Array.isArray(payload)||
    (payload.id!==undefined&&payload.id!==row.id)||
    (payload.status!==undefined&&payload.status!==row.status)||
    regKey(payload.reg)!==regKey(row.registration_key)||
    (key(payload.chassis)||null)!==(key(row.chassis_key)||null))
  throw Error('Stored cloud vehicle projection conflicts with its payload.');
 return {...row,payload,normalizedRegistration:regKey(row.registration_key),
  normalizedChassis:key(row.chassis_key)||null};
}

export function planImport(backup,existing,existingLeads,revision,expectedRevision){
 const errors=validateBackup(backup);
 if(errors.length)return {valid:false,errors,revision,cloudChanged:false};
 if(expectedRevision!==revision)return {
  valid:false,
  errors:['Cloud revision changed or is missing. Refresh connection status and preview again.'],
  revision,cloudChanged:false
 };
 if(!Array.isArray(existing)||!Array.isArray(existingLeads))
  throw Error('Cloud import preview requires complete existing rows.');
 const byId=new Map(),byReg=new Map(),byChassis=new Map();
 for(const original of existing){
  const row=storedVehicle(original);
  if(byId.has(row.id))throw Error('Duplicate cloud vehicle IDs require reconciliation.');
  byId.set(row.id,row);
  for(const [value,index] of [[row.normalizedRegistration,byReg],[row.normalizedChassis,byChassis]]){
   if(!value)continue;
   if(index.has(value)&&index.get(value)!==row.id)
    throw Error('Duplicate cloud vehicle projection requires reconciliation.');
   index.set(value,row.id);
  }
 }
 const counts={insert:0,update:0,skip:0,conflict:0,review:0},records=[];
 for(const b of backup.bikes){
  const row=byId.get(b.id),reasons=[];
  let action='insert';
  const reg=regKey(b.reg),chassis=key(b.chassis)||null;
  if((reg&&byReg.has(reg)&&byReg.get(reg)!==b.id)||
     (chassis&&byChassis.has(chassis)&&byChassis.get(chassis)!==b.id)){
   action='conflict';
   reasons.push('Registration or chassis belongs to a different cloud ID.');
  }else if(row){
   if(row.status!==b.status){
    action='conflict';
    reasons.push('Source and cloud vehicle statuses differ; manual reconciliation required.');
   }else if(row.normalizedRegistration!==reg||row.normalizedChassis!==chassis){
    action='conflict';
    reasons.push('Source and cloud registration/chassis projections differ; manual reconciliation required.');
   }else if(stable(row.payload)===stable(b)){
    action='skip';
   }else if(!Number.isSafeInteger(b.cloudRevision)||b.cloudRevision!==row.revision){
    action='conflict';
    reasons.push('Different existing record; matching per-record cloudRevision is required.');
   }else action='update';
  }
  if(b.status==='Review')reasons.push('Original status requires review; it will not be corrected.');
  if(b.parking===undefined||b.otherExpenses===undefined)
   reasons.push('Separate parking and other expenses are missing; no inferred allocation.');
  if(b.expenses!=null&&b.parking!=null&&b.otherExpenses!=null&&
     Number(b.expenses)!==Number(b.parking)+Number(b.otherExpenses))
   reasons.push('Legacy combined expenses differ from parking + other; preserve and review.');
  if(b.status==='Sold'&&(b.sale===null||b.sale===undefined||b.sale===''))
   reasons.push('Sold record has no selling price.');
  if(b.balance!=null&&b.sale!=null&&Number(b.balance)>Number(b.sale))
   reasons.push('Buyer balance exceeds sale price.');
  counts[action]++;
  if(reasons.length)counts.review++;
  records.push({id:b.id,registration:b.reg,action,reasons,existingRevision:row?.revision??null});
 }
 const lm=new Map(),leadCounts={insert:0,skip:0,conflict:0};
 for(const row of existingLeads){
  if(!row||typeof row.id!=='string'||!row.id||lm.has(row.id)||
     typeof row.payload_json!=='string')
   throw Error('Existing cloud enquiries require reconciliation.');
  lm.set(row.id,row);
 }
 for(const lead of backup.leads){
  const old=lm.get(lead.id);
  let action='insert';
  if(old){
   let stored;
   try{stored=JSON.parse(old.payload_json);}
   catch{throw Error('Stored cloud enquiry payload requires reconciliation.');}
   if(!stored||typeof stored!=='object'||Array.isArray(stored)||
      (stored.id!==undefined&&stored.id!==old.id))
    throw Error('Stored cloud enquiry identity requires reconciliation.');
   action=stable(stored)===stable(lead)?'skip':'conflict';
  }
  leadCounts[action]++;
 }
 return {valid:true,revision,counts,leadCounts,records,reviewIsSubset:true,
  cloudChanged:false,importEnabled:false,
  preservation:'Original IDs, values and source rows are retained. No values are corrected, imported or persisted by this preview.'};
}

