import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import ts from 'typescript';
import * as policy from '../lib/cloud-core.mjs';
const origin='https://crm.nainamotors.com';
function compile(path,imports){
 const source=fs.readFileSync(path,'utf8');
 const js=ts.transpileModule(source,{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;
 const exports={};vm.runInNewContext(js,{exports,require(name){if(!(name in imports))throw Error('Unexpected import '+name);return imports[name]},Response,Object});return exports;
}
function harness(identity,broken=false){
 // This is the PLATFORM context, separate from attacker-controlled Request headers.
 const trusted=new Headers();
 if(identity?.userId!==undefined)trusted.set('oai-authenticated-user-id',identity.userId);
 if(identity?.email!==undefined)trusted.set('oai-authenticated-user-email',identity.email);
 const auth=compile('app/chatgpt-auth.ts',{'next/headers':{headers:async()=>{if(broken)throw Error('No platform context');return trusted}},'next/navigation':{redirect(){throw Error('Unexpected redirect')}}});
 const {requireOwner}=compile('lib/owner-auth.ts',{'../app/chatgpt-auth':auth,'./cloud-core.mjs':policy});
 let dbAccess=0;
 const cloud={guard:requireOwner,json:(x,s=200)=>Response.json(x,{status:s}),database(){dbAccess++;throw Error('Test forbids database access')},readStatus:async()=>{dbAccess++;return {connected:true,importEnabled:false,cloudSwitchEnabled:false}},failure:async fn=>fn()};
 return {guard:requireOwner,route(name){return compile(`app/api/cloud/${name}/route.ts`,{'../../../../lib/cloud-release':compile('lib/cloud-release.ts',{}),'../../../../lib/cloud-server':cloud,'../../../../lib/cloud-core.mjs':policy})},page(){return compile('app/cloud/route.ts',{'../../lib/cloud-server':cloud,'../../ui/cloud.html?raw':{default:'private cloud page'}})},get dbAccess(){return dbAccess}};
}
const owner={userId:'synthetic-site-owner',email:policy.OWNER_EMAIL};
const req=(method='GET',headers={})=>new Request(origin+'/api/cloud/status',{method,headers});
test('legitimate platform owner is authorized and context frozen',async()=>{const h=harness(owner);const result=await h.guard(req());assert.equal(result.user.userId,owner.userId);assert.equal(Object.isFrozen(result.user),true)});
test('missing identity and unavailable platform context fail closed',async()=>{for(const h of [harness(null),harness(owner,true),harness({email:policy.OWNER_EMAIL}),harness({userId:owner.userId})])assert.equal((await h.guard(req())).error.status,401)});
test('different authenticated account is forbidden',async()=>{assert.equal((await harness({...owner,email:'someone@example.com'}).guard(req())).error.status,403)});
test('malformed identity fields are rejected without exceptions',()=>{for(const u of [null,{},[],{userId:1,email:policy.OWNER_EMAIL},{userId:' ',email:policy.OWNER_EMAIL},{userId:'id,spoof',email:policy.OWNER_EMAIL},{userId:'id',email:[]},{userId:'id',email:'x\n'+policy.OWNER_EMAIL}])assert.equal(policy.authorize(u),401)});
test('optional stable-subject policy denies mismatches and invalid configuration',()=>{assert.equal(policy.OWNER_SUBJECT,null);assert.equal(policy.authorize(owner,owner.userId),200);assert.equal(policy.authorize(owner,'other-subject'),403);assert.equal(policy.authorize(owner,''),403)});
test('spoofed Request identity, flags, query and bearer cannot supply platform identity',async()=>{
 const request=new Request(origin+'/api/cloud/import?userId=synthetic-site-owner&verifiedByPlatform=true',{method:'POST',headers:{origin,'content-type':'application/json','oai-authenticated-user-id':owner.userId,'oai-authenticated-user-email':owner.email,'x-owner-id':owner.userId,authorization:'Bearer fake'},body:JSON.stringify({...owner,verifiedByPlatform:true})});
 const h=harness(null);assert.equal((await h.guard(request)).error.status,401);assert.equal(request.bodyUsed,false);
 const other=harness({...owner,email:'other@example.com'});assert.equal((await other.guard(request)).error.status,403);
});
for(const method of ['POST','PUT','PATCH','DELETE'])test(`${method} automatically requires same-origin even without caller flag`,async()=>{
 const h=harness(owner);
 for(const headers of [{},{origin:'https://evil.example'},{origin:'null'},{origin, 'sec-fetch-site':'cross-site'}])assert.equal((await h.guard(req(method,headers))).error.status,403);
 assert.equal((await h.guard(req(method,{origin}))).user.userId,owner.userId);
});
test('origin rejects lookalikes, userinfo, paths and malformed values',()=>{for(const value of ['https://crm.nainamotors.com.evil.test','https://evil@crm.nainamotors.com',origin+'/path','garbage','null'])assert.equal(policy.sameOrigin(value,origin+'/api'),false)});
for(const [name,method] of [['status','GET'],['records','GET'],['dry-run','POST'],['test','POST'],['import','POST']])test(`direct ${name} route rejects unauthorized users before database work`,async()=>{
