import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';

// Two independent simulated browser tabs sharing one synthetic revisioned
// server. This never touches cloud bindings, live accounts or browser storage.
const sandbox={URL,URLSearchParams,Set,Map,setInterval,clearInterval};
vm.runInNewContext(fs.readFileSync('public/main-cloud-adapter.js','utf8'),sandbox);
vm.runInNewContext(fs.readFileSync('public/main-cloud-sync.js','utf8'),sandbox);
const adapter=sandbox.NainaMainCloudAdapter;
const watcher=sandbox.NainaCloudSync;

function fakeServer(){
 let revision=1,name='Synthetic scooter',requests=0;
 const fetch=async (url,options)=>{
  requests++;
  assert.equal(options.credentials,'same-origin');
  assert.equal(options.cache,'no-store');
  const p=new URL(url,'https://synthetic.invalid').searchParams;
  const resource=p.get('resource');
  const data=resource==='vehicles'?[{id:'synthetic-v1',status:'Available',
   payload:{id:'synthetic-v1',status:'Available',name}}]:[];
  return {ok:true,status:200,async json(){return {
   source:'owner-d1-read-only',revision,editEnabled:false,mediaEnabled:false,
   result:resource==='revision'?{}:{items:data,limit:100,offset:Number(p.get('offset')),nextOffset:null}
  };}};
 };
 return {fetch,get revision(){return revision;},get requests(){return requests;},
  update(value){name=value;revision++;},regress(){revision--;}};
}
async function device(server){
 let view=await adapter.load(server.fetch),editing=false;
 const states=[];
 const sync=watcher.create({
  fetchRevision:async()=>server.revision,
  applyUpdate:async required=>{
   const candidate=await adapter.load(server.fetch);
   // Same lower-bound rule enforced by the real dashboard before state swap.
   if(candidate.cloudRevision<required||candidate.cloudRevision<view.cloudRevision)return false;
   view=candidate;return view.cloudRevision;
  },
  hasOpenEdits:()=>editing,isCloudActive:()=>true,
  onStatus:(status,revision)=>states.push([status,revision]),
  schedule:()=>1,unschedule:()=>{}
 });
 sync.start(view.cloudRevision);
 return {sync,states,get view(){return view;},set editing(value){editing=value;}};
}
test('laptop and phone simulations converge only after safe refresh and edit close',async()=>{
 const server=fakeServer(),laptop=await device(server),phone=await device(server);
 assert.equal(laptop.view.bikes[0].name,'Synthetic scooter');
 assert.equal(phone.view.cloudRevision,1);
 server.update('Synthetic scooter — updated');
 phone.editing=true;
 assert.equal(await laptop.sync.check(),true);
 assert.equal(await phone.sync.check(),false);
 assert.equal(laptop.view.bikes[0].name,'Synthetic scooter — updated');
 assert.equal(phone.view.bikes[0].name,'Synthetic scooter');
 assert.equal(phone.sync.status().pendingRevision,2);
 phone.editing=false;
 assert.equal(await phone.sync.check(),true);
 assert.equal(phone.view.cloudRevision,2);
 assert.equal(phone.view.bikes[0].name,laptop.view.bikes[0].name);
 assert.equal(phone.sync.status().pendingRevision,null);
 laptop.sync.stop();phone.sync.stop();
});
test('stale cloud revision is not applied to an already newer device',async()=>{
 const server=fakeServer(),laptop=await device(server);
 server.update('Synthetic v2');
 assert.equal(await laptop.sync.check(),true);
 server.regress();
 const count=server.requests;
 assert.equal(await laptop.sync.check(),false);
 assert.equal(server.requests,count,'stale global revision blocks page fetching');
 assert.equal(laptop.view.bikes[0].name,'Synthetic v2');
 assert.equal(laptop.view.cloudRevision,2);
 laptop.sync.stop();
});

