#!/usr/bin/env node
// READS one legacy backup and CREATES one new OWNER-PRIVATE review file locally.
// No network, cloud, browser storage, repository output, or overwrites.
import {createHash} from 'node:crypto';
import {openSync,closeSync,fchmodSync,readFileSync,statSync,realpathSync,rmSync,writeFileSync} from 'node:fs';
import {isAbsolute,resolve,dirname,extname,sep} from 'node:path';
import {fileURLToPath} from 'node:url';
import {createPrivateSaleReview,attachCloudCandidatesToSaleReview} from '../lib/private-sale-review.mjs';
import {validatedCloudSnapshot} from './compare-local-browser-cloud.mjs';

const root=realpathSync(fileURLToPath(new URL('../',import.meta.url)));
const inside=(a,b)=>a===b||a.startsWith(b+sep);
function outputPath(value,inputPath){
 if(typeof value!=='string'||!isAbsolute(value)||extname(value).toLowerCase()!=='.json')
  throw Error('Output must be an absolute JSON file path.');
 const folder=realpathSync(dirname(value));
 const destination=resolve(folder,value.slice(value.lastIndexOf(sep)+1));
 if(inside(destination,root))throw Error('Private review cannot be written into the source repository.');
 if(destination===inputPath)throw Error('Original input cannot be overwritten.');
 return destination;
}
function main(){
 if(![4,6].includes(process.argv.length))
  throw Error('Usage: node scripts/create-private-sale-review.mjs PRIVATE_BACKUP.json /absolute/private-review.json [SIGNED_CLOUD_SNAPSHOT.json INDEPENDENT_RAW_SHA256]');
 const source=realpathSync(process.argv[2]);
 // Refuse private input accidentally placed under git checkout.
 if(inside(source,root))throw Error('Original business backup must be outside the source repository.');
 const stats=statSync(source);
 if(!stats.isFile()||stats.size<2||stats.size>25*1024*1024)
  throw Error('Invalid original backup size.');
 const raw=readFileSync(source);
 const sourceHash=createHash('sha256').update(raw).digest('hex');
 let worksheet=createPrivateSaleReview(JSON.parse(raw.toString('utf8')),sourceHash);
 const destination=outputPath(process.argv[3],source);
 if(process.argv.length===6){
  const target=realpathSync(process.argv[4]);
  if(inside(target,root)||target===source||target===destination)
   throw Error('Cloud export must be independent and outside repository.');
  const info=statSync(target);
  if(!info.isFile()||info.size<10||info.size>20*1024*1024)
   throw Error('Invalid cloud snapshot size.');
  const expected=process.argv[5],cloudRaw=readFileSync(target);
  if(!/^[a-f0-9]{64}$/.test(expected)||
     createHash('sha256').update(cloudRaw).digest('hex')!==expected)
   throw Error('Independent cloud snapshot fingerprint mismatch.');
  const tables=validatedCloudSnapshot(JSON.parse(cloudRaw.toString('utf8')));
  worksheet=attachCloudCandidatesToSaleReview(worksheet,tables,expected);
 }
 let fd=null;
 try {
  // 'wx' refuses existing files and symlinks, including all prior review files.
  fd=openSync(destination,'wx',0o600);
  fchmodSync(fd,0o600);
  writeFileSync(fd,JSON.stringify(worksheet,null,2)+'\n');
 } catch {
  // Do not leave a partial PII file when the write fails after creating it.
  if(fd!==null)rmSync(destination,{force:true});
  throw Error('Private review could not be created safely.');
 } finally {
  if(fd!==null)closeSync(fd);
 }
 // No vehicle IDs, customer names, phone numbers or file contents on stdout.
 console.log(JSON.stringify({
  format:worksheet.format,
  sourceBackupSha256:sourceHash,
  historicalVehiclesToReview:worksheet.reviewRowCount,
  soldVehicles:worksheet.originalStatusCounts.Sold,
  reviewStatusVehicles:worksheet.originalStatusCounts.Review,
  buyerNamesMissing:worksheet.soldWithUnrecordedBuyerName,
  realCloudSnapshotCompared:worksheet.cloudSnapshotCompared===true,
  linkedCloudSaleCandidates:worksheet.linkedCloudSaleCandidates??0,
  existingCloudSaleIdsVerified:0,
  outputCreatedPrivate:true,cloudImportExecuted:false,migrationAllowed:false,
 },null,2));
}
try{main();}catch{
 console.error('FAIL: Private historical review unavailable. Original backup unchanged; no cloud action.');
 process.exitCode=2;
}

