/* Explicit, guarded cloud feature editing. No localStorage reads or writes.
   The server independently gates all reads and writes; browser capabilities are UI hints. */
(function(root,factory){
 const api=factory();
 if(typeof module==='object'&&module.exports)module.exports=api;
 else root.NainaCloudFeatureEditor=api;
})(typeof globalThis==='object'?globalThis:this,function(){
 'use strict';
 const statuses=new Set(['Missing','Pending','Received','Delivered','Not Applicable']);
 const locations=['Showroom','Godown','Mechanic','In Transit','Other'];
 let pending=false;
 const text=(value,max=3000)=>{if(typeof value!=='string'||value.length>max||/[\x00-\x08\x0b\x0c\x0e-\x1f]/.test(value))throw Error('Invalid or excessive text.');return value.trim();};
 const id=value=>{const result=text(value,256);if(!result)throw Error('Vehicle or document ID is required.');return result;};
 const revision=value=>{if(!Number.isSafeInteger(value)||value<0)throw Error('Cloud revision unavailable. Refresh before editing.');return value;};
 const uuid=()=>{if(typeof crypto==='undefined'||typeof crypto.randomUUID!=='function')throw Error('Secure identifiers are unavailable.');return crypto.randomUUID();};
 function plan(resource,recordId,mode,data,expectedRevision){return {resource,id:recordId,mode,data,expectedRevision:revision(expectedRevision),idempotencyKey:uuid()};}
 function location(vehicleId,existing,values,expectedRevision){
  const vehicle=id(vehicleId),type=text(values.location_type,100),label=text(values.location_label,300),notes=text(values.notes,3000);
  if(!locations.includes(type))throw Error('Select a valid location type.');
  if(existing&&(typeof existing!=='object'||existing.vehicle_id!==vehicle))throw Error('Cloud location does not match this vehicle.');
  return plan('vehicle_locations',vehicle,existing?'update':'create',{location_type:type,location_label:label,notes},expectedRevision);
 }
 function documentPlan(vehicleId,rows,values,expectedRevision){
  const vehicle=id(vehicleId),type=text(values.document_type,300),status=text(values.status,100),notes=text(values.notes,3000),due=text(values.due_at||'',20);
  if(!type)throw Error('Select a document.');if(!statuses.has(status))throw Error('Invalid document status.');
  if(due&&!/^\d{4}-\d{2}-\d{2}$/.test(due))throw Error('Invalid due date.');
  if(due&&new Date(due+'T00:00:00Z').toISOString().slice(0,10)!==due)throw Error('Invalid calendar date.');
  const list=Array.isArray(rows)?rows:[];
  const matches=list.filter(row=>row&&row.document_type===type);
  if(matches.length>1)throw Error('Duplicate document requirement. Refresh and reconcile records.');
  const old=matches[0];if(old&&old.vehicle_id!==vehicle)throw Error('Document belongs to another vehicle.');
  return plan('document_requirements',old?id(old.id):uuid(),old?'update':'create',{vehicle_id:vehicle,document_type:type,status,due_at:due||null,notes},expectedRevision);
 }
 async function write(fetchFn,instruction){
  if(typeof fetchFn!=='function'||!instruction||!['vehicle_locations','document_requirements'].includes(instruction.resource)||!['create','update'].includes(instruction.mode))throw Error('Unsupported cloud write request.');
  let response;
  try{response=await fetchFn('/api/private-crm-write',{method:'POST',credentials:'same-origin',cache:'no-store',redirect:'error',headers:{'Content-Type':'application/json'},body:JSON.stringify(instruction)});}
  catch{throw Error('Cloud connection failed. Save outcome is unknown. Refresh before attempting another edit.');}
  if(!response)throw Error('No cloud response. Refresh current records before retrying.');
  if(!response.ok){
   if(response.status===423)throw Error('Cloud editing is locked until production activation is approved.');
   if(response.status===409)throw Error('Cloud records conflicted. Refresh before editing again.');
   throw Error('Cloud save not confirmed ('+response.status+'). Refresh and verify current records before retrying.');
  }
