#!/usr/bin/env node
// OFFLINE source/target audit: never contacts hosting and never writes output
// or mutates inputs. Reports aggregate counts only; keeps both files local.
import {readFileSync,statSync} from 'node:fs';
import {resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
import {createHash} from 'node:crypto';
import {stable} from '../lib/cloud-core.mjs';
import {auditSnapshotLinks} from '../lib/snapshot-link-audit.mjs';
import {compareLegacyWithCloud} from '../lib/local-migration-compare.mjs';
export const TABLE_NAMES=Object.freeze([
 'vehicles','sales','customers','leads','expenses','import_history','audit_logs',
 'cloud_metadata','connection_probes','vehicle_media','document_requirements',
 'vehicle_age_baselines','vehicle_locations','vehicle_timeline',
 'vehicle_inspections','cashbook_entries','customer_payments','auction_plans',
 'reservations','enquiry_notes','price_history','repair_jobs','rto_cases',
 'reminders','document_expiries','generated_documents','owner_preferences'
]);
export function validatedCloudSnapshot(source){
 if(!source||typeof source!=='object'||Array.isArray(source)||
   Object.keys(source).sort().join(',')!=='exportedAt,format,sha256,tables'||
   source.format!=='naina-cloud-snapshot-v1'||
   typeof source.exportedAt!=='string'||!Number.isFinite(Date.parse(source.exportedAt))||
   typeof source.sha256!=='string'||!/^[a-f0-9]{64}$/.test(source.sha256)||
   !source.tables||typeof source.tables!=='object'||Array.isArray(source.tables)||
   Object.keys(source.tables).sort().join(',')!==[...TABLE_NAMES].sort().join(','))
  throw Error('Invalid or incomplete private cloud snapshot format.');
 const {sha256,...body}=source;
 if(createHash('sha256').update(stable(body)).digest('hex')!==sha256)
  throw Error('Private cloud snapshot SHA-256 checksum mismatch.');
 const audit=auditSnapshotLinks(source.tables,{maxIssues:1});
 if(!audit.consistent)throw Error('Private cloud snapshot has unresolved relationship issues.');
 return source.tables;
}
const load=(filename,cap)=>{
 const info=statSync(filename);
 if(!info.isFile()||info.size<2||info.size>cap)throw Error('Local input size invalid.');
 return JSON.parse(readFileSync(filename,'utf8'));
};
async function main(){
 if(process.argv.length!==4){
  console.error('Usage: node scripts/compare-local-browser-cloud.mjs BROWSER_BACKUP.json CLOUD_SNAPSHOT.json');
  process.exitCode=64;return;
 }
 try{
  const browser=load(process.argv[2],25*1024*1024);
  const cloud=validatedCloudSnapshot(load(process.argv[3],20*1024*1024));
  const comparison=compareLegacyWithCloud(browser,cloud);
  console.log(JSON.stringify(comparison,null,2));
  console.log('HOLD: no import, cloud write or historical identity approval was performed.');
 }catch{
  // Do not echo filenames, raw validation errors, customer IDs or payload text.
  console.error('FAIL: Local source/cloud comparison unavailable or inconsistent. No data was changed.');
  process.exitCode=2;
 }
}
if(process.argv[1]&&import.meta.url===pathToFileURL(resolve(process.argv[1])).href)await main();

