// Read-only validation of a private, independently exported D1 + R2 backup.
// Files are exported with their opaque media IDs: <media-id>.bin, NOT object keys.
// This module cannot write files, contact hosting or authorize production recovery.
import {constants} from 'node:fs';
import {lstat,readdir,readFile,open} from 'node:fs/promises';
import {join} from 'node:path';
import {createHash} from 'node:crypto';
import {validatedCloudSnapshot} from '../scripts/compare-local-browser-cloud.mjs';

const SHA=/^[a-f0-9]{64}$/;
const SAFE_ID=/^[A-Za-z0-9_-]{1,200}$/;
const MAX_SNAPSHOT_BYTES=20*1024*1024;
const MAX_MEDIA_BYTES=15*1024*1024;
const MAX_MEDIA_FILES=5000;
const INCOMPLETE='Internal: upload incomplete; reconciliation required';
const sha256=buffer=>createHash('sha256').update(buffer).digest('hex');

// Caller must retain the SHA256 of the EXACT raw snapshot JSON separately,
// ideally with a protected copy of the file. An embedded hash is self-supplied.
export async function auditOfflinePrivateMedia(snapshotPath,mediaDirectory,expectedRawSha256){
 if(typeof expectedRawSha256!=='string'||!SHA.test(expectedRawSha256))
  throw Error('A separate, lowercase 64-character SHA-256 of the original export is required.');
 const stat=await lstat(snapshotPath);
 if(!stat.isFile()||stat.size<10||stat.size>MAX_SNAPSHOT_BYTES)
  throw Error('Invalid private database snapshot input.');
 const raw=await readFile(snapshotPath);
 if(sha256(raw)!==expectedRawSha256)
  throw Error('Independent database snapshot checksum mismatch.');
 // Validates embedded canonical SHA-256, all 27 tables, revision, ID relationships,
 // sales/payment mirrors and private-media metadata BEFORE inspecting files.
 const snapshot=JSON.parse(raw.toString('utf8'));
 const tables=validatedCloudSnapshot(snapshot);
 const rows=tables.vehicle_media;
 if(!Array.isArray(rows)||rows.length>MAX_MEDIA_FILES)throw Error('Invalid bounded media manifest.');
 const folder=await lstat(mediaDirectory);
 if(!folder.isDirectory())throw Error('Media backup path must be an ordinary directory.');
 const entries=await readdir(mediaDirectory,{withFileTypes:true});
 if(entries.length>MAX_MEDIA_FILES+100)throw Error('Media backup directory is oversized.');
 const present=new Map();
 let invalidDirectoryEntries=0;
 for(const entry of entries){
  // Explicitly forbid subfolders, symlinks, special files and arbitrary names.
  // A backup needs exactly one independently saved file per active/archived row.
  if(!entry.isFile()||!SAFE_ID.test(entry.name.replace(/\.bin$/,''))||
    !entry.name.endsWith('.bin')){invalidDirectoryEntries++;continue;}
  present.set(entry.name,true);
 }
 const wanted=new Set();
 let verified=0,missing=0,mismatched=0,invalidIds=0,pending=0,bytesVerified=0;
 for(const row of rows){
  if(row.notes===INCOMPLETE){pending++;continue;}
  if(typeof row.id!=='string'||!SAFE_ID.test(row.id)){invalidIds++;continue;}
  const name=row.id+'.bin';
  if(wanted.has(name)){invalidIds++;continue;}
  wanted.add(name);
  if(!present.has(name)){missing++;continue;}
  let fh;
  try{
   // O_NOFOLLOW prevents a symlink substituted between readdir and open on
   // supported platforms; fstat independently checks exact size/type.
   fh=await open(join(mediaDirectory,name),constants.O_RDONLY|(constants.O_NOFOLLOW||0));
   const info=await fh.stat();
   if(!info.isFile()||!Number.isSafeInteger(row.bytes)||
      row.bytes<1||row.bytes>MAX_MEDIA_BYTES||info.size!==row.bytes)
    {mismatched++;continue;}
   const hash=createHash('sha256');
   let size=0;
   for await(const chunk of fh.createReadStream({autoClose:false})){
    size+=chunk.length;if(size>MAX_MEDIA_BYTES)throw Error('Oversized media item.');
    hash.update(chunk);
   }
   if(size!==row.bytes||hash.digest('hex')!==row.sha256){mismatched++;continue;}
   verified++;bytesVerified+=size;
  }catch{mismatched++;}
  finally{if(fh)await fh.close();}
 }
 const extras=[...present.keys()].filter(name=>!wanted.has(name)).length;
 const expectedRows=rows.length;
 const passed=invalidDirectoryEntries===0&&invalidIds===0&&pending===0&&
  missing===0&&mismatched===0&&extras===0&&verified===expectedRows;
 return {
  format:'naina-offline-private-media-audit-v1',
  databaseSnapshotRawSha256Verified:true,
  databaseSnapshotStructureAndRelationsVerified:true,
  expectedMediaRecords:expectedRows,archivedRecords:rows.filter(x=>x.archived_at!==null).length,
  verifiedMediaFiles:verified,verifiedBytes:bytesVerified,
  pendingRecords:pending,missingFiles:missing,checksumOrSizeMismatches:mismatched,
  invalidMediaIds:invalidIds,unexpectedFiles:extras,
  invalidDirectoryEntries,
  backupFilesComplete:passed,
  contentSha256Verified:passed,
  separateOffsiteCopyVerified:false,
  hostedR2RestoreVerified:false,
  ownerSignInVerified:false,
  productionReleaseApproved:false,
  mutationsPerformed:false,
  note:'One local copy was checked byte-for-byte against a separately fingerprinted, internally validated D1 snapshot. No hosted storage, second backup copy, Owner login or recovery was tested.'
 };
}

