// Pure read-only browser backup audit. NEVER generates replacement IDs,
// modifies records, sends data anywhere, or claims a cloud import occurred.
import { validateBackup, planImport } from './cloud-core.mjs';

const amount=value=>{
 if(value===undefined||value===null||value==='')return null;
 if(typeof value!=='number'&&typeof value!=='string')return null;
 const n=Number(value);return Number.isFinite(n)&&n>=0?n:null;
};
const present=value=>typeof value==='string'&&value.trim().length>0;
// Compare normalized legacy sale fields back to preserved original spreadsheet
// cells, not just with other projections from the same imported row.
// Original sales sheet spells the column "REMAINNING AMOUNT" (double N).
// Also accept later corrected headers; two synonym columns are ambiguous.
const remainingLabels=new Set(['REMAINNING AMOUNT','REMAINING AMOUNT']);
const sourceCells=(bike,label)=>Array.isArray(bike.sourceSales)
 ? bike.sourceSales.filter(x=>x&&typeof x==='object'&&
    (label==='REMAINING AMOUNT'
     ?remainingLabels.has(String(x.label||'').trim().toUpperCase())
     :String(x.label||'').trim().toUpperCase()===label))
 : [];
const sourceCell=(bike,label)=>sourceCells(bike,label)[0]?.value;
const sourceMoney=value=>{
 if(value===null||value===undefined||String(value).trim()==='')return null;
 const clean=typeof value==='string'?value.trim().replace(/[₹,\s]/g,''):value;
 if(typeof clean!=='number'&&!(typeof clean==='string'&&/^(?:0|[1-9]\d{0,11})(?:\.\d{1,2})?$/.test(clean)))return null;
 const n=Number(clean);
 return Number.isFinite(n)&&n>=0&&Number.isSafeInteger(Math.round(n*100))?Math.round(n*100):null;
};
const sameLegacyAmount=(a,b)=>sourceMoney(a)===sourceMoney(b);
const sameBuyer=(a,b)=>String(a??'').trim().toLocaleLowerCase('en-US')===String(b??'').trim().toLocaleLowerCase('en-US');


/**
 * Check original workbook row/serial evidence without ever revealing IDs.
 * Distinct source references identify spreadsheet lines, NOT independently
 * verified historical cloud sale/customer/payment IDs.
 */
const positiveSourceNumber=value=>{
 let n=null;
 if(typeof value==='number')n=value;
 else if(typeof value==='string'&&/^[0-9]+$/.test(value.trim()))n=Number(value.trim());
 return Number.isSafeInteger(n)&&n>0?String(n):null;
};
export function auditSourceSaleReferences(bikes){
 if(!Array.isArray(bikes))throw Error('Expected vehicle records.');
 const seenRows=new Set(),seenSerials=new Set();
 const out={vehicleCount:bikes.length,completeDistinctSourceReferences:0,
  missingSalesRow:0,invalidSalesRow:0,duplicateSalesRow:0,
  missingSerial:0,ambiguousSerial:0,invalidSerial:0,duplicateSerial:0};
 for(const bike of bikes){
  let rowValid=false,serialValid=false;
  const rowRaw=bike?.sourceSalesRow;
  if(rowRaw===undefined||rowRaw===null||rowRaw==='')out.missingSalesRow++;
  else {
   const row=positiveSourceNumber(rowRaw);
   if(row===null)out.invalidSalesRow++;
   else if(seenRows.has(row))out.duplicateSalesRow++;
   else{seenRows.add(row);rowValid=true;}
  }
  const cells=sourceCells(bike||{},'S NO.');
  if(cells.length===0)out.missingSerial++;
  else if(cells.length!==1)out.ambiguousSerial++;
  else{
   const serial=positiveSourceNumber(cells[0].value);
   if(serial===null)out.invalidSerial++;
   else if(seenSerials.has(serial))out.duplicateSerial++;
   else{seenSerials.add(serial);serialValid=true;}
  }
  if(rowValid&&serialValid)out.completeDistinctSourceReferences++;
 }
 return {...out,sourceReferencesUniqueAndComplete:
  out.completeDistinctSourceReferences===bikes.length&&
  Object.entries(out).every(([k,v])=>!/(?:missing|invalid|duplicate|ambiguous)/i.test(k)||v===0),
  historicalCloudSaleIdsVerified:false,cloudImportAllowed:false};
}

export function auditBrowserBackup(backup){
 const issues=validateBackup(backup);
 if(issues.length)return {
  format:'naina-browser-backup-audit-v1',backupValid:false,validationIssueCount:issues.length,
  requiresReconciliation:true,cloudImportExecuted:false,noWritesPerformed:true,
  note:'Original backup failed structure validation. No records were modified or imported.'
 };
 const bikes=backup.bikes;
 const sourceSaleReferences=auditSourceSaleReferences(bikes);
 const sold=bikes.filter(v=>v.status==='Sold');
 const statuses={Sold:sold.length,Available:bikes.filter(v=>v.status==='Available').length,
  Review:bikes.filter(v=>v.status==='Review').length};
 const soldWithoutBuyer=sold.filter(v=>!present(v.buyer)).length;
 const soldWithoutSalePrice=sold.filter(v=>amount(v.sale)===null).length;
 const soldWithoutSaleDate=sold.filter(v=>!present(v.saleDate)).length;
 const excessiveBalance=bikes.filter(v=>{
  const balance=amount(v.balance),sale=amount(v.sale);
  return balance!==null&&sale!==null&&balance>sale;
 }).length;
 const inconsistentExpenses=bikes.filter(v=>{
  const parking=amount(v.parking),other=amount(v.otherExpenses),combined=amount(v.expenses);
  return parking!==null&&other!==null&&combined!==null&&
   Math.round(parking*100)+Math.round(other*100)!==Math.round(combined*100);
 }).length;
 const evidence=sold.reduce((out,bike)=>{
  if(!Array.isArray(bike.sourceSales)||!bike.sourceSales.length){out.missingSalesEvidence++;return out;}
  const sourceStatus=String(sourceCell(bike,'STATUS')??'').trim().toUpperCase();
  if(sourceStatus!=='SOLD'||String(bike.sourceSalesStatus??'').trim().toUpperCase()!=='SOLD')
   out.sourceStatusDisagreements++;
  if(!sameLegacyAmount(sourceCell(bike,'SELLING PRICE'),bike.sale))out.salePriceDifferences++;
  const remaining=sourceCells(bike,'REMAINING AMOUNT');
  if(remaining.length===0)out.missingRemainingAmountEvidence++;
  else if(remaining.length>1)out.ambiguousRemainingAmountEvidence++;
  else if(!sameLegacyAmount(remaining[0].value,bike.balance))out.remainingAmountDifferences++;
  if(!sameBuyer(sourceCell(bike,'COSTUMER NAME'),bike.buyer))out.buyerNameDifferences++;
  return out;
 },{missingSalesEvidence:0,sourceStatusDisagreements:0,salePriceDifferences:0,
    remainingAmountDifferences:0,buyerNameDifferences:0,
    missingRemainingAmountEvidence:0,ambiguousRemainingAmountEvidence:0});
 const crossSheetStatusConflicts=bikes.filter(bike=>
  typeof bike.sourceInventoryStatus==='string'&&typeof bike.sourceSalesStatus==='string'&&
  bike.sourceInventoryStatus.toUpperCase()!==bike.sourceSalesStatus.toUpperCase()).length;
 // This deliberately previews against a SYNTHETIC EMPTY database, and does not
 // imply that the real D1 binding is empty or that any migration may proceed.
 const syntheticEmptyPlan=planImport(backup,[],[],0,0);
 return {
  format:'naina-browser-backup-audit-v1',backupValid:true,validationIssueCount:0,
  version:backup.version,vehicleCount:bikes.length,leadCount:backup.leads.length,statuses,
  legacySalesWithMissingBuyerName:soldWithoutBuyer,
  legacySalesWithMissingSalePrice:soldWithoutSalePrice,
  legacySalesWithMissingSaleDate:soldWithoutSaleDate,
  balanceExceedsSalePrice:excessiveBalance,
  inconsistentExpenseTotals:inconsistentExpenses,
  originalSaleEvidenceAudit:evidence,
  sourceSaleReferences,
  crossSheetStatusConflicts,
  soldWithPositiveOutstandingBalance:sold.filter(b=>amount(b.balance)!==null&&amount(b.balance)>0).length,
  reviewStatusCount:statuses.Review,
  uniqueSaleIdMappingVerified:false,customerIdMappingVerified:false,
  productionD1Compared:false,backupMediaBytesIncluded:false,
  syntheticEmptyDatabaseProjection:{
   wouldInsertVehicles:syntheticEmptyPlan.counts?.insert??null,
   requiresRecordReview:syntheticEmptyPlan.counts?.review??null,
   notAProductionImportPlan:true,
  },
  requiresReconciliation:statuses.Review>0||soldWithoutBuyer>0||soldWithoutSalePrice>0||
   soldWithoutSaleDate>0||excessiveBalance>0||inconsistentExpenses>0||crossSheetStatusConflicts>0||
   Object.values(evidence).some(n=>n>0)||
   !sourceSaleReferences.sourceReferencesUniqueAndComplete||sold.length>0,
  cloudImportExecuted:false,noWritesPerformed:true,
  note:'Read-only summary without customer names, registrations, chassis or original IDs. Real cloud state and historical sale/customer IDs still require explicit reconciliation.'
 };
}

