import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,mkdirSync,writeFileSync,readFileSync,rmSync,unlinkSync,symlinkSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {createHash} from 'node:crypto';
import {stable} from '../lib/cloud-core.mjs';
import {TABLE_NAMES} from '../scripts/compare-local-browser-cloud.mjs';
import {auditOfflinePrivateMedia} from '../lib/offline-private-media-audit.mjs';

const digest=b=>createHash('sha256').update(b).digest('hex');
function setup({archived=true}={}){
 const dir=mkdtempSync(join(tmpdir(),'naina-synthetic-media-audit-'));
 const mediaDir=join(dir,'private-export');
 mkdirSync(mediaDir);
 const first=Buffer.from('FAKE MEDIA A -- no real user data');
 const second=Buffer.from('FAKE ARCHIVED MEDIA B -- no real user data');
 const rows=[{
  id:'synthetic-media-01',vehicle_id:'synthetic-vehicle-01',
  object_key:'private/synthetic-object-01',mime_type:'image/png',
  original_filename:'fictional.png',sha256:digest(first),bytes:first.length,
  version_number:1,is_cover:1,category:'photo',archived_at:null,notes:null
 }];
 if(archived)rows.push({
  id:'synthetic-media-02',vehicle_id:'synthetic-vehicle-01',
  object_key:'private/synthetic-object-02',mime_type:'application/pdf',
  original_filename:'fictional.pdf',sha256:digest(second),bytes:second.length,
  version_number:1,is_cover:0,category:'other',
  archived_at:'2026-10-10T00:00:00Z',notes:null
 });
 const tables=Object.fromEntries(TABLE_NAMES.map(x=>[x,[]]));
 tables.cloud_metadata=[{key:'revision',value:'3'}];
 tables.vehicles=[{id:'synthetic-vehicle-01',status:'Available',
  payload_json:'{"id":"synthetic-vehicle-01","name":"Fictional test","status":"Available"}'}];
 tables.vehicle_media=rows;
 function save(){
  const payload={format:'naina-cloud-snapshot-v1',
   exportedAt:'2026-10-15T00:00:00Z',tables};
  const snapshot={...payload,sha256:digest(stable(payload))};
  const json=JSON.stringify(snapshot),path=join(dir,'private-d1.json');
  writeFileSync(path,json);
  return {path,independent:digest(json)};
 }
 const {path,independent}=save();
 writeFileSync(join(mediaDir,rows[0].id+'.bin'),first);
 if(archived)writeFileSync(join(mediaDir,rows[1].id+'.bin'),second);
 return {dir,mediaDir,path,independent,tables,save,first,second,
  cleanup(){rmSync(dir,{force:true,recursive:true});}};
}
test('full local media bundle verifies active + archived file bytes without mutation',async()=>{
 const f=setup();
 try{
  const source=readFileSync(f.path),file=readFileSync(join(f.mediaDir,'synthetic-media-02.bin'));
  const r=await auditOfflinePrivateMedia(f.path,f.mediaDir,f.independent);
  assert.equal(r.databaseSnapshotRawSha256Verified,true);
  assert.equal(r.databaseSnapshotStructureAndRelationsVerified,true);
  assert.equal(r.expectedMediaRecords,2);
  assert.equal(r.archivedRecords,1);
  assert.equal(r.verifiedMediaFiles,2);
  assert.equal(r.verifiedBytes,f.first.length+f.second.length);
  assert.equal(r.backupFilesComplete,true);
  assert.equal(r.contentSha256Verified,true);
  assert.equal(r.hostedR2RestoreVerified,false);
  assert.equal(r.separateOffsiteCopyVerified,false);
  assert.equal(r.mutationsPerformed,false);
  assert.equal(readFileSync(f.path).equals(source),true);
  assert.equal(readFileSync(join(f.mediaDir,'synthetic-media-02.bin')).equals(file),true);
  assert.doesNotMatch(JSON.stringify(r),/synthetic-vehicle|synthetic-media|private\/synthetic-object|fictional/);
 }finally{f.cleanup();}
});
test('missing archived photo or document cannot pass recovery even when active files match',async()=>{
 const f=setup();
 try{
  unlinkSync(join(f.mediaDir,'synthetic-media-02.bin'));
  const r=await auditOfflinePrivateMedia(f.path,f.mediaDir,f.independent);
  assert.equal(r.missingFiles,1);
  assert.equal(r.archivedRecords,1);
  assert.equal(r.verifiedMediaFiles,1);
  assert.equal(r.backupFilesComplete,false);
 }finally{f.cleanup();}
});
test('wrong file content with same byte length fails SHA-256, and extras block completeness',async()=>{
 const f=setup({archived:false});
 try{
  writeFileSync(join(f.mediaDir,'synthetic-media-01.bin'),Buffer.alloc(f.first.length,0));
  let r=await auditOfflinePrivateMedia(f.path,f.mediaDir,f.independent);
  assert.equal(r.checksumOrSizeMismatches,1);
  assert.equal(r.backupFilesComplete,false);
  writeFileSync(join(f.mediaDir,'synthetic-media-01.bin'),f.first);
  writeFileSync(join(f.mediaDir,'unknown.bin'),Buffer.from('untracked private backup'));
  r=await auditOfflinePrivateMedia(f.path,f.mediaDir,f.independent);
  assert.equal(r.unexpectedFiles,1);
  assert.equal(r.backupFilesComplete,false);
 }finally{f.cleanup();}
});
test('independent raw-file fingerprint and internally signed manifest are both mandatory',async()=>{
 const f=setup({archived:false});
 try{
  await assert.rejects(()=>auditOfflinePrivateMedia(f.path,f.mediaDir,'0'.repeat(64)),/Independent database snapshot checksum/);
  await assert.rejects(()=>auditOfflinePrivateMedia(f.path,f.mediaDir,'bad'),/separate.*SHA-256/);
  f.tables.cloud_metadata[0].value='04';
  const res=f.save();
  await assert.rejects(()=>auditOfflinePrivateMedia(res.path,f.mediaDir,res.independent),/relationship issues/);
 }finally{f.cleanup();}
});
test('symlinks, nested files and invalid media IDs never become trusted backup bytes',async()=>{
 const f=setup({archived:false});
 try{
  const name=join(f.mediaDir,'synthetic-media-01.bin');
  const out=join(f.dir,'external-synthetic.txt');
  writeFileSync(out,f.first);
  unlinkSync(name);
  symlinkSync(out,name);
  const linked=await auditOfflinePrivateMedia(f.path,f.mediaDir,f.independent);
  assert.equal(linked.backupFilesComplete,false);
  assert.equal(linked.invalidDirectoryEntries,1);
  assert.equal(linked.missingFiles,1);
  unlinkSync(name);
  writeFileSync(name,f.first);
  f.tables.vehicle_media[0].id='../escape';
  const next=f.save();
  const invalid=await auditOfflinePrivateMedia(next.path,f.mediaDir,next.independent);
  assert.equal(invalid.invalidMediaIds,1);
  assert.equal(invalid.backupFilesComplete,false);
 }finally{f.cleanup();}
});
test('incomplete uploads cannot be certified simply because local bytes exist',async()=>{
 const f=setup({archived:false});
 try{
  f.tables.vehicle_media[0].notes='Internal: upload incomplete; reconciliation required';
  const next=f.save();
  await assert.rejects(()=>auditOfflinePrivateMedia(next.path,f.mediaDir,next.independent),/relationship issues/);
 }finally{f.cleanup();}
});
test('empty metadata and empty directory verify honestly as zero recovered files',async()=>{
 const f=setup({archived:false});
 try{
  f.tables.vehicle_media=[];rmSync(join(f.mediaDir,'synthetic-media-01.bin'));
  const next=f.save(),r=await auditOfflinePrivateMedia(next.path,f.mediaDir,next.independent);
  assert.equal(r.expectedMediaRecords,0);
  assert.equal(r.verifiedMediaFiles,0);
  assert.equal(r.backupFilesComplete,true);
  assert.equal(r.hostedR2RestoreVerified,false);
 }finally{f.cleanup();}
});

tests/main-cloud-reservations.test.mjs.value:
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const sandbox={crypto:{randomUUID:(()=>{let n=0;return ()=> 'synthetic-uuid-'+(++n);})()},Date,Number,Object,Array,String,Error};
vm.runInNewContext(fs.readFileSync('public/main-cloud-reservations.js','utf8'),sandbox);
const reservations=sandbox.NainaCloudReservations;
const bike={id:'private-test-bike',status:'Available'};
const data={customer_name:'Synthetic buyer',customer_phone:'123',token_amount:'500.25',
 reserved_at:'2026-10-15',expires_at:'2026-10-20',status:'Active',notes:'No payment booked'};
const plain=v=>JSON.parse(JSON.stringify(v));
test('new reservation preserves vehicle ID and treats token as metadata only',()=>{
 const cmd=reservations.plan(bike,null,data,4,[]);
 assert.equal(cmd.resource,'reservations');
 assert.equal(cmd.mode,'create');assert.equal(cmd.data.vehicle_id,bike.id);
 assert.equal(cmd.data.token_amount,500.25);assert.equal(cmd.expectedRevision,4);
 assert.equal(Object.hasOwn(cmd.data,'payment_method'),false);
 assert.equal(Object.hasOwn(cmd.data,'sale'),false);
});
test('unavailable or already reserved vehicles cannot be booked',()=>{
 assert.throws(()=>reservations.plan({...bike,status:'Sold'},null,data,4),/unreserved available/);
 assert.throws(()=>reservations.plan(bike,null,data,4,[{vehicle_id:bike.id,status:'Active'}]),/unreserved available/);
 assert.doesNotThrow(()=>reservations.plan(bike,null,data,4,[{vehicle_id:bike.id,status:'Expired'}]));
});
test('expiry and amount validation never sends invalid financial notes',()=>{
 for(const amount of ['-5','0.001','1,000','1e4','NaN',''])assert.throws(
  ()=>reservations.plan(bike,null,{...data,token_amount:amount},4),/token amount|precision/i);
 assert.throws(()=>reservations.plan(bike,null,{...data,expires_at:'2026-10-14'},4),/expiry/);
 assert.throws(()=>reservations.plan(bike,null,{...data,reserved_at:'2026-02-30'},4),/calendar/);
 assert.throws(()=>reservations.plan(bike,null,data,-1),/revision/);
});
test('closed reservations cannot be reopened or edited; fields remain stable on closure',()=>{
 const existing={id:'existing',vehicle_id:bike.id,customer_name:'Original buyer',
  customer_phone:'001',token_amount:350,reserved_at:'2026-10-15T10:00:00Z',
  expires_at:'2026-10-20',status:'Active',notes:'Original'};
 const frozen=JSON.stringify(existing);
 const cmd=reservations.plan(bike,existing,{...data,status:'Converted',notes:'Converted only'},5);
 assert.equal(cmd.id,'existing');
 assert.equal(Object.hasOwn(cmd.data,'reserved_at'),false);
 assert.equal(Object.hasOwn(cmd.data,'customer_name'),false);
 assert.equal(Object.hasOwn(cmd.data,'customer_phone'),false);
 assert.equal(Object.hasOwn(cmd.data,'token_amount'),false);
 assert.equal(cmd.data.status,'Converted');
 assert.equal(JSON.stringify(existing),frozen);
 assert.throws(()=>reservations.plan(bike,{...existing,status:'Cancelled'},data,5),/Only the matching active/);
 assert.throws(()=>reservations.plan(bike,{...existing,vehicle_id:'wrong'},data,5),/Only the matching active/);
});
test('receipts must match exact resource, ID and revision; no automatic retry',async()=>{
 const cmd=reservations.plan(bike,null,data,5);
 let calls=0;
 const valid=async(url,options)=>{calls++;assert.equal(url,'/api/private-crm-write');assert.equal(options.credentials,'same-origin');return {ok:true,async json(){return {result:{id:cmd.id,resource:'reservations',revision:6}}}};};
 assert.equal((await reservations.write(valid,cmd)).revision,6);
 assert.equal(calls,1);
 await assert.rejects(()=>reservations.write(async()=>({ok:true,json:async()=>({result:{id:'other',resource:'reservations',revision:6}})}),cmd),/not verified/);
 await assert.rejects(()=>reservations.write(async()=>{throw Error('offline');},cmd),/outcome unknown/);
 await assert.rejects(()=>reservations.write(async()=>({ok:false,status:409}),cmd),/conflict/);
});

test('closing a legacy booking with null phone never sends replaced source fields',()=>{
 const existing={id:'old',vehicle_id:bike.id,customer_name:'Fictional buyer',
  customer_phone:null,token_amount:0,reserved_at:'2026-10-15T07:30:00Z',
  expires_at:null,status:'Active',notes:null};
 const unchanged=JSON.stringify(existing);
 const cmd=reservations.plan(bike,existing,{status:'Cancelled',notes:'Closed'},7);
 assert.deepEqual(Object.keys(cmd.data).sort(),['expires_at','notes','status']);
 assert.equal(cmd.data.status,'Cancelled');
 assert.equal(JSON.stringify(existing),unchanged);
});

test('status-only booking closure retains full original expiration timestamp',()=>{
 const exact='2026-10-24T14:45:00+05:30';
 const existing={id:'hold',vehicle_id:bike.id,customer_name:'Fictional buyer',
  customer_phone:'001',token_amount:80,reserved_at:'2026-10-15T12:35:00+05:30',
  expires_at:exact,status:'Active',notes:'Original'};
 const changed=reservations.plan(bike,existing,{status:'Cancelled',
  expires_at:'2026-10-24',notes:'Close without expiry change'},4);
 assert.equal(changed.data.expires_at,exact);
 assert.equal(Object.hasOwn(changed.data,'reserved_at'),false);
 const renewed=reservations.plan(bike,existing,{status:'Active',
  expires_at:'2026-10-26',notes:'Extended'},4);
 assert.equal(renewed.data.expires_at,'2026-10-26');
 assert.throws(()=>reservations.plan(bike,existing,{
