import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,mkdirSync,writeFileSync,readFileSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {createHash} from 'node:crypto';
import {spawnSync} from 'node:child_process';
import {stable} from '../lib/cloud-core.mjs';
import {TABLE_NAMES} from '../scripts/compare-local-browser-cloud.mjs';
const sha=v=>createHash('sha256').update(v).digest('hex');
function setup(){
 const root=mkdtempSync(join(tmpdir(),'naina-private-full-readiness-'));
 const tables=Object.fromEntries(TABLE_NAMES.map(t=>[t,[]]));
 tables.cloud_metadata=[{key:'revision',value:'0'}];
 function copy(name,exportedAt){
  const folder=join(root,name),media=join(folder,'media');
  mkdirSync(media,{recursive:true});
  const payload={format:'naina-cloud-snapshot-v1',exportedAt,tables};
  const data=JSON.stringify({...payload,sha256:sha(stable(payload))});
  const file=join(folder,'d1.json');
  writeFileSync(file,data);
  return [file,media,sha(data)];
 }
 const source=copy('source','2026-10-25T00:00:00Z'),
  candidate=copy('candidate','2026-10-25T01:00:00Z');
 return {root,source,candidate,cleanup(){rmSync(root,{recursive:true,force:true})}};
}
const cli='scripts/verify-private-recovery-readiness.mjs';
const run=args=>spawnSync(process.execPath,[cli,...args],{encoding:'utf8'});
test('one command validates two independent D1 copies and both in-memory SQL rehearsals',()=>{
 const f=setup();
 try{
  const before=readFileSync(f.source[0]),other=readFileSync(f.candidate[0]);
  const completed=run([...f.source,...f.candidate]);
  assert.equal(completed.status,0,completed.stderr);
  const output=JSON.parse(completed.stdout);
  assert.equal(output.tableCount,27);
  assert.equal(output.sourceMediaComplete,true);
  assert.equal(output.candidateMediaComplete,true);
  assert.equal(output.disposableSqliteSourceVerified,true);
  assert.equal(output.disposableSqliteCandidateVerified,true);
  assert.equal(output.sqliteRestoreRehearsed,true);
  assert.equal(output.localCopiesEquivalentAndComplete,true);
  assert.equal(output.hostedD1RestoreVerified,false);
  assert.equal(output.hostedR2RestoreVerified,false);
  assert.equal(output.releaseReady,false);
  assert.equal(output.mutationsPerformed,false);
  assert.equal(readFileSync(f.source[0]).equals(before),true);
  assert.equal(readFileSync(f.candidate[0]).equals(other),true);
  assert.doesNotMatch(completed.stdout+completed.stderr,/naina-private-full-readiness-|d1\.json/);
 }finally{f.cleanup();}
});
test('signed D1 row disagreement never reaches in-memory SQL rehearsal',()=>{
 const f=setup();
 try{
  const payload=JSON.parse(readFileSync(f.candidate[0],'utf8'));
  payload.tables.cloud_metadata[0].value='1';
  const {sha256,...body}=payload;
  payload.sha256=sha(stable(body));
  const newBytes=JSON.stringify(payload);
  writeFileSync(f.candidate[0],newBytes);
  const output=run([...f.source,f.candidate[0],f.candidate[1],sha(newBytes)]);
  assert.equal(output.status,2);
  const bodyOut=JSON.parse(output.stdout);
  assert.equal(bodyOut.identicalD1Rows,false);
  assert.equal(bodyOut.releaseReady,false);
  assert.equal(bodyOut.disposableSqliteSourceVerified,false);
  assert.doesNotMatch(output.stdout,/revision.?1|private-full-readiness/);
 }finally{f.cleanup();}
});
test('valid but SQL-column-invalid snapshot cannot be called a restored database',()=>{
 const f=setup();
 try{
  const payload=JSON.parse(readFileSync(f.candidate[0],'utf8'));
  payload.tables.cloud_metadata[0].unknown_private_extra='NOT A DATABASE COLUMN';
  const {sha256,...body}=payload;payload.sha256=sha(stable(body));
  const newBytes=JSON.stringify(payload);
  writeFileSync(f.source[0],newBytes);
  writeFileSync(f.candidate[0],newBytes);
  const output=run([f.source[0],f.source[1],sha(newBytes),f.candidate[0],f.candidate[1],sha(newBytes)]);
  assert.equal(output.status,2);
  assert.equal(output.stdout,'');
  assert.doesNotMatch(output.stderr,/unknown_private_extra|NOT A DATABASE COLUMN|naina-private-full-readiness-/);
 }finally{f.cleanup();}
});
test('incorrect independent fingerprint fails without leaking private source path',()=>{
 const f=setup();
 try{
  const output=run([f.source[0],f.source[1],'0'.repeat(64),...f.candidate]);
  assert.equal(output.status,2);
  assert.equal(output.stdout,'');
  assert.doesNotMatch(output.stderr,/naina-private-full-readiness-|d1\.json/);
 }finally{f.cleanup();}
});

