import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const sandbox={URLSearchParams,URL,Set,Map,Number,Object,Array,String,Error};
vm.runInNewContext(fs.readFileSync('public/main-cloud-adapter.js','utf8'),sandbox);
const a=sandbox.NainaMainCloudAdapter;
const v={id:'exact-vehicle',status:'Sold',payload:{id:'exact-vehicle',status:'Sold',name:'Synthetic bike',balance:50}};
const sale={id:'sale-01',vehicleId:'exact-vehicle',payload:{},recordedBalance:50};
function fixture(rev=7,override){return async u=>{const p=new URL(u,'https://example.org'),name=p.searchParams.get('resource'),items={vehicles:[v],sales:[sale],leads:[{id:'lead01',payload:{id:'lead01',name:'Synthetic lead'}}],vehicle_locations:[{vehicle_id:'exact-vehicle',location_type:'Godown'}]};if(override)return override(name);return {ok:true,status:200,async json(){return {source:'owner-d1-read-only',revision:rev,editEnabled:false,result:name==='revision'?{}:{items:items[name]||[],limit:100,offset:Number(p.searchParams.get('offset')),nextOffset:null}}}}};}
test('complete explicit preview preserves IDs, balance and location',async()=>{const s=await a.load(fixture());assert.equal(s.bikes[0].id,'exact-vehicle');assert.equal(s.bikes[0].balance,50);assert.equal(s.bikes[0].vehicleLocation.location_type,'Godown')});
test('cloud customers appear separately and cannot rewrite sold buyer history',async()=>{const response=async u=>{const p=new URL(u,'https://example.org'),resource=p.searchParams.get('resource');if(resource==='customers')return {ok:true,status:200,async json(){return {source:'owner-d1-read-only',revision:7,editEnabled:false,result:{items:[{id:'contact-1',payload:{id:'contact-1',name:'Synthetic contact',phone:'000'}}],limit:100,offset:0,nextOffset:null}}}};return fixture()(u);};const result=await a.load(response);assert.equal(result.customers[0].id,'contact-1');assert.equal(result.bikes[0].buyer,undefined);});
test('rejects duplicate cloud customer IDs and incorrect payload IDs',()=>{const base={vehicles:[v],sales:[sale],leads:[]};assert.throws(()=>a.recordsToView({...base,customers:[{id:'1',payload:{name:'Name'}},{id:'1',payload:{name:'Name'}}]}),/customer.*reconciliation/);assert.throws(()=>a.recordsToView({...base,customers:[{id:'1',payload:{id:'other',name:'Name'}}]}),/customer.*reconciliation/);});
test('disabled/unauthorized cloud response fails without fallback',async()=>assert.rejects(a.load(async()=>({ok:false,status:423})),/423/));
test('unmigrated inventory is rejected',()=>assert.throws(()=>a.recordsToView({vehicles:[],leads:[]}),/not imported/));
test('duplicate or status-conflicting IDs are rejected',()=>{assert.throws(()=>a.recordsToView({vehicles:[v,v],leads:[]}),/reconciliation/);assert.throws(()=>a.recordsToView({vehicles:[{...v,status:'Available'}],leads:[]}),/reconciliation/)});
test('historical sale mismatch is rejected',()=>assert.throws(()=>a.recordsToView({vehicles:[v],sales:[{...sale,recordedBalance:20}],leads:[]}),/disagree/));
test('changing revision refuses inconsistent snapshot',async()=>assert.rejects(a.load(fixture(7,n=>({ok:true,async json(){return {source:'owner-d1-read-only',revision:n==='sales'?8:7,editEnabled:false,mediaEnabled:false,result:{items:n==='vehicles'?[v]:n==='sales'?[sale]:[],limit:100,offset:0,nextOffset:null}}}}))),/changed/));
test('invalid source and incomplete page rejected',async()=>{await assert.rejects(a.load(async()=>({ok:true,async json(){return {source:'incorrect',revision:1,result:{}}}})),/Unverified/);await assert.rejects(a.load(async()=>({ok:true,async json(){return {source:'owner-d1-read-only',revision:1,editEnabled:false,result:{items:[],offset:0,limit:100,nextOffset:100}}}})),/Incomplete/)});

test('server capability must be explicit and stable across all cloud pages',async()=>{
 const make=async url=>{const r=await fixture()(url);const data=await r.json();data.editEnabled=true;return {ok:true,status:200,async json(){return data}};};
 assert.equal((await a.load(make)).cloudEditsEnabled,true);
 const changed=async url=>{const r=await fixture()(url);const data=await r.json();data.editEnabled=new URL(url,'https://x.invalid').searchParams.get('resource')!=='sales';return {ok:true,status:200,async json(){return data}};};
 await assert.rejects(a.load(changed),/capability changed/);
});

test('orphaned and duplicate feature rows cannot silently disappear from cloud preview',()=>{
 const base={vehicles:[{id:'source-id',status:'Available',payload:{id:'source-id',name:'Synthetic bike',status:'Available'}}],leads:[]};
 for(const [resource,row,pattern] of [
  ['vehicle_locations',{vehicle_id:'missing-vehicle',location_type:'Godown'},/location linkage/],
  ['document_requirements',{id:'doc-1',vehicle_id:'missing-vehicle',document_type:'RC'},/document linkage/],
  ['vehicle_media',{id:'media-1',vehicle_id:'missing-vehicle',mime_type:'image/jpeg'},/media linkage/],
 ])assert.throws(()=>a.recordsToView({...base,[resource]:[row]}),pattern,resource);
 const loc={vehicle_id:'source-id',location_type:'Showroom'};
 assert.throws(()=>a.recordsToView({...base,vehicle_locations:[loc,loc]}),/location linkage/);
});
test('cloud photo view rejects raw R2 object keys and private uploader metadata',()=>{
 const base={vehicles:[{id:'v',status:'Available',payload:{id:'v',name:'Synthetic',status:'Available'}}],leads:[]};
 const row={id:'media',vehicle_id:'v',mime_type:'image/jpeg',object_key:'private/secret',uploaded_by:'secret-user'};
 assert.throws(()=>a.recordsToView({...base,vehicle_media:[row]}),/redacted/);
 assert.deepEqual(a.recordsToView({...base,vehicle_media:[{id:'media',vehicle_id:'v',mime_type:'image/jpeg'}]}).bikes[0].vehicleMedia.length,1);
});

test('reservation projection preserves booked customer and enforces one active hold',()=>{
 const base={vehicles:[{id:'available',status:'Available',payload:{id:'available',name:'Synthetic bike',status:'Available'}}],leads:[],sales:[]};
 const first={id:'booking-1',vehicle_id:'available',customer_name:'Synthetic customer',status:'Active',token_amount:300,reserved_at:'2026-10-15'};
 const output=a.recordsToView({...base,reservations:[first]});
 assert.equal(output.reservations.length,1);
 assert.equal(output.bikes[0].cloudReservations[0].id,'booking-1');
 assert.equal(output.bikes[0].status,'Available');
 assert.throws(()=>a.recordsToView({...base,reservations:[first,{...first,id:'booking-2'}]}),/Active cloud reservation/);
 assert.throws(()=>a.recordsToView({...base,reservations:[first,{...first,id:'booking-1',status:'Cancelled'}]}),/Cloud reservation records/);
});
test('active reservation on sold stock and orphaned vehicle fail closed',()=>{
 const sold={vehicles:[v],leads:[],sales:[sale]},held={id:'held',vehicle_id:'exact-vehicle',customer_name:'Customer',status:'Active'};
 assert.throws(()=>a.recordsToView({...sold,reservations:[held]}),/Active cloud reservation/);
 assert.throws(()=>a.recordsToView({...sold,reservations:[{...held,vehicle_id:'unknown'}]}),/Cloud reservation records/);
 assert.doesNotThrow(()=>a.recordsToView({...sold,reservations:[{...held,status:'Converted'}]}));
});

test('cloud vehicle inspection and auction histories attach separately without changing financials',()=>{
 const base={vehicles:[{id:'bike',status:'Available',payload:{id:'bike',name:'Fictional',status:'Available',cost:20000,parking:500,otherExpenses:300,expenses:800}}],leads:[],sales:[]};
 const s=a.recordsToView({...base,vehicle_inspections:[{id:'ins-1',vehicle_id:'bike',inspected_at:'2026-10-25'}],
  auction_plans:[{id:'auc-1',vehicle_id:'bike',outcome:'Planned',expected_resale:60000,maximum_bid:45000}]});
 assert.equal(s.bikes[0].cloudInspections.length,1);
 assert.equal(s.bikes[0].cloudAuctions.length,1);
 assert.equal(s.bikes[0].cost,20000);assert.equal(s.bikes[0].expenses,800);
});
test('duplicate and orphaned history records must not disappear from cloud view',()=>{
 const base={vehicles:[{id:'bike',status:'Available',payload:{id:'bike',name:'Fictional',status:'Available'}}],leads:[],sales:[]};
 const ins={id:'ins-1',vehicle_id:'bike',inspected_at:'2026-10-25'};
 const auction={id:'auc-1',vehicle_id:'bike',outcome:'Planned',expected_resale:60000,maximum_bid:45000};
 for(const fields of [
  {vehicle_inspections:[ins,ins]},
  {vehicle_inspections:[{...ins,vehicle_id:'unknown'}]},
  {auction_plans:[{...auction,vehicle_id:'unknown'}]},
  {auction_plans:[{...auction,maximum_bid:-10}]}
 ])assert.throws(()=>a.recordsToView({...base,...fields}),/reconciliation/);
