const code=fs.readFileSync('public/app.js','utf8');
const bike={id:'original-id',name:'Synthetic bike',reg:'TEST123',status:'Available',cost:100,parking:10,otherExpenses:20,expenses:30,buyer:'Preserved',sourceInventory:[{column:'S',value:10},{column:'T',value:20}]};
const data=(b=bike)=>({bikes:[structuredClone(b)],leads:[],importMeta:{id:'old'},appliedChanges:['historical-marker'],custom:{keep:true}});
function boot(raw,options={}){
 let value=raw;const writes=[],nodes=new Map(),dialogs=[];
 const node=()=>({innerHTML:'',textContent:'',value:'',style:{},classList:{toggle(){},remove(){}},addEventListener(){},close(){},showModal(){},click(){}});
 const context=vm.createContext({console,Intl,Date,JSON,Number,Object,Array,Set,Map,String,Math,Error,crypto:globalThis.crypto,Blob,URL,setTimeout(){},location:{hash:''},confirm:()=>options.confirm??true,window:{NAINA_IMPORT:{meta:{id:'new'},bikes:[{...bike,id:'should-not-import'}]},addEventListener(){}},document:{querySelector(s){if(!nodes.has(s))nodes.set(s,node());return nodes.get(s)},querySelectorAll(){return []},addEventListener(){},createElement:node},localStorage:{getItem(){if(options.readError)throw Error('Access denied');return value},setItem(k,v){if(options.writeError)throw Error('Quota');assert.equal(k,'naina-desk-v1');writes.push(v);value=v},clear(){throw Error('Forbidden clear')},removeItem(){throw Error('Forbidden removal')}}});
 vm.runInContext(code,context);
 const run=s=>vm.runInContext(s,context);
 context.capture=(...args)=>dialogs.push(args);run('showForm=(...args)=>capture(...args)');
 return {run,writes,nodes,dialogs,get value(){return value},set value(v){value=v},context};
}
const inspect=b=>boot(JSON.stringify(data({...bike,...b})));
test('location maps actual schema columns without changing vehicle IDs',()=>{const a=inspect({vehicleLocation:{vehicle_id:bike.id,location_type:'Mechanic',location_label:'Bay 2',notes:'Synthetic note',changed_at:'2026-10-12'}});const v=a.run('vehicleLocationView(state.bikes[0])');assert.equal(v.type,'Mechanic');assert.equal(v.label,'Bay 2');assert.equal(v.updated,'2026-10-12');assert.equal(a.writes.length,0)});
test('missing location and wrong vehicle association are unassigned',()=>{for(const vehicleLocation of [undefined,{vehicle_id:'other',location_type:'Showroom'}]){const a=inspect({vehicleLocation});assert.equal(a.run('vehicleLocationView(state.bikes[0]).type'),'Location not assigned')}});
test('all documented types received counted correctly',()=>{const docs=Object.fromEntries(['rc','noc','form35','hpa','insurance','puc','auctionLetter','transfer','fir','hsrp','printed'].map(k=>[k,'YES']));const a=inspect({docs});assert.equal(a.run('documentChecklistView(state.bikes[0]).counts.complete'),11);assert.equal(a.run('documentChecklistView(state.bikes[0]).counts.unknown'),0)});
test('pending missing in-progress and unknown counted separately',()=>{const a=inspect({docs:{rc:'NO',noc:'Missing',form35:'In Progress',hpa:'Not Applicable',insurance:'waiting for bank'}});const c=a.run('documentChecklistView(state.bikes[0]).counts');assert.equal(c.pending,3);assert.equal(c.na,1);assert.equal(c.unknown,7);assert.equal(c.complete,0);assert.match(a.run('documentChecklistSection(state.bikes[0])'),/waiting for bank/)});
test('source fallback and explicit local values keep existing precedence',()=>{const a=inspect({docs:{rc:'NO'},sourceInventory:[{column:'K',value:'YES'},{column:'L',value:'YES'}]});const rows=a.run('documentChecklistView(state.bikes[0]).items');assert.equal(rows[0].status,'Pending');assert.equal(rows[1].status,'Received')});
test('buyer handover is not inferred as stock receipt',()=>{const a=inspect({handover:{rc:'YES'}});assert.equal(a.run('documentChecklistView(state.bikes[0]).items[0].status'),'Not Recorded')});
test('custom document names and unrecognized statuses remain visible and escaped',()=>{const a=inspect({docs:{'<img src=x onerror=alert(1)>':'<script>bad</script>',rc:'Delivered'}});const html=a.run('documentChecklistSection(state.bikes[0])');assert(!html.includes('<script>'));assert.match(html,/&lt;img/);assert.match(html,/Delivered/);assert.equal(a.run('documentChecklistView(state.bikes[0]).counts.unknown'),12)});
for(const status of ['Available','Sold'])test(status+' existing details contains both new sections and original controls',()=>{const a=inspect({status});a.run("showDetails('original-id')");const html=a.dialogs.at(-1)[1];for(const text of ['Vehicle Location','Document Checklist','Stock documents','Buyer handover documents','Original Excel','data-pane="costs"','name="reg"'])assert(html.includes(text),text);assert.equal(a.writes.length,0);assert.match(html,/type="button" disabled aria-describedby/)});
test('repeated opening, navigation and search do not write or call cloud',()=>{const a=inspect({});const raw=a.value;a.context.fetch=()=>{throw Error('Cloud forbidden')};for(let i=0;i<3;i++){a.run("initialise();render();showDetails('original-id','docs');search='TEST123';stockFilter='All';page='inventory';drawInventory()");assert.equal(a.run('stockRows().length'),1);a.run("search='missing';drawInventory()");assert.equal(a.run('stockRows().length'),0)}assert.equal(a.value,raw);assert.equal(a.writes.length,0)});
test('markup and responsive rules provide labels disabled buttons and mobile wrapping',()=>{const a=inspect({});const html=a.run('locationSection(state.bikes[0])+documentChecklistSection(state.bikes[0])');assert.match(html,/aria-labelledby="vehicle-location-title"/);assert.match(html,/<dl/);assert.match(html,/<ul/);assert(!/<input|<select|<textarea/.test(html));const css=fs.readFileSync('public/style.css','utf8');assert.match(css,/location-grid\{grid-template-columns:1fr\}/);assert.match(css,/focus-visible/);assert.match(css,/min-height:44px/)});

